tokio::task_local! {
    static SLOT_CONTINUATION_OWNER: ParkedHoleAbortRegistration;
    static INVOCATION_CANCEL: Arc<std::sync::atomic::AtomicBool>;
    static COMPILER_CLOSE_OWNER: crate::capabilities::CompilerOwnerScope;
    static EXECUTION_CONTROL: Arc<crate::WorkbenchExecutionControl>;
}

#[derive(Clone)]
pub(crate) enum CompilerCloseOwner {
    ActorLifecycle(crate::RetainedActorExit),
    ActorFinalization(crate::RetainedActorExit),
    SharedPreparation {
        producer: crate::RetainedActorExit,
        observer: Box<CompilerCloseOwner>,
    },
    Hosted(Arc<crate::WorkbenchExecutionControl>),
    Invocation {
        work: Arc<crate::resident_actor::invocation_work::InvocationWork>,
        control: Option<Arc<crate::WorkbenchExecutionControl>>,
    },
}

impl CompilerCloseOwner {
    pub(crate) fn close_settled(&self) {
        match self {
            Self::ActorLifecycle(owner) | Self::ActorFinalization(owner) => {
                owner.notify_compiler_close()
            }
            Self::SharedPreparation { producer, observer } => {
                producer.notify_compiler_close();
                observer.close_settled();
            }
            Self::Hosted(control) => control.notify_compiler_close(),
            Self::Invocation { control, .. } => {
                if let Some(control) = control {
                    control.notify_compiler_close();
                }
            }
        }
    }
}

impl crate::capabilities::CompilerOwnerScope {
    /// Capture before spawning: Tokio task-local contexts are not inherited.
    pub(crate) fn current() -> Result<Self, ResidentActorWorkbenchError> {
        COMPILER_CLOSE_OWNER
            .try_with(Clone::clone)
            .map_err(|_| ResidentActorWorkbenchError::CompilerCleanupOwnerUnavailable)
    }

    pub(crate) fn scope<T>(
        &self,
        operation: impl std::future::Future<Output = T>,
    ) -> impl std::future::Future<Output = T> {
        // Keep large resident operations behind the same pinned-pointer boundary
        // formerly owned by the concrete lifecycle scope helper.
        COMPILER_CLOSE_OWNER.scope(self.clone(), Box::pin(operation))
    }

    fn sync_scope<T>(&self, operation: impl FnOnce() -> T) -> T {
        COMPILER_CLOSE_OWNER.sync_scope(self.clone(), operation)
    }
}

impl CompilerCloseOwner {
    pub(crate) fn shared_preparation(&self, producer: crate::RetainedActorExit) -> Self {
        Self::SharedPreparation {
            producer,
            observer: Box::new(self.clone()),
        }
    }
}

/// Direct fixtures supply the existing lifecycle owner explicitly.
#[cfg(test)]
pub(crate) fn with_test_compiler_owner<T, F: std::future::Future<Output = T>>(
    operation: impl FnOnce(crate::CompilerPreparationClient) -> F,
) -> impl std::future::Future<Output = T> {
    // Keep caller payload and operation state behind heap boundaries before
    // composing owner, unwind, and cleanup adapters.
    let operation = Box::new(operation);
    async move {
        let mut owner = crate::CompilerPreparationOwner::new();
        let cleanup = owner.cleanup();
        let result = futures_util::FutureExt::catch_unwind(std::panic::AssertUnwindSafe(
            owner.scope_with_client(move |client| Box::pin(operation(client))),
        ))
        .await;
        let observation = cleanup
            .wait_for_settlement(std::time::Duration::from_secs(5))
            .await;
        assert!(
            observation.is_confirmed(),
            "compiler cleanup: {observation:?}"
        );
        match result {
            Ok(outcome) => outcome.action,
            Err(panic) => std::panic::resume_unwind(panic),
        }
    }
}

#[cfg(test)]
fn with_test_bound_source<T, F: std::future::Future<Output = T>>(
    config: ActorWorkbenchSource,
    operation: impl FnOnce(BoundActorWorkbenchSource) -> F,
) -> impl std::future::Future<Output = T> {
    with_test_compiler_owner(move |client| operation(config.bind_preparation(client)))
}

#[cfg(test)]
#[test]
fn compiler_owner_wrapper_size_does_not_scale_with_operation_state() {
    fn operation<const N: usize>() -> impl std::future::Future<Output = ()> {
        let payload = [0_u8; N];
        async move {
            std::hint::black_box(payload);
        }
    }
    let small = operation::<1>();
    let large = operation::<65536>();
    assert!(std::mem::size_of_val(&large) > std::mem::size_of_val(&small));
    let small = with_test_compiler_owner(|_| small);
    let large = with_test_compiler_owner(|_| large);
    assert_eq!(std::mem::size_of_val(&large), std::mem::size_of_val(&small));
    let small_payload = [0_u8; 1];
    let large_payload = [0_u8; 65536];
    let small = with_test_compiler_owner(move |_| async move {
        std::hint::black_box(small_payload);
    });
    let large = with_test_compiler_owner(move |_| async move {
        std::hint::black_box(large_payload);
    });
    assert_eq!(std::mem::size_of_val(&large), std::mem::size_of_val(&small));
}

pub(crate) fn with_invocation_cancellation<T>(
    cancel: Arc<std::sync::atomic::AtomicBool>,
    operation: impl std::future::Future<Output = T>,
) -> impl std::future::Future<Output = T> {
    INVOCATION_CANCEL.scope(cancel, operation)
}

pub(crate) fn with_execution_control<T>(
    control: Arc<crate::WorkbenchExecutionControl>,
    operation: impl std::future::Future<Output = T>,
) -> impl std::future::Future<Output = T> {
    let cancel = control.native_cancel();
    EXECUTION_CONTROL.scope(control, with_invocation_cancellation(cancel, operation))
}

pub(crate) fn execution_control() -> Option<Arc<crate::WorkbenchExecutionControl>> {
    EXECUTION_CONTROL.try_with(Arc::clone).ok()
}

impl ActorWorkbenchSource {
    fn compile_inputs(
        &self,
        context: &crate::ActorSessionContext,
    ) -> Result<tidepool_runtime::session::RuntimeCompileInputs, ResidentActorWorkbenchError> {
        tidepool_runtime::session::RuntimeCompileInputs::new(
            self.request_annotations()
                .map_err(ResidentActorWorkbenchError::Compile)?,
            context.source_imports.declaration_projections()?,
        )
        .map_err(ResidentActorWorkbenchError::Compile)
    }

    fn inspection_scope<H, O>(
        &self,
        session: &ResidentSession<H, O>,
        context: &crate::ActorSessionContext,
        request_scope: Option<&RequestWorkbenchScope>,
        label: tidepool_runtime::session::NameScope,
    ) -> Result<tidepool_runtime::session::InspectionScopeSnapshot, ResidentActorWorkbenchError>
    where
        H: DispatchEffect<O> + Send,
        O: OutputSink + Sync,
    {
        let source_revision = match &context.source_layer {
            crate::ActorSourceRoots::Complete(source) => source.source_revision_identity(),
            crate::ActorSourceRoots::Deployment(_) => None,
        }
        .filter(|revision| !revision.is_empty())
        .ok_or(ActorCompileViewError::UnobservedSourceIdentity)?;
        let inputs = self.compile_inputs(context)?;
        let actor = Self::inspection_actor(context, request_scope);
        let mut imports = context.selected_source_imports();
        imports.extend(&self.workbench_imports);
        session
            .capture_inspection_scope_in(
                context.placement.lexical_scope,
                source_revision.as_bytes(),
                &imports,
                &inputs,
                Some(&actor),
                label,
            )
            .map_err(|error| ResidentActorWorkbenchError::Resident(ResidentError::Session(error)))
    }

    fn inspection_provenance<H, O>(
        &self,
        session: &ResidentSession<H, O>,
        context: &crate::ActorSessionContext,
        request_scope: Option<&RequestWorkbenchScope>,
        label: tidepool_runtime::session::NameScope,
    ) -> Result<tidepool_runtime::session::ScopeProvenance, ResidentActorWorkbenchError>
    where
        H: DispatchEffect<O> + Send,
        O: OutputSink + Sync,
    {
        self.inspection_scope(session, context, request_scope, label)
            .map(|snapshot| snapshot.provenance())
    }

    fn inspection_actor(
        context: &crate::ActorSessionContext,
        request_scope: Option<&RequestWorkbenchScope>,
    ) -> tidepool_runtime::session::InspectionActorObservation {
        use tidepool_runtime::session::{InspectionActorObservation, InspectionRequestIdentity};
        InspectionActorObservation::new(
            tidepool_repr::PrincipalId::from(context.actor),
            context.haskell_effects_alias.clone(),
            request_scope.map(|scope| InspectionRequestIdentity::new(scope.request.0)),
            context
                .current_model
                .as_ref()
                .map(|(identity, _)| current_model_type_source(identity)),
        )
    }

    fn request_annotations(
        &self,
    ) -> Result<Option<tidepool_runtime::session::RequestCompileAnnotations>, CompileError> {
        match &self.request_evidence {
            Some(evidence) => tidepool_runtime::session::RequestCompileAnnotations::new(
                evidence.clone(),
                self.request_helper_recipe,
            )
            .map(Some),
            None if self.request_helper_recipe
                == tidepool_toolchain::declaration_join::RequestHelperRecipe::None =>
            {
                Ok(None)
            }
            None => Err(CompileError::ExtractFailed(
                "actor reply helpers require authenticated request evidence".into(),
            )),
        }
    }

    fn request_preamble(&self, request: crate::RequestId, effects_alias: &str) -> String {
        self.request_preamble_for(request, effects_alias, PreambleBindings::Runtime)
    }

    fn request_preamble_for(
        &self,
        request: crate::RequestId,
        effects_alias: &str,
        bindings: PreambleBindings,
    ) -> String {
        let preamble = &self.preamble;
        let signatures = self
            .request_evidence
            .as_ref()
            .and_then(|evidence| evidence.request_type_signatures());
        let mut preamble = insert_preamble_imports(
            preamble,
            "qualified Tidepool.Agent.Reply.Internal as TidepoolReplies",
        );
        preamble = insert_preamble_imports(&preamble, "qualified Data.Void as TidepoolVoid");
        preamble = insert_preamble_imports(&preamble, "qualified Prelude as TidepoolPrelude");
        let reply = bindings.body(|| {
            format!(
                "TidepoolReplies.Reply (TidepoolReplies.RequestId {})",
                request.0
            )
        });
        let respond = bindings.body(|| "TidepoolReplies.reply sessionReply".to_owned());
        preamble.push_str(&format!(
            "\nsessionReply :: TidepoolReplies.Reply TidepoolRequestReply\nsessionReply = {reply}\nrespond :: TidepoolRequestReply -> Eff {effects_alias} TidepoolVoid.Void\nrespond = {respond}\n",
        ));
        if signatures
            .and_then(|signatures| signatures.progress())
            .is_some()
        {
            let progress_type = "TidepoolRequestProgress";
            let report = bindings.body(|| format!(
                "\\value -> do\n  outcome <- TidepoolReplies.reportRequestProgress (TidepoolReplies.ProgressSink (TidepoolReplies.RequestId {})) value\n  case outcome of\n    Left failure -> TidepoolPrelude.error (TidepoolPrelude.show failure)\n    Right () -> pure ()", request.0,
            ));
            preamble.push_str(&format!(
                "\nreportProgress :: ({progress_type}) -> Eff {effects_alias} ()\nreportProgress = {report}\n",
            ));
        }
        preamble
    }
}

#[derive(Clone, Copy)]
enum PreambleBindings {
    Runtime,
    TypeObservation,
}

impl PreambleBindings {
    fn body(self, runtime: impl FnOnce() -> String) -> String {
        match self {
            Self::Runtime => runtime(),
            Self::TypeObservation => "(let observation = observation in observation)".to_owned(),
        }
    }
}

fn actor_preamble(preamble: &str, context: &crate::ActorSessionContext) -> String {
    actor_preamble_for(preamble, context, PreambleBindings::Runtime)
}

fn current_model_source_profile(
    identity: &crate::AdmittedModelIdentity,
) -> (&'static str, &'static str, &'static str, &'static str) {
    match identity.model().backend() {
        crate::Backend::OpenAIPlan => ("OpenAI", "openAI", "OpenAIOptions", "OpenAI"),
        crate::Backend::GeminiInteractions => ("Argon", "argon", "ArgonOptions", "Effort"),
        crate::Backend::DeepSeek => ("DeepSeek", "deepSeek", "DeepSeekOptions", "DeepSeek"),
    }
}

fn current_model_type_source(
    identity: &crate::AdmittedModelIdentity,
) -> tidepool_runtime::session::HaskellTypeSource {
    let (family, _, _, _) = current_model_source_profile(identity);
    let mut imports = tidepool_runtime::session::SourceImports::default();
    imports.extend_text("qualified Tidepool.Model.Selection as TidepoolModelSelection");
    tidepool_runtime::session::HaskellTypeSource::new(
        format!("TidepoolModelSelection.Model TidepoolModelSelection.{family}"),
        imports,
    )
}

fn actor_preamble_for(
    preamble: &str,
    context: &crate::ActorSessionContext,
    bindings: PreambleBindings,
) -> String {
    let preamble = insert_preamble_imports(
        preamble,
        "qualified Tidepool.Agent.Ref.Internal as TidepoolAgentRef",
    );
    let me = bindings.body(|| {
        format!(
            "TidepoolAgentRef.internalAgentRef {} {}",
            context.actor.id.0, context.actor.incarnation.0
        )
    });
    let mut rendered = format!("{preamble}\nme :: TidepoolAgentRef.AgentRef\nme = {me}\n",);
    if let Some((identity, reasoning)) = &context.current_model {
        let (_, constructor, options, prefix) = current_model_source_profile(identity);
        let model_type = current_model_type_source(identity);
        let effort = match reasoning {
            crate::Reasoning::OpenAIReasoning(crate::OpenAIReasoning::OpenAILow)
            | crate::Reasoning::ArgonReasoning(crate::ArgonEffort::EffortLow)
            | crate::Reasoning::DeepSeekReasoning(crate::DeepSeekReasoning::DeepSeekLow) => "Low",
            crate::Reasoning::OpenAIReasoning(crate::OpenAIReasoning::OpenAIMedium)
            | crate::Reasoning::ArgonReasoning(crate::ArgonEffort::EffortMedium) => "Medium",
            crate::Reasoning::OpenAIReasoning(crate::OpenAIReasoning::OpenAIHigh)
            | crate::Reasoning::ArgonReasoning(crate::ArgonEffort::EffortHigh)
            | crate::Reasoning::DeepSeekReasoning(crate::DeepSeekReasoning::DeepSeekHigh) => "High",
            crate::Reasoning::DeepSeekReasoning(crate::DeepSeekReasoning::DeepSeekNone) => "None",
            crate::Reasoning::DeepSeekReasoning(crate::DeepSeekReasoning::DeepSeekMax) => "Max",
        };
        let literal = |text: &str| {
            format!(
                "\"{}\"",
                tidepool_runtime::session::escape_workbench_haskell_string(text)
            )
        };
        for import in model_type.required_imports().specs() {
            rendered = insert_preamble_imports(&rendered, import);
        }
        let current_model = bindings.body(|| format!(
            "TidepoolModelSelection.{constructor} {} {} (TidepoolModelSelection.{options} TidepoolModelSelection.{prefix}{effort})",
            literal(identity.catalog_identity()), literal(identity.key()),
        ));
        rendered.push_str(&format!(
            "\ncurrentModel :: {}\ncurrentModel = {current_model}\n",
            model_type.expression(),
        ));
    }
    rendered
}

// This header belongs to the trusted generated template, never authored cell text.
fn cell_module_preamble(
    preamble: &str,
    module: &str,
) -> Result<String, ResidentActorWorkbenchError> {
    let mut replaced = false;
    let rendered = preamble
        .split_inclusive('\n')
        .map(|line| {
            if !replaced
                && line.trim_start().starts_with("module ")
                && line.trim_end().ends_with(" where")
            {
                replaced = true;
                let newline = if line.ends_with('\n') { "\n" } else { "" };
                format!("module {module} where{newline}")
            } else {
                line.to_owned()
            }
        })
        .collect::<String>();
    if replaced {
        Ok(rendered)
    } else {
        Err(ResidentActorWorkbenchError::CompileInfrastructure(
            "resident cell preamble has no module declaration".into(),
        ))
    }
}

/// The same cell-check failure mapping every `prepare_cell` exit uses:
/// a genuine Haskell error becomes a rejectable [`CellCheck`] failure the
/// caller can present, anything else is infrastructure trouble.
/// When a cell GHC has already rejected has a declaration reaching for a name
/// an earlier statement binds, say so beside GHC's own diagnostics.
///
/// The scan that finds this shape is lexical and cannot see every way Haskell
/// binds a name (a case alternative, a record field, an operator containing
/// `<-`), so it explains a failure and never causes one: a cell GHC accepts is
/// never refused on its word. It speaks only when GHC's diagnostics name the
/// same binder, which keeps it quiet on failures it has nothing to do with.
fn explain_source_order(
    failure: &mut tidepool_runtime::session::CellCheckFailure,
    cell_source: &str,
) {
    let CompileError::Diagnostics(diagnostics) = &mut failure.error else {
        return;
    };
    let Some(collision) =
        tidepool_runtime::session::detect_hoisted_declaration_collision(cell_source)
    else {
        return;
    };
    if !diagnostics
        .iter()
        .any(|diagnostic| diagnostic.message.contains(&collision.binder_name))
    {
        return;
    }
    let line = u32::try_from(collision.declaration_line).unwrap_or(u32::MAX);
    diagnostics.push(tidepool_toolchain::diag::ExtractDiag {
        span: Some(tidepool_toolchain::diag::DiagSpan {
            file: "<cell>".to_string(),
            start_line: line,
            start_col: 1,
            end_line: line,
            end_col: 1,
        }),
        severity: tidepool_toolchain::diag::DiagnosticSeverity::Warning,
        message: collision.message(),
    });
}

fn cell_check_error(
    failure: tidepool_runtime::session::CellCheckFailure,
    cell_source: &str,
) -> ResidentActorWorkbenchError {
    if let Some(error) = &failure.source_admission {
        return error.clone().into();
    }
    if classify_compile(&failure.error).class == FailureClass::UserHaskell {
        let mut failure = failure;
        explain_source_order(&mut failure, cell_source);
        ResidentActorWorkbenchError::CellCheck(failure)
    } else {
        let mut diagnostic = classify_compile(&failure.error);
        diagnostic.message =
            tidepool_runtime::session::render_cell_compile_error(&failure.error, cell_source);
        ResidentActorWorkbenchError::CompileInfrastructure(diagnostic)
    }
}

