/// Trusted source environment supplied by actor deployment. The canonical
/// `ActorEffects` alias itself lives in the imported Haskell facade; Rust does
/// not reflect or authorize its row entries.
#[derive(Clone)]
pub struct ActorWorkbenchSource {
    preamble: Arc<str>,
    observation_preamble: Option<Arc<str>>,
    base_include: Arc<[PathBuf]>,
    workbench_imports: SourceImports,
    /// The workspace's `[haskell] spec` key, when it names one. Rule two of
    /// spec discovery; rule one is `AgentSpec.hs` in the run graph.
    spec: Option<Arc<str>>,
    workspace_modules: Arc<[String]>,
    installed_effect_support: Arc<[exomonad_tool::ToolEffectKey]>,
    tool_surface_validator:
        Option<Arc<dyn Fn(&[exomonad_tool::HostedTool]) -> Result<(), String> + Send + Sync>>,
    request_evidence: Option<Arc<tidepool_runtime::session::SiteTypeEvidence>>,
    request_helper_recipe: tidepool_toolchain::declaration_join::RequestHelperRecipe,
    toolset_support: Arc<[PathBuf]>,
    toolset_support_manifests:
        Arc<std::sync::OnceLock<Vec<tidepool_toolchain::cache::SourceRootManifest>>>,
    prepared_toolset: Option<PreparedSourceToolset>,
}

/// Source configuration bound to one run's preparation lifetime. Clones share
/// pending work, including separate bindings to the same issued client.
/// Independently issued owner lifetimes have independent preparation state.
#[derive(Clone)]
pub struct BoundActorWorkbenchSource {
    config: ActorWorkbenchSource,
    preparation: crate::CompilerPreparationClient,
    toolset_preparation: Arc<crate::agent_spec::preparation::ToolsetPreparation>,
}

impl BoundActorWorkbenchSource {
    pub(crate) fn with_source_dependency(
        mut self,
        dependency: &generation_admission::SourceDependency,
    ) -> Self {
        self.preparation = self.preparation.with_source_dependency(dependency);
        self
    }
    pub fn config(&self) -> &ActorWorkbenchSource {
        &self.config
    }
    /// Change authored configuration while preserving the exact run and shared
    /// preparation owner. New recipes remain independently keyed by the owner.
    pub fn with_config(
        mut self,
        update: impl FnOnce(ActorWorkbenchSource) -> ActorWorkbenchSource,
    ) -> Self {
        self.config = update(self.config);
        self
    }

    pub fn into_config(self) -> ActorWorkbenchSource {
        self.config
    }
}

/// Immutable installer readiness. It owns source and native code, while each
/// actor still executes its own installation in a fresh lexical scope.
#[derive(Clone)]
pub struct PreparedSourceToolset {
    prepared: Arc<crate::agent_spec::preparation::PreparedToolset>,
    effects: Vec<crate::ActorEffectKey>,
}

/// Observations of the exact installer recipe built by the preparation owner.
/// These fields describe coverage; they do not issue compiler or source custody.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SourceToolsetRecipe {
    pub requested_effects: Vec<crate::ActorEffectKey>,
    pub effective_effects: Vec<crate::ActorEffectKey>,
    pub source_revision: String,
    pub program: crate::ToolsetProgramRecipe,
}

impl std::fmt::Debug for PreparedSourceToolset {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("PreparedSourceToolset")
            .field("acquisition", self.acquisition())
            .field("effects", &self.effects)
            .finish()
    }
}

fn installer_program_recipe(
    recipe: &crate::agent_spec::preparation::InstallerRecipe,
) -> Result<crate::ToolsetProgramRecipe, ResidentActorWorkbenchError> {
    match &recipe.builtin {
        Some(program) => Ok(crate::ToolsetProgramRecipe::BuiltinDeploymentProgram(
            program.clone(),
        )),
        None => crate::agent_spec::preparation::durable_recipe_key(recipe)
            .map(crate::ToolsetProgramRecipe::WorkspaceOriginal)
            .map_err(|error| ResidentActorWorkbenchError::ActorProtocol(format!("{error:?}"))),
    }
}

fn sync_effects_supported(supported: &[exomonad_tool::ToolEffectKey]) -> bool {
    exomonad_tool::ToolEffectKey::ALL
        .iter()
        .filter(|effect| effect.is_invocation_only())
        .all(|effect| supported.contains(effect))
}

fn builtin_toolset_policy(
    rule: crate::agent_spec::SpecRule,
    effects: &[crate::ActorEffectKey],
    supported: &[exomonad_tool::ToolEffectKey],
) -> Option<crate::BuiltinToolsetPolicy> {
    if rule != crate::agent_spec::SpecRule::BuiltinDefault
        || effects != crate::ActorCapabilities::default().effect_keys()
    {
        return None;
    }
    Some(if sync_effects_supported(supported) {
        crate::BuiltinToolsetPolicy::Workbench
    } else {
        crate::BuiltinToolsetPolicy::AsyncWorkbench
    })
}

impl PreparedSourceToolset {
    #[must_use]
    pub fn selection(&self) -> Option<crate::ToolsetProgramSelection> {
        self.prepared.acquisition.selection()
    }

    #[must_use]
    pub fn image_registry(&self) -> Arc<tidepool_runtime::session::ImageRegistry> {
        Arc::clone(self.prepared.entry.image_registry())
    }
    #[must_use]
    pub fn source_revision(&self) -> &str {
        &self.prepared.source_revision
    }

    #[must_use]
    pub fn effects(&self) -> &[crate::ActorEffectKey] {
        &self.effects
    }

    /// Provenance issued by the original preparation, retained across cache hits.
    #[must_use]
    pub fn acquisition(&self) -> &crate::ToolsetAcquisition {
        &self.prepared.acquisition
    }

    /// Exact completed output selected after full native readiness. This is
    /// retained-source metadata; loading still validates original custody.
    #[must_use]
    pub fn completed_entry_selection(&self) -> Option<(&str, uuid::Uuid)> {
        self.prepared.acquisition.completed_entry_selection()
    }
}

/// One prepared import environment for evaluation and inspection. Name
/// resolution comes from the exact lexical view before either path builds
/// a compiler request.
struct WorkbenchCompilation {
    preamble: String,
    imports: String,
    include: Vec<PathBuf>,
    injected: Vec<String>,
}

impl BoundActorWorkbenchSource {
    /// Prepare one exact granted and supported row from an owned immutable run
    /// source graph. Preparation does not install tools or borrow actor heaps.
    /// The caller selects urgency; required startup is foreground and optional
    /// warming is preparation work.
    pub async fn prepare_source_toolset(
        &self,
        workload: tidepool_toolchain::artifacts::CompileWorkload,
        source: crate::CheckpointSourceLayer,
        granted_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
        registry: Arc<tidepool_runtime::session::ImageRegistry>,
    ) -> Result<PreparedSourceToolset, ResidentActorWorkbenchError> {
        self.prepare_source_toolset_selected(
            workload,
            source,
            granted_effects,
            supported_effects,
            registry,
            None,
        )
        .await
    }

    pub async fn prepare_source_toolset_with_validation(
        &self,
        workload: tidepool_toolchain::artifacts::CompileWorkload,
        source: crate::CheckpointSourceLayer,
        granted_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
        registry: Arc<tidepool_runtime::session::ImageRegistry>,
        validation: &SourceImports,
    ) -> Result<PreparedSourceToolset, ResidentActorWorkbenchError> {
        self.prepare_source_toolset_selected(
            workload,
            source,
            granted_effects,
            supported_effects,
            registry,
            Some(validation),
        )
        .await
    }

    async fn prepare_source_toolset_selected(
        &self,
        workload: tidepool_toolchain::artifacts::CompileWorkload,
        source: crate::CheckpointSourceLayer,
        granted_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
        registry: Arc<tidepool_runtime::session::ImageRegistry>,
        validation: Option<&SourceImports>,
    ) -> Result<PreparedSourceToolset, ResidentActorWorkbenchError> {
        self.preparation.claim(|| ())?;
        let (recipe, resolved) = self.config.installer_recipe_selected(
            &source,
            granted_effects,
            supported_effects,
            validation,
        )?;
        let effects = recipe.effects.clone();
        if let Some(ready) = &self.config.prepared_toolset {
            let exact_selection = match ready.selection() {
                Some(crate::ToolsetProgramSelection::BuiltinDeploymentProgram { .. }) => true,
                Some(crate::ToolsetProgramSelection::WorkspaceOriginal { recipe, original }) => {
                    matches!(source.prepared_entries(), Some(crate::SourceEntryStorage::CompletedOriginal { selections, .. })
                        if selections.get(&recipe) == Some(&original))
                }
                None => false,
            };
            if ready.effects == effects
                && exact_selection
                && ready.selection().map(|selection| selection.recipe())
                    == Some(installer_program_recipe(&recipe)?)
            {
                return self.preparation.claim(|| ready.clone());
            }
        }
        let prepared = self
            .toolset_preparation
            .prepare(
                &self.preparation,
                workload,
                recipe,
                resolved,
                source,
                registry,
            )
            .await
            .map_err(|failure| match failure {
                crate::agent_spec::preparation::PreparationFailure::AbsentSelection { recipe } => {
                    ResidentActorWorkbenchError::PreparedEntryAbsent { recipe }
                }
                crate::agent_spec::preparation::PreparationFailure::Admission(error) => {
                    ResidentActorWorkbenchError::PreparationAdmission(error)
                }
                crate::agent_spec::preparation::PreparationFailure::Compiler(diagnostic) => {
                    ResidentActorWorkbenchError::CompileInfrastructure(diagnostic)
                }
                crate::agent_spec::preparation::PreparationFailure::Source(detail)
                | crate::agent_spec::preparation::PreparationFailure::Native(detail) => {
                    ResidentActorWorkbenchError::ActorProtocol(detail)
                }
            })?;
        Ok(PreparedSourceToolset { prepared, effects })
    }

    /// Load the compiler original selected by durable installation evidence.
    /// Its retained wrapper carries the candidate's exact validation imports.
    pub async fn restore_source_toolset(
        &self,
        workload: tidepool_toolchain::artifacts::CompileWorkload,
        source: crate::CheckpointSourceLayer,
        installation: &PersistedActorInstallation,
        granted_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
        registry: Arc<tidepool_runtime::session::ImageRegistry>,
    ) -> Result<PreparedSourceToolset, ResidentActorWorkbenchError> {
        self.preparation.claim(|| ())?;
        if source
            .generation_evidence()
            .is_none_or(|evidence| evidence.reference.sha256() != &installation.source_sha256)
        {
            return Err(ResidentActorWorkbenchError::ActorProtocol(
                "recovered installer selects a different source artifact".into(),
            ));
        }
        let mut pinned = self.config.clone();
        pinned.spec = installation.entry().map(Arc::from);
        // Metadata is resolved against immutable source with the persisted
        // entry pin. These imports are never used to locate or load the entry.
        let (mut recipe, resolved) = pinned.installer_recipe_selected(
            &source,
            granted_effects,
            supported_effects,
            Some(&SourceImports::default()),
        )?;
        if resolved.entry.as_deref() != installation.entry() {
            return Err(ResidentActorWorkbenchError::ActorProtocol(
                "recovered installer entry differs from its immutable source".into(),
            ));
        }
        if let crate::ToolsetAcquisition::BuiltinDeploymentProgram { program } =
            installation.acquisition()
        {
            if builtin_toolset_policy(resolved.rule, &recipe.effects, supported_effects)
                != Some(program.policy)
            {
                return Err(ResidentActorWorkbenchError::ActorProtocol(
                    "recovered built-in installer does not match the actor contract".into(),
                ));
            }
            recipe.source_revision = program.manifest_blake3.clone();
        }
        let effects = recipe.effects.clone();
        let prepared = self
            .toolset_preparation
            .restore(
                &self.preparation,
                workload,
                recipe,
                resolved,
                source,
                installation.acquisition().clone(),
                registry,
            )
            .await
            .map_err(|failure| match failure {
                crate::agent_spec::preparation::PreparationFailure::AbsentSelection { recipe } => {
                    ResidentActorWorkbenchError::PreparedEntryAbsent { recipe }
                }
                crate::agent_spec::preparation::PreparationFailure::Admission(error) => {
                    ResidentActorWorkbenchError::PreparationAdmission(error)
                }
                crate::agent_spec::preparation::PreparationFailure::Compiler(diagnostic) => {
                    ResidentActorWorkbenchError::CompileInfrastructure(diagnostic)
                }
                crate::agent_spec::preparation::PreparationFailure::Source(detail)
                | crate::agent_spec::preparation::PreparationFailure::Native(detail) => {
                    ResidentActorWorkbenchError::ActorProtocol(detail)
                }
            })?;
        Ok(PreparedSourceToolset { prepared, effects })
    }
}

impl ActorWorkbenchSource {
    /// Recompute deployment coverage against the same source, imports and
    /// actual interpreter support used by installer acquisition, without
    /// looking up readiness or admitting compiler work.
    pub fn source_toolset_recipe(
        &self,
        source: &crate::CheckpointSourceLayer,
        requested_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
    ) -> Result<SourceToolsetRecipe, ResidentActorWorkbenchError> {
        let (recipe, _) = self.installer_recipe(source, requested_effects, supported_effects)?;
        let program = installer_program_recipe(&recipe)?;
        Ok(SourceToolsetRecipe {
            requested_effects: requested_effects.to_vec(),
            effective_effects: recipe.effects,
            source_revision: recipe.source_revision,
            program,
        })
    }

    fn installer_recipe(
        &self,
        source: &crate::CheckpointSourceLayer,
        granted_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
    ) -> Result<
        (
            crate::agent_spec::preparation::InstallerRecipe,
            crate::agent_spec::ResolvedSpec,
        ),
        ResidentActorWorkbenchError,
    > {
        self.installer_recipe_selected(source, granted_effects, supported_effects, None)
    }

    fn installer_recipe_selected(
        &self,
        source: &crate::CheckpointSourceLayer,
        granted_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
        validation: Option<&SourceImports>,
    ) -> Result<
        (
            crate::agent_spec::preparation::InstallerRecipe,
            crate::agent_spec::ResolvedSpec,
        ),
        ResidentActorWorkbenchError,
    > {
        let mut effects = Vec::new();
        for key in granted_effects {
            if supported_effects.contains(&exomonad_tool::ToolEffectKey::Actor(*key))
                && !effects.contains(key)
            {
                effects.push(*key);
            }
        }
        let roots = if source.generation_evidence().is_some() {
            source.include_paths().to_vec()
        } else {
            let mut roots = self.toolset_support.to_vec();
            roots.extend(source.include_paths().iter().cloned());
            roots
        };
        let roots = roots
            .into_iter()
            .map(std::fs::canonicalize)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| ResidentActorWorkbenchError::ActorProtocol(error.to_string()))?;
        let resolved = crate::agent_spec::resolve(roots.clone(), self.spec.as_deref());
        let builtin = if let Some(policy) = validation
            .is_none()
            .then(|| builtin_toolset_policy(resolved.rule, &effects, supported_effects))
            .flatten()
        {
            // Observe the current deployment selection before reusing issuer-owned
            // readiness. This reads metadata without decoding its native images.
            crate::agent_spec::preparation::builtin_program(policy)
                .map_err(|error| ResidentActorWorkbenchError::ActorProtocol(format!("{error:?}")))?
        } else {
            None
        };
        if let Some(program) = builtin {
            return Ok((
                crate::agent_spec::preparation::InstallerRecipe {
                    source_authority: None,
                    source_revision: program.manifest_blake3.clone(),
                    roots: Vec::new(),
                    preamble: String::new(),
                    imports: String::new(),
                    entry: match program.policy {
                        crate::BuiltinToolsetPolicy::Workbench => {
                            "Tidepool.Actors.Workbench.installDefaultWorkbench"
                        }
                        crate::BuiltinToolsetPolicy::AsyncWorkbench => {
                            "Tidepool.Actors.Workbench.installDefaultAsyncWorkbench"
                        }
                    }
                    .into(),
                    effects,
                    builtin: Some(program),
                },
                resolved,
            ));
        }
        let source_revision = if let Some(manifests) = source.source_manifests() {
            if manifests.len() != source.include_paths().len() {
                return Err(ResidentActorWorkbenchError::ActorProtocol(
                    "source owner's ordered manifest count differs from its roots".into(),
                ));
            }
            if self.toolset_support_manifests.get().is_none() {
                let captured = self
                    .toolset_support
                    .iter()
                    .map(|root| {
                        let files = tidepool_toolchain::cache::source_root_manifest(root)
                            .map_err(|error| error.to_string())?;
                        tidepool_toolchain::cache::SourceRootManifest::from_file_digests(files)
                            .map_err(|error| error.to_string())
                    })
                    .collect::<Result<Vec<_>, String>>()
                    .map_err(ResidentActorWorkbenchError::ActorProtocol)?;
                // A failed acquisition is retryable. Concurrent successful
                // acquisitions observe the same immutable deployment roots.
                let _ = self.toolset_support_manifests.set(captured);
            }
            let support = self
                .toolset_support_manifests
                .get()
                .expect("support acquired");
            let ordered = if source.generation_evidence().is_some() {
                manifests.to_vec()
            } else {
                support.iter().chain(manifests).cloned().collect::<Vec<_>>()
            };
            tidepool_toolchain::cache::source_manifests_identity(
                b"exomonad-agent-spec-ordered-source-closure-v1",
                &ordered,
            )
        } else {
            resolved
                .source_closure_revision()
                .map_err(ResidentActorWorkbenchError::ActorProtocol)?
        };
        let entry = resolved.entry.clone().unwrap_or_else(|| {
            if sync_effects_supported(supported_effects) {
                "Tidepool.Agent.Contract.defaultWorkbenchSpec".into()
            } else {
                "Tidepool.Agent.Contract.defaultAsyncWorkbenchSpec".into()
            }
        });
        let mut imports = SourceImports::default();
        if let Some((module, _)) = entry.rsplit_once('.') {
            imports.extend_text(&format!("qualified {module}"));
        }
        if let Some(validation) = validation {
            imports.extend(validation);
        }
        imports.extend_text("qualified Tidepool.Agent.Contract");
        imports.extend_text("qualified Tidepool.Effects.Core");
        imports = crate::agent_spec::installation_expression(&entry, &effects)
            .effect_row
            .source_imports(&imports);
        Ok((
            crate::agent_spec::preparation::InstallerRecipe {
                builtin: None,
                source_authority: Some(source.semantic_digest()),
                source_revision,
                roots,
                preamble: format!(
                    "{}\nmodule Expr where\nimport Prelude\nimport Control.Monad.Freer (Eff)\nimport qualified Data.Text as T\n{}",
                    tidepool_runtime::session::EVAL_PRAGMAS,
                    tidepool_runtime::session::PREAMBLE_IMPORT_MARKER
                ),
                imports: imports.template_text(),
                entry,
                effects,
            },
            resolved,
        ))
    }

    fn prepare(&self, scope: &crate::ActorCompileView) -> WorkbenchCompilation {
        tidepool_toolchain::timing::record_host_work(
            tidepool_toolchain::timing::HostWorkCounter::ActorSourcePrepare,
            1,
        );
        WorkbenchCompilation {
            preamble: scope.shadow_preamble(&hide_preamble_exports(
                &self.preamble,
                &["print"]
                    .map(|name| tidepool_runtime::session::ExportItem::Value { name: name.into() }),
            )),
            imports: scope.turn_imports(),
            include: scope.include_paths(&self.base_include),
            injected: scope.injected_module_names(),
        }
    }

    #[must_use]
    pub fn bind_preparation(
        self,
        preparation: crate::CompilerPreparationClient,
    ) -> BoundActorWorkbenchSource {
        BoundActorWorkbenchSource {
            config: self,
            toolset_preparation: preparation.preparation(),
            preparation,
        }
    }

    pub fn new(preamble: impl Into<Arc<str>>, base_include: Vec<PathBuf>) -> Self {
        Self {
            preamble: preamble.into(),
            observation_preamble: None,
            toolset_support: base_include.clone().into(),
            toolset_support_manifests: Default::default(),
            base_include: base_include.into(),
            workbench_imports: SourceImports::from_specs([
                "qualified Data.Set as Set",
                "Tidepool.Inspection (display, expand, expansions)",
                "qualified Tidepool.Effects.Core",
            ]),
            spec: None,
            workspace_modules: Arc::from([]),
            installed_effect_support: Arc::from([]),
            tool_surface_validator: None,
            request_evidence: None,
            request_helper_recipe: Default::default(),
            prepared_toolset: None,
        }
    }

    /// Carry only immutable issuer-owned readiness into immediate launch.
    #[must_use]
    pub fn with_prepared_toolset(mut self, ready: Option<PreparedSourceToolset>) -> Self {
        self.prepared_toolset = ready;
        self
    }

    /// Deployment-owned support roots, ahead of the source owner's published
    /// toolset graph. Notebook/helper roots do not enter installer construction.
    #[must_use]
    pub fn with_toolset_support_roots(mut self, roots: Vec<PathBuf>) -> Self {
        self.toolset_support = roots.into();
        self.toolset_support_manifests = Default::default();
        self
    }

    /// Capture support from the actual assembled interpreter instances and
    /// installed host services, before admitting source-authored tools.
    #[must_use]
    pub fn with_installed_effect_support(
        mut self,
        keys: impl IntoIterator<Item = exomonad_tool::ToolEffectKey>,
    ) -> Self {
        let mut installed = Vec::new();
        for key in keys {
            if !installed.contains(&key) {
                installed.push(key);
            }
        }
        self.installed_effect_support = installed.into();
        self
    }

    /// Validate the admitted provider-neutral surface before its installation is published.
    #[must_use]
    pub fn with_tool_surface_validator(
        mut self,
        validator: Arc<dyn Fn(&[exomonad_tool::HostedTool]) -> Result<(), String> + Send + Sync>,
    ) -> Self {
        self.tool_surface_validator = Some(validator);
        self
    }

    pub(crate) fn installed_effect_support(&self) -> &[exomonad_tool::ToolEffectKey] {
        &self.installed_effect_support
    }

    /// Name the workspace-authored Haskell modules already compiled into
    /// every session and imported into every actor's preamble, so the doc
    /// catalog can list them beside the built-in topics. Absent for the
    /// operator workbench and tests, which have no `FrozenWorkspace`.
    #[must_use]
    pub fn with_workspace_modules(
        mut self,
        modules: impl IntoIterator<Item = impl Into<String>>,
    ) -> Self {
        self.workspace_modules = modules.into_iter().map(Into::into).collect();
        self
    }

    /// Preload the small quasiquoter vocabulary promised by a hosted
    /// workbench. Deployment selects this policy; the generic actor engine
    /// does not inspect input text or depend on an MCP-specific parser.
    #[must_use]
    pub fn with_default_quasiquoters(mut self) -> Self {
        self.workbench_imports
            .extend_text("Tidepool.QQ (fmt, j, patch, uri)");
        self
    }

    /// The import block every cell of this workbench compiles against, before
    /// a session view adds its own declaration and value modules. The compiler
    /// warm-up reads it so the graph it primes is the graph a cell reaches.
    #[must_use]
    pub fn workbench_import_text(&self) -> String {
        self.workbench_imports.template_text()
    }

    /// Additional shared imports must enter declaration compilation as well as
    /// expression templates, so bindings keep the same vocabulary after a fork.
    #[must_use]
    pub fn with_imports(mut self, imports: &str) -> Self {
        self.workbench_imports.extend_text(imports);
        self
    }

    /// Select the workspace's `[haskell] spec` value — rule two of spec
    /// discovery, for a workspace that wants a name other than
    /// `AgentSpec.agentSpec`. The installer owns its import; this selection
    /// does not expose the policy module to authored notebook cells.
    #[must_use]
    pub fn with_spec(mut self, entry: impl Into<Arc<str>>) -> Self {
        self.spec = Some(entry.into());
        self
    }

    /// [`Self::with_spec`] when the workspace named one, and nothing when it
    /// did not.
    #[must_use]
    pub fn with_spec_if(self, entry: Option<&str>) -> Self {
        match entry {
            Some(entry) => self.with_spec(entry),
            None => self,
        }
    }
}

/// One installed spec: the surface it declares, the retained value every call
/// and every slot is an application of, and the identity of this install.
pub(crate) struct ResidentWorkbenchTools {
    declarations: Arc<[exomonad_tool::HostedTool]>,
    pub(crate) endpoints: Vec<crate::tool_contract::AdmittedEndpoint>,
    pub(crate) dispatch: Arc<RootCustody>,
    /// Installer source roots belong to the installed implementation, not the
    /// actor's published declaration and value surface.
    _installation_scope: Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
    /// Exact source selection retained with a prepared candidate or installation.
    _source_original: Option<Arc<tidepool_toolchain::artifacts::PublishedSourceOriginalSelection>>,
    code: InstalledToolCode,
    pub(crate) after_tool: Option<crate::tool_contract::AfterToolEntry>,
    pub(crate) initial_context: Option<crate::tool_contract::InitialContextEntry>,
    dispatcher_effects: tidepool_runtime::session::HaskellTypeSource,
    /// Which install this record is, counting from one within this actor
    /// incarnation. A completed call names it, so a receipt says which record
    /// served the call and not merely which record is active now.
    pub(crate) install: u64,
}

/// A public application's receiver retains its source domain independently of tool reloads.
pub(crate) struct PreparedRequestReceiver {
    pub(crate) entry: RequestReceiverEntry,
    pub(crate) scope: Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
}

#[derive(Clone, Copy)]
enum ToolInstallationPurpose {
    InitialTools,
    RecoveredTools,
    CandidateTools,
    SpawnApplication,
    RequestReplyTools,
}

struct PreparedToolInstallation {
    tools: ResidentWorkbenchTools,
    receiver: Option<PreparedRequestReceiver>,
}

/// Code and values retained by the installation's real producer.
enum InstalledToolCode {
    SourcePrepared(Arc<crate::agent_spec::preparation::PreparedToolset>),
    ExplicitLive(Arc<RootCustody>),
}

impl InstalledToolCode {
    fn prepared(&self) -> Option<&Arc<crate::agent_spec::preparation::PreparedToolset>> {
        match self {
            Self::SourcePrepared(prepared) => Some(prepared),
            Self::ExplicitLive(_) => None,
        }
    }
}

/// Captured installer sent through the target actor's ordinary mailbox.
pub struct SpecReplacementDefinition {
    pub(crate) caller: crate::ActorRef,
    pub(crate) installer: RootCustody,
    pub(crate) session: tidepool_repr::SessionId,
    pub(crate) effects: Vec<crate::ActorEffectKey>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SpecReplacementError {
    Unavailable,
    Unauthorized,
    SurfaceChanged,
    Failed(String),
}

/// Persisted installation facts; decoding does not issue compiler custody.
#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PersistedActorInstallation {
    version: u32,
    source_sha256: [u8; 32],
    acquisition: crate::ToolsetAcquisition,
    entry: Option<String>,
    effects: String,
    declarations: Vec<exomonad_tool::HostedTool>,
    slots: Vec<String>,
}

#[derive(Debug, thiserror::Error)]
pub enum ActorInstallationRecoveryError {
    #[error("corrupt installation reference: {0}")]
    Corrupt(String),
    #[error("unsupported installation reference version {0}")]
    UnsupportedVersion(u32),
    #[error("installation reference has no completed original")]
    MissingOriginal,
    #[error("installation reference selects a different source artifact")]
    SourceMismatch,
    #[error("recovered installation differs from persisted {0}")]
    InstallationMismatch(&'static str),
}

impl PersistedActorInstallation {
    pub fn decode(
        reference: &tidepool_runtime::session::GenerationArtifactReference,
        source: &tidepool_runtime::session::GenerationArtifactReference,
    ) -> Result<Self, ActorInstallationRecoveryError> {
        reference
            .validate()
            .map_err(|error| ActorInstallationRecoveryError::Corrupt(error.to_string()))?;
        source
            .validate()
            .map_err(|error| ActorInstallationRecoveryError::Corrupt(error.to_string()))?;
        let installation: Self = serde_json::from_slice(reference.bytes())
            .map_err(|error| ActorInstallationRecoveryError::Corrupt(error.to_string()))?;
        if installation.version != 1 {
            return Err(ActorInstallationRecoveryError::UnsupportedVersion(
                installation.version,
            ));
        }
        if installation.source_sha256 != *source.sha256() {
            return Err(ActorInstallationRecoveryError::SourceMismatch);
        }
        if installation.acquisition.selection().is_none() {
            return Err(ActorInstallationRecoveryError::MissingOriginal);
        }
        Ok(installation)
    }
    pub fn acquisition(&self) -> &crate::ToolsetAcquisition {
        &self.acquisition
    }
    pub fn entry(&self) -> Option<&str> {
        self.entry.as_deref()
    }
    pub fn effects(&self) -> &str {
        &self.effects
    }
    pub fn declarations(&self) -> &[exomonad_tool::HostedTool] {
        &self.declarations
    }
    pub fn slots(&self) -> &[String] {
        &self.slots
    }

    fn capture(
        lease: &InstalledToolLease,
        source: &tidepool_runtime::session::GenerationArtifactReference,
    ) -> Result<Self, String> {
        let evidence = lease
            .source()
            .generation_evidence()
            .ok_or("source-backed generation has no complete retained artifact evidence")?;
        if &evidence.reference != source {
            return Err("installation and generation select different source artifacts".into());
        }
        let tools = lease
            .tools()
            .ok_or("generation has no native installation")?;
        let acquisition = lease
            .toolset_acquisition()
            .ok_or("generation has no compiler-issued installation acquisition")?;
        if acquisition.selection().is_none() {
            return Err("generation installer has no retained original for recovery".into());
        }
        Ok(Self {
            version: 1,
            source_sha256: *source.sha256(),
            acquisition: acquisition.clone(),
            entry: tools
                .resolved_spec()
                .and_then(|resolved| resolved.entry.clone()),
            effects: tools.dispatcher_effects.expression().to_owned(),
            declarations: tools.surface(),
            slots: tools.slots(),
        })
    }
    fn verify(
        &self,
        lease: &InstalledToolLease,
        source: &tidepool_runtime::session::GenerationArtifactReference,
    ) -> Result<(), ActorInstallationRecoveryError> {
        let recovered =
            Self::capture(lease, source).map_err(ActorInstallationRecoveryError::Corrupt)?;
        self.verify_facts(&recovered)
    }
    fn verify_facts(&self, actual: &Self) -> Result<(), ActorInstallationRecoveryError> {
        if self.acquisition.selection() != actual.acquisition.selection() {
            return Err(ActorInstallationRecoveryError::InstallationMismatch(
                "completed original",
            ));
        }
        if self.entry != actual.entry {
            return Err(ActorInstallationRecoveryError::InstallationMismatch(
                "entry",
            ));
        }
        if self.effects != actual.effects {
            return Err(ActorInstallationRecoveryError::InstallationMismatch(
                "effect row",
            ));
        }
        if self.declarations != actual.declarations {
            return Err(ActorInstallationRecoveryError::InstallationMismatch(
                "registered declarations",
            ));
        }
        if self.slots != actual.slots {
            return Err(ActorInstallationRecoveryError::InstallationMismatch(
                "slots",
            ));
        }
        Ok(())
    }
}

#[cfg(test)]
mod installation_reference_tests {
    use super::*;
    use tidepool_runtime::session::GenerationArtifactReference;

    #[test]
    fn decoded_installation_checks_version_source_and_completed_selection() {
        let source = GenerationArtifactReference::capture(b"source graph".to_vec());
        let installation = PersistedActorInstallation {
            version: 1,
            source_sha256: *source.sha256(),
            acquisition: crate::ToolsetAcquisition::FreshRunOriginal {
                recipe: "recipe".into(),
                original: uuid::Uuid::new_v4(),
            },
            entry: Some("Spec.agentSpec".into()),
            effects: "ActorEffects".into(),
            declarations: vec![],
            slots: vec!["haskell".into()],
        };
        let reference =
            GenerationArtifactReference::capture(serde_json::to_vec(&installation).unwrap());
        assert_eq!(
            PersistedActorInstallation::decode(&reference, &source).unwrap(),
            installation
        );
        let corrupt = GenerationArtifactReference::capture(b"broken json".to_vec());
        assert!(matches!(
            PersistedActorInstallation::decode(&corrupt, &source),
            Err(ActorInstallationRecoveryError::Corrupt(_))
        ));
        let another = GenerationArtifactReference::capture(b"another graph".to_vec());
        assert!(matches!(
            PersistedActorInstallation::decode(&reference, &another),
            Err(ActorInstallationRecoveryError::SourceMismatch)
        ));
        let mut unsupported = installation.clone();
        unsupported.version = 2;
        let reference =
            GenerationArtifactReference::capture(serde_json::to_vec(&unsupported).unwrap());
        assert!(matches!(
            PersistedActorInstallation::decode(&reference, &source),
            Err(ActorInstallationRecoveryError::UnsupportedVersion(2))
        ));
        let mut missing = installation.clone();
        missing.acquisition = crate::ToolsetAcquisition::UnretainedCompilation {
            recipe: "recipe".into(),
        };
        let reference = GenerationArtifactReference::capture(serde_json::to_vec(&missing).unwrap());
        assert!(matches!(
            PersistedActorInstallation::decode(&reference, &source),
            Err(ActorInstallationRecoveryError::MissingOriginal)
        ));
        let mut restored = installation.clone();
        let (recipe, original) = installation
            .acquisition
            .completed_entry_selection()
            .unwrap();
        restored.acquisition = crate::ToolsetAcquisition::ExistingRunOriginal {
            recipe: recipe.into(),
            original,
        };
        assert!(installation.verify_facts(&restored).is_ok());
        restored.slots.push("different".into());
        assert!(matches!(
            installation.verify_facts(&restored),
            Err(ActorInstallationRecoveryError::InstallationMismatch(
                "slots"
            ))
        ));
        restored = installation.clone();
        restored.acquisition = crate::ToolsetAcquisition::ExistingRunOriginal {
            recipe: recipe.into(),
            original: uuid::Uuid::new_v4(),
        };
        assert!(matches!(
            installation.verify_facts(&restored),
            Err(ActorInstallationRecoveryError::InstallationMismatch(
                "completed original"
            ))
        ));
    }
}

/// Authority over one actor's installed handler and immutable source revision.
/// The handler root remains live while an issued request retains this value.
#[derive(Clone)]
pub struct InstalledToolLease {
    actor: crate::ActorRef,
    source: crate::CheckpointSourceLayer,
    tools: Option<Arc<ResidentWorkbenchTools>>,
    dependency: generation_admission::SourceDependency,
}

/// An exact endpoint selected from one retained installation. Cloning preserves
/// the original implementation even after the active installation is replaced.
#[derive(Clone)]
pub(crate) struct InstalledToolSelection {
    pub(crate) reply_activation: Option<Arc<crate::RequestReplyActivation>>,
    snapshot: ActorRequestSnapshot,
    index: usize,
}

impl InstalledToolSelection {
    pub(crate) fn lease(&self) -> &InstalledToolLease {
        self.snapshot.installation()
    }
    pub(crate) fn snapshot(&self) -> &ActorRequestSnapshot {
        &self.snapshot
    }
    pub(crate) fn entry_index(&self) -> i64 {
        (self.index + 3) as i64
    }
    pub(crate) fn endpoint(&self) -> &crate::tool_contract::AdmittedEndpoint {
        &self
            .lease()
            .tools
            .as_ref()
            .expect("selection retains installation")
            .endpoints[self.index]
    }
    pub(crate) fn admit(
        self,
        arguments: exomonad_tool::ToolArguments,
    ) -> Result<AdmittedToolCall, crate::ResidentToolError> {
        let arguments = match (&self.reply_activation, arguments) {
            (Some(activation), exomonad_tool::ToolArguments::Structured(wire)) => {
                activation.admit_wire_arguments(wire)?.into_arguments()
            }
            (Some(_), _) => {
                return Err(crate::ResidentToolError::InvalidInvocation(
                    "reply endpoint requires structured provider wire arguments".into(),
                ))
            }
            (None, arguments) => arguments,
        };
        let arguments = self.endpoint().plan().admit_arguments(arguments)?;
        Ok(AdmittedToolCall {
            selected: self,
            arguments,
        })
    }
}

/// Invocation arguments and their issuing endpoint selection travel together.
pub(crate) struct AdmittedToolCall {
    selected: InstalledToolSelection,
    arguments: exomonad_tool::EndpointArguments,
}

impl AdmittedToolCall {
    pub(crate) fn selected(&self) -> &InstalledToolSelection {
        &self.selected
    }

    pub(crate) fn request(&self) -> WorkbenchRequest {
        match &self.arguments {
            exomonad_tool::EndpointArguments::Resident(arguments) => WorkbenchRequest::for_tool(
                self.selected.endpoint().plan().name().into(),
                arguments.clone(),
            ),
            exomonad_tool::EndpointArguments::Haskell(source) => {
                WorkbenchRequest::from_cell_input(source)
            }
        }
    }
}

/// One admitted after-tool slot, retaining its exact actor, source and implementation.
pub(crate) struct InstalledAfterTool {
    actor: crate::ActorRef,
    _source: crate::CheckpointSourceLayer,
    tools: Arc<ResidentWorkbenchTools>,
}

impl InstalledAfterTool {
    pub(crate) fn entry(&self) -> &crate::tool_contract::AfterToolEntry {
        self.tools
            .after_tool
            .as_ref()
            .expect("issued after-tool selection retains its admitted entry")
    }

    pub(crate) fn actor(&self) -> crate::ActorRef {
        self.actor
    }

    pub(crate) fn tools(&self) -> &ResidentWorkbenchTools {
        &self.tools
    }
}

impl InstalledToolLease {
    /// A transferred source callback may inspect its retained inputs, but it
    /// carries no destination AgentSpec or notebook publication authority.
    pub(crate) fn source_callback_custody(
        actor: crate::ActorRef,
        source: crate::CheckpointSourceLayer,
        dependency: generation_admission::SourceDependency,
    ) -> Self {
        Self {
            actor,
            source,
            tools: None,
            dependency,
        }
    }

    pub(crate) fn new(
        actor: crate::ActorRef,
        source: crate::CheckpointSourceLayer,
        tools: Option<Arc<ResidentWorkbenchTools>>,
    ) -> Self {
        Self {
            actor,
            source,
            tools,
            dependency: generation_admission::SourceDependency::Unqualified,
        }
    }

    pub(crate) fn actor(&self) -> crate::ActorRef {
        self.actor
    }

    pub(crate) fn source_dependency(&self) -> &generation_admission::SourceDependency {
        &self.dependency
    }

    pub(crate) fn with_source_dependency(
        mut self,
        dependency: &generation_admission::SourceDependency,
    ) -> Self {
        self.dependency = dependency.clone();
        self
    }

    pub(crate) fn source(&self) -> &crate::CheckpointSourceLayer {
        &self.source
    }

    pub(crate) fn tools(&self) -> Option<&ResidentWorkbenchTools> {
        self.tools.as_deref()
    }

    #[must_use]
    pub fn toolset_acquisition(&self) -> Option<&crate::ToolsetAcquisition> {
        self.tools
            .as_ref()
            .and_then(|tools| tools.code.prepared().map(|prepared| &prepared.acquisition))
    }

    pub(crate) fn tools_arc(&self) -> Option<Arc<ResidentWorkbenchTools>> {
        self.tools.clone()
    }

    pub(crate) fn select(&self, name: &str) -> Option<InstalledToolSelection> {
        let index = self
            .tools
            .as_ref()?
            .endpoints
            .iter()
            .position(|endpoint| endpoint.plan().name() == name)?;
        Some(InstalledToolSelection {
            reply_activation: None,
            snapshot: ActorRequestSnapshot::Bootstrap(self.clone()),
            index,
        })
    }

    pub(crate) fn after_tool(&self) -> Option<InstalledAfterTool> {
        let tools = self.tools.clone()?;
        tools.after_tool.as_ref()?;
        Some(InstalledAfterTool {
            actor: self.actor,
            _source: self.source.clone(),
            tools,
        })
    }

    fn same_installation(&self, expected: &Self) -> bool {
        self.actor() == expected.actor()
            && self.source().same_revision(expected.source())
            && match (&self.tools, &expected.tools) {
                (Some(active), Some(expected)) => Arc::ptr_eq(active, expected),
                (None, None) => true,
                _ => false,
            }
    }

    fn observe_generation(self) -> Result<ObservedInstallation, String> {
        let evidence = self
            .source()
            .generation_evidence()
            .ok_or("generation preparation has no issued source evidence")?;
        let source = evidence.reference.clone();
        let configuration_digest = evidence.configuration_digest;
        let facts = PersistedActorInstallation::capture(&self, &source)?;
        source.validate().map_err(|error| {
            ActorInstallationRecoveryError::Corrupt(error.to_string()).to_string()
        })?;
        Ok(ObservedInstallation {
            lease: self,
            source,
            facts,
            configuration_digest,
            #[cfg(test)]
            work: InstallationObservationWork {
                captures: 1,
                ..Default::default()
            },
        })
    }

    pub(crate) fn verify_recovered_generation(
        &self,
        references: &tidepool_runtime::session::DurableGenerationReferences,
    ) -> Result<(), ActorInstallationRecoveryError> {
        let installation =
            PersistedActorInstallation::decode(&references.installation, &references.source)?;
        installation.verify(self, &references.source)
    }
}

#[cfg(test)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct InstallationObservationWork {
    // Successful owner observations, not a census of all capture API calls.
    captures: usize,
    encodings: usize,
    restored_decodes: usize,
}

/// Installation facts derived from this exact retained lease. Durable encoding
/// is a projection for a new stored generation, not preparation authority.
struct ObservedInstallation {
    lease: InstalledToolLease,
    source: tidepool_runtime::session::GenerationArtifactReference,
    facts: PersistedActorInstallation,
    configuration_digest: [u8; 32],
    #[cfg(test)]
    work: InstallationObservationWork,
}

impl ObservedInstallation {
    fn into_durable_references(
        self,
        prompts: tidepool_runtime::session::ComposedPromptSnapshot,
    ) -> Result<EncodedInstallation, String> {
        #[cfg(test)]
        let work = InstallationObservationWork {
            encodings: self.work.encodings + 1,
            ..self.work
        };
        let bytes = serde_json::to_vec(&self.facts).map_err(|error| error.to_string())?;
        Ok(EncodedInstallation {
            lease: self.lease,
            references: tidepool_runtime::session::DurableGenerationReferences {
                source: self.source,
                installation: tidepool_runtime::session::GenerationArtifactReference::capture(
                    bytes,
                ),
                prompts,
            },
            #[cfg(test)]
            work,
        })
    }

    fn verify_restored(
        &mut self,
        references: &tidepool_runtime::session::DurableGenerationReferences,
        prompts: &tidepool_runtime::session::ComposedPromptSnapshot,
    ) -> Result<(), String> {
        references.validate().map_err(|error| error.to_string())?;
        if self.source != references.source || prompts != &references.prompts {
            return Err("restored generation must retain its source and prompt references".into());
        }
        #[cfg(test)]
        {
            self.work.restored_decodes += 1;
        }
        let persisted =
            PersistedActorInstallation::decode(&references.installation, &references.source)
                .map_err(|error| error.to_string())?;
        persisted
            .verify_facts(&self.facts)
            .map_err(|error| error.to_string())
    }
}

/// Consuming durable projection of the same observed lease and source bytes.
struct EncodedInstallation {
    lease: InstalledToolLease,
    references: tidepool_runtime::session::DurableGenerationReferences,
    #[cfg(test)]
    work: InstallationObservationWork,
}

