/// The reservation owns its frozen candidate and the sole publication guard.
#[must_use]
pub(crate) struct ReservedActorGeneration {
    prepared: PreparedActorGeneration,
    guard: ActorPublicationGuard,
    publication_kind: ActorGenerationPublication,
}

/// Serial publication custody. The executor never receives this owner.
#[must_use]
pub(crate) struct ActorGenerationPublicationOwner {
    guard: ActorPublicationGuard,
    prepared: Option<PreparedActorGeneration>,
    publication_kind: ActorGenerationPublication,
    body: Option<RecordedPublicationBody>,
    settlement: PublicationOwnerSettlement,
}

/// One-use execution rights for the same reserved candidate. No source fence or
/// unpublished-scope cleanup authority crosses the worker boundary.
#[must_use]
pub(crate) struct ActorGenerationPublicationBody {
    prepared: PreparedActorGeneration,
    visibility: ActorPublicationVisibility,
    decision: Arc<tidepool_runtime::session::PublicationDecision>,
    publication_kind: ActorGenerationPublication,
}

/// Body visibility is not confirmed publication. Only the retained serial owner
/// may turn this observation into a settled publication and notify its caller.
#[must_use]
pub(crate) struct ActorGenerationPublicationBodyResult {
    attempt: ActorPublicationAttemptObserver,
    completion: ActorGenerationPublicationBodyCompletion,
}

impl ActorGenerationPublicationBodyResult {
    pub(crate) fn completion(&self) -> &ActorGenerationPublicationBodyCompletion {
        &self.completion
    }
}

pub(crate) enum ActorGenerationPublicationBodyCompletion {
    Observed {
        outcome: Result<ActorGenerationBodyOutcome, ResidentActorWorkbenchError>,
        obligations: PublicationBodyObligations,
    },
    Unobserved {
        primary: ResidentActorWorkbenchError,
    },
}

/// Visibility alone cannot be passed to a lifecycle notification.
pub(crate) enum ActorGenerationBodyOutcome {
    Visible {
        generation: Arc<ActorGeneration>,
        cancellation_pending: bool,
    },
    Refused(ActorGenerationPublicationIssue),
    Unconfirmed(ActorGenerationPublicationIssue),
}

enum RecordedPublicationBody {
    Visible {
        generation: Arc<ActorGeneration>,
        cancellation_pending: bool,
    },
    Failure {
        outcome: Arc<Result<ActorGenerationCommit, ResidentActorWorkbenchError>>,
        obligations: PublicationBodyObligations,
    },
    Unobserved {
        primary: Arc<ResidentActorWorkbenchError>,
    },
}

pub(crate) enum PublicationOwnerSettlement {
    Pending,
    Confirming,
    Confirmed,
    Restoring,
    Restored,
    Failed(Arc<PublicationSettlementError>),
}

impl ActorGenerationPublicationOwner {
    pub(crate) fn take_body(
        &mut self,
    ) -> Result<ActorGenerationPublicationBody, Arc<PublicationSettlementError>> {
        if !matches!(self.settlement, PublicationOwnerSettlement::Pending)
            || self.prepared.is_none()
        {
            return Err(self
                .settlement_error()
                .cloned()
                .unwrap_or_else(|| Arc::new(PublicationSettlementError::ReopenAttempted)));
        }
        // Failed visibility admission remains in this same owner. A caller
        // cannot turn a generic dispatch refusal into retry authority.
        let visibility = match self.guard.visibility() {
            Ok(visibility) => visibility,
            Err(error) => {
                let error = Arc::new(error);
                self.settlement = PublicationOwnerSettlement::Failed(error.clone());
                return Err(error);
            }
        };
        let prepared = self
            .prepared
            .take()
            .ok_or_else(|| Arc::new(PublicationSettlementError::ReopenAttempted))?;
        Ok(ActorGenerationPublicationBody {
            prepared,
            visibility,
            decision: self.guard.decision.clone(),
            publication_kind: self.publication_kind,
        })
    }

    pub(crate) fn record_body(
        &mut self,
        body: ActorGenerationPublicationBodyResult,
    ) -> Result<(), ActorGenerationPublicationBodyResult> {
        if self.body.is_some()
            || self.prepared.is_some()
            || !Arc::ptr_eq(&self.guard.attempt, &body.attempt.0)
        {
            return Err(body);
        }
        self.body = Some(match body.completion {
            ActorGenerationPublicationBodyCompletion::Observed {
                outcome:
                    Ok(ActorGenerationBodyOutcome::Visible {
                        generation,
                        cancellation_pending,
                    }),
                ..
            } => RecordedPublicationBody::Visible {
                generation,
                cancellation_pending,
            },
            ActorGenerationPublicationBodyCompletion::Observed {
                outcome,
                obligations,
            } => {
                let outcome = outcome.map(|outcome| match outcome {
                    ActorGenerationBodyOutcome::Refused(issue) => {
                        ActorGenerationCommit::Refused(issue)
                    }
                    ActorGenerationBodyOutcome::Unconfirmed(issue) => {
                        ActorGenerationCommit::Unconfirmed(issue)
                    }
                    ActorGenerationBodyOutcome::Visible { .. } => unreachable!("handled above"),
                });
                RecordedPublicationBody::Failure {
                    outcome: Arc::new(outcome),
                    obligations,
                }
            }
            ActorGenerationPublicationBodyCompletion::Unobserved { primary } => {
                RecordedPublicationBody::Unobserved {
                    primary: Arc::new(primary),
                }
            }
        });
        Ok(())
    }

    pub(crate) fn return_unstarted(
        &mut self,
        body: ActorGenerationPublicationBody,
    ) -> Result<(), ActorGenerationPublicationBody> {
        if self.prepared.is_some()
            || self.body.is_some()
            || !matches!(self.settlement, PublicationOwnerSettlement::Pending)
            || !Arc::ptr_eq(&self.guard.attempt, &body.visibility.attempt)
            || !Arc::ptr_eq(&self.guard.state, &body.visibility.state)
        {
            return Err(body);
        }
        self.prepared = Some(body.prepared);
        Ok(())
    }

    pub(crate) fn settlement(&self) -> &PublicationOwnerSettlement {
        &self.settlement
    }

    pub(crate) fn settlement_error(&self) -> Option<&Arc<PublicationSettlementError>> {
        match &self.settlement {
            PublicationOwnerSettlement::Failed(error) => Some(error),
            _ => None,
        }
    }

    pub(crate) fn source_restored(&self) -> bool {
        matches!(self.settlement, PublicationOwnerSettlement::Restored)
    }

    pub(crate) fn settled_obligations(&self) -> bool {
        self.source_restored()
            && (self.prepared.is_some()
                || matches!(
                    self.body,
                    Some(RecordedPublicationBody::Failure {
                        obligations: PublicationBodyObligations::DiagnosticOnly,
                        ..
                    })
                ))
    }

    pub(crate) fn failure_outcome(
        &self,
    ) -> Option<&Arc<Result<ActorGenerationCommit, ResidentActorWorkbenchError>>> {
        match &self.body {
            Some(RecordedPublicationBody::Failure { outcome, .. }) => Some(outcome),
            _ => None,
        }
    }

    pub(crate) fn unobserved_primary(&self) -> Option<&ResidentActorWorkbenchError> {
        match &self.body {
            Some(RecordedPublicationBody::Unobserved { primary }) => Some(primary),
            _ => None,
        }
    }

    pub(crate) fn diagnostic_outcome(
        &self,
    ) -> Option<(
        &Result<ActorGenerationCommit, ResidentActorWorkbenchError>,
        ActorGenerationPublicationRefusalObservation,
    )> {
        let RecordedPublicationBody::Failure { outcome, .. } = self.body.as_ref()? else {
            return None;
        };
        publication_failure_observation(outcome).map(|observation| (outcome.as_ref(), observation))
    }

    pub(crate) fn confirm(&mut self) -> &PublicationOwnerSettlement {
        if !matches!(self.settlement, PublicationOwnerSettlement::Pending) {
            return &self.settlement;
        }
        if !matches!(
            self.body.as_ref(),
            Some(RecordedPublicationBody::Visible { .. })
        ) {
            return &self.settlement;
        }
        // Record before entering callbacks. Unwind leaves both the exact guard
        // and its consumed fence phase in the original serial owner.
        self.settlement = PublicationOwnerSettlement::Confirming;
        self.settlement = match self.guard.confirmed() {
            Ok(()) => PublicationOwnerSettlement::Confirmed,
            Err(error) => PublicationOwnerSettlement::Failed(Arc::new(error)),
        };
        &self.settlement
    }

    pub(crate) fn confirmed_generation(&self) -> Option<(&Arc<ActorGeneration>, bool)> {
        if !matches!(self.settlement, PublicationOwnerSettlement::Confirmed) {
            return None;
        }
        match self.body.as_ref()? {
            RecordedPublicationBody::Visible {
                generation,
                cancellation_pending,
            } => Some((generation, *cancellation_pending)),
            _ => None,
        }
    }

    pub(crate) fn refuse_initial(&mut self) -> &PublicationOwnerSettlement {
        if !matches!(self.settlement, PublicationOwnerSettlement::Pending)
            || !matches!(
                self.guard.attempt.expected,
                ActorRequestSnapshot::Bootstrap(_)
            )
        {
            return &self.settlement;
        }
        let known_unpublished = match &self.body {
            Some(RecordedPublicationBody::Failure { outcome, .. }) => {
                self.guard.known_unpublished(outcome)
            }
            Some(
                RecordedPublicationBody::Visible { .. }
                | RecordedPublicationBody::Unobserved { .. },
            ) => false,
            None => self.prepared.is_some(),
        };
        if !known_unpublished {
            return &self.settlement;
        }
        self.settlement = PublicationOwnerSettlement::Restoring;
        self.settlement = match self.guard.refuse_unstarted() {
            Ok(()) => PublicationOwnerSettlement::Restored,
            Err(error) => PublicationOwnerSettlement::Failed(Arc::new(error)),
        };
        &self.settlement
    }

    pub(crate) fn refuse_retirement(
        &mut self,
        original: &mut generation_admission::GenerationRetirementFence,
    ) -> &PublicationOwnerSettlement {
        if !matches!(self.settlement, PublicationOwnerSettlement::Pending) {
            return &self.settlement;
        }
        let known_unpublished = match &self.body {
            Some(RecordedPublicationBody::Failure { outcome, .. }) => {
                self.guard.known_unpublished(outcome)
            }
            Some(
                RecordedPublicationBody::Visible { .. }
                | RecordedPublicationBody::Unobserved { .. },
            ) => false,
            None => self.prepared.is_some(),
        };
        if !known_unpublished {
            return &self.settlement;
        }
        self.settlement = PublicationOwnerSettlement::Restoring;
        self.settlement = match self.guard.refuse_retirement(original) {
            Ok(()) => PublicationOwnerSettlement::Restored,
            Err(error) => PublicationOwnerSettlement::Failed(Arc::new(error)),
        };
        &self.settlement
    }
}

/// Witnesses this reservation's actual B-then-A refusal transition. It grants
/// no authority and says nothing about compiler, storage, or physical cleanup.
#[must_use]
pub(crate) struct UnstartedRetirementSourceSettlement {
    attempt: std::sync::Weak<ActorPublicationAttempt>,
}

pub(crate) enum ActorGenerationReservation {
    Reserved(ReservedActorGeneration),
    Refused(String),
}

pub(crate) enum ActorGenerationRetirementCutoff {
    Fenced(generation_admission::GenerationRetirementFence),
    Refused(ResidentActorWorkbenchError),
    Unconfirmed {
        fence: generation_admission::GenerationRetirementFence,
        error: ResidentActorWorkbenchError,
    },
}

impl ReservedActorGeneration {
    pub(crate) fn into_publication_owner(self) -> ActorGenerationPublicationOwner {
        let Self {
            prepared,
            guard,
            publication_kind,
        } = self;
        ActorGenerationPublicationOwner {
            guard,
            prepared: Some(prepared),
            publication_kind,
            body: None,
            settlement: PublicationOwnerSettlement::Pending,
        }
    }

    pub(crate) fn candidate_custody(&self) -> ActorGenerationCandidateCustody {
        ActorGenerationCandidateCustody(self.prepared.candidate.clone())
    }

    pub(crate) fn publication_phase(&self) -> tidepool_runtime::session::PublicationPhase {
        self.guard.decision.phase()
    }

    pub(crate) fn attempt_observer(&self) -> ActorPublicationAttemptObserver {
        ActorPublicationAttemptObserver(self.guard.attempt.clone())
    }

    pub(crate) fn expected_generation(&self) -> Option<&Arc<ActorGeneration>> {
        self.guard.attempt.expected.generation()
    }

    pub(crate) fn reload_report(&self) -> Option<&PreparedReloadReport> {
        self.prepared.reload_report()
    }

    pub(crate) fn fence_original(&mut self) -> ActorGenerationRetirementCutoff {
        self.guard.fence_original()
    }

    pub(crate) fn refuse_unstarted(
        &mut self,
        detail: &str,
    ) -> Result<(), ResidentActorWorkbenchError> {
        self.guard.refuse_unstarted().map_err(|settlement| {
            ResidentActorWorkbenchError::PublicationSettlement {
                failure: Box::new(ActorPublicationSettlementFailure {
                    outcome: Arc::new(Ok(ActorGenerationCommit::Refused(detail.to_owned().into()))),
                    settlement,
                }),
            }
        })
    }

    pub(crate) fn refuse_retirement(
        &mut self,
        original: &mut generation_admission::GenerationRetirementFence,
        detail: &str,
    ) -> Result<UnstartedRetirementSourceSettlement, ResidentActorWorkbenchError> {
        self.guard
            .refuse_retirement(original)
            .map(|()| UnstartedRetirementSourceSettlement {
                attempt: Arc::downgrade(&self.guard.attempt),
            })
            .map_err(
                |settlement| ResidentActorWorkbenchError::PublicationSettlement {
                    failure: Box::new(ActorPublicationSettlementFailure {
                        outcome: Arc::new(Ok(ActorGenerationCommit::Refused(
                            detail.to_owned().into(),
                        ))),
                        settlement,
                    }),
                },
            )
    }

    /// Consumes the same never-executed reservation and its source settlement.
    /// The retirement record retains candidate and physical custody separately.
    pub(crate) fn into_settled_unstarted(
        self,
        settlement: UnstartedRetirementSourceSettlement,
    ) -> Result<(), (Self, UnstartedRetirementSourceSettlement)> {
        if matches!(self.guard.settlement, ActorPublicationState::Settled)
            && settlement
                .attempt
                .ptr_eq(&Arc::downgrade(&self.guard.attempt))
        {
            Ok(())
        } else {
            Err((self, settlement))
        }
    }
}

/// Prospective durable facts retained only when initial publication is unknown.
/// This has no bound public owner and is never an installed generation.
struct InitialPublicationCandidate {
    installation: InstalledToolLease,
    context: crate::ActorSessionContext,
    scope: Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
    prompts: tidepool_runtime::session::ComposedPromptSnapshot,
    configuration_digest: [u8; 32],
    selected: tidepool_runtime::session::ActiveNotebookGeneration,
    public_owner: crate::resident_actor::PreparedWorkbenchGenerationOwner,
}

struct UnconfirmedInitialPublication {
    previous: InstalledToolLease,
    candidate: InitialPublicationCandidate,
}

impl InitialPublicationCandidate {
    fn visible(
        self,
        readiness: Arc<tidepool_runtime::session::RuntimeDurablePublicReadiness>,
    ) -> Arc<ActorGeneration> {
        Arc::new(ActorGeneration {
            id: self.selected.generation(),
            installation: self.installation,
            prompts: self.prompts,
            context: self.context,
            scope: self.scope,
            configuration_digest: self.configuration_digest,
            durable: Some(self.selected),
            public_owner: self.public_owner.bind(Some(readiness)),
        })
    }
}

fn retain_unconfirmed_generation(
    current: &mut InstalledToolsAvailability,
    previous: Option<&InstalledToolLease>,
    candidate: &mut Option<InitialPublicationCandidate>,
) {
    match current {
        InstalledToolsAvailability::Generation(generation) => {
            *current = InstalledToolsAvailability::GenerationUnavailable(generation.clone());
        }
        InstalledToolsAvailability::PublicationVisible { generation, .. } => {
            *current = InstalledToolsAvailability::GenerationUnavailable(generation.clone());
        }
        InstalledToolsAvailability::PublicationInProgress(_)
        | InstalledToolsAvailability::PublicationUnavailable(_) => {
            if let (Some(previous), Some(candidate)) = (previous, candidate.take()) {
                *current = InstalledToolsAvailability::InitialPublicationUnconfirmed(Box::new(
                    UnconfirmedInitialPublication {
                        previous: previous.clone(),
                        candidate,
                    },
                ));
            }
        }
        _ => {}
    }
}

/// The existing actor issuance fence and machine owner, with no source issuer.
pub(crate) struct ActorGenerationPublisher<H, O> {
    access: ResidentMachineAccess<H, O>,
    state: Arc<InstalledToolsState>,
    owner: ActorPublicationOwner,
    #[cfg(test)]
    settlement_probe: Option<Arc<PublicationSettlementProbe>>,
    #[cfg(test)]
    disposal_probe: Option<PublicationDisposalProbe>,
}

#[cfg(test)]
struct PublicationDisposalProbe {
    disposed: Arc<std::sync::atomic::AtomicBool>,
}

#[cfg(test)]
impl Drop for PublicationDisposalProbe {
    fn drop(&mut self) {
        self.disposed
            .store(true, std::sync::atomic::Ordering::Release);
        panic!("controlled publication disposer panic");
    }
}

type GenerationPublicationAction = Box<
    dyn FnOnce(
            ActorGenerationPublicationBody,
        )
            -> futures_util::future::BoxFuture<'static, ActorGenerationPublicationBodyResult>
        + Send,
>;

type GenerationReservationAction =
    Box<dyn FnOnce(PreparedActorGeneration) -> ActorGenerationRetirementPreparationOutcome + Send>;

/// The real publisher and its single frozen candidate cross into RunState
/// before reservation changes either source admission or installed state.
#[must_use]
pub(crate) struct ActorGenerationRetirementPreparation {
    prepared: PreparedActorGeneration,
    driver: ActorGenerationReservationDriver,
}

pub(crate) enum ActorGenerationRetirementPreparationOutcome {
    Reserved {
        reserved: ReservedActorGeneration,
        publisher: ActorGenerationPublicationDriver,
    },
    Refused(String),
    Failed(ResidentActorWorkbenchError),
}

impl ActorGenerationRetirementPreparation {
    pub(crate) fn is_initial(&self) -> bool {
        matches!(self.prepared.expected, ActorRequestSnapshot::Bootstrap(_))
    }

    pub(crate) fn actor(&self) -> crate::ActorRef {
        self.prepared.candidate.context.actor
    }

    pub(crate) fn candidate_custody(&self) -> ActorGenerationCandidateCustody {
        ActorGenerationCandidateCustody(self.prepared.candidate.clone())
    }

    pub(crate) fn reload_report(&self) -> Option<&PreparedReloadReport> {
        self.prepared.reload_report()
    }

    pub(crate) fn expected_generation(&self) -> Option<&Arc<ActorGeneration>> {
        self.prepared.expected.generation()
    }

    pub(crate) fn matches_execution_control(
        &self,
        control: Option<&Arc<crate::WorkbenchExecutionControl>>,
    ) -> bool {
        match (self.driver.publication_kind, control) {
            (ActorGenerationPublication::Terminal, None) => true,
            (ActorGenerationPublication::Continuing, Some(control)) => {
                Arc::ptr_eq(&self.driver.decision, &control.publication_decision())
            }
            _ => false,
        }
    }

    /// The serial owner retains the affine preparation before invoking its
    /// transient driver. Dropping that driver cannot drop the preparation.
    pub(crate) fn into_parts(self) -> (PreparedActorGeneration, ActorGenerationReservationDriver) {
        let Self { prepared, driver } = self;
        (prepared, driver)
    }
}

/// Executable endpoints are separate from the retained affine state. Their
/// private issuer binds each endpoint to the same immutable candidate.
#[must_use]
pub(crate) struct ActorGenerationReservationDriver {
    candidate: std::sync::Weak<ActorGenerationCandidate>,
    decision: Arc<tidepool_runtime::session::PublicationDecision>,
    publication_kind: ActorGenerationPublication,
    reserve: GenerationReservationAction,
}

impl ActorGenerationReservationDriver {
    pub(crate) fn reserve(
        self,
        prepared: PreparedActorGeneration,
    ) -> Result<ActorGenerationRetirementPreparationOutcome, (PreparedActorGeneration, Self)> {
        if !self.candidate.ptr_eq(&Arc::downgrade(&prepared.candidate)) {
            return Err((prepared, self));
        }
        Ok((self.reserve)(prepared))
    }
}

#[must_use]
pub(crate) struct ActorGenerationPublicationDriver {
    candidate: std::sync::Weak<ActorGenerationCandidate>,
    attempt: ActorPublicationAttemptObserver,
    publish: GenerationPublicationAction,
}

impl ActorGenerationPublicationDriver {
    pub(crate) async fn run(
        self,
        body: ActorGenerationPublicationBody,
    ) -> Result<ActorGenerationPublicationBodyResult, (ActorGenerationPublicationBody, Self)> {
        if !self
            .candidate
            .ptr_eq(&Arc::downgrade(&body.prepared.candidate))
            || !Arc::ptr_eq(&self.attempt.0, &body.visibility.attempt)
        {
            return Err((body, self));
        }
        Ok((self.publish)(body).await)
    }
}

/// The observed outcome carries no settlement authority. Only `Unpublished`
/// retains the original armed guard needed to restore a held retirement fence.
#[must_use]
#[cfg(test)]
pub(crate) enum ActorGenerationPublicationSettlement {
    Unpublished(ActorGenerationPublicationRefusal),
    Settled(Arc<Result<ActorGenerationCommit, ResidentActorWorkbenchError>>),
}

#[cfg(test)]
impl ActorGenerationPublicationSettlement {
    pub(crate) fn diagnostic_outcome(
        &self,
    ) -> Option<(
        &Result<ActorGenerationCommit, ResidentActorWorkbenchError>,
        ActorGenerationPublicationRefusalObservation,
    )> {
        let outcome = match self {
            Self::Unpublished(refusal) => refusal.outcome(),
            Self::Settled(outcome) => outcome,
        };
        publication_failure_observation(outcome).map(|observation| (outcome.as_ref(), observation))
    }
}

/// Causal metadata only: no source leases, compiler products, or error Arcs.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum ActorGenerationPublicationRefusalObservation {
    Refused,
    Failed {
        cause: ActorPublicationFailureCause,
        execution: Option<tidepool_runtime::session::PreparedFailureKind>,
        requires_recovery: bool,
    },
}

impl ActorGenerationPublicationRefusalObservation {
    pub(crate) fn requires_recovery(&self) -> bool {
        matches!(
            self,
            Self::Failed {
                requires_recovery: true,
                ..
            }
        )
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum ActorPublicationFailureCause {
    SourceAdmission(tidepool_runtime::session::SourceAdmissionError),
    OperationDiagnostic(crate::WorkbenchDiagnosticRefusal),
    Io(std::io::ErrorKind),
    RecoveryStore(tidepool_runtime::session::StoreErrorKind),
    RecoveryStoreRefused,
    RequestAdmission,
    ToolSurface,
    Directory,
    CleanupOwnerUnavailable,
    CleanupAdmissionClosed,
    ContinuationHandoff,
    ActorRetired,
    InvocationCancelled,
    CompileView,
    Checkout,
    Compilation,
    WorldInspection,
    CellCheck,
    CompileInfrastructure,
    PreparedEntryAbsent,
    PublicationSettlement,
    Resident,
    Delivered,
    MachineLost,
    NativeTaskCancelled,
    NativeTaskPanicked,
    InputCompilation,
    RendererProduction,
    RendererAdmission,
    InputMount,
    ActivationPreviewSuspended,
    Inspection,
    InspectionScopeChanged,
    InspectionWorldUnavailable,
    InspectionWorldRejected(tidepool_toolchain::compiler_world::WorldQueryRejection),
    CompletedResultObservation,
    InterpreterSupport,
    ActorProtocol,
    PublicOwner,
    Kernel,
    ToolDeclaration,
    UnsupportedRequest,
    RequestDecode,
    Bridge,
    InteractiveSessionCapture,
    StartCapture,
    WaitCapture,
    ToolDispatch,
    ToolDeclarations,
}

#[must_use]
#[cfg(test)]
pub(crate) struct ActorGenerationPublicationRefusal {
    guard: ActorPublicationGuard,
    outcome: Arc<Result<ActorGenerationCommit, ResidentActorWorkbenchError>>,
    obligations: PublicationBodyObligations,
}

/// Issued by the observed body before any durable publication work starts.
/// Source restoration and diagnostic recording do not settle unassessed work.
pub(crate) enum PublicationBodyObligations {
    DiagnosticOnly,
    Retained,
}

#[cfg(test)]
impl ActorGenerationPublicationRefusal {
    pub(crate) fn outcome(
        &self,
    ) -> &Arc<Result<ActorGenerationCommit, ResidentActorWorkbenchError>> {
        &self.outcome
    }

    pub(crate) fn observation(&self) -> ActorGenerationPublicationRefusalObservation {
        publication_failure_observation(self.outcome.as_ref())
            .expect("an unpublished refusal retains its original refusal or error")
    }

    pub(crate) fn into_settled_diagnostic(
        self,
    ) -> Result<ActorGenerationPublicationRefusalObservation, Self> {
        if matches!(self.obligations, PublicationBodyObligations::DiagnosticOnly)
            && matches!(self.guard.settlement, ActorPublicationState::Settled)
        {
            Ok(self.observation())
        } else {
            Err(self)
        }
    }

    pub(crate) fn refuse_retirement(
        &mut self,
        original: &mut generation_admission::GenerationRetirementFence,
    ) -> Result<(), ResidentActorWorkbenchError> {
        self.guard
            .refuse_retirement(original)
            .map_err(
                |settlement| ResidentActorWorkbenchError::PublicationSettlement {
                    failure: Box::new(ActorPublicationSettlementFailure {
                        outcome: self.outcome.clone(),
                        settlement,
                    }),
                },
            )
    }
}

fn publication_failure_observation(
    outcome: &Result<ActorGenerationCommit, ResidentActorWorkbenchError>,
) -> Option<ActorGenerationPublicationRefusalObservation> {
    use ActorGenerationPublicationRefusalObservation as Observation;
    Some(match outcome {
        Ok(ActorGenerationCommit::Published { .. }) => return None,
        Ok(ActorGenerationCommit::Refused(ActorGenerationPublicationIssue::Detail(_))) => {
            Observation::Refused
        }
        Ok(ActorGenerationCommit::Refused(ActorGenerationPublicationIssue::Durable(error))) => {
            Observation::Failed {
                cause: publication_session_failure_cause(
                    error,
                    ActorPublicationFailureCause::Resident,
                ),
                execution: None,
                requires_recovery: session_error_requires_recovery(error),
            }
        }
        Ok(ActorGenerationCommit::Unconfirmed(issue)) => Observation::Failed {
            cause: match issue {
                ActorGenerationPublicationIssue::Detail(_) => {
                    ActorPublicationFailureCause::PublicationSettlement
                }
                ActorGenerationPublicationIssue::Durable(error) => {
                    publication_session_failure_cause(
                        error,
                        ActorPublicationFailureCause::PublicationSettlement,
                    )
                }
            },
            execution: None,
            requires_recovery: true,
        },
        Err(error) => Observation::Failed {
            cause: error.publication_failure_cause(),
            execution: error.execution_failure_kind(),
            requires_recovery: error.requires_recovery(),
        },
    })
}

/// Checkout completion and source settlement are distinct observations. An
/// unobserved body never grants the right to reopen either source.
#[cfg(test)]
enum PublicationBodyCompletion {
    Observed {
        guard: ActorPublicationGuard,
        outcome: Result<ActorGenerationCommit, ResidentActorWorkbenchError>,
        obligations: PublicationBodyObligations,
    },
    Unobserved {
        guard: ActorPublicationGuard,
        primary: ResidentActorWorkbenchError,
    },
    Terminal(Result<ActorGenerationCommit, ResidentActorWorkbenchError>),
}

#[cfg(test)]
impl PublicationBodyCompletion {
    fn complete(self) -> Result<ActorGenerationCommit, ResidentActorWorkbenchError> {
        match self {
            Self::Observed { guard, outcome, .. } => guard.complete(outcome),
            Self::Unobserved { guard, primary } => Err(guard.unobserved(primary)),
            Self::Terminal(outcome) => outcome,
        }
    }

    fn for_retirement(self) -> ActorGenerationPublicationSettlement {
        match self {
            Self::Observed {
                guard,
                outcome,
                obligations,
            } if matches!(&guard.settlement, ActorPublicationState::Armed(_))
                && guard.known_unpublished(&outcome) =>
            {
                ActorGenerationPublicationSettlement::Unpublished(
                    ActorGenerationPublicationRefusal {
                        guard,
                        outcome: Arc::new(outcome),
                        obligations,
                    },
                )
            }
            completion => {
                ActorGenerationPublicationSettlement::Settled(Arc::new(completion.complete()))
            }
        }
    }
}

#[cfg(test)]
static_assertions::assert_not_impl_any!(ActorGenerationReservationDriver: Clone, Copy);
#[cfg(test)]
static_assertions::assert_not_impl_any!(ActorGenerationPublicationDriver: Clone, Copy);
#[cfg(test)]
static_assertions::assert_not_impl_any!(ActorGenerationRetirementPreparation: Clone, Copy);

#[derive(Clone)]
pub(crate) enum ActorPublicationOwner {
    Actor(crate::LifecycleHandle),
    #[cfg(test)]
    Preparation(crate::CompilerPreparationClient),
}
impl ActorPublicationOwner {
    fn matches_actor(&self, actor: crate::ActorRef) -> bool {
        match self {
            Self::Actor(lifecycle) => lifecycle.identity() == actor,
            #[cfg(test)]
            Self::Preparation(_) => true,
        }
    }
    fn retained_liveness(&self) -> ActorPublicationLiveness {
        match self {
            Self::Actor(lifecycle) => {
                ActorPublicationLiveness::Actor(lifecycle.retained_terminal().clone())
            }
            #[cfg(test)]
            Self::Preparation(owner) => ActorPublicationLiveness::Preparation(owner.clone()),
        }
    }
}

/// Settlement retains terminal liveness, never the actor's client/notification
/// graph. The broad lifecycle endpoint belongs to the disposable driver.
#[derive(Clone)]
enum ActorPublicationLiveness {
    Actor(crate::RetainedActorExit),
    #[cfg(test)]
    Preparation(crate::CompilerPreparationClient),
}

impl ActorPublicationLiveness {
    fn with_live_source_settlement<R>(&self, settle: impl FnOnce() -> R) -> Option<R> {
        match self {
            Self::Actor(terminal) => terminal.with_live_source_settlement(settle),
            #[cfg(test)]
            Self::Preparation(owner) => owner.with_live_source_settlement(settle),
        }
    }
}

/// The exact prepared selection reserved by the current installation owner.
struct ActorPublicationAttempt {
    // Guard and callback retain this snapshot outside installation locks. State
    // replacement drops only shared clones, never its last tools/source custody.
    expected: ActorRequestSnapshot,
    target: generation_admission::GenerationDependency,
}

/// Identifies the actual reserved operation without granting settlement authority.
#[derive(Clone)]
pub(crate) struct ActorPublicationAttemptObserver(Arc<ActorPublicationAttempt>);

impl ActorPublicationAttemptObserver {
    pub(crate) fn same_attempt(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.0, &other.0)
    }
}

/// The one exclusive authority reserved for a publication attempt. A bootstrap
/// world publication owns its fence and prerequisite; every other attempt owns
/// the target's source fence and optional prerequisite claim directly.
enum PublicationAuthority {
    World(generation_admission::WorldPublication),
    TargetFence {
        fence: PublicationFence,
        prerequisite: Option<tidepool_runtime::session::RuntimeSourcePublicationPrerequisite>,
    },
}

/// Moving the affine fence into reopening must not move its cleanup owner.
enum PublicationFence {
    Held(tidepool_runtime::session::RuntimeSourceFence),
    ReopenAttempted,
}

#[derive(Debug, thiserror::Error)]
pub(crate) enum PublicationSettlementError {
    #[error(transparent)]
    Source(#[from] tidepool_runtime::session::SourceAdmissionError),
    #[error("publication no longer owns its exact installation or world")]
    SelectionChanged,
    #[error("publication's actor or preparation owner is unavailable")]
    OwnerUnavailable,
    #[error("publication already attempted to reopen its source fence")]
    ReopenAttempted,
    #[error("publication's worker outcome was not observed")]
    BodyUnobserved,
    #[error("publication completion cannot establish whether visibility committed")]
    PublicationUnconfirmed,
    #[error("the generation was published, but its lifecycle owner refused notification")]
    NotificationRefused,
    #[error("retirement {stage} settlement failed: {source}")]
    Retirement {
        stage: RetirementSettlementStage,
        source: Box<PublicationSettlementError>,
    },
}

#[derive(Debug, Clone, Copy, thiserror::Error)]
enum RetirementSettlementStage {
    #[error("candidate")]
    Candidate,
    #[error("original")]
    Original,
}

impl PublicationFence {
    fn publication_view(
        &self,
        prerequisite: Option<&tidepool_runtime::session::RuntimeSourcePublicationPrerequisite>,
    ) -> Result<tidepool_runtime::session::RuntimeSourcePublicationView, PublicationSettlementError>
    {
        match self {
            Self::Held(fence) => Ok(fence.publication_view(prerequisite)),
            Self::ReopenAttempted => Err(PublicationSettlementError::ReopenAttempted),
        }
    }

    fn reserve_scope(
        &self,
        scope: tidepool_runtime::session::UnpublishedNotebookScope,
    ) -> Result<
        tidepool_runtime::session::ReservedNotebookScope,
        (
            tidepool_runtime::session::UnpublishedNotebookScope,
            PublicationSettlementError,
        ),
    > {
        match self {
            Self::Held(fence) => scope
                .into_reserved(fence)
                .map_err(|(scope, error)| (scope, error.into())),
            Self::ReopenAttempted => Err((scope, PublicationSettlementError::ReopenAttempted)),
        }
    }

    fn confirm(
        &mut self,
        target: &Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
        prerequisite: Option<&tidepool_runtime::session::RuntimeSourcePublicationPrerequisite>,
        settle: impl for<'a> FnOnce(
            tidepool_runtime::session::RuntimeSourceReopen<'a>,
        ) -> Result<(), PublicationSettlementError>,
    ) -> Result<tidepool_runtime::session::ConfirmedSourcePublication, PublicationSettlementError>
    {
        let Self::Held(fence) = std::mem::replace(self, Self::ReopenAttempted) else {
            return Err(PublicationSettlementError::ReopenAttempted);
        };
        fence.confirm_publication_with(target, prerequisite, settle)?
    }

    fn reopen(
        &mut self,
        target: &Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
        settle: impl for<'a> FnOnce(
            tidepool_runtime::session::RuntimeSourceReopen<'a>,
        ) -> Result<(), PublicationSettlementError>,
    ) -> Result<tidepool_runtime::session::OwnSourceFenceReopened, PublicationSettlementError> {
        let Self::Held(fence) = std::mem::replace(self, Self::ReopenAttempted) else {
            return Err(PublicationSettlementError::ReopenAttempted);
        };
        fence.reopen_with(target.original_source(), settle)?
    }
}

enum ActorPublicationState {
    Armed(PublicationAuthority),
    Settled,
}

enum PublicationScopeSettlement {
    Pending,
    Reopened(tidepool_runtime::session::OwnSourceFenceReopened),
    Confirmed(tidepool_runtime::session::ConfirmedSourcePublication),
}

struct ActorPublicationGuard {
    state: Arc<InstalledToolsState>,
    attempt: Arc<ActorPublicationAttempt>,
    settlement: ActorPublicationState,
    decision: Arc<tidepool_runtime::session::PublicationDecision>,
    owner: ActorPublicationLiveness,
    notebook_scope: Option<tidepool_runtime::session::ReservedNotebookScope>,
    scope_settlement: PublicationScopeSettlement,
    #[cfg(test)]
    settlement_probe: Option<Arc<PublicationSettlementProbe>>,
}

#[cfg(test)]
pub(super) struct PublicationSettlementProbe {
    pub(super) entered: std::sync::mpsc::SyncSender<()>,
    pub(super) release: Mutex<std::sync::mpsc::Receiver<()>>,
    pub(super) unwind: bool,
}
#[cfg(test)]
impl PublicationSettlementProbe {
    fn wait(&self) {
        self.entered.send(()).unwrap();
        self.release
            .lock()
            .recv_timeout(std::time::Duration::from_secs(10))
            .unwrap();
        assert!(!self.unwind, "publication settlement control unwound");
    }
}

#[derive(Clone)]
struct ActorPublicationVisibility {
    state: Arc<InstalledToolsState>,
    attempt: Arc<ActorPublicationAttempt>,
    world: Option<generation_admission::WorldPublicationVisibility>,
    source: tidepool_runtime::session::RuntimeSourcePublicationView,
}

impl ActorPublicationGuard {
    fn reserve(
        state: Arc<InstalledToolsState>,
        expected: ActorRequestSnapshot,
        target: generation_admission::GenerationDependency,
        source: &generation_admission::SourceDependency,
        decision: Arc<tidepool_runtime::session::PublicationDecision>,
        owner: ActorPublicationOwner,
    ) -> Result<Option<Self>, ResidentActorWorkbenchError> {
        target.runtime_lease().validate_lexical_issuer()?;
        let authority = match (&expected, source) {
            (
                ActorRequestSnapshot::Bootstrap(_),
                generation_admission::SourceDependency::World(world),
            ) => PublicationAuthority::World(world.begin_publication(&target)?),
            _ => {
                let prerequisite = target
                    .prerequisite()
                    .as_ref()
                    .map(|parent| {
                        parent
                            .runtime_lease()
                            .admit_source()
                            .map(|claim| claim.for_publication())
                    })
                    .transpose()?;
                let fence = target.runtime_admission().fence_if_idle()?;
                PublicationAuthority::TargetFence {
                    fence: PublicationFence::Held(fence),
                    prerequisite,
                }
            }
        };
        let attempt = Arc::new(ActorPublicationAttempt { expected, target });
        let same = {
            let mut record = state.0.lock();
            let current = &mut record.availability;
            let same = match (&*current, &attempt.expected) {
                (
                    InstalledToolsAvailability::Generation(active),
                    ActorRequestSnapshot::Generation(expected),
                ) => Arc::ptr_eq(active, expected),
                (
                    InstalledToolsAvailability::Available(active),
                    ActorRequestSnapshot::Bootstrap(expected),
                ) => active.same_installation(expected),
                _ => false,
            };
            if same {
                *current = InstalledToolsAvailability::PublicationInProgress(attempt.clone());
            }
            same
        };
        if !same {
            // No selected owner remains to authorize restoration. Abandoned
            // candidate fences remain closed; custody is retained separately.
            drop(authority);
            return Ok(None);
        }
        Ok(Some(Self {
            state,
            attempt,
            settlement: ActorPublicationState::Armed(authority),
            decision,
            owner: owner.retained_liveness(),
            notebook_scope: None,
            scope_settlement: PublicationScopeSettlement::Pending,
            #[cfg(test)]
            settlement_probe: None,
        }))
    }

    fn reserve_notebook_scope(
        &mut self,
        scope: tidepool_runtime::session::UnpublishedNotebookScope,
    ) -> Result<
        (),
        (
            tidepool_runtime::session::UnpublishedNotebookScope,
            PublicationSettlementError,
        ),
    > {
        let reserved = match &self.settlement {
            ActorPublicationState::Armed(authority) => authority.reserve_scope(scope)?,
            ActorPublicationState::Settled => {
                return Err((scope, PublicationSettlementError::ReopenAttempted))
            }
        };
        self.notebook_scope = Some(reserved);
        Ok(())
    }

    fn close_unpublished_scope(&mut self) -> Result<(), PublicationSettlementError> {
        if let Some(scope) = &mut self.notebook_scope {
            let PublicationScopeSettlement::Reopened(witness) = &self.scope_settlement else {
                return Err(PublicationSettlementError::ReopenAttempted);
            };
            scope.close_reopened_source(witness)?;
            self.notebook_scope = None;
        }
        Ok(())
    }

    fn release_published_scope(&mut self) -> Result<(), PublicationSettlementError> {
        if let Some(scope) = &mut self.notebook_scope {
            let PublicationScopeSettlement::Confirmed(witness) = &self.scope_settlement else {
                return Err(PublicationSettlementError::PublicationUnconfirmed);
            };
            scope.settle_published(witness)?;
            self.notebook_scope = None;
        }
        Ok(())
    }

    fn has_no_commit_claim(&self) -> bool {
        matches!(
            self.decision.phase(),
            tidepool_runtime::session::PublicationPhase::Running
                | tidepool_runtime::session::PublicationPhase::CancellationRequested
                | tidepool_runtime::session::PublicationPhase::Terminated
        )
    }

    fn known_unpublished(
        &self,
        outcome: &Result<ActorGenerationCommit, ResidentActorWorkbenchError>,
    ) -> bool {
        self.has_no_commit_claim()
            && !matches!(
                outcome,
                Ok(ActorGenerationCommit::Published { .. } | ActorGenerationCommit::Unconfirmed(_))
            )
    }

    #[cfg(test)]
    fn complete(
        mut self,
        outcome: Result<ActorGenerationCommit, ResidentActorWorkbenchError>,
    ) -> Result<ActorGenerationCommit, ResidentActorWorkbenchError> {
        let known_unpublished = self.known_unpublished(&outcome);
        let settlement = if known_unpublished {
            self.refused()
        } else if matches!(&outcome, Ok(ActorGenerationCommit::Published { .. })) {
            self.confirmed()
        } else if matches!(&outcome, Ok(ActorGenerationCommit::Unconfirmed(_))) {
            return outcome;
        } else {
            return Err(ResidentActorWorkbenchError::PublicationSettlement {
                failure: Box::new(ActorPublicationSettlementFailure {
                    outcome: Arc::new(outcome),
                    settlement: PublicationSettlementError::PublicationUnconfirmed,
                }),
            });
        };
        if let Err(settlement) = settlement {
            return Err(ResidentActorWorkbenchError::PublicationSettlement {
                failure: Box::new(ActorPublicationSettlementFailure {
                    outcome: Arc::new(outcome),
                    settlement,
                }),
            });
        }
        outcome
    }

    #[cfg(test)]
    fn unobserved(self, primary: ResidentActorWorkbenchError) -> ResidentActorWorkbenchError {
        ResidentActorWorkbenchError::PublicationSettlement {
            failure: Box::new(ActorPublicationSettlementFailure {
                outcome: Arc::new(Err(primary)),
                settlement: PublicationSettlementError::BodyUnobserved,
            }),
        }
    }

    fn visibility(&self) -> Result<ActorPublicationVisibility, PublicationSettlementError> {
        let source = match &self.settlement {
            ActorPublicationState::Armed(PublicationAuthority::World(world)) => {
                world.source_publication_view()?
            }
            ActorPublicationState::Armed(PublicationAuthority::TargetFence {
                fence,
                prerequisite,
            }) => fence.publication_view(prerequisite.as_ref())?,
            ActorPublicationState::Settled => {
                return Err(PublicationSettlementError::ReopenAttempted)
            }
        };
        Ok(ActorPublicationVisibility {
            state: self.state.clone(),
            attempt: self.attempt.clone(),
            world: match &self.settlement {
                ActorPublicationState::Armed(PublicationAuthority::World(world)) => {
                    Some(world.visibility())
                }
                ActorPublicationState::Armed(PublicationAuthority::TargetFence { .. })
                | ActorPublicationState::Settled => None,
            },
            source,
        })
    }

    fn cutoff_error(error: PublicationSettlementError) -> ResidentActorWorkbenchError {
        ResidentActorWorkbenchError::PublicationSettlement {
            failure: Box::new(ActorPublicationSettlementFailure {
                outcome: Arc::new(Ok(ActorGenerationCommit::Refused(
                    "generation cutoff was refused".into(),
                ))),
                settlement: PublicationSettlementError::Retirement {
                    stage: RetirementSettlementStage::Original,
                    source: Box::new(error),
                },
            }),
        }
    }

    fn fence_original(&mut self) -> ActorGenerationRetirementCutoff {
        let Some(expected) = self.attempt.expected.generation() else {
            return ActorGenerationRetirementCutoff::Refused(Self::cutoff_error(
                PublicationSettlementError::SelectionChanged,
            ));
        };
        if !matches!(&self.settlement, ActorPublicationState::Armed(_)) {
            return ActorGenerationRetirementCutoff::Refused(Self::cutoff_error(
                PublicationSettlementError::SelectionChanged,
            ));
        }
        expected.dependency().fence_selected_with(|transition| {
            self.owner.with_live_source_settlement(|| {
                let record = self.state.0.lock();
                if !matches!(&record.availability, InstalledToolsAvailability::PublicationInProgress(issued) if Arc::ptr_eq(issued, &self.attempt)) {
                    return Err(PublicationSettlementError::SelectionChanged);
                }
                transition.commit();
                Ok(())
            }).ok_or(PublicationSettlementError::OwnerUnavailable)?
        })
    }

    fn refuse_retirement(
        &mut self,
        original: &mut generation_admission::GenerationRetirementFence,
    ) -> Result<(), PublicationSettlementError> {
        let at = |stage, source| PublicationSettlementError::Retirement {
            stage,
            source: Box::new(source),
        };
        original
            .validate_held()
            .map_err(|error| at(RetirementSettlementStage::Original, error))?;
        let Some(expected) = self.attempt.expected.generation() else {
            return Err(at(
                RetirementSettlementStage::Original,
                PublicationSettlementError::SelectionChanged,
            ));
        };
        if !expected.dependency().same_prepared(original.dependency()) {
            return Err(at(
                RetirementSettlementStage::Original,
                PublicationSettlementError::SelectionChanged,
            ));
        }
        let owner = self.owner.clone();
        let state = self.state.clone();
        let attempt = self.attempt.clone();
        let ActorPublicationState::Armed(authority) = &mut self.settlement else {
            return Err(at(
                RetirementSettlementStage::Candidate,
                PublicationSettlementError::ReopenAttempted,
            ));
        };
        let reopened = authority.refused_when(&attempt.target, |reopen| {
            owner.with_live_source_settlement(|| {
                let record = state.0.lock();
                if !matches!(&record.availability, InstalledToolsAvailability::PublicationInProgress(issued) if Arc::ptr_eq(issued, &attempt)) {
                    return Err(PublicationSettlementError::SelectionChanged);
                }
                reopen.commit();
                Ok(())
            }).ok_or(PublicationSettlementError::OwnerUnavailable)?
        }).map_err(|error| at(RetirementSettlementStage::Candidate, error))?;
        self.scope_settlement = PublicationScopeSettlement::Reopened(reopened);
        #[cfg(test)]
        if let Some(probe) = &self.settlement_probe {
            probe.wait();
        }
        original.reopen_with(|reopen| {
            owner.with_live_source_settlement(|| {
                let mut record = state.0.lock();
                if !matches!(&record.availability, InstalledToolsAvailability::PublicationInProgress(issued) if Arc::ptr_eq(issued, &attempt)) {
                    return Err(PublicationSettlementError::SelectionChanged);
                }
                let ActorRequestSnapshot::Generation(generation) = &attempt.expected else {
                    return Err(PublicationSettlementError::SelectionChanged);
                };
                record.availability = InstalledToolsAvailability::Generation(generation.clone());
                reopen.commit();
                Ok(())
            }).ok_or(PublicationSettlementError::OwnerUnavailable)?
        }).map_err(|error| at(RetirementSettlementStage::Original, error))?;
        self.close_unpublished_scope()?;
        self.settlement = ActorPublicationState::Settled;
        Ok(())
    }

    #[cfg(test)]
    fn refused(mut self) -> Result<(), PublicationSettlementError> {
        self.refuse_unstarted()
    }

    fn refuse_unstarted(&mut self) -> Result<(), PublicationSettlementError> {
        let restore = |reopen: tidepool_runtime::session::RuntimeSourceReopen<'_>| {
            self.owner.with_live_source_settlement(|| {
                let mut record = self.state.0.lock();
                let current = &mut record.availability;
                if !matches!(&*current, InstalledToolsAvailability::PublicationInProgress(attempt) if Arc::ptr_eq(attempt, &self.attempt)) {
                    return Err(PublicationSettlementError::SelectionChanged);
                }
                *current = match &self.attempt.expected {
                    ActorRequestSnapshot::Bootstrap(lease) => InstalledToolsAvailability::Available(lease.clone()),
                    ActorRequestSnapshot::Generation(generation) => InstalledToolsAvailability::Generation(generation.clone()),
                    ActorRequestSnapshot::SourceCallback(_) => unreachable!("callback is not current publication"),
                };
                #[cfg(test)]
                if let Some(probe) = &self.settlement_probe { probe.wait(); }
                reopen.commit();
                Ok(())
            }).ok_or(PublicationSettlementError::OwnerUnavailable)?
        };
        let ActorPublicationState::Armed(authority) = &mut self.settlement else {
            return Err(PublicationSettlementError::ReopenAttempted);
        };
        let reopened = authority.refused_when(&self.attempt.target, restore)?;
        self.scope_settlement = PublicationScopeSettlement::Reopened(reopened);
        self.close_unpublished_scope()?;
        self.settlement = ActorPublicationState::Settled;
        Ok(())
    }

    fn confirmed(&mut self) -> Result<(), PublicationSettlementError> {
        let promote = |reopen: tidepool_runtime::session::RuntimeSourceReopen<'_>| {
            self.owner
                .with_live_source_settlement(|| {
                    let mut record = self.state.0.lock();
                    let current = &mut record.availability;
                    let selected = match &*current {
                        InstalledToolsAvailability::PublicationVisible {
                            attempt,
                            generation,
                        } if Arc::ptr_eq(attempt, &self.attempt)
                            && generation.dependency().same_prepared(&self.attempt.target) =>
                        {
                            Some(generation.clone())
                        }
                        _ => None,
                    };
                    let Some(generation) = selected else {
                        return Err(PublicationSettlementError::SelectionChanged);
                    };
                    #[cfg(test)]
                    if let Some(probe) = &self.settlement_probe {
                        probe.wait();
                    }
                    *current = InstalledToolsAvailability::Generation(generation);
                    reopen.commit();
                    Ok(())
                })
                .ok_or(PublicationSettlementError::OwnerUnavailable)?
        };
        let ActorPublicationState::Armed(authority) = &mut self.settlement else {
            return Err(PublicationSettlementError::ReopenAttempted);
        };
        let confirmed = authority.confirmed_when(&self.attempt.target, promote)?;
        self.scope_settlement = PublicationScopeSettlement::Confirmed(confirmed);
        self.release_published_scope()?;
        self.settlement = ActorPublicationState::Settled;
        Ok(())
    }
}

impl Drop for ActorPublicationGuard {
    fn drop(&mut self) {
        let ActorPublicationState::Armed(authority) = &mut self.settlement else {
            return;
        };
        self.decision.request_cancellation();
        let state = self.state.clone();
        let attempt = self.attempt.clone();
        let mark_installed = || {
            let mut record = state.0.lock();
            let current = &mut record.availability;
            match &*current {
                InstalledToolsAvailability::PublicationInProgress(issued)
                    if Arc::ptr_eq(issued, &attempt) =>
                {
                    *current = InstalledToolsAvailability::PublicationUnavailable(issued.clone())
                }
                InstalledToolsAvailability::Generation(generation)
                    if generation.dependency().same_prepared(&attempt.target) =>
                {
                    *current = InstalledToolsAvailability::GenerationUnavailable(generation.clone())
                }
                InstalledToolsAvailability::PublicationVisible {
                    attempt: issued,
                    generation,
                } if Arc::ptr_eq(issued, &attempt) => {
                    *current =
                        InstalledToolsAvailability::GenerationUnavailable(generation.clone());
                }
                _ => {}
            }
        };
        authority.unavailable(mark_installed);
        // WorldPublication drops prerequisite claims only after both locks unlock.
    }
}

impl ActorPublicationVisibility {
    fn is_current(&self) -> bool {
        matches!(&self.state.0.lock().availability, InstalledToolsAvailability::PublicationInProgress(attempt) if Arc::ptr_eq(attempt, &self.attempt))
    }

    fn install(&self, generation: Arc<ActorGeneration>) -> bool {
        if let Some(world) = &self.world {
            return world.install(&self.state, &self.attempt, generation);
        }
        let mut record = self.state.0.lock();
        let current = &mut record.availability;
        let live = generation.dependency().same_prepared(&self.attempt.target)
            && Arc::ptr_eq(&generation.scope, self.attempt.target.runtime_lease())
            && matches!(&*current, InstalledToolsAvailability::PublicationInProgress(attempt) if Arc::ptr_eq(attempt, &self.attempt));
        if matches!(&*current, InstalledToolsAvailability::PublicationInProgress(attempt) | InstalledToolsAvailability::PublicationUnavailable(attempt) if Arc::ptr_eq(attempt, &self.attempt))
        {
            *current = if live {
                InstalledToolsAvailability::PublicationVisible {
                    attempt: self.attempt.clone(),
                    generation,
                }
            } else {
                InstalledToolsAvailability::GenerationUnavailable(generation)
            };
        }
        live
    }

    fn retain_unconfirmed(&self, candidate: &mut Option<InitialPublicationCandidate>) {
        let mut record = self.state.0.lock();
        let current = &mut record.availability;
        let exact = match &*current {
            InstalledToolsAvailability::PublicationInProgress(attempt)
            | InstalledToolsAvailability::PublicationUnavailable(attempt) => {
                Arc::ptr_eq(attempt, &self.attempt)
            }
            InstalledToolsAvailability::Generation(generation)
            | InstalledToolsAvailability::GenerationUnavailable(generation) => {
                generation.dependency().same_prepared(&self.attempt.target)
            }
            InstalledToolsAvailability::PublicationVisible { attempt, .. } => {
                Arc::ptr_eq(attempt, &self.attempt)
            }
            _ => false,
        };
        if !exact {
            return;
        }
        let previous = match &self.attempt.expected {
            ActorRequestSnapshot::Bootstrap(previous) => Some(previous),
            _ => None,
        };
        retain_unconfirmed_generation(current, previous, candidate);
    }
}

impl PublicationAuthority {
    fn reserve_scope(
        &self,
        scope: tidepool_runtime::session::UnpublishedNotebookScope,
    ) -> Result<
        tidepool_runtime::session::ReservedNotebookScope,
        (
            tidepool_runtime::session::UnpublishedNotebookScope,
            PublicationSettlementError,
        ),
    > {
        match self {
            Self::World(world) => world.reserve_scope(scope),
            Self::TargetFence { fence, .. } => fence.reserve_scope(scope),
        }
    }

    fn unavailable(&mut self, mark_installed: impl FnOnce()) {
        match self {
            Self::World(world) => world.unavailable(mark_installed),
            Self::TargetFence { prerequisite, .. } => {
                mark_installed();
                if let Some(claim) = prerequisite.take() {
                    claim.retain_unconfirmed();
                }
            }
        }
    }

    fn refused_when(
        &mut self,
        target: &generation_admission::GenerationDependency,
        restore: impl for<'a> FnOnce(
            tidepool_runtime::session::RuntimeSourceReopen<'a>,
        ) -> Result<(), PublicationSettlementError>,
    ) -> Result<tidepool_runtime::session::OwnSourceFenceReopened, PublicationSettlementError> {
        match self {
            Self::World(world) => world.refused_when(restore),
            Self::TargetFence {
                fence,
                prerequisite,
            } => {
                let reopened = fence.reopen(target.runtime_lease(), restore)?;
                drop(prerequisite.take());
                Ok(reopened)
            }
        }
    }

    fn confirmed_when(
        &mut self,
        target: &generation_admission::GenerationDependency,
        promote: impl for<'a> FnOnce(
            tidepool_runtime::session::RuntimeSourceReopen<'a>,
        ) -> Result<(), PublicationSettlementError>,
    ) -> Result<tidepool_runtime::session::ConfirmedSourcePublication, PublicationSettlementError>
    {
        match self {
            Self::World(world) => world.confirmed_when(promote),
            Self::TargetFence {
                fence,
                prerequisite,
            } => {
                let confirmed =
                    fence.confirm(target.runtime_lease(), prerequisite.as_ref(), promote)?;
                drop(prerequisite.take());
                Ok(confirmed)
            }
        }
    }
}

impl<H, O> ActorGenerationPublisher<H, O>
where
    H: DispatchEffect<O> + Send + 'static,
    O: OutputSink + Sync + 'static,
{
    #[cfg(test)]
    fn with_disposal_probe(mut self, disposed: Arc<std::sync::atomic::AtomicBool>) -> Self {
        assert!(self.disposal_probe.is_none());
        self.disposal_probe = Some(PublicationDisposalProbe { disposed });
        self
    }

    pub(crate) fn into_publication_preparation(
        self,
        prepared: PreparedActorGeneration,
        decision: Arc<tidepool_runtime::session::PublicationDecision>,
        kind: ActorGenerationPublication,
    ) -> ActorGenerationRetirementPreparation {
        let candidate = Arc::downgrade(&prepared.candidate);
        ActorGenerationRetirementPreparation {
            prepared,
            driver: ActorGenerationReservationDriver {
                candidate,
                decision: decision.clone(),
                publication_kind: kind,
                reserve: Box::new(
                    move |prepared| match self.reserve(prepared, decision, kind) {
                        Ok(ActorGenerationReservation::Reserved(reserved)) => {
                            let candidate = Arc::downgrade(&reserved.prepared.candidate);
                            let attempt = reserved.attempt_observer();
                            ActorGenerationRetirementPreparationOutcome::Reserved {
                                reserved,
                                publisher: ActorGenerationPublicationDriver {
                                    candidate,
                                    attempt,
                                    publish: Box::new(move |reserved| {
                                        Box::pin(async move {
                                            self.run_publication_execution(reserved).await
                                        })
                                    }),
                                },
                            }
                        }
                        Ok(ActorGenerationReservation::Refused(reason)) => {
                            ActorGenerationRetirementPreparationOutcome::Refused(reason)
                        }
                        Err(error) => ActorGenerationRetirementPreparationOutcome::Failed(error),
                    },
                ),
            },
        }
    }

    #[cfg(test)]
    pub(crate) async fn publish(
        &self,
        prepared: PreparedActorGeneration,
        publication: Arc<tidepool_runtime::session::PublicationDecision>,
        publication_kind: ActorGenerationPublication,
    ) -> Result<ActorGenerationCommit, ResidentActorWorkbenchError> {
        match self.reserve(prepared, publication, publication_kind)? {
            ActorGenerationReservation::Reserved(reserved) => self.publish_reserved(reserved).await,
            ActorGenerationReservation::Refused(detail) => {
                Ok(ActorGenerationCommit::Refused(detail.into()))
            }
        }
    }

    pub(crate) fn reserve(
        &self,
        mut prepared: PreparedActorGeneration,
        publication: Arc<tidepool_runtime::session::PublicationDecision>,
        publication_kind: ActorGenerationPublication,
    ) -> Result<ActorGenerationReservation, ResidentActorWorkbenchError> {
        if !self.owner.matches_actor(prepared.checkout_context.actor) {
            return Ok(ActorGenerationReservation::Refused(
                "publication owner belongs to another actor".into(),
            ));
        }
        let machine_owner = {
            let owner: Arc<dyn std::any::Any + Send + Sync> = self.access.machines.clone();
            Arc::downgrade(&owner)
        };
        if !prepared.machine_owner.ptr_eq(&machine_owner) {
            return Ok(ActorGenerationReservation::Refused(
                "prepared generation belongs to a different machine owner".into(),
            ));
        }
        let Some(mut owner) = ActorPublicationGuard::reserve(
            self.state.clone(),
            prepared.expected.clone(),
            prepared
                .candidate
                .installation
                .source_dependency()
                .generation()
                .expect("prepared generation dependency")
                .clone(),
            prepared.checkout_context.source_dependency(),
            publication.clone(),
            self.owner.clone(),
        )?
        else {
            return Ok(ActorGenerationReservation::Refused(
                "actor generation changed during reload preparation".into(),
            ));
        };
        if let Some(scope) = prepared.unpublished.take() {
            if let Err((scope, settlement)) = owner.reserve_notebook_scope(scope) {
                prepared.unpublished = Some(scope);
                return Err(ResidentActorWorkbenchError::PublicationSettlement {
                    failure: Box::new(ActorPublicationSettlementFailure {
                        outcome: Arc::new(Ok(ActorGenerationCommit::Refused(
                            "provisional source reservation refused".into(),
                        ))),
                        settlement,
                    }),
                });
            }
        }
        Ok(ActorGenerationReservation::Reserved(
            ReservedActorGeneration {
                prepared,
                guard: owner,
                publication_kind,
            },
        ))
    }

    #[cfg(test)]
    pub(crate) async fn publish_reserved(
        &self,
        reserved: ReservedActorGeneration,
    ) -> Result<ActorGenerationCommit, ResidentActorWorkbenchError> {
        self.run_publication_body(reserved).await.complete()
    }

    #[cfg(test)]
    async fn run_publication_body(
        &self,
        reserved: ReservedActorGeneration,
    ) -> PublicationBodyCompletion {
        let ReservedActorGeneration {
            prepared,
            guard: owner,
            publication_kind,
        } = reserved;
        if !matches!(&owner.settlement, ActorPublicationState::Armed(_)) {
            return PublicationBodyCompletion::Terminal(Ok(ActorGenerationCommit::Refused(
                "publication reservation already settled".into(),
            )));
        }
        let machine_owner = {
            let owner: Arc<dyn std::any::Any + Send + Sync> = self.access.machines.clone();
            Arc::downgrade(&owner)
        };
        let obligations = match &prepared.commit {
            PreparedGenerationCommit::Ephemeral { .. } => {
                PublicationBodyObligations::DiagnosticOnly
            }
            PreparedGenerationCommit::Restored { .. }
            | PreparedGenerationCommit::Durable { .. } => PublicationBodyObligations::Retained,
        };
        if !Arc::ptr_eq(&self.state, &owner.state) || !prepared.machine_owner.ptr_eq(&machine_owner)
        {
            return PublicationBodyCompletion::Observed {
                guard: owner,
                obligations,
                outcome: Ok(ActorGenerationCommit::Refused(
                    "publication reservation belongs to another publisher".into(),
                )),
            };
        }
        let publication = owner.decision.clone();
        let visibility = match owner.visibility() {
            Ok(visibility) => visibility,
            Err(settlement) => {
                return PublicationBodyCompletion::Terminal(Err(
                    ResidentActorWorkbenchError::PublicationSettlement {
                        failure: Box::new(ActorPublicationSettlementFailure {
                            outcome: Arc::new(Ok(ActorGenerationCommit::Refused(
                                "publication has no armed source fence".into(),
                            ))),
                            settlement,
                        }),
                    },
                ));
            }
        };
        let body = ActorGenerationPublicationBody {
            prepared,
            visibility,
            decision: publication,
            publication_kind,
        };
        match self.run_publication_execution(body).await.completion {
            ActorGenerationPublicationBodyCompletion::Observed {
                outcome,
                obligations,
            } => PublicationBodyCompletion::Observed {
                guard: owner,
                outcome: outcome.map(|outcome| match outcome {
                    ActorGenerationBodyOutcome::Visible {
                        generation,
                        cancellation_pending,
                    } => ActorGenerationCommit::Published {
                        generation,
                        cancellation_pending,
                    },
                    ActorGenerationBodyOutcome::Refused(issue) => {
                        ActorGenerationCommit::Refused(issue)
                    }
                    ActorGenerationBodyOutcome::Unconfirmed(issue) => {
                        ActorGenerationCommit::Unconfirmed(issue)
                    }
                }),
                obligations,
            },
            ActorGenerationPublicationBodyCompletion::Unobserved { primary } => {
                PublicationBodyCompletion::Unobserved {
                    guard: owner,
                    primary,
                }
            }
        }
    }

    async fn run_publication_execution(
        &self,
        body: ActorGenerationPublicationBody,
    ) -> ActorGenerationPublicationBodyResult {
        let attempt = ActorPublicationAttemptObserver(body.visibility.attempt.clone());
        let ActorGenerationPublicationBody {
            prepared,
            visibility,
            decision: publication,
            publication_kind,
        } = body;
        let obligations = match &prepared.commit {
            PreparedGenerationCommit::Ephemeral { .. } => {
                PublicationBodyObligations::DiagnosticOnly
            }
            _ => PublicationBodyObligations::Retained,
        };
        // The affine phase/fence owner is outside checkout, including cancellation
        // and setup failure. The worker receives visibility rights only.
        let completed = self.access.with_machine_wait_mode(prepared.checkout_context.clone(), None, false, move |session, _, _| {
            let mut obligations = obligations;
            if !visibility.is_current() {
                return Ok((Ok(ActorGenerationBodyOutcome::Refused("publication attempt is unavailable".into())), obligations));
            }
            let outcome = (|| {
            session.validate_lexical_scope_lease(prepared.candidate.scope.scope(), &prepared.candidate.scope)?;
            let PreparedActorGeneration { candidate, commit, public_owner, .. } = prepared;
            let installation = candidate.installation.clone();
            let context = candidate.context.clone();
            let scope = candidate.scope.clone();
            let prompts = candidate.prompts.clone();
            let configuration_digest = candidate.configuration_digest;
            let mut visible = None;
            let mut visibility_live = true;
            match commit {
                PreparedGenerationCommit::Restored { selected, readiness } => {
                    obligations = PublicationBodyObligations::Retained;
                    let canonical = selected.owner.for_notebook_generation(tidepool_runtime::session::NotebookGenerationId::INITIAL);
                    let observed = session.active_notebook_generation(&canonical).map_err(ResidentError::Session)?;
                    if observed.as_ref() != Some(&selected) || !readiness.is_current() {
                        return Ok(ActorGenerationBodyOutcome::Refused("restored generation changed before adoption".into()));
                    }
                    installation.verify_recovered_generation(&selected.references).map_err(|error| ResidentActorWorkbenchError::ActorProtocol(error.to_string()))?;
                    if prompts != selected.references.prompts {
                        return Ok(ActorGenerationBodyOutcome::Refused("restored prompt snapshot changed before adoption".into()));
                    }
                    let owner = public_owner.bind(Some(readiness));
                    let generation = Arc::new(ActorGeneration { id:selected.generation(),installation,prompts:selected.references.prompts.clone(),context,public_owner:owner,scope,configuration_digest,durable:Some(selected) });
                    if !session.with_current_compiler_world(&candidate.compiler_world, &visibility.source, || visibility.install(generation.clone())).map_err(ResidentError::Session)? {
                        return Ok(ActorGenerationBodyOutcome::Unconfirmed("publication became unavailable at visibility".into()));
                    }
                    visible=Some((generation, false));
                },
                PreparedGenerationCommit::Ephemeral { id } => {
                    let owner = public_owner.bind(None);
                    let generation = Arc::new(ActorGeneration { id,installation,prompts,context,public_owner:owner,scope,configuration_digest,durable:None });
                    let settled = session.with_current_compiler_world(&candidate.compiler_world, &visibility.source, || {
                        let Some(claim) = publication.claim_commit() else { return Err(ActorGenerationBodyOutcome::Refused("reload cancelled before commit".into())); };
                        obligations = PublicationBodyObligations::Retained;
                        visibility_live = visibility.install(generation.clone());
                        let cancellation_pending = match publication_kind {
                            ActorGenerationPublication::Terminal => claim.published(),
                            ActorGenerationPublication::Continuing => claim.published_continuing(),
                        };
                        visible = Some((generation, cancellation_pending));
                        Ok(())
                    }).map_err(ResidentError::Session)?;
                    if let Err(refusal) = settled {
                        return Ok(refusal);
                    }
                },
                PreparedGenerationCommit::Durable { prepared, selected } => {
                    obligations = PublicationBodyObligations::Retained;
                    let mut candidate = Some(InitialPublicationCandidate {
                        installation, context, scope, public_owner, prompts, configuration_digest, selected,
                    });
                    let on_visible = |readiness| {
                        let generation = candidate.take().expect("publication visibility consumes exact candidate once").visible(readiness);
                        visibility_live = visibility.install(generation.clone());
                        visible = Some((generation, false));
                    };
                    let result = match publication_kind {
                        ActorGenerationPublication::Terminal => session
                            .commit_notebook_generation_with_world(prepared, &publication, &visibility.source, on_visible),
                        ActorGenerationPublication::Continuing => session
                            .commit_notebook_generation_with_world_continuing(prepared, &publication, &visibility.source, on_visible),
                    };
                    let result = match result {
                        Ok(result) => result,
                        Err(error) if matches!(publication.phase(),tidepool_runtime::session::PublicationPhase::Published | tidepool_runtime::session::PublicationPhase::CommitClaimed { .. }) => {
                            visibility.retain_unconfirmed(&mut candidate);
                            return Ok(ActorGenerationBodyOutcome::Unconfirmed(ActorGenerationPublicationIssue::Durable(Box::new(error))));
                        },
                        Err(error) => return Err(ResidentActorWorkbenchError::Resident(ResidentError::Session(error))),
                    };
                    match result {
                        tidepool_runtime::session::DurablePublicOwnerPublication::CommittedContinuing { cancellation_pending, .. } => {
                            visible = visible.map(|(generation, _)| (generation, cancellation_pending));
                        },
                        tidepool_runtime::session::DurablePublicOwnerPublication::Committed(_) => {},
                        tidepool_runtime::session::DurablePublicOwnerPublication::Refused { error } => return Ok(ActorGenerationBodyOutcome::Refused(ActorGenerationPublicationIssue::Durable(error))),
                        tidepool_runtime::session::DurablePublicOwnerPublication::RecoveryRequired { error } => {
                            visibility.retain_unconfirmed(&mut candidate);
                            return Ok(ActorGenerationBodyOutcome::Unconfirmed(ActorGenerationPublicationIssue::Durable(error)));
                        },
                    }
                },
            }
            match visible {
                Some((generation, cancellation_pending)) if visibility_live => Ok(ActorGenerationBodyOutcome::Visible {
                    generation,
                    cancellation_pending,
                }),
                _ => {
                    visibility.retain_unconfirmed(&mut None);
                    Ok(ActorGenerationBodyOutcome::Unconfirmed("native publication confirmed without its live generation; admission requires reconciliation".into()))
                },
            }
            })();
            // Preserve whether the body actually ran; a checkout/setup error is
            // never evidence that a publication claim had no physical effects.
            Ok((outcome, obligations))
        }).await;
        let (outcome, obligations) = match completed {
            Ok(outcome) => outcome,
            Err(primary) => {
                return ActorGenerationPublicationBodyResult {
                    attempt,
                    completion: ActorGenerationPublicationBodyCompletion::Unobserved { primary },
                };
            }
        };
        #[cfg(test)]
        if let Some(probe) = &self.settlement_probe {
            probe.wait();
        }
        ActorGenerationPublicationBodyResult {
            attempt,
            completion: ActorGenerationPublicationBodyCompletion::Observed {
                outcome,
                obligations,
            },
        }
    }
}

mod reload_preparation;
pub(crate) use reload_preparation::{
    HasReloadPreparation, ReloadPreparation, ReloadPreparationOutcome, ReloadPreparationServices,
};

pub(crate) enum ActorGenerationCommit {
    Published {
        generation: Arc<ActorGeneration>,
        cancellation_pending: bool,
    },
    Refused(ActorGenerationPublicationIssue),
    Unconfirmed(ActorGenerationPublicationIssue),
}

#[derive(Debug, thiserror::Error)]
pub(crate) enum ActorGenerationPublicationIssue {
    #[error("{0}")]
    Detail(String),
    #[error(transparent)]
    Durable(Box<tidepool_runtime::session::SessionError>),
}

impl From<String> for ActorGenerationPublicationIssue {
    fn from(detail: String) -> Self {
        Self::Detail(detail)
    }
}

impl From<&str> for ActorGenerationPublicationIssue {
    fn from(detail: &str) -> Self {
        Self::Detail(detail.into())
    }
}

impl ActorGenerationPublicationIssue {
    pub(crate) fn failure_diagnostic(
        &self,
    ) -> Option<tidepool_toolchain::failclass::FailureEnvelope> {
        match self {
            Self::Detail(_) => None,
            Self::Durable(error) => Some(tidepool_runtime::failclass::classify_session(error)),
        }
    }
}

#[cfg(test)]
impl ActorGenerationCommit {
    fn into_initial_generation(self) -> Result<Arc<ActorGeneration>, ResidentActorWorkbenchError> {
        match self {
            Self::Published { generation, .. } => Ok(generation),
            Self::Refused(ActorGenerationPublicationIssue::Detail(detail)) => {
                Err(ResidentActorWorkbenchError::ActorProtocol(detail))
            }
            Self::Refused(ActorGenerationPublicationIssue::Durable(error)) => Err(
                ResidentActorWorkbenchError::Resident(ResidentError::Session(*error)),
            ),
            outcome @ Self::Unconfirmed(_) => {
                Err(ResidentActorWorkbenchError::PublicationSettlement {
                    failure: Box::new(ActorPublicationSettlementFailure {
                        outcome: Arc::new(Ok(outcome)),
                        settlement: PublicationSettlementError::PublicationUnconfirmed,
                    }),
                })
            }
        }
    }
}

/// A primary publication outcome and its independent failed source settlement.
/// The outcome stays typed until the actor's final diagnostic boundary.
pub struct ActorPublicationSettlementFailure {
    outcome: Arc<Result<ActorGenerationCommit, ResidentActorWorkbenchError>>,
    settlement: PublicationSettlementError,
}

impl std::fmt::Debug for ActorPublicationSettlementFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ActorPublicationSettlementFailure")
            .field("settlement", &self.settlement)
            .field("primary", &self.to_string())
            .finish()
    }
}

impl std::fmt::Display for ActorPublicationSettlementFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self.outcome.as_ref() {
            Ok(ActorGenerationCommit::Published { generation, .. }) => {
                write!(formatter, "generation {:?} became visible", generation.id())?;
            }
            Ok(ActorGenerationCommit::Refused(reason)) => {
                write!(formatter, "publication refused: {reason}")?
            }
            Ok(ActorGenerationCommit::Unconfirmed(reason)) => {
                write!(formatter, "publication unconfirmed: {reason}")?
            }
            Err(error) => write!(formatter, "{error}")?,
        }
        write!(formatter, "; source settlement failed: {}", self.settlement)
    }
}

impl std::error::Error for ActorPublicationSettlementFailure {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.settlement)
    }
}

#[derive(Clone, Copy)]
pub(crate) enum ActorGenerationPublication {
    Terminal,
    Continuing,
}

/// Bootstrap policies precede generation publication. Production requests
/// retain one complete generation rather than independently selected heads.
#[derive(Clone)]
pub(crate) enum ActorRequestSnapshot {
    Bootstrap(InstalledToolLease),
    SourceCallback(InstalledToolLease),
    Generation(Arc<ActorGeneration>),
}

impl ActorRequestSnapshot {
    pub(crate) fn source_dependency(&self) -> &generation_admission::SourceDependency {
        self.installation().source_dependency()
    }
    pub(crate) fn select(&self, name: &str) -> Option<InstalledToolSelection> {
        let mut selected = self.installation().select(name)?;
        selected.snapshot = self.clone();
        Some(selected)
    }

    pub(crate) fn installation(&self) -> &InstalledToolLease {
        match self {
            Self::Bootstrap(lease) | Self::SourceCallback(lease) => lease,
            Self::Generation(generation) => &generation.installation,
        }
    }

    pub(crate) fn generation(&self) -> Option<&Arc<ActorGeneration>> {
        match self {
            Self::Bootstrap(_) | Self::SourceCallback(_) => None,
            Self::Generation(generation) => Some(generation),
        }
    }
}

/// The actor's single current installation. Requests clone an immutable lease;
/// spec reload replaces the paired source and handlers at source visibility.
#[derive(Default)]
pub(crate) struct InstalledToolsState(Mutex<InstalledToolsRecord>);

#[derive(Default)]
struct InstalledToolsRecord {
    availability: InstalledToolsAvailability,
    reply: Option<Arc<crate::RequestReplyActivation>>,
}

/// Custody removed by one terminal drain. Dropping it releases the installation
/// and reply owners after the state lock has been released.
pub(crate) struct InstalledToolsDrain {
    _availability: InstalledToolsAvailability,
    _reply: Option<Arc<crate::RequestReplyActivation>>,
}

#[derive(Default)]
enum InstalledToolsAvailability {
    #[default]
    Empty,
    /// No later publication may install into a retired actor's state.
    Retired,
    Available(InstalledToolLease),
    Generation(Arc<ActorGeneration>),
    GenerationUnavailable(Arc<ActorGeneration>),
    PublicationInProgress(Arc<ActorPublicationAttempt>),
    PublicationUnavailable(Arc<ActorPublicationAttempt>),
    PublicationVisible {
        attempt: Arc<ActorPublicationAttempt>,
        generation: Arc<ActorGeneration>,
    },
    InitialPublicationUnconfirmed(Box<UnconfirmedInitialPublication>),
}

pub(crate) enum InstalledToolsObservation {
    Empty,
    Available(Option<Arc<ResidentWorkbenchTools>>),
    SourceUnavailable(Option<Arc<ResidentWorkbenchTools>>),
}

impl InstalledToolsAvailability {
    fn available(&self) -> Option<&InstalledToolLease> {
        match self {
            Self::Available(lease) => Some(lease),
            Self::Generation(generation) => Some(&generation.installation),
            Self::Empty
            | Self::Retired
            | Self::GenerationUnavailable(_)
            | Self::InitialPublicationUnconfirmed(_)
            | Self::PublicationInProgress(_)
            | Self::PublicationUnavailable(_) => None,
            Self::PublicationVisible { .. } => None,
        }
    }
}

/// Expected bootstrap state captured by its existing initialization owner.
pub(crate) enum BootstrapExpectation<'a> {
    Empty,
    Available(&'a InstalledToolLease),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub(crate) enum BootstrapInstallationError {
    #[error("bootstrap installation changed before publication")]
    Changed,
    #[error("bootstrap cannot install into a retired actor")]
    Retired,
    #[error("bootstrap cannot replace a published generation")]
    PublishedGeneration,
    #[error("bootstrap cannot replace an unconfirmed generation")]
    UnconfirmedGeneration,
}

impl InstalledToolsState {
    /// Keep the publication check and observation publication under the same
    /// installation lock; a reload cannot slip between them.
    pub(crate) fn with_current_generation<T>(
        &self,
        expected: &Arc<ActorGeneration>,
        observe: impl FnOnce() -> T,
    ) -> Option<T> {
        let state = self.0.lock();
        match &state.availability {
            InstalledToolsAvailability::Generation(current) if Arc::ptr_eq(current, expected) => {
                Some(observe())
            }
            _ => None,
        }
    }
    pub(crate) fn active_reply(&self) -> Option<Arc<crate::RequestReplyActivation>> {
        self.0.lock().reply.clone()
    }
    /// A retired actor accepts no new reply custody. Existing holders keep their
    /// own clones; clearing an absent reply remains a no-op success.
    pub(crate) fn publish_reply(&self, reply: Option<Arc<crate::RequestReplyActivation>>) -> bool {
        let mut state = self.0.lock();
        if matches!(state.availability, InstalledToolsAvailability::Retired) {
            return reply.is_none();
        }
        state.reply = reply;
        true
    }

    pub(crate) fn observe(&self) -> InstalledToolsObservation {
        match &self.0.lock().availability {
            InstalledToolsAvailability::Empty | InstalledToolsAvailability::Retired => {
                InstalledToolsObservation::Empty
            }
            InstalledToolsAvailability::Available(lease) => {
                InstalledToolsObservation::Available(lease.tools_arc())
            }
            InstalledToolsAvailability::Generation(generation) => {
                InstalledToolsObservation::Available(generation.installation.tools_arc())
            }
            InstalledToolsAvailability::GenerationUnavailable(generation) => {
                InstalledToolsObservation::SourceUnavailable(generation.installation.tools_arc())
            }
            InstalledToolsAvailability::InitialPublicationUnconfirmed(pending) => {
                InstalledToolsObservation::SourceUnavailable(pending.previous.tools_arc())
            }
            InstalledToolsAvailability::PublicationInProgress(attempt)
            | InstalledToolsAvailability::PublicationUnavailable(attempt) => {
                InstalledToolsObservation::SourceUnavailable(
                    attempt.expected.installation().tools_arc(),
                )
            }
            InstalledToolsAvailability::PublicationVisible { generation, .. } => {
                InstalledToolsObservation::SourceUnavailable(generation.installation.tools_arc())
            }
        }
    }

    pub(crate) fn current(&self) -> Option<InstalledToolLease> {
        self.0.lock().availability.available().cloned()
    }

    pub(crate) fn snapshot_for_call(
        &self,
    ) -> Result<ActorRequestSnapshot, crate::ResidentToolError> {
        let unavailable = |actor| {
            crate::ResidentToolError::Invocation(crate::KernelInvocationFailure::Rejected {
                receipts: Vec::new(),
                actor,
                detail: "actor's installed source is unavailable".into(),
                diagnostic: None,
            })
        };
        match &self.0.lock().availability {
            InstalledToolsAvailability::Available(lease) => {
                Ok(ActorRequestSnapshot::Bootstrap(lease.clone()))
            }
            InstalledToolsAvailability::Generation(generation) => {
                Ok(ActorRequestSnapshot::Generation(generation.clone()))
            }
            InstalledToolsAvailability::Empty | InstalledToolsAvailability::Retired => {
                Err(crate::ResidentToolError::Unavailable(
                    "actor has no installed endpoint snapshot".into(),
                ))
            }
            InstalledToolsAvailability::GenerationUnavailable(generation) => {
                Err(unavailable(generation.context.actor))
            }
            InstalledToolsAvailability::InitialPublicationUnconfirmed(pending) => {
                Err(unavailable(pending.candidate.context.actor))
            }
            InstalledToolsAvailability::PublicationInProgress(attempt)
            | InstalledToolsAvailability::PublicationUnavailable(attempt) => {
                Err(unavailable(attempt.expected.installation().actor()))
            }
            InstalledToolsAvailability::PublicationVisible { generation, .. } => {
                Err(unavailable(generation.context.actor))
            }
        }
    }

    /// Bootstrap installation cannot replace a published or uncertain generation.
    pub(crate) fn install_bootstrap(
        &self,
        expected: BootstrapExpectation<'_>,
        lease: InstalledToolLease,
    ) -> Result<(), BootstrapInstallationError> {
        let mut state = self.0.lock();
        match (&state.availability, expected) {
            (InstalledToolsAvailability::Retired, _) => {
                return Err(BootstrapInstallationError::Retired)
            }
            (InstalledToolsAvailability::Generation(_), _) => {
                return Err(BootstrapInstallationError::PublishedGeneration)
            }
            (
                InstalledToolsAvailability::GenerationUnavailable(_)
                | InstalledToolsAvailability::InitialPublicationUnconfirmed(_)
                | InstalledToolsAvailability::PublicationInProgress(_)
                | InstalledToolsAvailability::PublicationUnavailable(_),
                _,
            ) => return Err(BootstrapInstallationError::UnconfirmedGeneration),
            (InstalledToolsAvailability::PublicationVisible { .. }, _) => {
                return Err(BootstrapInstallationError::UnconfirmedGeneration)
            }
            (InstalledToolsAvailability::Empty, BootstrapExpectation::Empty) => {}
            (
                InstalledToolsAvailability::Available(active),
                BootstrapExpectation::Available(expected),
            ) if active.same_installation(expected) && active.actor() == lease.actor() => {}
            _ => return Err(BootstrapInstallationError::Changed),
        }
        state.availability = InstalledToolsAvailability::Available(lease);
        Ok(())
    }

    pub(crate) fn current_tools(&self) -> Option<Arc<ResidentWorkbenchTools>> {
        self.current()?.tools_arc()
    }

    pub(crate) fn snapshot(&self) -> Option<ActorRequestSnapshot> {
        self.snapshot_for_call().ok()
    }

    pub(crate) fn current_generation(&self) -> Option<Arc<ActorGeneration>> {
        self.snapshot()?.generation().cloned()
    }

    /// Publish against the exact admitted implementation. Accepted calls retain
    /// their immutable lease, including when this actor replaces its own tools.
    pub(crate) fn replace_explicit(
        &self,
        expected: &InstalledToolLease,
        tools: Arc<ResidentWorkbenchTools>,
    ) -> Result<(), SpecReplacementError> {
        let mut state = self.0.lock();
        let active = state
            .availability
            .available()
            .ok_or(SpecReplacementError::Unavailable)?;
        if active.actor() != expected.actor()
            || active.source().semantic_digest() != expected.source().semantic_digest()
            || !active
                .tools_arc()
                .zip(expected.tools_arc())
                .is_some_and(|(active, expected)| Arc::ptr_eq(&active, &expected))
        {
            return Err(SpecReplacementError::Unavailable);
        }
        let old = active.tools().ok_or(SpecReplacementError::Unavailable)?;
        if !exomonad_tool::surface::compare_surfaces(&old.surface(), &tools.surface()).is_empty() {
            return Err(SpecReplacementError::SurfaceChanged);
        }
        let mut replacement =
            InstalledToolLease::new(expected.actor(), expected.source().clone(), Some(tools));
        replacement.dependency = active.dependency.clone();
        let published = match &state.availability {
            InstalledToolsAvailability::Generation(generation) => {
                InstalledToolsAvailability::Generation(Arc::new(ActorGeneration {
                    id: generation.id,
                    installation: replacement,
                    prompts: generation.prompts.clone(),
                    context: generation.context.clone(),
                    public_owner: generation.public_owner.clone(),
                    scope: generation.scope.clone(),
                    configuration_digest: generation.configuration_digest,
                    durable: generation.durable.clone(),
                }))
            }
            _ => InstalledToolsAvailability::Available(replacement),
        };
        state.availability = published;
        Ok(())
    }

    /// One terminal transition for both state-owned slots. The returned owners
    /// are dropped by the caller after the lock is released.
    pub(crate) fn drain_retired(&self) -> InstalledToolsDrain {
        let mut state = self.0.lock();
        let availability =
            std::mem::replace(&mut state.availability, InstalledToolsAvailability::Retired);
        let reply = state.reply.take();
        InstalledToolsDrain {
            _availability: availability,
            _reply: reply,
        }
    }

    #[cfg(test)]
    pub(crate) fn is_retired(&self) -> bool {
        matches!(
            self.0.lock().availability,
            InstalledToolsAvailability::Retired
        )
    }
}

impl<H, O> ResidentActorWorkbench<H, O>
where
    H: DispatchEffect<O> + Send + 'static,
    O: OutputSink + Sync + 'static,
{
    pub(crate) async fn startup_generation(
        &self,
        context: crate::ActorSessionContext,
        descriptor: crate::ActorDescriptor,
        predecessor: Option<crate::ActorRef>,
    ) -> Result<
        Option<tidepool_runtime::session::ActiveNotebookGeneration>,
        ResidentActorWorkbenchError,
    > {
        self.access
            .with_machine(context, move |session, context, _| {
                let Some(path) = descriptor.actor_path() else {
                    return Ok(None);
                };
                let owner = tidepool_runtime::session::RecoveryPublicOwner::new(
                    path,
                    context.actor.incarnation.0,
                )
                .ok_or_else(|| {
                    ResidentActorWorkbenchError::ActorProtocol(
                        "startup generation has no canonical actor owner".into(),
                    )
                })?;
                if let Some(head) = session
                    .active_notebook_generation(&owner)
                    .map_err(ResidentError::Session)?
                {
                    return Ok(Some(head));
                }
                let Some(predecessor) = predecessor else {
                    return Ok(None);
                };
                let previous = tidepool_runtime::session::RecoveryPublicOwner::new(
                    path,
                    predecessor.incarnation.0,
                )
                .ok_or_else(|| {
                    ResidentActorWorkbenchError::ActorProtocol(
                        "startup predecessor has no canonical actor owner".into(),
                    )
                })?;
                session
                    .active_notebook_generation(&previous)
                    .map_err(|error| {
                        ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                    })
            })
            .await
    }

    /// Startup preparation derives its expected bootstrap from the actual owner.
    /// Reload preparation uses its separately admitted immutable generation.
    pub(crate) async fn prepare_initial_generation(
        &self,
        state: Arc<InstalledToolsState>,
        context: crate::ActorSessionContext,
        descriptor: crate::ActorDescriptor,
        installation: InstalledToolLease,
        prompts: tidepool_runtime::session::ComposedPromptSnapshot,
    ) -> Result<PreparedActorGeneration, ResidentActorWorkbenchError> {
        let expected = state.snapshot().ok_or_else(|| {
            ResidentActorWorkbenchError::ActorProtocol(
                "initial generation lost bootstrap source custody".into(),
            )
        })?;
        if !matches!(expected, ActorRequestSnapshot::Bootstrap(_)) {
            return Err(ResidentActorWorkbenchError::ActorProtocol(
                "initial generation already published".into(),
            ));
        }
        self.prepare_actor_generation(context, descriptor, expected, installation, prompts)
            .await
    }

    async fn prepare_actor_generation(
        &self,
        context: crate::ActorSessionContext,
        descriptor: crate::ActorDescriptor,
        expected_snapshot: ActorRequestSnapshot,
        installation: InstalledToolLease,
        prompts: tidepool_runtime::session::ComposedPromptSnapshot,
    ) -> Result<PreparedActorGeneration, ResidentActorWorkbenchError> {
        self.prepare_actor_generation_in(
            context,
            descriptor,
            expected_snapshot,
            installation,
            prompts,
            None,
        )
        .await
    }

    async fn prepare_actor_generation_in(
        &self,
        context: crate::ActorSessionContext,
        descriptor: crate::ActorDescriptor,
        expected_snapshot: ActorRequestSnapshot,
        installation: InstalledToolLease,
        prompts: tidepool_runtime::session::ComposedPromptSnapshot,
        unpublished: Option<tidepool_runtime::session::UnpublishedNotebookScope>,
    ) -> Result<PreparedActorGeneration, ResidentActorWorkbenchError> {
        if context.actor != installation.actor()
            || expected_snapshot.installation().actor() != context.actor
        {
            return Err(ResidentActorWorkbenchError::ActorProtocol(
                "generation preparation actor does not own installation".into(),
            ));
        }
        let mut observed = installation
            .observe_generation()
            .map_err(ResidentActorWorkbenchError::ActorProtocol)?;
        let configuration_digest = observed.configuration_digest;
        let expected = expected_snapshot.generation().cloned();
        let checkout_context = context.clone();
        // Erasing the generic registry retains its actual allocation identity.
        let machine_owner = {
            let owner: Arc<dyn std::any::Any + Send + Sync> = self.access.machines.clone();
            Arc::downgrade(&owner)
        };
        let source = expected
            .as_ref()
            .and_then(|_| observed.lease.tools.as_ref())
            .and_then(|tools| tools._source_original.clone());
        let preparing = self
            .access
            .with_continuation_machine(context, move |session, context, _, _| {
                let _source_claim = context.source_dependency().claim()?;
                let mut next_context = context.clone();
                let prerequisite = expected.as_ref().map_or_else(
                    || match context.source_dependency() {
                        generation_admission::SourceDependency::World(world) => {
                            world.prerequisite().clone()
                        }
                        generation_admission::SourceDependency::Generation(parent) => {
                            Some(parent.clone())
                        }
                        generation_admission::SourceDependency::Unqualified => None,
                    },
                    |generation| generation.dependency().prerequisite().clone(),
                );
                let scope = if let Some(owner) = &unpublished {
                    owner.lease().clone()
                } else if expected.is_some() {
                    let retained = session
                        .mint_notebook_scope_with_lease(
                            prerequisite
                                .as_ref()
                                .map(|dependency| dependency.runtime_lease().clone()),
                        )
                        .map_err(ResidentError::Session)?;
                    next_context.placement.lexical_scope = retained.scope();
                    // A replacement notebook inherits no notebook facades, bindings or imports.
                    next_context.source_imports = crate::ActorSourceImports::default();
                    retained
                } else {
                    session
                        .adopt_initial_notebook_scope_with_source(
                            context.placement.lexical_scope,
                            prerequisite
                                .as_ref()
                                .map(|dependency| dependency.runtime_lease().clone()),
                        )
                        .map_err(ResidentError::Session)?
                };
                session.validate_lexical_scope_lease(scope.scope(), &scope)?;
                let mut installation;
                #[cfg(test)]
                let installation_work;
                let commit = match descriptor.persistence_policy() {
                    crate::ActorPersistencePolicy::Ephemeral => {
                        #[cfg(test)]
                        {
                            installation_work = observed.work;
                        }
                        installation = observed.lease;
                        if let Some(selection) = source {
                            let pending = session
                                .stage_published_source_originals_in(scope.scope(), selection)?;
                            session.publish_source_originals(pending)?;
                        }
                        PreparedGenerationCommit::Ephemeral {
                            id: expected
                                .as_ref()
                                .map_or(
                                    Ok(tidepool_runtime::session::NotebookGenerationId::INITIAL),
                                    |generation| generation.id.next(),
                                )
                                .map_err(|error| {
                                    ResidentActorWorkbenchError::ActorProtocol(error.to_string())
                                })?,
                        }
                    }
                    crate::ActorPersistencePolicy::Durable => {
                        let owner = descriptor
                            .actor_path()
                            .and_then(|path| {
                                tidepool_runtime::session::RecoveryPublicOwner::new(
                                    path,
                                    context.actor.incarnation.0,
                                )
                            })
                            .ok_or_else(|| {
                                ResidentActorWorkbenchError::ActorProtocol(
                                    "durable generation has no canonical actor owner".into(),
                                )
                            })?;
                        let restored = if expected.is_none() {
                            session
                                .active_notebook_generation(&owner)
                                .map_err(ResidentError::Session)?
                        } else {
                            None
                        };
                        if let Some(selected) = restored {
                            observed
                                .verify_restored(&selected.references, &prompts)
                                .map_err(ResidentActorWorkbenchError::ActorProtocol)?;
                            let readiness = session
                                .durable_public_readiness(&selected.owner, scope.scope())
                                .map_err(ResidentError::Session)?;
                            #[cfg(test)]
                            {
                                installation_work = observed.work;
                            }
                            installation = observed.lease;
                            PreparedGenerationCommit::Restored {
                                selected,
                                readiness,
                            }
                        } else {
                            let encoded = observed
                                .into_durable_references(prompts.clone())
                                .map_err(ResidentActorWorkbenchError::ActorProtocol)?;
                            #[cfg(test)]
                            {
                                installation_work = encoded.work;
                            }
                            installation = encoded.lease;
                            let references = encoded.references;
                            let prepared = session
                                .prepare_notebook_generation(
                                    scope.scope(),
                                    &owner,
                                    expected
                                        .as_ref()
                                        .and_then(|generation| generation.durable.clone()),
                                    references,
                                    source,
                                )
                                .map_err(ResidentError::Session)?;
                            let selected = prepared.selection();
                            PreparedGenerationCommit::Durable { prepared, selected }
                        }
                    }
                };
                let native_owner = match &commit {
                    PreparedGenerationCommit::Ephemeral { .. } => None,
                    PreparedGenerationCommit::Restored { selected, .. } => Some(&selected.owner),
                    PreparedGenerationCommit::Durable { prepared, .. } => Some(prepared.owner()),
                };
                let generation = match &commit {
                    PreparedGenerationCommit::Ephemeral { id, .. } => *id,
                    PreparedGenerationCommit::Restored { selected, .. }
                    | PreparedGenerationCommit::Durable { selected, .. } => selected.generation(),
                };
                let dependency = if unpublished.is_some() {
                    match context.source_dependency() {
                        generation_admission::SourceDependency::Generation(dependency)
                            if dependency.generation() == generation
                                && Arc::ptr_eq(dependency.runtime_lease(), &scope) =>
                        {
                            generation_admission::SourceDependency::Generation(dependency.clone())
                        }
                        _ => {
                            return Err(
                                generation_admission::GenerationAdmissionError::StaleSourceLease
                                    .into(),
                            )
                        }
                    }
                } else {
                    generation_admission::SourceDependency::Generation(
                        generation_admission::GenerationDependency::new(
                            context.actor,
                            generation,
                            installation.source().clone(),
                            &scope,
                            prerequisite,
                        ),
                    )
                };
                installation.dependency = dependency.clone();
                next_context.source_dependency = dependency;
                let public_owner = crate::resident_actor::WorkbenchPublicOwner::prepare_generation(
                    &next_context,
                    &descriptor,
                    &scope,
                    native_owner,
                )?;
                Ok(PreparingActorGeneration {
                    unpublished,
                    machine_owner,
                    checkout_context,
                    expected: expected_snapshot,
                    prompts,
                    configuration_digest,
                    #[cfg(test)]
                    installation_work,
                    installation,
                    context: next_context,
                    scope,
                    commit,
                    public_owner,
                })
            })
            .await?;
        self.complete_actor_generation_world(preparing).await
    }

    async fn complete_actor_generation_world(
        &self,
        preparing: PreparingActorGeneration,
    ) -> Result<PreparedActorGeneration, ResidentActorWorkbenchError> {
        let source = preparing.installation.source().clone();
        let reference = source
            .generation_evidence()
            .ok_or_else(|| {
                ResidentActorWorkbenchError::ActorProtocol(
                    "candidate compiler world lacks its frozen source evidence".into(),
                )
            })?
            .reference
            .clone();
        let context = preparing.context.clone();
        let capture_reference = reference.clone();
        let (preparing, admitted) = self
            .access
            .with_compiler_machine(context.clone(), move |session, _, _, _| {
                let admitted = match &preparing.commit {
                    PreparedGenerationCommit::Durable { prepared, .. } => session
                        .capture_notebook_generation_world(
                            prepared,
                            preparing.scope.original_source(),
                        )
                        .map_err(ResidentError::Session)?,
                    _ => session
                        .capture_inspection_world_in(
                            preparing.scope.scope(),
                            &capture_reference,
                            preparing.scope.original_source(),
                        )
                        .map_err(ResidentError::Session)?,
                };
                Ok((preparing, admitted))
            })
            .await?;
        let dependency = context.source_dependency().clone();
        let work = crate::capabilities::CompilerOwnerScope::current()?
            .with_source_dependency(&dependency)
            .admit_work()?;
        let mut cancel_on_drop = CancelCompilerTransactionOnDrop(Some(work.control()));
        let completed = crate::call_timing::timed_compile(spawn_blocking_in_span(move || {
            let settled = work.run_source_compiler_phase(
                &dependency,
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                |owner, _| tidepool_runtime::session::run_admitted_compiler_world(owner, admitted, || {
                    source.capture_compiler_sources().map_err(|error| match error {
                        crate::SourceInspectionError::Unavailable(detail) => tidepool_runtime::session::WorldInspectionError::SourceUnavailable(detail),
                        crate::SourceInspectionError::Unreadable(detail) => tidepool_runtime::session::WorldInspectionError::SourceUnreadable(detail),
                    })
                }),
            ).map_err(ResidentActorWorkbenchError::from)?;
            tidepool_runtime::session::finish_admitted_compiler_world(settled)
                .map_err(ResidentActorWorkbenchError::WorldInspection)
        })).await.map_err(ResidentActorWorkbenchError::Join)??;
        cancel_on_drop.0 = None;
        let compiler_world = Arc::new(completed);
        if matches!(
            &preparing.commit,
            PreparedGenerationCommit::Restored { .. } | PreparedGenerationCommit::Ephemeral { .. }
        ) {
            let install = compiler_world.clone();
            let original = preparing.scope.original_source().clone();
            self.access
                .with_compiler_machine(context, move |session, _, _, _| {
                    if !session.install_compiler_world_if_current(&install, &reference, &original) {
                        return Err(ResidentActorWorkbenchError::ActorProtocol(
                            "candidate compiler world changed before installation".into(),
                        ));
                    }
                    Ok(())
                })
                .await?;
        }
        let commit = match preparing.commit {
            PreparedGenerationCommit::Durable { prepared, selected } => {
                PreparedGenerationCommit::Durable {
                    prepared: prepared
                        .with_compiler_world(compiler_world.clone())
                        .map_err(ResidentError::Session)?,
                    selected,
                }
            }
            PreparedGenerationCommit::Restored {
                selected,
                readiness,
            } => PreparedGenerationCommit::Restored {
                selected,
                readiness,
            },
            PreparedGenerationCommit::Ephemeral { id } => {
                PreparedGenerationCommit::Ephemeral { id }
            }
        };
        Ok(PreparedActorGeneration {
            machine_owner: preparing.machine_owner,
            checkout_context: preparing.checkout_context,
            expected: preparing.expected,
            reload_report: None,
            unpublished: preparing.unpublished,
            candidate: Arc::new(ActorGenerationCandidate {
                installation: preparing.installation,
                prompts: preparing.prompts,
                configuration_digest: preparing.configuration_digest,
                context: preparing.context,
                scope: preparing.scope,
                compiler_world,
            }),
            commit,
            public_owner: preparing.public_owner,
            #[cfg(test)]
            installation_work: preparing.installation_work,
        })
    }

    /// The existing machine checkout and one actor issuance fence own publication.
    /// Native code preparation and immutable artifact capture finish beforehand.
    pub(crate) fn generation_publisher(
        &self,
        state: Arc<InstalledToolsState>,
        owner: ActorPublicationOwner,
    ) -> ActorGenerationPublisher<H, O> {
        ActorGenerationPublisher {
            access: self.access.sharing(),
            state,
            owner,
            #[cfg(test)]
            settlement_probe: None,
            #[cfg(test)]
            disposal_probe: None,
        }
    }
}

use crate::tool_contract::decode_installation;
#[cfg(test)]
use crate::tool_contract::SpecInstallation;

impl ResidentWorkbenchTools {
    fn slots(&self) -> Vec<String> {
        self.after_tool
            .iter()
            .map(|_| "afterTool".to_owned())
            .chain(
                self.initial_context
                    .iter()
                    .map(|_| "initialContext".to_owned()),
            )
            .collect()
    }

    pub(crate) fn declaration_snapshot(&self) -> Arc<[exomonad_tool::HostedTool]> {
        Arc::clone(&self.declarations)
    }

    pub(crate) fn surface(&self) -> Vec<exomonad_tool::HostedTool> {
        self.declarations.to_vec()
    }

    /// The installer revision, not the revision of every reachable closure.
    pub(crate) fn revision(&self) -> Option<&str> {
        self.code
            .prepared()
            .map(|prepared| prepared.source_revision.as_str())
    }

    pub(crate) fn resolved_spec(&self) -> Option<&crate::agent_spec::ResolvedSpec> {
        self.code.prepared().map(|prepared| &prepared.resolved)
    }

    pub(crate) fn origin_description(&self) -> String {
        match self.resolved_spec() {
            Some(resolved) => resolved.describe(),
            None => "origin=explicit live spec".into(),
        }
    }

    /// The provenance a completed call records: this record, and the revision
    /// it was built from.
    pub(crate) fn provenance(&self) -> String {
        format!(
            "install={} revision={} {}",
            self.install,
            self.revision().unwrap_or("(run)"),
            self.origin_description()
        )
    }
}

/// Shared-machine registry shape used by actors. String holes are only the
/// registry's checkout index; obligation-carrying `ResidentHole` values stay
/// inside each running segment.
pub type ActorMachineRegistry<H, O> = SessionRegistry<ResidentSession<H, O>, String>;

/// Read-only counters for matched resident performance measurements.
///
/// Every value comes from the session's existing codegen, heap, or residency
/// authority. `None` means the prepared machine has not bootstrapped yet;
/// callers must preserve that distinction instead of reporting zero.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
pub struct ResidentMachineMeasurement {
    pub native_functions: Option<u64>,
    pub native_code_bytes: Option<u64>,
    pub live_old_bytes: Option<usize>,
    pub major_collections: Option<u64>,
    pub programs: Option<usize>,
    pub block_words: Option<usize>,
    pub persistent_roots: Option<usize>,
    pub handles: Option<usize>,
    pub code_exports: Option<usize>,
    pub parked: Option<usize>,
    pub static_regions: Option<usize>,
    pub descriptor_rows: Option<usize>,
    pub callable_rows: Option<usize>,
    pub enter_rows: Option<usize>,
}

impl ResidentMachineMeasurement {
    fn of<H, O>(session: &ResidentSession<H, O>) -> Self
    where
        H: DispatchEffect<O> + Send,
        O: OutputSink + Sync,
    {
        let residency = session.residency();
        let codegen = session.codegen_totals();
        let heap = session.heap_stats();
        Self {
            native_functions: codegen.map(|(functions, _)| functions),
            native_code_bytes: codegen.map(|(_, bytes)| bytes),
            live_old_bytes: heap.map(|stats| stats.live_bytes),
            major_collections: heap.map(|stats| stats.gc_count),
            programs: residency.map(|counts| counts.programs),
            block_words: residency.map(|counts| counts.block_words),
            persistent_roots: residency.map(|counts| counts.persistent_roots),
            handles: residency.map(|counts| counts.handles),
            code_exports: residency.map(|counts| counts.code_exports),
            parked: residency.map(|counts| counts.parked),
            static_regions: residency.map(|counts| counts.static_regions),
            descriptor_rows: residency.map(|counts| counts.descriptor_rows),
            callable_rows: residency.map(|counts| counts.callable_rows),
            enter_rows: residency.map(|counts| counts.enter_rows),
        }
    }
}

/// The fixed nominal type and compiler recipe for an original host binding.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum HostCarrierKind {
    Job,
    Json,
    Text,
}

impl HostCarrierKind {
    fn host_binding_type(self) -> HostBindingType {
        match self {
            HostCarrierKind::Job => HostBindingType::COMMAND_JOB,
            HostCarrierKind::Json => HostBindingType::JSON_VALUE,
            HostCarrierKind::Text => HostBindingType::TEXT,
        }
    }

    fn type_name(self) -> &'static str {
        match self {
            HostCarrierKind::Job => COMMAND_JOB_TYPE_NAME,
            HostCarrierKind::Json => JSON_INPUT_TYPE_NAME,
            HostCarrierKind::Text => TEXT_BINDING_TYPE_NAME,
        }
    }

    fn anchor(self) -> &'static str {
        match self {
            HostCarrierKind::Job => COMMAND_JOB_ANCHOR,
            HostCarrierKind::Json => JSON_INPUT_ANCHOR,
            HostCarrierKind::Text => TEXT_BINDING_ANCHOR,
        }
    }

    fn imports(self) -> SourceImports {
        match self {
            HostCarrierKind::Job => command_job_carrier_imports(),
            HostCarrierKind::Json => json_input_carrier_imports(),
            HostCarrierKind::Text => text_binding_carrier_imports(),
        }
    }
}

/// Shared checkout boundary for every actor machine entry path. Fenced
/// fragments and installed actor programs differ above this layer, but use
/// exactly the same admission and settlement mechanism. Every checkout
/// installs the supplied actor context before invoking its operation, so a
/// child cannot leak its lexical scope, runtime resource scope, or principal into the
/// next parent or sibling entry.
///
/// An immutable observation of the actual handler instances in a checkout.
pub type HandlerEffectSupport<H> =
    Arc<dyn Fn(&H) -> Vec<exomonad_tool::ToolEffectKey> + Send + Sync + 'static>;

struct ResidentMachineAccess<H, O> {
    machines: Arc<ActorMachineRegistry<H, O>>,
    source: BoundActorWorkbenchSource,
    capabilities: crate::capabilities::WorkbenchServices,
    handler_effect_support: HandlerEffectSupport<H>,
    /// Builds a fresh, idle machine for a session id this host has decided
    /// deserves its own — installed once by the composition root; `None`
    /// keeps every launch on the shared session, unchanged, which is also
    /// today's behavior everywhere this hasn't been wired up yet. See
    /// [`crate::start::child_session_eligibility`] for the one caller that
    /// consults this.
    child_session_factory: Option<ChildSessionFactory<H, O>>,
    /// The compiled turn a fresh child session bootstraps with before
    /// anything imports into it — the SAME program the composition root
    /// itself bootstrapped with (`bridge/facade`'s `compile_root`), so a
    /// child's image matches the parent's for whatever a transferred entry's
    /// constituent objects need to resolve. Installed once by the
    /// composition root, alongside [`Self::child_session_factory`]; `None`
    /// makes [`ResidentActorRunner::provision_child_session`] refuse
    /// (there's a factory but nothing to bootstrap the machine it builds
    /// with — `ResidentSession::import_parcel` and `set_image_registry` both
    /// require an already-bootstrapped engine).
    child_bootstrap_program: Option<Arc<tidepool_runtime::session::CompiledTurn>>,
    /// This run's shared [`tidepool_runtime::session::ImageRegistry`], if
    /// the composition root installed one — `None` leaves every session
    /// compiling its own images, unchanged. Applied to a session's engine
    /// on every checkout ([`Self::with_host_machine`]): a no-op before that
    /// session's own first turn bootstraps its engine (there is nothing yet
    /// to share an image with — see
    /// [`tidepool_runtime::session::ResidentSession::set_image_registry`]),
    /// so a session's bootstrap install is never a hit, but every later
    /// install on that session, root or child alike, can be.
    image_registry: Option<Arc<tidepool_runtime::session::ImageRegistry>>,
    /// Sessions `provision_child_session` built — a launch's OWN
    /// dedicated machine, as opposed to the run's single shared session
    /// (never a member here, and never torn down). Membership is what makes
    /// a session id eligible for `ResidentActorRunner::retire_child_session`
    /// at all.
    child_sessions: Arc<std::sync::Mutex<std::collections::HashSet<tidepool_repr::SessionId>>>,
    /// Dedicated child sessions whose actor has retired but whose machine
    /// still held at least one live value handle. Each entry owns the one
    /// cleanup worker and its custody-drop signal until checkout settlement
    /// removes the entry.
    pending_child_teardown: Arc<
        std::sync::Mutex<
            std::collections::HashMap<tidepool_repr::SessionId, Arc<PendingChildTeardown>>,
        >,
    >,
    // The `compile_blocking` span omits `include_roots` from every line (the
    // full search path is long and rarely changes turn to turn); this tracks
    // the last-logged roots per session so a diagnostic reader still sees
    // them once, and again whenever they actually change.
    logged_include_roots:
        std::sync::Mutex<std::collections::HashMap<tidepool_repr::SessionId, String>>,
}

/// One detached cleanup owner for a retired dedicated child session. The
/// worker handle remains here so tests can prove the actual task finished,
/// rather than treating session removal alone as sufficient evidence.
struct PendingChildTeardown {
    wake: Arc<tokio::sync::Notify>,
    #[cfg(test)]
    initial_checkout_complete: std::sync::atomic::AtomicBool,
    #[cfg(test)]
    worker: std::sync::Mutex<Option<tokio::task::JoinHandle<()>>>,
}

impl PendingChildTeardown {
    fn new() -> Self {
        Self {
            wake: Arc::new(tokio::sync::Notify::new()),
            #[cfg(test)]
            initial_checkout_complete: std::sync::atomic::AtomicBool::new(false),
            #[cfg(test)]
            worker: std::sync::Mutex::new(None),
        }
    }
}

fn reject_activation_declaration<H, O>(
    session: &ResidentSession<H, O>,
    scope: ScopeId,
) -> Result<(), ResidentActorWorkbenchError>
where
    H: DispatchEffect<O> + Send,
    O: OutputSink + Sync,
{
    if session
        .current_decl_heads_in(scope)
        .iter()
        .any(|(name, _)| name == "sessionInput")
    {
        return Err(ResidentActorWorkbenchError::InputMount(
            "sessionInput is reserved for activation input; remove its authored declaration before activating".into(),
        ));
    }
    Ok(())
}

struct CancelCompilerTransactionOnDrop(Option<crate::termination::CompilerWorkControl>);

impl Drop for CancelCompilerTransactionOnDrop {
    fn drop(&mut self) {
        if let Some(cancellation) = self.0.take() {
            cancellation.cancel();
        }
    }
}

impl<H, O> ResidentMachineAccess<H, O> {
    fn new(machines: Arc<ActorMachineRegistry<H, O>>, source: BoundActorWorkbenchSource) -> Self {
        Self {
            machines,
            source,
            capabilities: crate::capabilities::WorkbenchServices::new(),
            handler_effect_support: Arc::new(|_| Vec::new()),
            child_session_factory: None,
            child_bootstrap_program: None,
            image_registry: None,
            child_sessions: Arc::new(std::sync::Mutex::new(std::collections::HashSet::new())),
            pending_child_teardown: Arc::new(std::sync::Mutex::new(
                std::collections::HashMap::new(),
            )),
            logged_include_roots: std::sync::Mutex::new(std::collections::HashMap::new()),
        }
    }

    /// Another entry point into the same machine registry, source, and
    /// carrier cache as `self` — used wherever the runner mints another
    /// workbench or runner for the same actor rather than an independent
    /// one, so a carrier built for one turn serves every later turn instead
    /// of being rebuilt each time a fresh `ResidentActorWorkbench` is
    /// constructed per call.
    fn sharing(&self) -> Self {
        Self {
            machines: Arc::clone(&self.machines),
            source: self.source.clone(),
            capabilities: self.capabilities.clone(),
            handler_effect_support: self.handler_effect_support.clone(),
            child_session_factory: self.child_session_factory.clone(),
            child_bootstrap_program: self.child_bootstrap_program.clone(),
            image_registry: self.image_registry.clone(),
            child_sessions: Arc::clone(&self.child_sessions),
            pending_child_teardown: Arc::clone(&self.pending_child_teardown),
            logged_include_roots: std::sync::Mutex::new(std::collections::HashMap::new()),
        }
    }

    fn owns_pending_child_teardown(
        &self,
        session_id: tidepool_repr::SessionId,
        owner: &Arc<PendingChildTeardown>,
    ) -> bool {
        self.pending_child_teardown
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(&session_id)
            .is_some_and(|current| Arc::ptr_eq(current, owner))
    }

    /// Complete terminal child cleanup under the same membership/owner lock
    /// order as retirement admission. An older worker cannot erase a different
    /// pending owner; terminal checkout settlement may complete the current one.
    fn finish_child_session_teardown(
        &self,
        session_id: tidepool_repr::SessionId,
        expected_owner: Option<&Arc<PendingChildTeardown>>,
    ) -> bool {
        let (removed_child, owner) = {
            let mut children = self
                .child_sessions
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let mut pending = self
                .pending_child_teardown
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if expected_owner.is_some_and(|owner| {
                !pending
                    .get(&session_id)
                    .is_some_and(|current| Arc::ptr_eq(current, owner))
            }) {
                return false;
            }
            (children.remove(&session_id), pending.remove(&session_id))
        };
        if let Some(owner) = &owner {
            owner.wake.notify_one();
        }
        removed_child || owner.is_some()
    }
}

/// Builds a fresh, idle [`ResidentSession`] for a session id the caller has
/// already minted — the composition root's one factory, installed once and
/// called by [`ResidentActorRunner::provision_child_session`] with the child's
/// fixed source layer. `Fn`, not `FnOnce`: called once per eligible child for
/// the life of the host.
pub type ChildSessionFactory<H, O> = Arc<
    dyn Fn(
            tidepool_repr::SessionId,
            &[PathBuf],
            &mut dyn FnMut(tidepool_runtime::CompilerTransactionClose),
        ) -> Result<Box<ResidentSession<H, O>>, String>
        + Send
        + Sync,
>;

/// Keeps an original host binding leased until its consumer accepts or abandons it.
/// Drop schedules retirement through the owning machine checkout.
struct HostInputRetirement {
    input: MountedHostInput,
    _lease: tidepool_runtime::session::resident::BindingLease,
    background_retire: Box<dyn FnOnce() + Send>,
    retire_private: Option<
        Box<
            dyn FnOnce(
                    tidepool_runtime::session::PendingHostValueWrite,
                ) -> futures_util::future::BoxFuture<
                    'static,
                    Result<
                        tidepool_runtime::session::PendingHostValueWrite,
                        ResidentActorWorkbenchError,
                    >,
                > + Send,
        >,
    >,
    write: Option<tidepool_runtime::session::PendingHostValueWrite>,
    private: Option<Arc<tidepool_runtime::session::PrivateExecutionAdmission>>,
}

impl HostInputRetirement {
    fn new<H, O>(
        access: &ResidentMachineAccess<H, O>,
        context: crate::ActorSessionContext,
        input: MountedHostInput,
        lease: tidepool_runtime::session::resident::BindingLease,
        write: tidepool_runtime::session::PendingHostValueWrite,
        private: Option<Arc<tidepool_runtime::session::PrivateExecutionAdmission>>,
    ) -> Self
    where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        let background_retire: Box<dyn FnOnce() + Send> = {
            let machines = Arc::clone(&access.machines);
            let source = access.source.clone();
            let context = context.clone();
            let binder = input.binder.clone();
            Box::new(move || {
                tokio::spawn(async move {
                    let access = ResidentMachineAccess::new(machines, source);
                    if let Err(error) = access
                        .with_machine(context, move |session, ctx, _| {
                            let session_root =
                                carrier_mount_session_root(session, ctx.placement.lexical_scope)?;
                            session.retire_host_binding_owner(&session_root, &binder);
                            Ok(())
                        })
                        .await
                    {
                        tracing::warn!(
                            %error,
                            "failed to retire an abandoned host binding"
                        );
                    }
                });
            })
        };
        let retire_private = private.as_ref().map(|private| {
            let access = access.sharing();
            let context = context.clone();
            let binder = input.binder.clone();
            let private = private.clone();
            Box::new(
                move |write| -> futures_util::future::BoxFuture<
                    'static,
                    Result<
                        tidepool_runtime::session::PendingHostValueWrite,
                        ResidentActorWorkbenchError,
                    >,
                > {
                    Box::pin(async move {
                        access
                            .with_machine(context, move |session, _, _| {
                                session
                                    .retire_private_host_binding_owner(&private, &binder, &write)
                                    .map_err(ResidentActorWorkbenchError::Resident)?;
                                Ok(write)
                            })
                            .await
                    })
                },
            )
                as Box<
                    dyn FnOnce(
                            tidepool_runtime::session::PendingHostValueWrite,
                        ) -> futures_util::future::BoxFuture<
                            'static,
                            Result<
                                tidepool_runtime::session::PendingHostValueWrite,
                                ResidentActorWorkbenchError,
                            >,
                        > + Send,
                >
        });
        Self {
            input,
            _lease: lease,
            background_retire,
            retire_private,
            write: Some(write),
            private,
        }
    }

    fn keep_binding(mut self) -> Result<(), ResidentActorWorkbenchError> {
        if let Some(private) = &self.private {
            self.write
                .take()
                .expect("original host mount write")
                .accept(private)
                .map_err(|error| ResidentActorWorkbenchError::Resident(error.into()))?;
        }
        self.background_retire = Box::new(|| {});
        Ok(())
    }

    async fn retire_for_publication(&mut self) -> Result<(), ResidentActorWorkbenchError> {
        let retire = self.retire_private.take().ok_or_else(|| {
            ResidentActorWorkbenchError::ActorProtocol(
                "host input lacks its original private retirement owner".into(),
            )
        })?;
        let write = self.write.take().expect("original private input write");
        self.write = Some(retire(write).await?);
        // The exact owner has completed retirement under its source gates.
        // Abandonment continues to use generic cleanup through Drop.
        self.background_retire = Box::new(|| {});
        Ok(())
    }

    fn mounted_input(&self) -> &MountedHostInput {
        &self.input
    }
}

/// A named host result whose mount remains guarded until its owned effect step
/// accepts it. The name is presentation; the guard carries exact runtime proof.
pub(crate) struct RetainedHostBinding {
    name: String,
    mounted: Option<HostInputRetirement>,
}

impl RetainedHostBinding {
    pub(crate) fn name(&self) -> &str {
        &self.name
    }

    pub(crate) fn accept(self) -> Result<String, ResidentActorWorkbenchError> {
        if let Some(mounted) = self.mounted {
            mounted.keep_binding()?;
        }
        Ok(self.name)
    }
}

impl Drop for HostInputRetirement {
    fn drop(&mut self) {
        let background = std::mem::replace(&mut self.background_retire, Box::new(|| {}));
        background();
    }
}

/// Owns one invocation's exact parked continuations across machine checkouts.
/// A slot can suspend a nested helper while its earlier hole remains parked,
/// so every created id stays owned until the session reports its retirement.
/// The registration is cloned into blocking checkouts; a late suspension
/// observes abandonment and queues cleanup of only that invocation's ids.
pub(crate) struct ParkedHoleAbortGuard {
    shared: Arc<ParkedHoleAbortState>,
}

struct ParkedHoleAbortState {
    owner: Option<(crate::ActorRef, crate::ActorPlacement)>,
    abort: Arc<dyn Fn(String) + Send + Sync>,
    state: Mutex<ParkedHoleState>,
    reason: String,
    retained_authority: Option<Arc<dyn std::any::Any + Send + Sync>>,
    compiler_owner: std::sync::OnceLock<CompilerOwnerScope>,
}

enum ParkedHoleState {
    Owned(std::collections::BTreeSet<String>),
    Abandoned(std::collections::BTreeSet<String>),
    Settled,
}

impl ParkedHoleAbortGuard {
    fn new<H, O>(
        access: &ResidentMachineAccess<H, O>,
        context: crate::ActorSessionContext,
        cont_id: String,
        reason: String,
    ) -> Self
    where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        Self::with_latest(access, context, Some(cont_id), reason)
    }

    fn with_latest<H, O>(
        access: &ResidentMachineAccess<H, O>,
        context: crate::ActorSessionContext,
        latest: Option<String>,
        reason: String,
    ) -> Self
    where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        Self::with_retained_latest(access, context, latest, reason, None)
    }

    fn with_retained_latest<H, O>(
        access: &ResidentMachineAccess<H, O>,
        context: crate::ActorSessionContext,
        latest: Option<String>,
        reason: String,
        retained_authority: Option<Arc<dyn std::any::Any + Send + Sync>>,
    ) -> Self
    where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        let machines = Arc::clone(&access.machines);
        let source = access.source.clone();
        let cleanup_context = context.clone();
        let cleanup_reason = reason.clone();
        let runtime = tokio::runtime::Handle::current();
        let shared = Arc::new_cyclic(|weak: &std::sync::Weak<ParkedHoleAbortState>| {
            let weak = weak.clone();
            let abort: Arc<dyn Fn(String) + Send + Sync> = Arc::new(move |cont_id| {
                let machines = Arc::clone(&machines);
                let source = source.clone();
                let context = cleanup_context.clone();
                let reason = cleanup_reason.clone();
                let cleanup_id = cont_id.clone();
                let owner = weak.upgrade();
                runtime.spawn(async move {
                    let access = ResidentMachineAccess::new(machines, source);
                    let result = access
                        .with_machine(context, move |session, _, _| {
                            abort_owned_hole(session, cont_id.clone(), reason)
                        })
                        .await;
                    if let Err(error) = result {
                        tracing::warn!(cont_id = %cleanup_id, %error, "failed to abort an abandoned continuation");
                    } else if let Some(owner) = owner {
                        ParkedHoleAbortRegistration(owner)
                            .observe(ResidentContinuationEvent::Retired(cleanup_id));
                    }
                });
            });
            ParkedHoleAbortState {
                owner: Some((context.actor, context.placement)),
                abort,
                state: Mutex::new(ParkedHoleState::Owned(latest.into_iter().collect())),
                reason,
                retained_authority,
                compiler_owner: std::sync::OnceLock::new(),
            }
        });
        Self { shared }
    }

    pub(crate) fn with_compiler_owner(self, owner: CompilerOwnerScope) -> Self {
        assert!(
            self.shared.compiler_owner.set(owner).is_ok(),
            "cleanup owner is assigned once before native admission"
        );
        self
    }

    pub(crate) fn registration(&self) -> ParkedHoleAbortRegistration {
        ParkedHoleAbortRegistration(Arc::clone(&self.shared))
    }

    /// The owning checkout is in hand: the hole's fate is now decided
    /// synchronously within it, so no background cleanup is needed.
    pub(crate) fn disarm(self) {
        let mut state = self.shared.state.lock();
        *state = ParkedHoleState::Settled;
        drop(state);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContinuationHandoffFailure {
    WrongOwner,
    Abandoned,
    Settled,
    NotOwned,
}

impl Drop for ParkedHoleAbortGuard {
    fn drop(&mut self) {
        let abandoned = {
            let mut state = self.shared.state.lock();
            match std::mem::replace(&mut *state, ParkedHoleState::Settled) {
                ParkedHoleState::Owned(current) => {
                    *state = ParkedHoleState::Abandoned(current.clone());
                    current
                }
                ParkedHoleState::Abandoned(current) => {
                    *state = ParkedHoleState::Abandoned(current);
                    std::collections::BTreeSet::new()
                }
                ParkedHoleState::Settled => std::collections::BTreeSet::new(),
            }
        };
        for cont_id in abandoned {
            (self.shared.abort)(cont_id);
        }
    }
}

pub(crate) struct ParkedHoleAbortRegistration(Arc<ParkedHoleAbortState>);

impl Clone for ParkedHoleAbortRegistration {
    fn clone(&self) -> Self {
        Self(Arc::clone(&self.0))
    }
}

impl ParkedHoleAbortRegistration {
    fn abandon_for_acknowledgement(
        &self,
        context: &crate::ActorSessionContext,
    ) -> Result<(), ResidentActorWorkbenchError> {
        let owner_matches = self.0.owner.is_some_and(|(actor, placement)| {
            actor == context.actor && placement == context.placement
        });
        let private_matches = self
            .0
            .retained_authority
            .as_ref()
            .and_then(|authority| {
                authority.downcast_ref::<crate::resident_actor::ExecutionResourceOwners>()
            })
            .is_some_and(|resources| resources.authorizes_cleanup_context(context));
        if !owner_matches && !private_matches {
            return Err(ResidentActorWorkbenchError::ActorProtocol(
                "continuation cleanup differs from its admitted actor placement".into(),
            ));
        }
        let mut state = self.0.state.lock();
        if let ParkedHoleState::Owned(current) = &mut *state {
            *state = ParkedHoleState::Abandoned(std::mem::take(current));
        }
        Ok(())
    }

    fn awaiting_acknowledgement(&self) -> Vec<String> {
        match &*self.0.state.lock() {
            ParkedHoleState::Owned(current) | ParkedHoleState::Abandoned(current) => {
                current.iter().cloned().collect()
            }
            ParkedHoleState::Settled => Vec::new(),
        }
    }

    fn confirm_acknowledgement_in_checkout(&self) -> Result<(), ResidentActorWorkbenchError> {
        let mut state = self.0.state.lock();
        match &*state {
            ParkedHoleState::Owned(current) | ParkedHoleState::Abandoned(current)
                if !current.is_empty() =>
            {
                Err(ResidentActorWorkbenchError::ActorProtocol(
                    "native continuation cleanup remains unconfirmed".into(),
                ))
            }
            _ => {
                *state = ParkedHoleState::Owned(Default::default());
                Ok(())
            }
        }
    }

    pub(crate) async fn scope<F: std::future::Future>(&self, operation: F) -> F::Output {
        let compiler_owner = self.0.compiler_owner.get().cloned();
        let scoped = SLOT_CONTINUATION_OWNER.scope(self.clone(), operation);
        match compiler_owner {
            Some(owner) => owner.scope(scoped).await,
            None => scoped.await,
        }
    }

    pub(crate) fn sync_scope<T>(&self, operation: impl FnOnce() -> T) -> T {
        let compiler_owner = self.0.compiler_owner.get().cloned();
        match compiler_owner {
            Some(owner) => {
                owner.sync_scope(|| SLOT_CONTINUATION_OWNER.sync_scope(self.clone(), operation))
            }
            None => SLOT_CONTINUATION_OWNER.sync_scope(self.clone(), operation),
        }
    }

    pub(crate) fn spawn_blocking<T: Send + 'static>(
        &self,
        timing: Option<crate::call_timing::CallTimingRegistration>,
        operation: impl FnOnce() -> T + Send + 'static,
    ) -> tokio::task::JoinHandle<T> {
        let cleanup = self.clone();
        spawn_blocking_in_span(move || {
            let scoped = || cleanup.sync_scope(operation);
            match timing {
                Some(timing) => timing.sync_scope(scoped),
                None => scoped(),
            }
        })
    }

    fn observe(&self, event: ResidentContinuationEvent) {
        let abort = {
            let mut state = self.0.state.lock();
            match event {
                ResidentContinuationEvent::Parked(cont_id) => match &mut *state {
                    ParkedHoleState::Owned(current) => {
                        current.insert(cont_id);
                        None
                    }
                    ParkedHoleState::Abandoned(current) => {
                        current.insert(cont_id.clone()).then_some(cont_id)
                    }
                    ParkedHoleState::Settled => None,
                },
                ResidentContinuationEvent::Retired(cont_id) => {
                    match &mut *state {
                        ParkedHoleState::Owned(current) | ParkedHoleState::Abandoned(current) => {
                            current.remove(&cont_id);
                        }
                        ParkedHoleState::Settled => {}
                    }
                    None
                }
            }
        };
        if let Some(cont_id) = abort {
            (self.0.abort)(cont_id);
        }
    }

    /// Transfer ownership to the exact continuation returned by this
    /// checkout. If the async owner was dropped while the blocking operation
    /// ran, settle the late successor before releasing the checked-out
    /// session.
    fn replace_in_checkout<H, O>(
        &self,
        session: &mut ResidentSession<H, O>,
        outcome: &ResidentOutcome,
    ) where
        H: DispatchEffect<O> + Send,
        O: OutputSink + Sync,
    {
        let successor = outcome_continuation_id(outcome);
        let abandoned = {
            let mut state = self.0.state.lock();
            match std::mem::replace(&mut *state, ParkedHoleState::Settled) {
                ParkedHoleState::Abandoned(_) => {
                    *state = ParkedHoleState::Abandoned(successor.clone().into_iter().collect());
                    true
                }
                ParkedHoleState::Owned(_) => {
                    *state = successor
                        .clone()
                        .map_or(ParkedHoleState::Settled, |cont_id| {
                            ParkedHoleState::Owned(std::iter::once(cont_id).collect())
                        });
                    false
                }
                ParkedHoleState::Settled => false,
            }
        };
        if abandoned {
            let reason = self.0.reason.clone();
            if let Some(cont_id) = successor {
                if let Err(error) = abort_owned_hole(session, cont_id.clone(), reason) {
                    tracing::warn!(%cont_id, %error, "failed to abort a late continuation after its owner was dropped");
                    (self.0.abort)(cont_id);
                } else {
                    self.observe(ResidentContinuationEvent::Retired(cont_id));
                }
            }
        }
    }
}

fn outcome_continuation_id(outcome: &ResidentOutcome) -> Option<String> {
    match outcome {
        ResidentOutcome::Suspended { hole, .. } | ResidentOutcome::Deferred { hole, .. } => {
            Some(hole.cont_id().to_owned())
        }
        ResidentOutcome::Completed { .. } | ResidentOutcome::BindingsCommitted { .. } => None,
    }
}

fn abort_owned_hole<H, O>(
    session: &mut ResidentSession<H, O>,
    cont_id: String,
    reason: String,
) -> Result<(), ResidentActorWorkbenchError>
where
    H: DispatchEffect<O> + Send,
    O: OutputSink + Sync,
{
    if !session.parked_holes().contains(&cont_id.as_str()) {
        return Ok(());
    }
    let outcome = session.abort(&cont_id, reason);
    if !session.parked_holes().contains(&cont_id.as_str()) {
        return Ok(());
    }
    match outcome {
        Err(error) => Err(ResidentActorWorkbenchError::Resident(error)),
        Ok(_) => Err(ResidentActorWorkbenchError::ActorProtocol(format!(
            "aborting continuation {cont_id} left it parked"
        ))),
    }
}

