    #[tokio::test]
    async fn empty_checkpoint_retirement_preserves_nonempty_machine_admission() {
        with_test_compiler_owner(empty_checkpoint_retirement_preserves_nonempty_machine_admission_with_preparation_client).await
    }

    async fn empty_checkpoint_retirement_preserves_nonempty_machine_admission_with_preparation_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, context, source, _root) = actor_registry_fixture();
        let runner = ResidentActorRunner::new(
            machines.clone(),
            (source).bind_preparation(preparation_client.clone()),
        );
        let id = context.placement.session;
        let mut checkout = machines.checkout_run(id).unwrap();
        let scope = checkout.machine().mint_isolated_scope();
        let mut empty = Box::pin(runner.retire_checkpoint_scopes(id, Vec::new()));
        assert!(
            matches!(
                futures_util::poll!(&mut empty),
                std::task::Poll::Ready(Ok(()))
            ),
            "an empty issued selection has no machine work"
        );
        drop(empty);
        let mut nonempty = Box::pin(runner.retire_checkpoint_scopes(id, vec![scope]));
        assert!(
            futures_util::poll!(&mut nonempty).is_pending(),
            "a real scope still waits for its owning machine"
        );
        assert!(checkout.machine().compile_view_in(scope).is_some());
        checkout.restore_suspended(Vec::new());
        nonempty.await.unwrap();
        let mut checkout = machines.checkout_run(id).unwrap();
        assert!(checkout.machine().compile_view_in(scope).is_none());
        assert!(checkout.machine().compile_view_in(ScopeId::ROOT).is_some());
        checkout.restore_suspended(Vec::new());
    }

    #[tokio::test]
    async fn shared_reload_view_preserves_installed_support_without_expanding_grants() {
        struct InstalledJev;
        impl crate::JevBackend for InstalledJev {
            fn ask(
                &self,
                _: String,
            ) -> futures_util::future::BoxFuture<'_, Result<String, crate::JevCallFailure>>
            {
                unreachable!("support observation must not execute judgment")
            }
        }
        for present in [false, true] {
            let jev: crate::JevBackendHandle = if present {
                Arc::new(InstalledJev)
            } else {
                crate::unconfigured_jev()
            };
            let conversation: crate::ConversationReader =
                Arc::new(|_, _| Box::pin(async { Err(crate::ConversationUnavailable::Unbound) }));
            let intrinsic = crate::installed_intrinsic_effect_support(
                None,
                &jev,
                None,
                present.then_some(&conversation),
            );
            let config = ActorWorkbenchSource::new("", Vec::new())
                .with_spec("Fixture.agentSpec")
                .with_installed_effect_support([exomonad_tool::ToolEffectKey::Actor(
                    crate::ActorEffectKey::FsRead,
                )]);
            with_test_bound_source(config, move |source| async move {
                let startup =
                    ResidentActorWorkbench::<frunk::HNil, tidepool_mcp::CapturedOutput>::new(
                        Arc::new(ActorMachineRegistry::new()),
                        source,
                        None,
                    )
                    .with_intrinsic_effect_support(intrinsic);
                let reload = startup.shared_view();
                let granted = [
                    crate::ActorEffectKey::Replies,
                    crate::ActorEffectKey::Reflect,
                    crate::ActorEffectKey::Jev,
                    crate::ActorEffectKey::Console,
                    crate::ActorEffectKey::FsRead,
                    crate::ActorEffectKey::Source,
                    crate::ActorEffectKey::ModelCallOpenAI,
                ];
                let recipe =
                    |view: &ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>| {
                        view.access
                            .source
                            .config
                            .source_toolset_recipe(
                                &crate::CheckpointSourceLayer::default(),
                                &granted,
                                view.access.source.config.installed_effect_support(),
                            )
                            .unwrap()
                    };
                let initial = recipe(&startup);
                let candidate = recipe(&reload);
                assert_eq!(candidate, initial);
                let expected = granted
                    .into_iter()
                    .filter(|key| {
                        !matches!(
                            key,
                            crate::ActorEffectKey::Source | crate::ActorEffectKey::ModelCallOpenAI
                        ) && (present
                            || !matches!(
                                key,
                                crate::ActorEffectKey::Jev | crate::ActorEffectKey::Reflect
                            ))
                    })
                    .collect::<Vec<_>>();
                assert_eq!(candidate.effective_effects, expected);
                assert!(reload
                    .access
                    .source
                    .config
                    .installed_effect_support()
                    .contains(&exomonad_tool::ToolEffectKey::Actor(
                        crate::ActorEffectKey::Commands
                    )));
                assert!(
                    !candidate
                        .effective_effects
                        .contains(&crate::ActorEffectKey::Commands),
                    "installed interpreter support cannot create an ungranted effect"
                );
                assert!(
                    !candidate
                        .effective_effects
                        .contains(&crate::ActorEffectKey::Source),
                    "an absent source owner cannot become installed support"
                );
                assert!(!candidate
                    .effective_effects
                    .contains(&crate::ActorEffectKey::ModelCallOpenAI));
            })
            .await;
        }
    }

    #[test]
    fn selected_spec_import_belongs_to_installer_only() {
        let source = ActorWorkbenchSource::new(String::new(), Vec::new())
            .with_imports("qualified PublicNotebook");
        let selected = source.clone().with_spec("PrivatePolicy.agentSpec");
        let public_imports = source.workbench_imports.template_text();
        assert_eq!(selected.workbench_imports.template_text(), public_imports);
        for template in resident_workbench_templates(&selected.preamble, "'[]", &public_imports) {
            // Decl is a parser-only template with no authored preamble.
            if template.kind == tidepool_runtime::session::TemplateSelector::Decl {
                continue;
            }
            let notebook =
                tidepool_runtime::session::render_template(&template.source, "pure ()", &[]);
            assert!(notebook.contains("import qualified PublicNotebook"));
            assert!(!notebook.contains("PrivatePolicy"));
            assert!(!notebook.contains("Tidepool.Actors.Exomonad"));
        }

        let effects = [
            crate::ActorEffectKey::Replies,
            crate::ActorEffectKey::Watches,
        ];
        let supported = effects.map(exomonad_tool::ToolEffectKey::Actor);
        let (recipe, resolved) = selected
            .installer_recipe(
                &crate::CheckpointSourceLayer::default(),
                &effects,
                &supported,
            )
            .unwrap();
        assert_eq!(resolved.entry.as_deref(), Some("PrivatePolicy.agentSpec"));
        assert_eq!(recipe.entry, "PrivatePolicy.agentSpec");
        let installation =
            crate::agent_spec::installation_expression(&recipe.entry, &recipe.effects);
        let templates = resident_workbench_templates(
            &recipe.preamble,
            installation.dispatcher_effect_row().expression(),
            &recipe.imports,
        );
        let template = templates
            .iter()
            .find(|template| {
                template.kind == tidepool_runtime::session::TemplateSelector::BindDiscard
            })
            .unwrap();
        let installer = tidepool_runtime::session::render_template(
            &template.source,
            &installation.expression,
            &[],
        );
        assert!(installer.contains("import qualified PrivatePolicy"));
        assert!(installer.contains("import qualified Tidepool.Agent.Contract"));
        assert!(!installer.contains("import qualified Tidepool.Actors.Exomonad"));
        assert!(installer.contains("Tidepool.Agent.Reply.Internal.Replies"));
        assert!(installer.contains("Tidepool.Agent.Watch.Internal.Watches"));
        assert!(installer.contains("PrivatePolicy.agentSpec"));
        assert!(!installer.contains("import qualified PublicNotebook"));
    }

    proptest::proptest! {
        #[test]
        fn builtin_selection_preserves_override_precedence_and_exact_row(
            removed in 0usize..exomonad_tool::DEFAULT_ACTOR_EFFECTS.len(),
            context_support in proptest::prelude::any::<bool>(),
        ) {
            use crate::agent_spec::SpecRule;
            let standard = exomonad_tool::DEFAULT_ACTOR_EFFECTS;
            let support = if context_support {
                exomonad_tool::ToolEffectKey::ALL.iter().copied().filter(|effect| effect.is_invocation_only()).collect::<Vec<_>>()
            } else { Vec::new() };
            let expected = if context_support { crate::BuiltinToolsetPolicy::Workbench }
                else { crate::BuiltinToolsetPolicy::AsyncWorkbench };
            proptest::prop_assert_eq!(builtin_toolset_policy(SpecRule::BuiltinDefault, standard, &support), Some(expected));
            for rule in [SpecRule::RunModule, SpecRule::WorkspaceSpec] {
                proptest::prop_assert_eq!(builtin_toolset_policy(rule, standard, &support), None);
            }
            let mut narrowed = standard.to_vec();
            narrowed.remove(removed);
            proptest::prop_assert_eq!(builtin_toolset_policy(SpecRule::BuiltinDefault, &narrowed, &support), None);
            let mut reordered = standard.to_vec();
            reordered.rotate_left(removed + 1);
            if reordered != standard {
                proptest::prop_assert_eq!(builtin_toolset_policy(SpecRule::BuiltinDefault, &reordered, &support), None);
            }
        }

        #[test]
        fn source_toolset_recipe_projects_public_rows_in_requested_order(
            mask in proptest::prelude::any::<u64>(),
            context_support in proptest::prelude::any::<bool>(),
        ) {
            let workbench = ActorWorkbenchSource::new(String::new(), Vec::new());
            let source = crate::CheckpointSourceLayer::default();
            let before = tidepool_extract_cmd::extract_spawn_count();
            for requested in [exomonad_tool::DEFAULT_ACTOR_EFFECTS] {
              for selected_mask in [0, u64::MAX, mask] {
                let members = requested.iter().enumerate()
                    .filter(|(index, _)| selected_mask & (1_u64 << *index) != 0)
                    .map(|(_, key)| *key)
                    .collect::<std::collections::HashSet<_>>();
                let expected = requested.iter().copied()
                    .filter(|key| members.contains(key))
                    .collect::<Vec<_>>();
                let mut support = members.iter().copied()
                    .map(exomonad_tool::ToolEffectKey::Actor)
                    .collect::<Vec<_>>();
                if context_support {
                    support.extend(exomonad_tool::ToolEffectKey::ALL.iter().copied().filter(|effect| effect.is_invocation_only()));
                }
                let actual = workbench.source_toolset_recipe(&source, requested, &support).unwrap();
                proptest::prop_assert_eq!(actual.requested_effects.as_slice(), requested);
                proptest::prop_assert_eq!(&actual.effective_effects, &expected);
                // Interpreter support is a membership observation. Its order
                // and repeated observations cannot change the installer row.
                support.reverse();
                support.extend(support.clone());
                let repeated = workbench.source_toolset_recipe(&source, requested, &support).unwrap();
                proptest::prop_assert_eq!(actual, repeated);
              }
            }
            proptest::prop_assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before);
        }
    }

    pub(crate) fn fixture_include_roots(effects: &tidepool_mcp::EffectsModuleDirs) -> Vec<PathBuf> {
        // Native resource locations can be relative to the runner's CWD.
        // Resolve only the source roots selected by the owning producers.
        let prelude = tidepool_testing::eval_harness::prelude_path()
            .canonicalize()
            .expect("declared stdlib sources are required");
        let actors = prelude
            .parent()
            .expect("stdlib source root has a parent")
            .join("actors")
            .canonicalize()
            .expect("declared actor Haskell sources are required");
        assert!(
            actors.join("Tidepool/Actors/Exomonad.hs").is_file(),
            "actor source root lacks Tidepool.Actors.Exomonad: {}",
            actors.display()
        );
        let mut include = effects
            .include_paths()
            .into_iter()
            .map(|root| {
                root.canonicalize().unwrap_or_else(|error| {
                    panic!("generated effect source root {}: {error}", root.display())
                })
            })
            .collect::<Vec<_>>();
        include.extend([prelude, actors]);
        assert!(
            include
                .iter()
                .all(|root| root.is_absolute() && root.is_dir()),
            "fixture compiler roots must be absolute existing directories: {include:?}"
        );
        include
    }

    fn host_mount_fixture() -> (
        ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
        ActorWorkbenchSource,
        tempfile::TempDir,
    ) {
        host_mount_fixture_with_lib(|_| {})
    }

    fn host_mount_fixture_with_lib(
        configure: impl FnOnce(&mut tidepool_runtime::session::SessionLib),
    ) -> (
        ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
        ActorWorkbenchSource,
        tempfile::TempDir,
    ) {
        host_mount_fixture_with_effects(
            configure,
            &[
                tidepool_mcp::notifications_decl(),
                tidepool_mcp::sleep_decl(),
            ],
            "'[Exomonad.Notifications, Sleep]",
        )
    }

    fn host_mount_fixture_with_effects(
        configure: impl FnOnce(&mut tidepool_runtime::session::SessionLib),
        declarations: &[tidepool_mcp::EffectDecl],
        effects_alias: &str,
    ) -> (
        ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
        ActorWorkbenchSource,
        tempfile::TempDir,
    ) {
        use tidepool_effect::{EffectRunPolicy, LivePayloadPolicy};
        use tidepool_runtime::session::{ModuleEnv, SessionLib};

        tidepool_testing::eval_harness::require_extract();
        let effects = tidepool_mcp::ensure_effects_module(declarations).expect("actor effects");
        let include = fixture_include_roots(&effects);
        let preamble = insert_preamble_imports(
            &tidepool_mcp::build_notebook_preamble(declarations, false),
            "qualified Tidepool.Actors.Exomonad as Exomonad",
        );
        let session_id = tidepool_repr::SessionId((u64::from(std::process::id()) << 16) | 4_244);
        let session_root = tempfile::tempdir().expect("session root");
        let mut lib = SessionLib::open(
            session_id,
            session_root.path(),
            ModuleEnv::standalone_default(),
        )
        .expect("declaration plane")
        .with_validation_include(include.clone());
        configure(&mut lib);
        let mut session = ResidentSession::unbootstrapped(
            frunk::HNil,
            tidepool_mcp::CapturedOutput::new(),
            tidepool_runtime::DEFAULT_NURSERY_SIZE,
            Some(lib),
        );
        let lexical_scope = session.mint_isolated_scope();
        let resource_scope = RealmId::fresh();
        session
            .set_actor_execution(
                tidepool_runtime::session::SessionRunContext {
                    lexical_scope,
                    resource_scope,
                    ..tidepool_runtime::session::SessionRunContext::ROOT
                },
                EffectRunPolicy::HandleOrSuspend,
                LivePayloadPolicy::HASKELL_EFFECT_VALUE,
            )
            .expect("actor execution context");
        let context = {
            let context_actor = crate::ActorRef::first(crate::ActorId(1));
            let context_placement = crate::ActorPlacement {
                session: session_id,
                resource_scope,
                lexical_scope,
            };
            crate::ActorSessionContext {
                actor: context_actor,
                placement: context_placement,
                effect_policy: EffectRunPolicy::HandleOrSuspend,
                live_payload: LivePayloadPolicy::HASKELL_EFFECT_VALUE,
                source_imports: crate::ActorSourceImports::default(),
                haskell_effects_alias: effects_alias.into(),
                current_model: None,
                source_layer: Vec::new().into(),
                ..crate::ActorDescriptor::new("fixture", context_placement)
                    .admit_independent_world()
                    .session_context(context_actor)
            }
        };
        (
            session,
            context,
            ActorWorkbenchSource::new(preamble, include),
            session_root,
        )
    }

