    /// A split compile takes its `ActorCompileView` snapshot, compiles
    /// off-checkout, then re-derives a fresh view before installing. With no
    /// mutation in between, the split
    /// path must publish the compiled Text binding.
    #[test]
    fn text_carrier_split_compile_then_install_publishes_the_binding() {
        let (mut session, context, source, _session_root) = host_mount_fixture();
        let scope = context.placement.lexical_scope;

        let view = actor_compile_view(&session, &context, &source).expect("compile view");
        let generation = view.next_value_generation();
        session.set_val_gen(generation);
        let retained = session.prepared_retained();

        let (binder, compiled) = compile_host_binding_off_checkout(
            &view,
            &source,
            context.haskell_effects_alias.expression(),
            generation,
            "text_binding",
            TEXT_BINDING_TYPE_NAME,
            TEXT_BINDING_ANCHOR,
            text_binding_carrier_imports(),
            true,
            &retained,
        )
        .expect("Text carrier compiles off-checkout");

        let fresh_view = actor_compile_view(&session, &context, &source).expect("fresh view");
        assert!(
            fresh_view.is_current_for(&view),
            "no mutation happened between snapshot and install: views must still match"
        );

        tidepool_testing::with_settlement(|settlement| {
            session.mount_text_binding_in(
                scope,
                &binder,
                generation,
                compiled.into_code(),
                "text payload",
                settlement,
            )
        })
        .expect("Text carrier installs after revalidation");

        assert!(session
            .binding_names_in(scope)
            .contains(&"text_binding".into()));
    }

    /// A write to the same scope between a split compile's snapshot and its
    /// re-checkout (here, another mount standing in for a concurrent
    /// actor's install) must be detected by `is_current_for` before
    /// installing the stale compile, and a fresh snapshot must still recover.
    #[test]
    fn a_mutation_between_split_checkouts_invalidates_the_snapshot_and_blocks_install() {
        let (mut session, context, source, _session_root) = host_mount_fixture();
        let scope = context.placement.lexical_scope;

        let view = actor_compile_view(&session, &context, &source).expect("compile view");
        let generation = view.next_value_generation();
        session.set_val_gen(generation);
        let retained = session.prepared_retained();

        let (binder, compiled) = compile_host_binding_off_checkout(
            &view,
            &source,
            context.haskell_effects_alias.expression(),
            generation,
            "text_binding",
            TEXT_BINDING_TYPE_NAME,
            TEXT_BINDING_ANCHOR,
            text_binding_carrier_imports(),
            true,
            &retained,
        )
        .expect("Text carrier compiles off-checkout");

        // Stand in for another actor writing to this exact scope while this
        // compile ran off-checkout: mount an unrelated Text carrier, which
        // changes `visible_values`/`shadowing`.
        mount_text_binding(
            &mut session,
            &context,
            &source,
            "interloper",
            "interloper text",
            None,
        )
        .expect("interloping carrier mounts");

        let fresh_view = actor_compile_view(&session, &context, &source).expect("fresh view");
        assert!(
            !fresh_view.is_current_for(&view),
            "an interleaved mutation to the same scope must invalidate the snapshot"
        );

        // The split path must refuse to install against a stale view — the
        // binder never reaches the persistent binding store.
        assert!(session
            .workbench_bindings_in(scope)
            .into_iter()
            .all(|binding| binding.name != "text_binding"));
        drop((binder, compiled, generation));

        // A fresh snapshot recompiles and installs cleanly.
        let retry_view = actor_compile_view(&session, &context, &source).expect("retry view");
        let retry_generation = retry_view.next_value_generation();
        session.set_val_gen(retry_generation);
        let retry_retained = session.prepared_retained();
        let (retry_binder, retry_compiled) = compile_host_binding_off_checkout(
            &retry_view,
            &source,
            context.haskell_effects_alias.expression(),
            retry_generation,
            "text_binding2",
            TEXT_BINDING_TYPE_NAME,
            TEXT_BINDING_ANCHOR,
            text_binding_carrier_imports(),
            true,
            &retry_retained,
        )
        .expect("recompile against the fresh snapshot succeeds");
        tidepool_testing::with_settlement(|settlement| {
            session.mount_text_binding_in(
                scope,
                &retry_binder,
                retry_generation,
                retry_compiled.into_code(),
                "retry text payload",
                settlement,
            )
        })
        .expect("recompiled carrier installs");
        assert!(session
            .binding_names_in(scope)
            .contains(&"text_binding2".into()));
    }

    /// Named-tool command output bindings reuse one cached Job carrier.
    #[test]
    fn job_carrier_failure_keeps_the_owned_command_recoverable() {
        let error = command_job_carrier_failure(
            "job-session-123",
            ResidentActorWorkbenchError::InputMount("typed completion input is unavailable".into()),
        );
        let ResidentActorWorkbenchError::InputMount(detail) = error else {
            panic!("carrier preparation failure should be reported at the binding mount boundary")
        };

        assert!(detail.contains("command job-session-123 remains owned"));
        assert!(detail.contains("no retained output binding was created"));
        assert!(detail.contains("typed completion input is unavailable"));
        assert!(detail.contains(
            "read_output session_id=job-session-123, stream=Stdout (or Stderr), offset=0"
        ));
        assert!(detail.contains("Do not rerun"));
        assert!(!detail.contains("retained as"));
    }

    #[tokio::test]
    async fn cleanup_scope_captures_compiler_owner_when_polled() {
        with_test_compiler_owner(cleanup_scope_captures_compiler_owner_when_polled_with_client)
            .await;
    }

    async fn cleanup_scope_captures_compiler_owner_when_polled_with_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let services = crate::capabilities::WorkbenchServices::new();
        let workbench = ResidentActorWorkbench::<frunk::HNil, tidepool_mcp::CapturedOutput>::new(
            Arc::new(crate::ActorMachineRegistry::new()),
            ActorWorkbenchSource::new("", Vec::new()).bind_preparation(preparation_client),
            None,
        );
        let descriptor = crate::ActorDescriptor::new(
            "lazy cleanup scope",
            crate::ActorPlacement {
                session: tidepool_repr::SessionId(991),
                resource_scope: RealmId::ROOT,
                lexical_scope: ScopeId::ROOT,
            },
        );
        let guard = workbench.actor_initialization_cleanup(
            descriptor.session_context(crate::ActorRef::first(crate::ActorId(991))),
        );
        let registration = guard.registration();
        let retained = crate::RetainedActorExit::new();
        let operation = registration.scope(async {
            crate::capabilities::CompilerOwnerScope::current()
                .and_then(|scope| scope.admit_work())
                .unwrap()
        });
        assert!(retained.compiler_close_observations().is_empty());
        let guard = guard.with_compiler_owner(
            services
                .with_compiler_owner(CompilerCloseOwner::ActorLifecycle(retained.clone()))
                .for_preparation(),
        );
        let ticket = operation.await;
        assert!(crate::capabilities::CompilerOwnerScope::current().is_err());
        assert!(matches!(
            retained.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Pending]
        ));
        ticket.run(|close| {
            close(tidepool_runtime::CompilerTransactionClose::NotStarted);
        });
        guard.disarm();
    }

    #[tokio::test]
    async fn actor_stop_interrupts_owned_host_work_before_source_read_and_recovers() {
        let services = crate::capabilities::WorkbenchServices::new();
        let control = crate::WorkbenchExecutionControl::untracked();
        let original = services
            .with_compiler_owner(CompilerCloseOwner::Hosted(control.clone()))
            .for_preparation();
        let (entered, observed) = tokio::sync::oneshot::channel();
        let (release, proceed) = std::sync::mpsc::channel();
        let directory = tempfile::tempdir().unwrap();
        let missing = directory.path().join("must-not-be-read");
        let task = tokio::spawn(async move {
            original
                .scope(async move {
                    let ticket = crate::capabilities::CompilerOwnerScope::current()
                        .and_then(|scope| scope.admit_work())
                        .unwrap();
                    spawn_blocking_in_span(move || {
                        ticket.run(|_settlement| {
                            entered.send(()).unwrap();
                            proceed.recv_timeout(Duration::from_secs(5)).unwrap();
                            // This is the real source-observation owner. Interruption
                            // must win over the absent path's filesystem failure.
                            let refused = tidepool_toolchain::cache::source_root_manifest(&missing);
                            let command = tidepool_extract_cmd::ExtractCmd::with_bin(
                                tidepool_extract_cmd::ResolvedExtractBin::assume_resolved(&missing),
                            );
                            let bind = command.bind().err().expect("stopped owner cannot bind");
                            assert_eq!(bind.source.kind(), std::io::ErrorKind::Interrupted);
                            assert!(bind.definitely_unsubmitted());
                            refused
                        })
                    })
                    .await
                    .unwrap()
                })
                .await
        });
        tokio::time::timeout(Duration::from_secs(5), observed)
            .await
            .unwrap()
            .unwrap();
        assert!(control.request_cancellation());
        assert!(control.publication_decision().claim_commit().is_none());
        release.send(()).unwrap();
        let error = tokio::time::timeout(Duration::from_secs(5), task)
            .await
            .unwrap()
            .unwrap()
            .unwrap_err();
        assert_eq!(error.source.kind(), std::io::ErrorKind::Interrupted);
        assert!(matches!(
            control.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Settled(
                tidepool_runtime::CompilerTransactionClose::NotStarted
            )]
        ));
        let fresh = crate::WorkbenchExecutionControl::untracked();
        let root = directory.path().to_path_buf();
        std::fs::write(
            root.join("Recovery.hs"),
            b"module Recovery where\nvalue = 1\n",
        )
        .unwrap();
        let result = services
            .with_compiler_owner(CompilerCloseOwner::Hosted(fresh.clone()))
            .for_preparation()
            .scope(async move {
                let ticket = crate::capabilities::CompilerOwnerScope::current()
                    .and_then(|scope| scope.admit_work())
                    .unwrap();
                spawn_blocking_in_span(move || {
                    ticket.run(|_settlement| tidepool_toolchain::cache::source_root_manifest(&root))
                })
                .await
                .unwrap()
                .unwrap()
            })
            .await;
        assert_eq!(result.len(), 1);
        assert!(matches!(
            fresh.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Settled(
                tidepool_runtime::CompilerTransactionClose::NotStarted
            )]
        ));
    }

    #[tokio::test]
    async fn commit_claimed_compiler_work_settles_after_losing_stop() {
        let services = crate::capabilities::WorkbenchServices::new();
        let control = crate::WorkbenchExecutionControl::untracked();
        let ticket = services
            .with_compiler_owner(CompilerCloseOwner::Hosted(control.clone()))
            .for_preparation()
            .admit_work()
            .unwrap();
        let claim = control.publication_decision().claim_commit().unwrap();
        let (entered, observed) = tokio::sync::oneshot::channel();
        let (release, proceed) = std::sync::mpsc::channel();
        let task = spawn_blocking_in_span(move || {
            ticket.run(|_settlement| {
                entered.send(()).unwrap();
                proceed.recv_timeout(Duration::from_secs(5)).unwrap();
                tidepool_extract_cmd::compiler_host_checkpoint()
            })
        });
        tokio::time::timeout(Duration::from_secs(5), observed)
            .await
            .unwrap()
            .unwrap();
        assert!(!control.request_cancellation());
        assert!(matches!(
            control.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Pending]
        ));
        release.send(()).unwrap();
        tokio::time::timeout(Duration::from_secs(5), task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        assert!(matches!(
            control.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Settled(
                tidepool_runtime::CompilerTransactionClose::NotStarted
            )]
        ));
        assert!(claim.published());
    }

    #[tokio::test]
    async fn cancelled_waiter_observes_shared_producer_completion_without_interrupting_it() {
        let services = crate::capabilities::WorkbenchServices::new();
        let control = crate::WorkbenchExecutionControl::untracked();
        let producer = crate::RetainedActorExit::new();
        let owner = services
            .with_compiler_owner(CompilerCloseOwner::Hosted(control.clone()))
            .for_preparation()
            .shared_preparation(producer.clone());
        let ticket = owner.admit_work().unwrap();
        let (entered, observed) = tokio::sync::oneshot::channel();
        let (release, proceed) = std::sync::mpsc::channel();
        let directory = tempfile::tempdir().unwrap();
        std::fs::write(
            directory.path().join("Shared.hs"),
            b"module Shared where\nvalue = 1\n",
        )
        .unwrap();
        let root = directory.path().to_path_buf();
        let work = spawn_blocking_in_span(move || {
            ticket.run(|_settlement| {
                entered.send(()).unwrap();
                proceed.recv_timeout(Duration::from_secs(5)).unwrap();
                tidepool_toolchain::cache::source_root_manifest(&root)
            })
        });
        tokio::time::timeout(Duration::from_secs(5), observed)
            .await
            .unwrap()
            .unwrap();
        assert!(control.request_cancellation());
        assert!(matches!(
            control.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Pending]
        ));
        assert!(matches!(
            producer.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Pending]
        ));
        release.send(()).unwrap();
        let completed = tokio::time::timeout(Duration::from_secs(5), work)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        assert_eq!(completed.len(), 1);
        for closes in [
            control.compiler_close_observations(),
            producer.compiler_close_observations(),
        ] {
            assert!(matches!(
                closes.as_slice(),
                [crate::termination::CompilerWorkClose::Settled(
                    tidepool_runtime::CompilerTransactionClose::NotStarted
                )]
            ));
        }
        assert!(directory.path().join("Shared.hs").exists());
    }

    #[tokio::test]
    async fn compiler_obligation_survives_waiter_loss_and_actor_stop_until_late_close() {
        let services = crate::capabilities::WorkbenchServices::new();
        let retained = crate::RetainedActorExit::new();
        let owner = services
            .with_compiler_owner(CompilerCloseOwner::ActorLifecycle(retained.clone()))
            .for_preparation();
        let (entered, observed) = std::sync::mpsc::channel();
        let (release, proceed) = std::sync::mpsc::channel();
        let (settled, settled_observation) = std::sync::mpsc::channel();
        let waiter = owner
            .scope(async {
                // Exercise the same admission boundary as every real compiler spawn.
                let ticket = crate::capabilities::CompilerOwnerScope::current()
                    .and_then(|scope| scope.admit_work())
                    .unwrap();
                let native = spawn_blocking_in_span(move || {
                    let action = ticket.run(|_settlement| {
                        entered.send(()).unwrap();
                        proceed
                            .recv_timeout(std::time::Duration::from_secs(5))
                            .unwrap();
                        Err::<(), _>("completed primary refusal")
                    });
                    settled.send(action).unwrap();
                });
                tokio::spawn(async move { native.await })
            })
            .await;
        observed
            .recv_timeout(std::time::Duration::from_secs(5))
            .unwrap();
        retained.retain_cleanup(crate::ResidentCleanupOutcome {
            actor: crate::ActorRef::first(crate::ActorId(1)),
            hook: crate::CleanupComponentOutcome::Confirmed,
            realm: crate::CleanupComponentOutcome::Confirmed,
            children: crate::CleanupComponentOutcome::Confirmed,
        });
        retained
            .publish(crate::ActorTerminal {
                kind: crate::ActorExitKind::Cancelled,
                summary: "stopped while compiler pending".into(),
                diagnostic: None,
            })
            .unwrap();
        assert!(!retained.cleanup().unwrap().is_confirmed());
        waiter.abort();
        assert!(waiter.await.unwrap_err().is_cancelled());
        assert!(!retained.cleanup().unwrap().is_confirmed());
        release.send(()).unwrap();
        assert_eq!(
            settled_observation
                .recv_timeout(std::time::Duration::from_secs(5))
                .unwrap(),
            Err("completed primary refusal")
        );
        assert!(retained.cleanup().unwrap().is_confirmed());
        assert_eq!(
            retained.get().unwrap().kind,
            crate::ActorExitKind::Cancelled
        );
    }

    #[tokio::test]
    async fn captured_preparation_owner_survives_waiter_loss_and_retirement() {
        let services = crate::capabilities::WorkbenchServices::new();
        let retained = crate::RetainedActorExit::new();
        let captured = services
            .with_compiler_owner(CompilerCloseOwner::ActorLifecycle(retained.clone()))
            .for_preparation()
            .scope(async { crate::capabilities::CompilerOwnerScope::current().unwrap() })
            .await;
        // Register before the task exists, using its captured actual owner.
        let ticket = captured.admit_work().unwrap();
        assert!(matches!(
            retained.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Pending]
        ));
        let (entered, observed) = tokio::sync::oneshot::channel();
        let (release, proceed) = std::sync::mpsc::channel();
        let (settled, completed) = std::sync::mpsc::channel();
        let waiter = tokio::spawn(async move {
            assert!(crate::capabilities::CompilerOwnerScope::current().is_err());
            spawn_blocking_in_span(move || {
                let action = ticket.run_for_workload(
                    tidepool_extract_cmd::CompileWorkload::Preparation,
                    |_settlement| {
                        entered.send(()).unwrap();
                        proceed
                            .recv_timeout(std::time::Duration::from_secs(5))
                            .unwrap();
                        Err::<(), _>("preparation action refused before compiler bind")
                    },
                );
                settled.send(action).unwrap();
            })
            .await
        });
        tokio::time::timeout(std::time::Duration::from_secs(5), observed)
            .await
            .unwrap()
            .unwrap();
        retained.retain_cleanup(crate::ResidentCleanupOutcome {
            actor: crate::ActorRef::first(crate::ActorId(1)),
            hook: crate::CleanupComponentOutcome::Confirmed,
            realm: crate::CleanupComponentOutcome::Confirmed,
            children: crate::CleanupComponentOutcome::Confirmed,
        });
        retained
            .publish(crate::ActorTerminal {
                kind: crate::ActorExitKind::Cancelled,
                summary: "retired with source preparation pending".into(),
                diagnostic: None,
            })
            .unwrap();
        assert!(!retained.cleanup().unwrap().is_confirmed());
        waiter.abort();
        assert!(waiter.await.unwrap_err().is_cancelled());
        assert!(!retained.cleanup().unwrap().is_confirmed());
        release.send(()).unwrap();
        assert_eq!(
            completed
                .recv_timeout(std::time::Duration::from_secs(5))
                .unwrap(),
            Err("preparation action refused before compiler bind")
        );
        assert!(retained.cleanup().unwrap().is_confirmed());
        assert!(matches!(
            retained.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Settled(
                tidepool_runtime::CompilerTransactionClose::NotStarted
            )]
        ));
        assert_eq!(
            retained.get().unwrap().kind,
            crate::ActorExitKind::Cancelled
        );
    }

