    async fn command_job_mounts_retain_original_checked_interfaces_and_reuse_exact_job_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        use tidepool_runtime::session::turn::HostBindingAuthority;
        let (machines, public, source, _root) = actor_registry_fixture();
        let (workbench, context) = ResidentActorWorkbench::new(
            machines,
            (source).bind_preparation(preparation_client.clone()),
            None,
        )
        .admit_private_cell_for_test(public.clone())
        .await
        .unwrap();
        let mut dispatcher_context = context.clone();
        dispatcher_context.haskell_effects_alias = format!(
            "(Tidepool.Effects.Core.AgentTools ': Tidepool.Effects.Core.ContextReadWrite ': {})",
            context.haskell_effects_alias.expression()
        )
        .into();
        assert!(!workbench
            .access
            .source
            .config
            .preamble
            .contains("import qualified Tidepool.Effects.Core"));
        let first = workbench
            .bind_command_job(dispatcher_context.clone(), "job one".into())
            .await
            .expect("first checked Job binding")
            .accept()
            .unwrap();
        let original = workbench
            .host_binding_identity_for_test(context.clone(), &first)
            .await;
        let before_repeat = tidepool_extract_cmd::extract_spawn_count();
        let repeated = workbench
            .bind_command_job(dispatcher_context.clone(), "job one".into())
            .await
            .expect("unchanged Job reuses its accepted original binder")
            .accept()
            .unwrap();
        assert_eq!(repeated, first);
        assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before_repeat);
        let first_fixture =
            tidepool_testing::fixture_source("exomonad/actor/src/fixtures/host-job-first.hs");
        workbench
            .execute_cell_for_test(context.clone(), &first_fixture.replace("{first}", &first))
            .await
            .unwrap();
        workbench
            .publish_completed_cell_for_test(context)
            .await
            .unwrap();
        let (workbench, context) = workbench
            .admit_private_cell_for_test(public.clone())
            .await
            .unwrap();
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), &first)
                .await,
            original
        );
        workbench
            .execute_cell_for_test(context.clone(), "data Job = SourceJob Bool")
            .await
            .unwrap();
        let before_second_job = tidepool_extract_cmd::extract_spawn_count();
        let before_second_interface =
            tidepool_toolchain::artifacts::host_binding_interface_request_count();
        let (carrier, dependencies) = workbench
            .prepare_host_input(
                crate::ActorSessionContext {
                    haskell_effects_alias: dispatcher_context.haskell_effects_alias.clone(),
                    ..context.clone()
                },
                HostCarrierKind::Job,
                None,
            )
            .await
            .expect("retained context still admits the original checked Job type");
        assert_eq!(
            tidepool_extract_cmd::extract_spawn_count(),
            before_second_job + 1
        );
        assert_eq!(
            tidepool_toolchain::artifacts::host_binding_interface_request_count(),
            before_second_interface + 1
        );
        assert!(
            carrier.checked_binding().is_err(),
            "fresh interface has no authored checked execution reservation"
        );
        let binder = carrier.binding().unwrap();
        assert_eq!(
            binder.host_authority,
            Some(HostBindingAuthority::CommandJob)
        );
        assert_ne!(
            tidepool_repr::SessionVarId::from_extract(binder.var_id),
            original.0
        );
        let carrier = workbench
            .refuse_host_payload_for_test(context.clone(), carrier)
            .await;
        let mounted = workbench
            .mount_prepared_host_input(
                context.clone(),
                carrier,
                OwnedHostPayload::Job("job two".into()),
                false,
            )
            .await
            .unwrap();
        let second = RetainedHostBinding {
            name: mounted.mounted_input().name.clone(),
            mounted: Some(mounted),
        }
        .accept()
        .unwrap();
        drop(dependencies);
        assert_ne!(first, second);
        let retained_fixture =
            tidepool_testing::fixture_source("exomonad/actor/src/fixtures/host-job-retained.hs");
        workbench
            .execute_cell_for_test(
                context.clone(),
                &retained_fixture
                    .replace("{first}", &first)
                    .replace("{second}", &second),
            )
            .await
            .unwrap();
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), &first)
                .await,
            original
        );
        let before_repeat = tidepool_extract_cmd::extract_spawn_count();
        assert_eq!(
            workbench
                .bind_command_job(context.clone(), "job two".into())
                .await
                .unwrap()
                .accept()
                .unwrap(),
            second
        );
        assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before_repeat);
        workbench
            .publish_completed_cell_for_test(context)
            .await
            .unwrap();
        assert_eq!(
            workbench
                .host_binding_identity_for_test(public, &first)
                .await,
            original
        );
    }

