    async fn whole_cell_bind_and_discard_preserve_settlement_with_preparation_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        with_test_compiler_owner(|_| async {
            let (machines, context, source, _root) = actor_registry_fixture();
            let (workbench, context) = ResidentActorWorkbench::new(
                machines,
                (source).bind_preparation(preparation_client.clone()),
                None,
            )
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
            let (checked, prepared) = workbench
                .prepare_cell(
                    context.clone(),
                    "x <- pure (1 :: Int)\n_ <- pure (2 :: Int)".into(),
                )
                .await
                .unwrap();
            let PreparedCell {
                items,
                dependencies,
            } = prepared;
            assert_eq!(checked.items.len(), 2);
            for (index, item) in items.into_iter().enumerate() {
                let step = workbench
                    .begin_prepared_cell_item(
                        context.clone(),
                        ParsedBlock {
                            ordinal: index + 1,
                            total: 2,
                            source: checked.items[index].source.clone(),
                        },
                        item,
                    )
                    .await
                    .unwrap();
                let ResidentWorkbenchStep::Committed {
                    output,
                    installed_bindings,
                    ..
                } = step
                else {
                    panic!("pure whole-cell item must commit");
                };
                if index == 0 {
                    assert_eq!(installed_bindings, vec!["x".to_owned()]);
                    assert!(output.contains('x'), "{output}");
                } else {
                    assert!(output.is_empty(), "discarded item created output: {output}");
                    assert!(installed_bindings.is_empty());
                }
            }
            drop(dependencies);
            workbench
                .access
                .with_machine(context, |session, context, _| {
                    assert_eq!(
                        session.binding_names_in(context.placement.lexical_scope),
                        vec!["x".to_owned()]
                    );
                    Ok(())
                })
                .await
                .unwrap();
        })
        .await;
    }

    #[tokio::test]
    async fn mutation_after_whole_cell_preparation_refuses_stale_item_and_fresh_preparation_succeeds(
    ) {
        with_test_compiler_owner(|preparation_client| async move {
            let (machines, context, source, _root) = actor_registry_fixture();
            let (workbench, context) = ResidentActorWorkbench::new(
                machines,
                (source).bind_preparation(preparation_client.clone()),
                None,
            )
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
            let text = "x <- pure (1 :: Int)";
            let (checked, prepared) = workbench
                .prepare_cell(context.clone(), text.into())
                .await
                .unwrap();
            let PreparedCell {
                mut items,
                dependencies,
            } = prepared;
            assert_eq!(
                items.len(),
                1,
                "stale control starts with genuine native preparation"
            );
            workbench
                .bind_tool_result(
                    context.clone(),
                    "interloper".into(),
                    "interloper text".into(),
                )
                .await
                .unwrap()
                .accept()
                .unwrap();
            let refused = workbench
                .begin_prepared_cell_item(
                    context.clone(),
                    ParsedBlock {
                        ordinal: 1,
                        total: 1,
                        source: checked.items[0].source.clone(),
                    },
                    items.pop().unwrap(),
                )
                .await;
            assert!(
                matches!(
                    refused,
                    Err(ResidentActorWorkbenchError::Resident(
                        ResidentError::Session(
                            tidepool_runtime::session::SessionError::StaleStagedDeclaration
                        )
                    ))
                ),
                "stale prepared item must be refused before native install"
            );
            drop(dependencies);
            workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    assert!(session
                        .current_binding_in(context.placement.lexical_scope, "x")
                        .is_none());
                    assert!(session
                        .current_binding_in(context.placement.lexical_scope, "interloper")
                        .is_some());
                    Ok(())
                })
                .await
                .unwrap();
            let step = workbench
                .begin_cell_for_test(
                    context,
                    ParsedBlock {
                        ordinal: 1,
                        total: 1,
                        source: text.into(),
                    },
                )
                .await
                .unwrap();
            let ResidentWorkbenchStep::Committed {
                installed_bindings, ..
            } = step
            else {
                panic!("fresh whole-cell preparation must commit");
            };
            assert_eq!(installed_bindings, vec!["x".to_owned()]);
        })
        .await
    }

    fn schema_constructor_table(effect: tidepool_protocol::schema::Effect) -> DataConTable {
        use tidepool_protocol::types::TypeShape;
        use tidepool_repr::{DataCon, DataConId};
        let mut table = tidepool_test_data::standard_datacon_table();
        let mut next_id = 100;
        for definition in effect.type_defs {
            let constructors: Vec<_> = match definition.shape {
                TypeShape::Record { fields } => vec![(definition.name, fields.len())],
                TypeShape::Sum { variants } => variants
                    .iter()
                    .map(|variant| (variant.ctor, variant.fields.types().len()))
                    .collect(),
                _ => continue,
            };
            for (index, (name, arity)) in constructors.into_iter().enumerate() {
                let module = definition.haskell_module.unwrap_or("Tidepool.Effects.Core");
                table
                    .insert_checked(DataCon {
                        identity: tidepool_repr::execution_schema::testing::metadata_identity(
                            tidepool_repr::execution_schema::SymbolIdentity {
                                unit: "fixture".into(),
                                module: module.into(),
                                namespace: "constructor".into(),
                                occurrence: name.into(),
                                record_parent: None,
                            },
                            definition.name,
                        ),
                        id: DataConId(next_id),
                        name: name.into(),
                        tag: index as u32 + 1,
                        rep_arity: arity as u32,
                        field_bangs: vec![tidepool_repr::datacon::SrcBang::NoSrcBang; arity],
                        qualified_name: Some(format!("{module}.{name}")),
                        type_name: definition.name.into(),
                    })
                    .expect("valid schema fixture metadata");
                next_id += 1;
            }
        }
        table
    }

    fn introspection_error_table() -> DataConTable {
        schema_constructor_table(tidepool_protocol::effects::introspection::introspection())
    }

