    async fn admitted_cell_preserves_shadowing_polykinds_and_prologue_only_items_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, context, source, _root) = actor_registry_fixture();
        let initial = ResidentActorWorkbench::new(
            Arc::clone(&machines),
            (source.clone()).bind_preparation(preparation_client.clone()),
            None,
        );
        let (initial, private_context) = initial
            .admit_private_cell_for_test(context.clone())
            .await
            .unwrap();
        initial
            .execute_cell_for_test(private_context.clone(), "sh args = length (args :: [Int])")
            .await
            .unwrap();
        initial
            .publish_completed_cell_for_test(private_context)
            .await
            .unwrap();
        let workbench = ResidentActorWorkbench::new(
            machines,
            (source).bind_preparation(preparation_client.clone()),
            None,
        );
        let (workbench, context) = workbench
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
        let (checked, prepared) = workbench
            .prepare_cell(
                context.clone(),
                "sh args = 2 * length (args :: [Int])\nrecentA <- pure (sh [1, 2, 3])".into(),
            )
            .await
            .expect("one admitted declaration shadows its prior exact owner");
        assert_eq!(checked.items.len(), 2);
        assert_eq!(prepared.items.len(), 2);

        let (expression, prepared) = workbench
            .prepare_cell(
                context.clone(),
                "{-# LANGUAGE PolyKinds #-}\nimport Data.Proxy (Proxy(..))\npure Proxy".into(),
            )
            .await
            .expect("the admitted native expression preserves its dependent telescope");
        assert_eq!(expression.expression_plans.len(), 1);
        assert!(!expression.expression_plans[0]
            .type_display
            .contains("ZonkAny"));
        let PreparedCell { items, .. } = prepared;
        assert_eq!(
            items
                .iter()
                .filter(|step| matches!(&step.ready,
            PreparedCellStep { item, .. }
                if item.kind() == tidepool_toolchain::checked_cell::CheckedItemKind::Expression))
                .count(),
            1
        );
        for text in ["import Data.List\n", "{-# LANGUAGE NoLambdaCase #-}\n"] {
            let (checked, prepared) = workbench
                .prepare_cell(context.clone(), text.into())
                .await
                .expect("a prologue-only item remains admitted declaration syntax");
            assert_eq!(checked.items.len(), 1);
            assert!(checked.items[0].prologue_only);
            assert!(checked.items[0].verdict.binders.is_empty());
            let PreparedCell { items, .. } = prepared;
            assert!(matches!(&items[0].ready, PreparedCellStep { item, .. }
                if item.kind() == tidepool_toolchain::checked_cell::CheckedItemKind::Declaration));
        }
    }

    impl ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput> {
        async fn host_binding_identity_for_test(
            &self,
            context: crate::ActorSessionContext,
            name: &str,
        ) -> (tidepool_repr::SessionVarId, tidepool_repr::SessionModule) {
            let name = name.to_owned();
            self.access
                .with_machine(context, move |session, context, _| {
                    let scope = context.placement.lexical_scope;
                    let binding = session
                        .current_binding_in(scope, &name)
                        .expect("original host binding remains visible");
                    let view = session.compile_view_in(scope).unwrap();
                    let inputs = session
                        .capture_inspection_inputs(&view)
                        .expect("original checked interface remains authenticated");
                    assert!(inputs.view().reachable_values().contains(&binding.1));
                    Ok((binding.0, binding.1))
                })
                .await
                .unwrap()
        }

        async fn wait_for_host_input_retirement_for_test(
            &self,
            context: crate::ActorSessionContext,
            name: String,
        ) {
            tokio::time::timeout(Duration::from_secs(10), async {
                loop {
                    let name = name.clone();
                    if self
                        .access
                        .with_machine(context.clone(), move |session, context, _| {
                            Ok(session
                                .current_binding_in(context.placement.lexical_scope, &name)
                                .is_none())
                        })
                        .await
                        .unwrap()
                    {
                        break;
                    }
                    tokio::task::yield_now().await;
                }
            })
            .await
            .expect("ephemeral host input retires after its dependencies release");
        }

        async fn refuse_host_payload_for_test(
            &self,
            context: crate::ActorSessionContext,
            carrier: HostCarrier,
        ) -> HostCarrier {
            use tidepool_runtime::session::turn::HostBindingAuthority;
            self.access
                .with_machine(context, move |session, context, _| {
                    if carrier.checked_binding().is_err() {
                        let binder = carrier.binding().unwrap();
                        let expected = match binder.host_authority.unwrap() {
                            HostBindingAuthority::JsonValue => HostBindingType::JSON_VALUE,
                            HostBindingAuthority::Text => HostBindingType::TEXT,
                            HostBindingAuthority::CommandJob => HostBindingType::COMMAND_JOB,
                        };
                        let residency = session.residency();
                        assert!(carrier
                            .code()
                            .certification()
                            .unwrap()
                            .checked_execution()
                            .is_none());
                        assert!(carrier
                            .code()
                            .certification()
                            .unwrap()
                            .checked_prefix()
                            .is_none());
                        assert!(matches!(
                            HostCarrier::from_compiled(binder, carrier.code(), expected),
                            Err(ResidentError::UnsupportedCheckedTurn)
                        ));
                        let wrong_json = serde_json::Value::Null;
                        let wrong = if expected == HostBindingType::JSON_VALUE {
                            HostPayload::Text("wrong nominal payload")
                        } else {
                            HostPayload::Json(&wrong_json)
                        };
                        assert!(matches!(
                            tidepool_testing::with_settlement(|settlement| session
                                .mount_checked_host_input(&carrier, wrong, settlement)),
                            Err(ResidentError::UnsupportedCheckedTurn)
                        ));
                        assert!(tidepool_testing::with_settlement(|settlement| session
                            .run_bind_with_sites(
                                "host prototype must never execute",
                                carrier.code(),
                                binder,
                                tidepool_repr::Generation(u64::MAX),
                                settlement
                            ))
                        .is_err());
                        assert_eq!(session.residency(), residency);
                        assert!(session
                            .current_binding_in(context.placement.lexical_scope, &binder.name)
                            .is_none());
                        return Ok(carrier);
                    }
                    let (reservation, binder) = carrier.checked_binding().unwrap();
                    let before = reservation.prefix().snapshot();
                    let expected = match binder.host_authority.unwrap() {
                        HostBindingAuthority::JsonValue => HostBindingType::JSON_VALUE,
                        HostBindingAuthority::Text => HostBindingType::TEXT,
                        HostBindingAuthority::CommandJob => HostBindingType::COMMAND_JOB,
                    };
                    let original = carrier.code();
                    let missing = tidepool_runtime::session::CompiledTurn::from_prepared(
                        Arc::new(original.prepared().clone()),
                        original.table().clone(),
                        Default::default(),
                        original.sites().to_vec(),
                    )
                    .unwrap()
                    .into_code();
                    assert!(matches!(
                        HostCarrier::from_checked(
                            reservation.clone(),
                            binder.clone(),
                            missing,
                            expected
                        ),
                        Err(ResidentError::UnsupportedCheckedTurn)
                    ));
                    let mut changed = binder.clone();
                    changed.name.push_str("Changed");
                    assert!(matches!(
                        HostCarrier::from_checked(
                            reservation.clone(),
                            changed,
                            carrier.code(),
                            expected
                        ),
                        Err(ResidentError::UnsupportedCheckedTurn)
                    ));
                    let residency = session.residency();
                    let wrong_json = serde_json::Value::Null;
                    let wrong = match binder
                        .host_authority
                        .expect("a genuine checked host binder")
                    {
                        HostBindingAuthority::JsonValue => {
                            HostPayload::Text("wrong nominal payload")
                        }
                        HostBindingAuthority::Text | HostBindingAuthority::CommandJob => {
                            HostPayload::Json(&wrong_json)
                        }
                    };
                    assert!(matches!(
                        tidepool_testing::with_settlement(|settlement| session
                            .mount_checked_host_input(&carrier, wrong, settlement)),
                        Err(ResidentError::UnsupportedCheckedTurn)
                    ));
                    assert!(tidepool_testing::with_settlement(|settlement| session
                        .run_bind_with_sites(
                            "host placeholder must never execute",
                            carrier.code(),
                            binder,
                            reservation.generation(),
                            settlement
                        ))
                    .is_err());
                    assert!(Arc::ptr_eq(&before, &reservation.prefix().snapshot()));
                    assert_eq!(before.compiler_prefix().next_item(), 0);
                    assert_eq!(session.residency(), residency);
                    assert!(session
                        .current_binding_in(context.placement.lexical_scope, &binder.name)
                        .is_none());
                    Ok(carrier)
                })
                .await
                .unwrap()
        }

        async fn begin_cell_for_test(
            &self,
            context: crate::ActorSessionContext,
            block: ParsedBlock,
        ) -> Result<ResidentWorkbenchStep, ResidentActorWorkbenchError> {
            let (checked, prepared) = self
                .prepare_cell(context.clone(), block.source.clone())
                .await?;
            let PreparedCell {
                mut items,
                dependencies,
            } = prepared;
            assert_eq!(checked.items.len(), 1, "fixture is one whole-cell item");
            assert_eq!(items.len(), 1);
            let block = ParsedBlock {
                source: checked.items[0].source.clone(),
                ..block
            };
            let step = self
                .begin_prepared_cell_item(context, block, items.pop().unwrap())
                .await;
            drop(dependencies);
            step
        }

        async fn execute_cell_for_test(
            &self,
            context: crate::ActorSessionContext,
            source: &str,
        ) -> Result<(), ResidentActorWorkbenchError> {
            let (checked, prepared) = self.prepare_cell(context.clone(), source.into()).await?;
            let PreparedCell {
                items,
                dependencies,
            } = prepared;
            assert!(!items.is_empty(), "fixture must execute a checked item");
            assert_eq!(checked.items.len(), items.len());
            for (index, (observed, item)) in checked.items.iter().zip(items).enumerate() {
                assert!(!item.ready.prefix.cell_program().items().is_empty());
                let step = self
                    .begin_prepared_cell_item(
                        context.clone(),
                        ParsedBlock {
                            ordinal: index + 1,
                            total: checked.items.len(),
                            source: observed.source.clone(),
                        },
                        item,
                    )
                    .await?;
                let settled = match step {
                    ResidentWorkbenchStep::Running { fragment, outcome } => {
                        self.settle_item(context.clone(), *fragment, (*outcome).into())
                            .await?
                    }
                    other => other,
                };
                assert!(matches!(settled, ResidentWorkbenchStep::Committed { .. }));
            }
            drop(dependencies);
            Ok(())
        }

        async fn publish_cell_for_test(
            &self,
            context: crate::ActorSessionContext,
            source: &str,
        ) -> Result<(), ResidentActorWorkbenchError> {
            let (writer, context) = workbench_runner_for_test(self)
                .application_workbench()
                .admit_private_cell_for_test(context)
                .await?;
            writer
                .execute_cell_for_test(context.clone(), source)
                .await?;
            writer.publish_completed_cell_for_test(context).await
        }

        async fn publish_completed_cell_for_test(
            &self,
            context: crate::ActorSessionContext,
        ) -> Result<(), ResidentActorWorkbenchError> {
            self.publish_completed_cell_with_commit_for_test(
                context,
                tidepool_runtime::session::PublicManifestCommit::Ephemeral,
            )
            .await
        }

        async fn publish_completed_cell_with_commit_for_test(
            &self,
            context: crate::ActorSessionContext,
            expected: tidepool_runtime::session::PublicManifestCommit,
        ) -> Result<(), ResidentActorWorkbenchError> {
            let execution = self
                .private_execution
                .as_ref()
                .expect("admitted private cell");
            let published = workbench_runner_for_test(self)
                .publish_private_execution(context.clone(), Arc::clone(execution))
                .await?;
            assert!(matches!(
                published,
                PrivateExecutionPublication::Manifest {
                    commit,
                    ..
                } if matches!((&commit, &expected),
                    (tidepool_runtime::session::PublicManifestCommit::Ephemeral,
                     tidepool_runtime::session::PublicManifestCommit::Ephemeral)
                    | (tidepool_runtime::session::PublicManifestCommit::Durable,
                       tidepool_runtime::session::PublicManifestCommit::Durable))
            ));
            let public_scope = execution.public_scope;
            self.access
                .with_machine(context, move |session, context, _| {
                    let private_scope = context.placement.lexical_scope;
                    session.retire_scope(private_scope);
                    assert!(session.compile_view_in(private_scope).is_none());
                    let public_view = session
                        .compile_view_in(public_scope)
                        .expect("paired publication survives private retirement");
                    session
                        .capture_inspection_inputs(&public_view)
                        .map_err(|error| {
                            ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                        })?;
                    Ok(())
                })
                .await
        }

        async fn admit_private_cell_for_test(
            self,
            context: crate::ActorSessionContext,
        ) -> Result<(Self, crate::ActorSessionContext), ResidentActorWorkbenchError> {
            let descriptor = crate::ActorDescriptor::new("private-cell-test", context.placement);
            let owner =
                crate::resident_actor::WorkbenchPublicOwner::issue(&context, &descriptor, None)
                    .expect("fixture has an ephemeral public owner");
            self.admit_private_cell_with_owner_for_test(context, owner)
                .await
        }

        async fn admit_private_cell_with_owner_for_test(
            self,
            mut context: crate::ActorSessionContext,
            owner: Arc<crate::resident_actor::WorkbenchPublicOwner>,
        ) -> Result<(Self, crate::ActorSessionContext), ResidentActorWorkbenchError> {
            let authority =
                crate::resident_actor::WorkbenchCompilationAuthority::for_test(context.clone());
            let private = Arc::new(
                workbench_runner_for_test(&self)
                    .begin_private_execution(
                        context.clone(),
                        owner,
                        tidepool_runtime::session::PublicationDecision::new(),
                        None,
                    )
                    .await?,
            );
            context.placement.lexical_scope = private.private_scope;
            Ok((
                self.with_compilation_authority(authority)
                    .with_private_execution(private),
                context,
            ))
        }
    }

