    #[tokio::test]
    async fn source_preparation_retains_actual_close_after_waiter_cancel_and_owner_retirement_observation(
    ) {
        with_test_compiler_owner(source_preparation_retains_actual_close_after_waiter_cancel_and_owner_retirement_observation_with_preparation_client).await
    }

    async fn source_preparation_retains_actual_close_after_waiter_cancel_and_owner_retirement_observation_with_preparation_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let services = crate::capabilities::WorkbenchServices::new();
        use tracing::instrument::WithSubscriber;

        let log = CapturedLog(Arc::new(std::sync::Mutex::new(Vec::new())));
        let subscriber = tracing_subscriber::fmt()
            .json()
            .with_writer(log.clone())
            .with_max_level(tracing::Level::INFO)
            .finish();
        let _subscriber = tracing::subscriber::set_default(subscriber);
        let (_, _, source, _session_root) = host_mount_fixture();
        let source = source.bind_preparation(preparation_client.clone());
        let retained = crate::RetainedActorExit::new();
        let owner = services
            .with_compiler_owner(CompilerCloseOwner::ActorLifecycle(retained.clone()))
            .for_preparation();
        let source_layer = crate::CheckpointSourceLayer::default();
        let registry = Arc::new(tidepool_runtime::session::ImageRegistry::new());
        let entered = Arc::new(tokio::sync::Notify::new());
        let (release, proceed) = std::sync::mpsc::channel();
        let proceed = parking_lot::Mutex::new(proceed);
        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        source.toolset_preparation.observe_fresh_launch(Arc::new({
            let entered = Arc::clone(&entered);
            let calls = Arc::clone(&calls);
            move || {
                assert_eq!(calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst), 0);
                tracing::info!(preparation_probe = true, "native preparation entered");
                entered.notify_one();
                proceed
                    .lock()
                    .recv_timeout(std::time::Duration::from_secs(15))
                    .unwrap();
            }
        }));
        let before = tidepool_extract_cmd::extract_spawn_count();
        let first = tokio::spawn({
            let source = source.clone();
            let source_layer = source_layer.clone();
            let registry = Arc::clone(&registry);
            async move {
                owner
                    .scope(source.prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Preparation,
                        source_layer,
                        &[],
                        &[],
                        registry,
                    ))
                    .await
            }
            .instrument(tracing::info_span!(
                "preparation_requester",
                issuer = 73_u64
            ))
            .with_current_subscriber()
        });
        tokio::time::timeout(std::time::Duration::from_secs(15), entered.notified())
            .await
            .unwrap();
        let trace = log.0.lock().unwrap().clone();
        let probe = std::str::from_utf8(&trace)
            .unwrap()
            .lines()
            .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
            .find(|event| event["fields"]["preparation_probe"] == true)
            .expect("shared native preparation retains its issuing scoped dispatcher");
        assert!(
            probe["spans"]
                .as_array()
                .unwrap()
                .iter()
                .any(|span| { span["name"] == "preparation_requester" && span["issuer"] == 73 }),
            "the original request owns shared preparation across async and blocking pools"
        );
        assert!(matches!(
            retained.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Pending]
        ));
        let (shared_registered, shared_observed) = tokio::sync::oneshot::channel();
        let remaining = tokio::spawn({
            let source = source.clone();
            let source_layer = source_layer.clone();
            let registry = Arc::clone(&registry);
            async move {
                // This waiter has no task-local owner; it borrows the admitted
                // source task instead of registering a replacement compiler.
                assert!(crate::capabilities::CompilerOwnerScope::current().is_err());
                let mut waiting = Box::pin(source.prepare_source_toolset(
                    tidepool_toolchain::artifacts::CompileWorkload::Preparation,
                    source_layer,
                    &[],
                    &[],
                    registry,
                ));
                // This path reaches the shared task's pending wait before the
                // winner can compile; do not count merely spawning a waiter.
                std::future::poll_fn(|context| {
                    assert!(std::future::Future::poll(waiting.as_mut(), context).is_pending());
                    std::task::Poll::Ready(())
                })
                .await;
                shared_registered.send(()).unwrap();
                waiting.await
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(15), shared_observed)
            .await
            .unwrap()
            .unwrap();
        first.abort();
        match first.await {
            Err(error) => assert!(error.is_cancelled()),
            Ok(_) => panic!("the first source waiter must be cancelled"),
        }
        retained.retain_cleanup(crate::ResidentCleanupOutcome {
            actor: crate::ActorRef::first(crate::ActorId(1)),
            hook: crate::CleanupComponentOutcome::Confirmed,
            realm: crate::CleanupComponentOutcome::Confirmed,
            children: crate::CleanupComponentOutcome::Confirmed,
        });
        retained
            .publish(crate::ActorTerminal {
                kind: crate::ActorExitKind::Cancelled,
                summary: "owner retirement observed while shared source preparation remains owned"
                    .into(),
                diagnostic: None,
            })
            .unwrap();
        assert!(!retained.cleanup().unwrap().is_confirmed());
        release.send(()).unwrap();
        let prepared = remaining.await.unwrap().unwrap();
        assert!(matches!(
            prepared.acquisition(),
            crate::ToolsetAcquisition::UnretainedCompilation { .. }
        ));
        assert!(
            tidepool_extract_cmd::extract_spawn_count() > before,
            "the retained source task must execute the actual compiler"
        );
        assert!(matches!(
            retained.compiler_close_observations().as_slice(),
            [crate::termination::CompilerWorkClose::Settled(
                tidepool_runtime::CompilerTransactionClose::Clean
            )]
        ));
        assert!(retained.cleanup().unwrap().is_confirmed());
        assert_eq!(
            retained.get().unwrap().kind,
            crate::ActorExitKind::Cancelled
        );
        let after = tidepool_extract_cmd::extract_spawn_count();
        let cached = source
            .prepare_source_toolset(
                tidepool_toolchain::artifacts::CompileWorkload::Preparation,
                source_layer,
                &[],
                &[],
                registry,
            )
            .await
            .unwrap();
        assert!(Arc::ptr_eq(&prepared.prepared, &cached.prepared));
        assert_eq!(prepared.acquisition(), cached.acquisition());
        assert_eq!(tidepool_extract_cmd::extract_spawn_count(), after);
        assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst), 1);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn dropped_pre_actor_preparation_scope_stops_and_joins_physical_work() {
        let (_, _, config, _session_root) = host_mount_fixture();
        let mut lifetime = crate::CompilerPreparationOwner::new();
        let cleanup = lifetime.cleanup();
        let (entered, started) = tokio::sync::oneshot::channel();
        let (cancelled, cancellation_seen) = tokio::sync::oneshot::channel();
        let (release, finish) = std::sync::mpsc::channel();
        let mut operation = Box::pin(lifetime.scope_with_client(|client| async move {
            let source = config.bind_preparation(client);
            let barrier = parking_lot::Mutex::new(Some((entered, cancelled, finish)));
            source
                .toolset_preparation
                .observe_fresh_launch(Arc::new(move || {
                    let (entered, cancelled, finish) = barrier.lock().take().unwrap();
                    entered.send(()).unwrap();
                    while tidepool_extract_cmd::compiler_host_checkpoint().is_ok() {
                        std::thread::yield_now();
                    }
                    cancelled.send(()).unwrap();
                    finish
                        .recv_timeout(std::time::Duration::from_secs(10))
                        .unwrap();
                }));
            source
                .prepare_source_toolset(
                    tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                    crate::CheckpointSourceLayer::default(),
                    &[],
                    &[],
                    Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                )
                .await
        }));
        tokio::select! {
            entered = started => entered.unwrap(),
            _ = &mut operation => panic!("preparation completed before controlled retirement"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(15)) => panic!("preparation never entered"),
        }
        drop(operation);
        tokio::time::timeout(std::time::Duration::from_secs(2), cancellation_seen)
            .await
            .unwrap()
            .unwrap();
        assert!(!cleanup.observation().is_confirmed());
        release.send(()).unwrap();
        assert!(cleanup
            .wait_for_settlement(std::time::Duration::from_secs(15))
            .await
            .is_confirmed());
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
