    async fn source_preparation_retirement_history(control_failure: bool) {
        let (_, _, config, _session_root) = host_mount_fixture();
        let (run, task) = crate::LocalActorDirectory::start().await.unwrap();
        let source = config.bind_preparation(run.preparation_client());
        let (entered, started) = tokio::sync::oneshot::channel();
        let (cancelled, cancellation_seen) = tokio::sync::oneshot::channel();
        let (release, finish) = std::sync::mpsc::channel();
        let barrier = parking_lot::Mutex::new(Some((entered, cancelled, finish)));
        source
            .toolset_preparation
            .observe_fresh_launch(Arc::new(move || {
                let (entered, cancelled, finish) = barrier.lock().take().unwrap();
                entered.send(()).unwrap();
                while tidepool_extract_cmd::compiler_host_checkpoint().is_ok() {
                    std::thread::yield_now();
                }
                cancelled.send(()).unwrap();
                finish
                    .recv_timeout(std::time::Duration::from_secs(10))
                    .unwrap();
            }));
        let pending = tokio::spawn({
            let source = source.clone();
            async move {
                let mut observer = crate::CompilerPreparationOwner::new();
                observer
                    .scope(source.prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        crate::CheckpointSourceLayer::default(),
                        &[],
                        &[],
                        Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                    ))
                    .await
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(15), started)
            .await
            .unwrap()
            .unwrap();
        if control_failure {
            run.stop_owner_for_test().await;
        } else {
            run.seal().await.unwrap();
        }
        tokio::time::timeout(std::time::Duration::from_secs(2), cancellation_seen)
            .await
            .unwrap()
            .unwrap();
        assert!(matches!(
            run.settle_run_preparations(std::time::Duration::from_millis(10))
                .await,
            crate::CleanupComponentOutcome::Unconfirmed(_)
        ));
        let late = source
            .prepare_source_toolset(
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                crate::CheckpointSourceLayer::default(),
                &[],
                &[],
                Arc::new(tidepool_runtime::session::ImageRegistry::new()),
            )
            .await;
        assert!(matches!(
            late,
            Err(ResidentActorWorkbenchError::CompilerCleanupAdmissionClosed)
        ));
        release.send(()).unwrap();
        let outcome = tokio::time::timeout(std::time::Duration::from_secs(15), pending)
            .await
            .unwrap()
            .unwrap();
        assert!(outcome.action.is_err());
        assert!(outcome.cleanup.observation().is_confirmed());
        let settled = run
            .settle_run_preparations(std::time::Duration::from_secs(2))
            .await;
        if control_failure {
            assert!(matches!(
                settled,
                crate::CleanupComponentOutcome::Unconfirmed(_)
            ));
        } else {
            assert_eq!(settled, crate::CleanupComponentOutcome::Confirmed);
            assert_eq!(
                run.shutdown_run_resources().await,
                crate::CleanupComponentOutcome::Confirmed
            );
            run.finish_run().await.unwrap();
        }
        task.await.unwrap();
    }

    #[tokio::test]
    async fn prepared_source_instance_and_effect_order_execute_original_native_semantics() {
        with_test_compiler_owner(prepared_source_instance_and_effect_order_execute_original_native_semantics_with_preparation_client).await
    }

    async fn prepared_source_instance_and_effect_order_execute_original_native_semantics_with_preparation_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        struct Snapshot {
            _owner: Arc<tempfile::TempDir>,
            identity: Vec<String>,
            roots: Vec<PathBuf>,
            manifests: Vec<tidepool_toolchain::cache::SourceRootManifest>,
        }
        impl crate::RetainedSourceLayer for Snapshot {
            fn catalog_selection(&self) -> tidepool_toolchain::toolchain::CatalogSelection {
                tidepool_toolchain::toolchain::CatalogSelection::Acquired(None)
            }

            fn identities(&self) -> &[String] {
                &self.identity
            }
            fn include_paths(&self) -> &[PathBuf] {
                &self.roots
            }
            fn source_manifests(&self) -> Option<&[tidepool_toolchain::cache::SourceRootManifest]> {
                Some(&self.manifests)
            }
        }
        let (_, _, source, _session_root) = host_mount_fixture();
        let source = source
            .with_spec("PreparedInstanceAgentSpec.agentSpec")
            .bind_preparation(preparation_client.clone());
        let authored = Arc::new(tempfile::tempdir().unwrap());
        let issuer = crate::SourceLayerIssuer::default();
        let snapshot = |value: &str| {
            let root = authored.path().join(value);
            std::fs::create_dir(&root).unwrap();
            std::fs::write(
                root.join("PreparedInstanceProvider.hs"),
                &tidepool_testing::fixture_source(
                    "exomonad/actor/src/fixtures/prepared-instance-provider.hs",
                )
                .replace("INSTANCE_RESULT", value),
            )
            .unwrap();
            std::fs::write(
                root.join("PreparedInstanceAgentSpec.hs"),
                &tidepool_testing::fixture_source(
                    "exomonad/actor/src/fixtures/prepared-instance-agent-spec.hs",
                ),
            )
            .unwrap();
            let root = root.canonicalize().unwrap();
            let manifests = vec![
                tidepool_toolchain::cache::SourceRootManifest::from_file_digests(
                    tidepool_toolchain::cache::source_root_manifest(&root).unwrap(),
                )
                .unwrap(),
            ];
            let revision = tidepool_toolchain::cache::source_manifests_identity(
                b"test-prepared-instance-source-owner",
                &manifests,
            );
            issuer.issue(Arc::new(Snapshot {
                _owner: Arc::clone(&authored),
                identity: vec![revision],
                roots: vec![root],
                manifests,
            }))
        };
        let original_source = snapshot("41");
        let changed_source = snapshot("42");
        let forward = [
            crate::ActorEffectKey::Sleep,
            crate::ActorEffectKey::Notifications,
        ];
        let reverse = [
            crate::ActorEffectKey::Notifications,
            crate::ActorEffectKey::Sleep,
        ];
        let support = forward.map(exomonad_tool::ToolEffectKey::Actor);
        let registry = Arc::new(tidepool_runtime::session::ImageRegistry::new());
        let mut compiler_owner = crate::CompilerPreparationOwner::new();
        let prepared = compiler_owner
            .scope(async {
                let original = source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        original_source.clone(),
                        &forward,
                        &support,
                        Arc::clone(&registry),
                    )
                    .await
                    .unwrap();
                let reordered = source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        original_source.clone(),
                        &reverse,
                        &support,
                        Arc::clone(&registry),
                    )
                    .await
                    .unwrap();
                let changed = source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        changed_source,
                        &forward,
                        &support,
                        Arc::clone(&registry),
                    )
                    .await
                    .unwrap();
                (original, reordered, changed)
            })
            .await;
        assert!(prepared.cleanup.observation().is_confirmed());
        let (original, reordered, changed) = prepared.action;
        assert_eq!(original.effects(), forward);
        assert_eq!(reordered.effects(), reverse);
        assert_eq!(original.source_revision(), reordered.source_revision());
        assert_ne!(original.source_revision(), changed.source_revision());
        assert!(!Arc::ptr_eq(&original.prepared, &reordered.prepared));
        assert!(!Arc::ptr_eq(&original.prepared, &changed.prepared));
        let before_execution = tidepool_extract_cmd::extract_spawn_count();
        let warm_original = source
            .prepare_source_toolset(
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                original_source,
                &forward,
                &support,
                Arc::clone(&registry),
            )
            .await
            .unwrap();
        assert!(Arc::ptr_eq(&original.prepared, &warm_original.prepared));
        crate::agent_spec::preparation::tests::distinct_ready_payload_histories([
            Arc::clone(&original.prepared),
            Arc::clone(&changed.prepared),
        ]);
        for (prepared, expected) in [
            (&original, "41"),
            (&reordered, "41"),
            (&changed, "42"),
            (&warm_original, "41"),
        ] {
            run_native_instance_effect_probe(source.clone(), prepared, &support, expected).await;
        }
        assert_eq!(
            tidepool_extract_cmd::extract_spawn_count(),
            before_execution,
            "ready preparation, fresh native installations and tool effects must not compile source"
        );
    }

    fn run_closed_source_probe_startup(
        session: &mut ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        context: &crate::ActorSessionContext,
        prepared: &tidepool_runtime::session::PreparedSourceEntry,
    ) -> (
        Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
        ResidentOutcome,
    ) {
        context
            .source_dependency()
            .adopt_final_scope(session, context.placement.lexical_scope)
            .unwrap();
        let source = context.source_dependency().source_lease().unwrap();
        let entry = session
            .with_source_compiler_transaction(
                source.original_source().clone(),
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                tidepool_runtime::CompilerTransactionCancellation::new(),
                None,
                |_| {},
                |session, _| session.prepare_source_startup_entry(prepared),
            )
            .unwrap()
            .into_outcome()
            .action
            .unwrap();
        let installation = entry.installation_scope().clone();
        session
            .set_run_context(tidepool_runtime::session::SessionRunContext {
                lexical_scope: installation.scope(),
                ..session.run_context()
            })
            .unwrap();
        let outcome = session
            .with_source_compiler_transaction(
                source.original_source().clone(),
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                tidepool_runtime::CompilerTransactionCancellation::new(),
                None,
                |_| {},
                |session, settlement| session.run_source_startup_entry(entry, settlement),
            )
            .unwrap()
            .into_outcome()
            .action
            .unwrap();
        (installation, outcome)
    }

    async fn run_native_instance_effect_probe(
        source: BoundActorWorkbenchSource,
        prepared: &PreparedSourceToolset,
        support: &[exomonad_tool::ToolEffectKey],
        expected: &str,
    ) {
        let (mut session, context, _, _session_root) = host_mount_fixture();
        let (_installation, outcome) =
            run_closed_source_probe_startup(&mut session, &context, &prepared.prepared.entry);
        let ResidentOutcome::Suspended { hole, request, .. } = outcome else {
            panic!("source-owned installer must publish its native dispatcher");
        };
        let ResidentRequest::AgentTools(
            crate::generated::agent_tools::AgentToolsReq::AgentToolsInstallWith(declarations, _),
        ) = ResidentRequest::decode(&request, session.data_con_table()).unwrap()
        else {
            panic!("installer must suspend at the original AgentTools owner");
        };
        let SpecInstallation {
            tools,
            slots,
            slot_effect_keys,
        } = decode_installation(tidepool_runtime::value_to_json(
            &declarations,
            session.data_con_table(),
            0,
        ))
        .unwrap();
        crate::tool_contract::validate_installation(
            &tools,
            &slots,
            &slot_effect_keys,
            prepared.effects(),
            support,
        )
        .unwrap();
        let dispatch = session
            .live_payload_handle_owned_by(hole.cont_id(), context.placement.resource_scope)
            .unwrap()
            .expect("original native dispatcher");
        let resumed = session
            .with_source_compiler_transaction(
                context
                    .source_dependency()
                    .source_lease()
                    .unwrap()
                    .original_source()
                    .clone(),
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                tidepool_runtime::CompilerTransactionCancellation::new(),
                None,
                |_| {},
                |session, settlement| session.resume(hole, (), settlement),
            )
            .unwrap()
            .into_outcome()
            .action
            .unwrap();
        assert!(matches!(resumed, ResidentOutcome::Completed { .. }));
        session
            .set_run_context(tidepool_runtime::session::SessionRunContext {
                lexical_scope: context.placement.lexical_scope,
                ..session.run_context()
            })
            .unwrap();
        let machines = Arc::new(ActorMachineRegistry::new());
        machines.insert_idle(context.placement.session, Box::new(session));
        let runner = ResidentActorRunner::new(Arc::clone(&machines), source.clone());
        let workbench = ResidentActorWorkbench::new(machines, source, None);
        let ResidentWorkbenchStep::Running { fragment, outcome } = workbench
            .begin_named_haskell_dispatch_contract(
                context.clone(),
                Arc::new(dispatch),
                "probe".into(),
                serde_json::json!({"topic": "source instance"}),
            )
            .await
            .unwrap()
        else {
            panic!("native tool must execute its authored Sleep effect");
        };
        let ResidentActorBoundary::Sleep {
            continuation,
            duration,
        } = runner
            .capture_boundary(
                context.clone(),
                (*outcome).into(),
                context.placement.resource_scope,
            )
            .await
            .unwrap()
        else {
            panic!("effect-row order must preserve the actual nominal Sleep request");
        };
        assert_eq!(duration, Duration::from_millis(19));
        let outcome = runner
            .resume_unit(context.clone(), continuation)
            .await
            .unwrap();
        let result = workbench
            .settle_item(context, *fragment, outcome)
            .await
            .unwrap();
        let ResidentWorkbenchStep::Committed { value, output, .. } = result else {
            panic!(
                "native instance tool did not complete: {}",
                describe_step(&result)
            );
        };
        assert_eq!(value, Some(serde_json::json!(expected)));
        assert_eq!(output, expected);
    }

    async fn run_native_quoted_probe(
        mut session: ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        context: crate::ActorSessionContext,
        source: BoundActorWorkbenchSource,
        prepared: &tidepool_runtime::session::PreparedSourceEntry,
        expected: &str,
    ) {
        let before = tidepool_extract_cmd::extract_spawn_count();
        let (_installation, outcome) =
            run_closed_source_probe_startup(&mut session, &context, prepared);
        let ResidentOutcome::Suspended { hole, request, .. } = outcome else {
            panic!("selected original must execute its actual installer");
        };
        assert!(matches!(
            ResidentRequest::decode(&request, session.data_con_table()).unwrap(),
            ResidentRequest::AgentTools(
                crate::generated::agent_tools::AgentToolsReq::AgentToolsInstallWith(_, _)
            )
        ));
        let dispatch = session
            .live_payload_handle_owned_by(hole.cont_id(), context.placement.resource_scope)
            .unwrap()
            .expect("installed dispatcher");
        let resumed = session
            .with_source_compiler_transaction(
                context
                    .source_dependency()
                    .source_lease()
                    .unwrap()
                    .original_source()
                    .clone(),
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                tidepool_runtime::CompilerTransactionCancellation::new(),
                None,
                |_| {},
                |session, settlement| session.resume(hole, (), settlement),
            )
            .unwrap()
            .into_outcome()
            .action
            .unwrap();
        assert!(matches!(resumed, ResidentOutcome::Completed { .. }));
        session
            .set_run_context(tidepool_runtime::session::SessionRunContext {
                lexical_scope: context.placement.lexical_scope,
                ..session.run_context()
            })
            .unwrap();
        let machines = Arc::new(ActorMachineRegistry::new());
        machines.insert_idle(context.placement.session, Box::new(session));
        let workbench = ResidentActorWorkbench::new(machines, source, None);
        let step = workbench
            .begin_named_haskell_dispatch_contract(
                context.clone(),
                Arc::new(dispatch),
                "probe".into(),
                serde_json::json!({"topic": "selected original"}),
            )
            .await
            .unwrap();
        let result = match step {
            ResidentWorkbenchStep::Running { fragment, outcome } => workbench
                .settle_item(context, *fragment, (*outcome).into())
                .await
                .unwrap(),
            step => step,
        };
        let ResidentWorkbenchStep::Committed { value, output, .. } = result else {
            panic!(
                "selected installer did not execute its native tool: {}",
                describe_step(&result)
            );
        };
        assert_eq!(value, Some(serde_json::json!(expected)));
        assert_eq!(output, expected);
        assert_eq!(
            tidepool_extract_cmd::extract_spawn_count(),
            before,
            "native installation and tool execution must use the selected original"
        );
    }

    #[tokio::test]
    async fn retained_quoted_toolset_loads_selected_original_without_compiler_replay() {
        with_test_compiler_owner(retained_quoted_toolset_loads_selected_original_without_compiler_replay_with_preparation_client).await
    }

    async fn retained_quoted_toolset_loads_selected_original_without_compiler_replay_with_preparation_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let services = crate::capabilities::WorkbenchServices::new();
        struct Snapshot {
            _owner: Arc<tempfile::TempDir>,
            identities: Vec<String>,
            paths: Vec<PathBuf>,
            manifests: Vec<tidepool_toolchain::cache::SourceRootManifest>,
            entries: crate::SourceEntryStorage,
        }
        impl crate::RetainedSourceLayer for Snapshot {
            fn catalog_selection(&self) -> tidepool_toolchain::toolchain::CatalogSelection {
                tidepool_toolchain::toolchain::CatalogSelection::Acquired(None)
            }

            fn identities(&self) -> &[String] {
                &self.identities
            }
            fn include_paths(&self) -> &[PathBuf] {
                &self.paths
            }
            fn source_manifests(&self) -> Option<&[tidepool_toolchain::cache::SourceRootManifest]> {
                Some(&self.manifests)
            }
            fn prepared_entries(&self) -> Option<&crate::SourceEntryStorage> {
                Some(&self.entries)
            }
        }
        let (session, context, source, _session_root) = host_mount_fixture();
        let authored = Arc::new(tempfile::tempdir().unwrap());
        let source_root = authored.path().join("sources");
        std::fs::create_dir(&source_root).unwrap();
        let input = authored.path().join("external-input");
        std::fs::write(&input, "41").unwrap();
        std::fs::write(
            source_root.join("QuotedProvider.hs"),
            &tidepool_testing::fixture_source(
                "exomonad/actor/src/fixtures/quoted-agent-provider.hs",
            ),
        )
        .unwrap();
        std::fs::write(
            source_root.join("QuotedAgentSpec.hs"),
            &tidepool_testing::fixture_source("exomonad/actor/src/fixtures/quoted-agent-spec.hs")
                .replace("{quotation-input}", input.to_str().unwrap()),
        )
        .unwrap();
        let storage = tidepool_atomic_write::DirectoryAnchor::open_existing(authored.path())
            .unwrap()
            .child("entries")
            .unwrap();
        let issuer = crate::SourceLayerIssuer::default();
        let snapshot = |entries| {
            let paths = vec![source_root.canonicalize().unwrap()];
            let manifests = paths
                .iter()
                .map(|root| {
                    tidepool_toolchain::cache::SourceRootManifest::from_file_digests(
                        tidepool_toolchain::cache::source_root_manifest(root).unwrap(),
                    )
                    .unwrap()
                })
                .collect::<Vec<_>>();
            let revision = tidepool_toolchain::cache::source_manifests_identity(
                b"test-retained-toolset-owner",
                &manifests,
            );
            issuer.issue(Arc::new(Snapshot {
                _owner: Arc::clone(&authored),
                identities: vec![revision],
                paths,
                manifests,
                entries,
            }))
        };
        let source = source
            .with_spec("QuotedAgentSpec.agentSpec")
            .bind_preparation(preparation_client.clone());
        let mut compiler_owner = crate::CompilerPreparationOwner::new();
        let fresh = compiler_owner
            .scope(source.prepare_source_toolset(
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                snapshot(crate::SourceEntryStorage::FreshCompilation {
                    directory: storage.path().to_owned(),
                    preparation: uuid::Uuid::new_v4(),
                }),
                &[],
                &[],
                Arc::new(tidepool_runtime::session::ImageRegistry::new()),
            ))
            .await;
        assert!(fresh.cleanup.observation().is_confirmed());
        let fresh = fresh.action.unwrap();
        assert!(matches!(
            fresh.acquisition(),
            crate::ToolsetAcquisition::FreshRunOriginal { .. }
        ));
        assert!(fresh
            .prepared
            .entry
            .ordinary_original_compile_input()
            .replay_eligible_identity()
            .is_none());
        std::fs::write(&input, "42").unwrap();
        let first_executions = std::fs::read_to_string(input.with_extension("executions")).unwrap();
        let before_handoff = tidepool_extract_cmd::extract_spawn_count();
        let handoff_source = source
            .clone()
            .with_config(|config| config.with_prepared_toolset(Some(fresh.clone())));
        let (recipe, original) = fresh.completed_entry_selection().unwrap();
        let immediate = with_test_compiler_owner(|_| {
            handoff_source.prepare_source_toolset(
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                snapshot(crate::SourceEntryStorage::CompletedOriginal {
                    directory: storage.path().to_owned(),
                    selections: [(recipe.to_owned(), original)].into_iter().collect(),
                }),
                &[],
                &[],
                Arc::new(tidepool_runtime::session::ImageRegistry::new()),
            )
        })
        .await
        .unwrap();
        assert!(Arc::ptr_eq(&fresh.prepared, &immediate.prepared));
        assert_eq!(immediate.acquisition(), fresh.acquisition());
        let (immediate_session, immediate_context, _, _immediate_root) = host_mount_fixture();
        run_native_quoted_probe(
            immediate_session,
            immediate_context,
            handoff_source,
            &immediate.prepared.entry,
            "41",
        )
        .await;
        assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before_handoff);
        assert_eq!(
            std::fs::read_to_string(input.with_extension("executions")).unwrap(),
            first_executions,
            "immediate immutable handoff must not execute the quoter again"
        );
        let successor = with_test_compiler_owner(|_| {
            source.prepare_source_toolset(
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                snapshot(crate::SourceEntryStorage::FreshCompilation {
                    directory: storage.path().to_owned(),
                    preparation: uuid::Uuid::new_v4(),
                }),
                &[],
                &[],
                Arc::new(tidepool_runtime::session::ImageRegistry::new()),
            )
        })
        .await
        .unwrap();
        assert_ne!(
            fresh.completed_entry_selection().unwrap().1,
            successor.completed_entry_selection().unwrap().1
        );
        let completed_executions =
            std::fs::read_to_string(input.with_extension("executions")).unwrap();
        assert!(
            completed_executions.lines().any(|input| input == "42"),
            "a newly admitted source preparation executes the changed untracked input"
        );
        // The installer wrapper imports separately certified original groups.
        // Its prepared bytes can stay equal when the quoted tool body changes.
        let (successor_session, successor_context, _, _successor_root) = host_mount_fixture();
        run_native_quoted_probe(
            successor_session,
            successor_context,
            source.clone(),
            &successor.prepared.entry,
            "42",
        )
        .await;
        assert_eq!(
            std::fs::read_to_string(input.with_extension("executions")).unwrap(),
            completed_executions,
            "executing the successor native body must not replay its quotation"
        );
        let reselected = with_test_compiler_owner(|_| async {
            let selected_source = source
                .clone()
                .with_config(|config| config.with_prepared_toolset(Some(fresh.clone())));
            selected_source
                .prepare_source_toolset(
                    tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                    snapshot(crate::SourceEntryStorage::CompletedOriginal {
                        directory: storage.path().to_owned(),
                        selections: [successor
                            .completed_entry_selection()
                            .map(|(recipe, original)| (recipe.to_owned(), original))
                            .unwrap()]
                        .into_iter()
                        .collect(),
                    }),
                    &[],
                    &[],
                    Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                )
                .await
        })
        .await
        .unwrap();
        assert_eq!(reselected.selection(), successor.selection());
        assert!(
            !Arc::ptr_eq(&fresh.prepared, &reselected.prepared),
            "same recipe cannot substitute a different selected quotation original"
        );
        // Reacquire readiness and native images independently of the old ready
        // cache. Selection is the completed artifact, not a fresh TH request.
        let mut cold_config = source.config.clone();
        cold_config.toolset_support_manifests = Default::default();
        let selected = snapshot(crate::SourceEntryStorage::CompletedOriginal {
            directory: storage.path().to_owned(),
            selections: [fresh
                .completed_entry_selection()
                .map(|(recipe, original)| (recipe.to_owned(), original))
                .unwrap()]
            .into_iter()
            .collect(),
        });
        let before = tidepool_extract_cmd::extract_spawn_count();
        with_test_bound_source(cold_config.clone(), |source| {
            let fresh = fresh.clone();
            async move {
                let load_control = crate::WorkbenchExecutionControl::untracked();
                let entered = Arc::new(tokio::sync::Notify::new());
                let (release, proceed) = std::sync::mpsc::channel();
                let proceed = parking_lot::Mutex::new(proceed);
                source.toolset_preparation.observe_completed_load(Arc::new({
                    let entered = entered.clone();
                    move || {
                        entered.notify_one();
                        proceed
                            .lock()
                            .recv_timeout(Duration::from_secs(15))
                            .unwrap();
                    }
                }));
                let loading = tokio::spawn({
                    let source = source.clone();
                    let selected = selected.clone();
                    let owner = services
                        .with_compiler_owner(CompilerCloseOwner::Hosted(load_control.clone()))
                        .for_preparation();
                    async move {
                        owner
                            .scope(source.prepare_source_toolset(
                                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                                selected,
                                &[],
                                &[],
                                Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                            ))
                            .await
                    }
                });
                tokio::time::timeout(Duration::from_secs(15), entered.notified())
                    .await
                    .unwrap();
                assert!(matches!(
                    load_control.compiler_close_observations().as_slice(),
                    [crate::termination::CompilerWorkClose::Pending]
                ));
                assert!(load_control.request_cancellation());
                assert!(load_control.publication_decision().claim_commit().is_none());
                release.send(()).unwrap();
                let loaded = tokio::time::timeout(Duration::from_secs(15), loading)
                    .await
                    .unwrap()
                    .unwrap()
                    .unwrap();
                assert!(matches!(
                    load_control.compiler_close_observations().as_slice(),
                    [crate::termination::CompilerWorkClose::Settled(
                        tidepool_runtime::CompilerTransactionClose::NotStarted
                    )]
                ));
                assert!(matches!(
                    loaded.acquisition(),
                    crate::ToolsetAcquisition::DeploymentOriginal { .. }
                ));
                assert!(!Arc::ptr_eq(&fresh.prepared, &loaded.prepared));
                assert!(fresh
                    .prepared
                    .entry
                    .has_same_prepared_code(&loaded.prepared.entry));
                assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before);

                run_native_quoted_probe(
                    session,
                    context,
                    source.clone(),
                    &loaded.prepared.entry,
                    "41",
                )
                .await;
                assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before);
            }
        })
        .await;
        let (recipe, original) = fresh.completed_entry_selection().unwrap();
        let retried_source = snapshot(crate::SourceEntryStorage::FreshCompilation {
            directory: storage.path().to_owned(),
            preparation: original,
        });
        let metadata = storage
            .path()
            .join(recipe)
            .join(original.to_string())
            .join("entry/raw/meta.cbor");
        let original_metadata = std::fs::read(&metadata).unwrap();
        std::fs::write(&metadata, b"post-publication fault").unwrap();
        with_test_bound_source(cold_config.clone(), |source| {
            let fresh = fresh.clone();
            let input = input.clone();
            let completed_executions = completed_executions.clone();
            async move {
                assert!(source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        retried_source.clone(),
                        &[],
                        &[],
                        Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                    )
                    .await
                    .is_err());
                std::fs::write(&metadata, original_metadata).unwrap();
                let retried = source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        retried_source,
                        &[],
                        &[],
                        Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                    )
                    .await
                    .unwrap();
                assert!(matches!(
                    retried.acquisition(),
                    crate::ToolsetAcquisition::ExistingRunOriginal { .. }
                ));
                assert_eq!(
                    retried.completed_entry_selection().unwrap(),
                    (recipe, original)
                );
                assert!(retried
                    .prepared
                    .entry
                    .has_same_prepared_code(&fresh.prepared.entry));
                assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before);
                assert_eq!(
                    std::fs::read_to_string(input.with_extension("executions")).unwrap(),
                    completed_executions
                );
            }
        })
        .await;
        let invalid = snapshot(crate::SourceEntryStorage::CompletedOriginal {
            directory: storage.path().to_owned(),
            selections: [(recipe.to_owned(), uuid::Uuid::new_v4())]
                .into_iter()
                .collect(),
        });
        assert!(
            with_test_bound_source(cold_config.clone(), |source| async move {
                source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        invalid,
                        &[],
                        &[],
                        Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                    )
                    .await
            })
            .await
            .is_err(),
            "a missing owner-selected original cannot fall back to source"
        );
        assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before);
        assert_eq!(
            std::fs::read_to_string(input.with_extension("executions")).unwrap(),
            completed_executions
        );

        let uncovered = snapshot(crate::SourceEntryStorage::CompletedOriginal {
            directory: storage.path().to_owned(),
            selections: Default::default(),
        });
        assert!(matches!(
            with_test_bound_source(cold_config.clone(), |source| async move {
                source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        uncovered,
                        &[],
                        &[],
                        Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                    )
                    .await
            })
            .await,
            Err(ResidentActorWorkbenchError::PreparedEntryAbsent { .. })
        ));
        assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before);

        let missing = snapshot(crate::SourceEntryStorage::CompletedOriginal {
            directory: authored.path().join("absent-entries"),
            selections: [fresh
                .completed_entry_selection()
                .map(|(recipe, original)| (recipe.to_owned(), original))
                .unwrap()]
            .into_iter()
            .collect(),
        });
        assert!(
            with_test_bound_source(cold_config.clone(), |source| async move {
                source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        missing,
                        &[],
                        &[],
                        Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                    )
                    .await
            })
            .await
            .is_err()
        );
        assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before);
    }

    fn assert_published_source_scope_histories(
        selection: Arc<tidepool_toolchain::artifacts::PublishedSourceOriginalSelection>,
    ) {
        use crate::recovery::recovery_test_fixture::RecoveryFixture;
        use proptest::prelude::*;
        use tidepool_runtime::session::{ModuleEnv, PersistentSession, SessionLib};
        let compiler_calls = tidepool_extract_cmd::extract_spawn_count();
        let durable = tempfile::tempdir().unwrap();
        let recovery = RecoveryFixture::create(durable.path());
        let declaration_root = durable.path().join("session");
        let mut lib = SessionLib::open(
            tidepool_repr::SessionId(7),
            &declaration_root,
            ModuleEnv::standalone_default(),
        )
        .unwrap();
        tidepool_testing::with_settlement(|settlement| recovery.attach_root(&mut lib, settlement));
        let mut session = PersistentSession::new(Some(lib), 0);
        let scope = session.mint_isolated_scope();
        let owner = tidepool_runtime::session::RecoveryPublicOwner::new(
            &tidepool_repr::ActorPath::parse("root/published-bootstrap").unwrap(),
            1,
        )
        .unwrap();
        session
            .initialize_durable_public_scope(owner.clone(), scope)
            .unwrap();
        let bootstrap = session
            .begin_durable_public_bootstrap(owner.clone(), scope)
            .unwrap();
        let pending = session
            .stage_published_source_originals_in(scope, Arc::clone(&selection))
            .unwrap();
        session.publish_source_originals(pending).unwrap();
        session.publish_durable_public_bootstrap(bootstrap).unwrap();
        let published = session.compile_view_in(scope).unwrap();
        let mut lib = SessionLib::open(
            tidepool_repr::SessionId(8),
            &declaration_root,
            ModuleEnv::standalone_default(),
        )
        .unwrap();
        tidepool_testing::with_settlement(|settlement| {
            recovery.reopen().attach_root(&mut lib, settlement)
        });
        let mut recovered = PersistentSession::new(Some(lib), 0);
        let scope = recovered.recover_public_scope(&owner).unwrap();
        let view = recovered.compile_view_in(scope).unwrap();
        assert_eq!(view.library(), None);
        assert_eq!(
            view.exact_declaration_context().unwrap().semantic_sha256(),
            published
                .exact_declaration_context()
                .unwrap()
                .semantic_sha256(),
            "native bootstrap durably carries an issued original at generation zero"
        );
        let mut config = proptest::test_runner::Config::with_source_file(file!());
        config.test_name = Some(concat!(
            module_path!(),
            "::quoted_toolset_reuses_completed_original_with_fresh_installations_and_refuses_source_replay"
        ));
        let mut runner = proptest::test_runner::TestRunner::new(config);
        runner.run(&proptest::collection::vec(0_u8..5, 1..40), |operations| {
            let root = tempfile::tempdir().unwrap();
            let lib = SessionLib::open(tidepool_repr::SessionId(7), root.path(), ModuleEnv::standalone_default()).unwrap();
            let mut session = PersistentSession::new(Some(lib), 0);
            let scope = ScopeId::ROOT;
            let empty = session.compile_view_in(scope).unwrap();
            let mut epoch = 0_u64;
            let mut pending = None;
            let mut children = Vec::new();
            for operation in operations {
                match operation {
                    0 => pending = Some((epoch,
                        session.stage_published_source_originals_in(scope, Arc::clone(&selection)).unwrap())),
                    1 => if let Some((admitted_epoch, token)) = pending.take() {
                        let before = session.compile_view_in(scope).unwrap();
                        let result = session.publish_source_originals(token);
                        if admitted_epoch == epoch {
                            prop_assert!(result.is_ok());
                            epoch += 1;
                        } else {
                            prop_assert!(matches!(result, Err(tidepool_runtime::session::SessionError::StaleStagedDeclaration)));
                            prop_assert_eq!(session.compile_view_in(scope).unwrap(), before);
                        }
                    },
                    2 => {
                        let token = session.stage_published_source_originals_in(scope, Arc::clone(&selection)).unwrap();
                        session.publish_source_originals(token).unwrap();
                        epoch += 1;
                    },
                    3 => {
                        let expected = session.compile_view_in(scope).unwrap().exact_declaration_context().cloned();
                        let child = session.mint_detached_scope(scope).unwrap();
                        let view = session.compile_view_in(child).unwrap();
                        prop_assert_eq!(view.exact_declaration_context(), expected.as_ref());
                        children.push((child, view));
                    },
                    4 => if let Some((child, captured)) = children.pop() {
                        prop_assert_eq!(session.compile_view_in(child).unwrap(), captured);
                        session.retire_scope(child);
                        prop_assert!(session.compile_view_in(child).is_none());
                    },
                    _ => unreachable!(),
                }
                let current = session.compile_view_in(scope).unwrap();
                prop_assert_eq!(current.exact_declaration_context().is_some(), epoch != 0);
                prop_assert_eq!(session.public_visibility_snapshot_in(scope).unwrap().epoch, epoch);
                prop_assert!(empty.exact_declaration_context().is_none());
                prop_assert_eq!(current.library(), None);
                for (child, captured) in &children {
                    prop_assert_eq!(&session.compile_view_in(*child).unwrap(), captured);
                }
            }
            Ok(())
        }).unwrap();
        assert_eq!(tidepool_extract_cmd::extract_spawn_count(), compiler_calls,
            "generated source-publication histories reuse immutable original custody without compiler work");
    }

    async fn assert_restore_preparation_stops_with_its_run(
        config: ActorWorkbenchSource,
        captured: crate::CheckpointSourceLayer,
        installation: PersistedActorInstallation,
    ) {
        let (run, task) = crate::LocalActorDirectory::start().await.unwrap();
        let source = config.bind_preparation(run.preparation_client());
        let (entered, started) = tokio::sync::oneshot::channel();
        let (cancelled, cancellation_seen) = tokio::sync::oneshot::channel();
        let (release, finish) = std::sync::mpsc::channel();
        let barrier = parking_lot::Mutex::new(Some((entered, cancelled, finish)));
        source
            .toolset_preparation
            .observe_completed_load(Arc::new(move || {
                let (entered, cancelled, finish) = barrier.lock().take().unwrap();
                entered.send(()).unwrap();
                while tidepool_extract_cmd::compiler_host_checkpoint().is_ok() {
                    std::thread::yield_now();
                }
                cancelled.send(()).unwrap();
                finish
                    .recv_timeout(std::time::Duration::from_secs(10))
                    .unwrap();
            }));
        let pending = tokio::spawn({
            let source = source.clone();
            let captured = captured.clone();
            let installation = installation.clone();
            async move {
                let mut observer = crate::CompilerPreparationOwner::new();
                observer
                    .scope(source.restore_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        captured,
                        &installation,
                        &[],
                        &[],
                        Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                    ))
                    .await
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(15), started)
            .await
            .unwrap()
            .unwrap();
        run.seal().await.unwrap();
        tokio::time::timeout(std::time::Duration::from_secs(2), cancellation_seen)
            .await
            .unwrap()
            .unwrap();
        assert!(matches!(
            run.settle_run_preparations(std::time::Duration::from_millis(10))
                .await,
            crate::CleanupComponentOutcome::Unconfirmed(_)
        ));
        assert!(matches!(
            source
                .restore_source_toolset(
                    tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                    captured,
                    &installation,
                    &[],
                    &[],
                    Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                )
                .await,
            Err(ResidentActorWorkbenchError::CompilerCleanupAdmissionClosed)
        ));
        release.send(()).unwrap();
        let outcome = tokio::time::timeout(std::time::Duration::from_secs(15), pending)
            .await
            .unwrap()
            .unwrap();
        assert!(
            outcome.action.is_err(),
            "retired run cannot issue a restored result"
        );
        assert!(outcome.cleanup.observation().is_confirmed());
        assert_eq!(
            run.settle_run_preparations(std::time::Duration::from_secs(2))
                .await,
            crate::CleanupComponentOutcome::Confirmed
        );
        assert_eq!(
            run.shutdown_run_resources().await,
            crate::CleanupComponentOutcome::Confirmed
        );
        run.finish_run().await.unwrap();
        task.await.unwrap();
    }

