    async fn assert_real_publisher_checkout_loss(
        workbench: &ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>,
        state: Arc<InstalledToolsState>,
        prepared: PreparedActorGeneration,
    ) {
        let target = prepared
            .candidate
            .installation
            .source_dependency()
            .generation()
            .unwrap()
            .clone();
        let parent = target.prerequisite().as_ref().unwrap().clone();
        let checkout = workbench
            .access
            .machines
            .checkout_run(prepared.checkout_context.placement.session)
            .unwrap();
        let (held_session, receipt) = checkout.into_parts();
        let terminal = crate::CompilerPreparationOwner::new();
        let publisher = workbench.generation_publisher(
            state.clone(),
            ActorPublicationOwner::Preparation(terminal.client()),
        );
        let preparation = publisher.into_publication_preparation(
            prepared,
            tidepool_runtime::session::PublicationDecision::new(),
            ActorGenerationPublication::Terminal,
        );
        let (prepared, reserve) = preparation.into_parts();
        let outcome = match reserve.reserve(prepared) {
            Ok(outcome) => outcome,
            Err(_) => panic!("the actual publisher retains its candidate"),
        };
        let ActorGenerationRetirementPreparationOutcome::Reserved {
            reserved,
            publisher,
        } = outcome
        else {
            panic!("the actual publisher reserves before checkout")
        };
        let mut publication_owner = reserved.into_publication_owner();
        let body = publication_owner.take_body().unwrap();
        let publication = publisher.run(body);
        tokio::pin!(publication);
        assert!(futures_util::poll!(publication.as_mut()).is_pending());
        assert!(
            matches!(&state.0.lock().availability, InstalledToolsAvailability::PublicationInProgress(attempt) if attempt.target.same_prepared(&target))
        );
        let parent_fence = parent.runtime_admission().fence().unwrap();
        assert_eq!(parent_fence.pending_claims(), 1);
        workbench.access.machines.settle_retire(
            receipt,
            "publication checkout control retired the actual owner",
        );
        let settlement = match publication.await {
            Ok(settlement) => settlement,
            Err(_) => panic!("the actual reservation matches its publisher"),
        };
        let ActorGenerationPublicationBodyCompletion::Unobserved { primary } =
            settlement.completion()
        else {
            panic!("unobserved checkout cannot grant source restoration")
        };
        assert!(matches!(primary, ResidentActorWorkbenchError::Checkout(_)));
        assert!(primary
            .to_string()
            .contains("publication checkout control retired the actual owner"));
        assert!(publication_owner.record_body(settlement).is_ok());
        assert!(matches!(
            publication_owner.confirm(),
            PublicationOwnerSettlement::Pending
        ));
        assert!(publication_owner.confirmed_generation().is_none());
        assert!(matches!(&state.0.lock().availability,
            InstalledToolsAvailability::PublicationInProgress(attempt) if attempt.target.same_prepared(&target)));
        assert_eq!(parent_fence.pending_claims(), 1);
        assert_eq!(parent_fence.unconfirmed_claims(), 0);
        // The retained owner holds the exact claim while recovery remains
        // unresolved. Only losing that actual owner marks it unconfirmed.
        drop(publication_owner);
        assert!(matches!(&state.0.lock().availability,
            InstalledToolsAvailability::PublicationUnavailable(attempt) if attempt.target.same_prepared(&target)));
        assert_eq!(parent_fence.unconfirmed_claims(), 1);
        drop(held_session);
    }

    async fn assert_unstarted_source_settlements(
        workbench: &ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>,
        state: Arc<InstalledToolsState>,
        preparations: Vec<PreparedActorGeneration>,
    ) {
        assert_eq!(preparations.len(), 3);
        let compiler_calls = tidepool_extract_cmd::extract_spawn_count();
        let preparation = crate::CompilerPreparationOwner::new();
        let mut preparations = preparations.into_iter();
        let issue = |prepared| {
            workbench
                .generation_publisher(
                    state.clone(),
                    ActorPublicationOwner::Preparation(preparation.client()),
                )
                .into_publication_preparation(
                    prepared,
                    tidepool_runtime::session::PublicationDecision::new(),
                    ActorGenerationPublication::Terminal,
                )
                .into_parts()
        };
        let reserve = |driver: ActorGenerationReservationDriver, prepared| match driver
            .reserve(prepared)
            .unwrap_or_else(|_| panic!("the issued driver must accept its same prepared candidate"))
        {
            ActorGenerationRetirementPreparationOutcome::Reserved {
                reserved,
                publisher,
            } => (reserved, publisher),
            ActorGenerationRetirementPreparationOutcome::Refused(detail) => panic!("{detail}"),
            ActorGenerationRetirementPreparationOutcome::Failed(error) => panic!("{error}"),
        };
        let capture = |reserved: &mut ReservedActorGeneration| match reserved.fence_original() {
            ActorGenerationRetirementCutoff::Fenced(fence) => fence,
            _ => panic!("the actual reservation must fence its selected source A"),
        };
        let (first_prepared, first_driver) = issue(preparations.next().unwrap());
        let (second_prepared, second_driver) = issue(preparations.next().unwrap());
        let (second_prepared, first_driver) = first_driver
            .reserve(second_prepared)
            .err()
            .expect("a driver cannot reserve another actual B candidate");
        let (first_prepared, second_driver) = second_driver
            .reserve(first_prepared)
            .err()
            .expect("the reverse crossed reservation returns both same owners");
        let (mut first, first_publisher) = reserve(first_driver, first_prepared);
        let first_candidate = first.candidate_custody();
        let first_identity = first_candidate.identity_observer();
        assert!(first_identity.same_candidate(&first_candidate));
        assert!(first_identity.same_observer(&first_identity.clone()));
        let mut first_original = capture(&mut first);
        let first_settlement = first
            .refuse_retirement(&mut first_original, "first actual refusal")
            .unwrap();
        let (mut second, second_publisher) = reserve(second_driver, second_prepared);
        let second_candidate = second.candidate_custody();
        assert!(!first_identity.same_candidate(&second_candidate));
        let mut second_original = capture(&mut second);
        let second_settlement = second
            .refuse_retirement(&mut second_original, "second actual refusal")
            .unwrap();
        drop((first_publisher, second_publisher));
        let (first, second_settlement) = first
            .into_settled_unstarted(second_settlement)
            .err()
            .expect("another actual attempt cannot settle the first reservation");
        assert!(first.candidate_custody().same_candidate(&first_candidate));
        let (second, first_settlement) = second
            .into_settled_unstarted(first_settlement)
            .err()
            .expect("the reverse crossed receipt also refuses without losing either owner");
        assert!(second.candidate_custody().same_candidate(&second_candidate));

        let (third_prepared, third_driver) = issue(preparations.next().unwrap());
        let (mut third, third_publisher) = reserve(third_driver, third_prepared);
        drop(third_publisher);
        let expected = third.expected_generation().unwrap().clone();
        let target = third.prepared.candidate.scope.clone();
        assert!(!target
            .source_admission()
            .same_owner(expected.scope.source_admission()));
        let original_source = expected.scope.clone();
        let mut third_original = capture(&mut third);
        let (entered, started) = std::sync::mpsc::sync_channel(0);
        let (release, finish) = std::sync::mpsc::sync_channel(0);
        third.guard.settlement_probe = Some(Arc::new(PublicationSettlementProbe {
            entered,
            release: parking_lot::Mutex::new(finish),
            unwind: false,
        }));
        let closer = std::thread::spawn(move || {
            started
                .recv_timeout(std::time::Duration::from_secs(10))
                .unwrap();
            // This probe runs after B settlement. A whole-DAG fresh admission
            // can still refuse the intentionally fenced original source A.
            let observed_b = target.source_admission().fence().and_then(|fence| {
                fence
                    .reopen_with(target.original_source(), |reopen| {
                        reopen.commit();
                        Ok::<(), std::convert::Infallible>(())
                    })
                    .map(|settled| match settled {
                        Ok(_) => (),
                        Err(never) => match never {},
                    })
            });
            let original_still_closed = original_source.admit_source().is_err();
            drop(preparation);
            release.send(()).unwrap();
            assert!(
                observed_b.is_ok(),
                "B's actual own gate did not reopen: {observed_b:?}"
            );
            assert!(
                original_still_closed,
                "the scoped B exercise cannot reopen A"
            );
        });
        let error = third
            .refuse_retirement(&mut third_original, "actual partial source settlement")
            .err()
            .unwrap();
        closer.join().unwrap();
        assert!(
            matches!(error, ResidentActorWorkbenchError::PublicationSettlement { failure }
            if matches!(failure.settlement, PublicationSettlementError::Retirement { stage: RetirementSettlementStage::Original, .. }))
        );
        assert!(expected.scope.admit_source().is_err());
        let (third, first_settlement) = third
            .into_settled_unstarted(first_settlement)
            .err()
            .expect("partial A failure cannot consume a foreign successful receipt");
        assert!(first.into_settled_unstarted(first_settlement).is_ok());
        assert!(second.into_settled_unstarted(second_settlement).is_ok());
        drop(third);
        assert!(state.current_generation().is_none());
        assert!(expected.scope.admit_source().is_err());
        assert_eq!(
            tidepool_extract_cmd::extract_spawn_count(),
            compiler_calls,
            "source settlement never replays compilation or executes a publication body"
        );
    }

    async fn assert_real_publisher_failure(
        workbench: &ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>,
        state: Arc<InstalledToolsState>,
        prepared: PreparedActorGeneration,
        control: PublicationFailureControl,
    ) {
        match control {
            PublicationFailureControl::UnstartedSourceSettlements
            | PublicationFailureControl::PublicationTransportProtocol
            | PublicationFailureControl::BootstrapCancelledBody => {
                unreachable!("the control enters at its actual preparation boundary")
            }
            PublicationFailureControl::RetirementNativeOwnerLoss(_) => {
                unreachable!("native controls use their actual directory owner")
            }
            PublicationFailureControl::BootstrapOwnerLoss
            | PublicationFailureControl::ReplacementOwnerLoss => {
                assert_real_publisher_owner_loss(workbench, state, prepared).await;
            }
            PublicationFailureControl::BootstrapCheckoutRetired
            | PublicationFailureControl::ReplacementCheckoutRetired => {
                assert_real_publisher_checkout_loss(workbench, state, prepared).await;
            }
            PublicationFailureControl::ReplacementFrozenSource => {
                let source = prepared.candidate.installation.source().clone();
                let reference = source.generation_evidence().unwrap().reference.clone();
                let captured = source.capture_compiler_sources().unwrap().unwrap();
                let candidate = ActorGenerationCandidateCustody(prepared.candidate.clone());
                let world = prepared.candidate.compiler_world.clone();
                let logical = *world.world().logical_id();
                let draft = source
                    .include_paths()
                    .last()
                    .unwrap()
                    .join("QuotedAgentSpec.hs");
                let frozen_body = std::fs::read(&draft).unwrap();
                assert!(!frozen_body.is_empty());
                let mut newer_body = frozen_body.clone();
                newer_body.extend_from_slice(b"\n-- later editable draft C\n");
                std::fs::write(&draft, &newer_body).unwrap();
                assert_ne!(std::fs::read(&draft).unwrap(), frozen_body);
                assert!(Arc::ptr_eq(
                    &captured,
                    &source.capture_compiler_sources().unwrap().unwrap()
                ));
                assert!(candidate
                    .same_candidate(&ActorGenerationCandidateCustody(prepared.candidate.clone())));
                assert!(Arc::ptr_eq(&world, &prepared.candidate.compiler_world));
                assert_eq!(world.world().logical_id(), &logical);
                let terminal = crate::CompilerPreparationOwner::new();
                let publisher = workbench.generation_publisher(
                    state.clone(),
                    ActorPublicationOwner::Preparation(terminal.client()),
                );
                let ActorGenerationReservation::Reserved(reserved) = publisher
                    .reserve(
                        prepared,
                        tidepool_runtime::session::PublicationDecision::new(),
                        ActorGenerationPublication::Terminal,
                    )
                    .unwrap()
                else {
                    panic!("the actual frozen candidate must reserve after draft C changes");
                };
                assert!(candidate.same_candidate(&reserved.candidate_custody()));
                let ActorGenerationCommit::Published { generation, .. } =
                    publisher.publish_reserved(reserved).await.unwrap()
                else {
                    panic!("the actual frozen candidate must publish after draft C changes");
                };
                assert!(Arc::ptr_eq(
                    &state.current_generation().unwrap(),
                    &generation
                ));
                assert_eq!(
                    generation
                        .installation()
                        .source()
                        .generation_evidence()
                        .unwrap()
                        .reference,
                    reference
                );
                let context = generation.context().clone();
                let original = generation.scope().clone();
                let installed_reference = reference.clone();
                let admitted = workbench
                    .access
                    .with_compiler_machine(context.clone(), move |session, _, _, _| {
                        session
                            .capture_inspection_world_in(
                                original.scope(),
                                &installed_reference,
                                original.original_source(),
                            )
                            .map_err(ResidentError::Session)
                            .map_err(ResidentActorWorkbenchError::from)
                    })
                    .await
                    .unwrap();
                assert!(
                    !admitted.needs_source_capture(),
                    "installed B must expose its existing World"
                );
                let dependency = context.source_dependency().clone();
                let work = crate::capabilities::CompilerOwnerScope::current()
                    .unwrap()
                    .with_source_dependency(&dependency)
                    .admit_work()
                    .unwrap();
                let warmed = spawn_blocking_in_span(move || {
                    let settled = work
                        .run_source_compiler_phase(
                            &dependency,
                            tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                            |owner, _| {
                                tidepool_runtime::session::run_admitted_compiler_world(
                                    owner,
                                    admitted,
                                    || panic!("installed B must not recapture draft C"),
                                )
                            },
                        )
                        .unwrap();
                    tidepool_runtime::session::finish_admitted_compiler_world(settled).unwrap()
                })
                .await
                .unwrap();
                assert!(Arc::ptr_eq(warmed.world(), world.world()));
                assert_eq!(warmed.world().logical_id(), &logical);
            }
        }
    }

    #[tokio::test]
    async fn prepared_candidate_world_retains_captured_source_after_later_draft() {
        with_test_compiler_owner(|client| async move {
            quoted_toolset_reuses_completed_original_with_fresh_installations_and_refuses_source_replay_with_compiler_owner(
                client,
                Some(crate::ActorPersistencePolicy::Ephemeral),
                Some(PublicationFailureControl::ReplacementFrozenSource),
            ).await;
        }).await;
    }

    #[tokio::test]
    async fn actual_publisher_owner_loss_after_visibility_retains_external_prerequisite() {
        for control in [
            PublicationFailureControl::BootstrapOwnerLoss,
            PublicationFailureControl::ReplacementOwnerLoss,
        ] {
            with_test_compiler_owner(|client| async move {
                quoted_toolset_reuses_completed_original_with_fresh_installations_and_refuses_source_replay_with_compiler_owner(
                    client, Some(crate::ActorPersistencePolicy::Ephemeral), Some(control),
                ).await;
            }).await;
        }
    }

    async fn assert_real_publisher_owner_loss(
        workbench: &ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>,
        state: Arc<InstalledToolsState>,
        prepared: PreparedActorGeneration,
    ) {
        let parent = prepared
            .candidate
            .installation
            .source_dependency()
            .generation()
            .unwrap()
            .prerequisite()
            .as_ref()
            .unwrap()
            .clone();
        let target = prepared
            .candidate
            .installation
            .source_dependency()
            .generation()
            .unwrap()
            .clone();
        let terminal = crate::CompilerPreparationOwner::new();
        let mut publisher = workbench.generation_publisher(
            state.clone(),
            ActorPublicationOwner::Preparation(terminal.client()),
        );
        let (entered, observed) = std::sync::mpsc::sync_channel(0);
        let (release, released) = std::sync::mpsc::channel();
        publisher.settlement_probe = Some(Arc::new(PublicationSettlementProbe {
            entered,
            release: Mutex::new(released),
            unwind: false,
        }));
        let close = std::thread::spawn(move || {
            observed
                .recv_timeout(std::time::Duration::from_secs(30))
                .unwrap();
            let fence = parent.runtime_admission().fence().unwrap();
            assert_eq!(fence.pending_claims(), 1);
            drop(terminal);
            release.send(()).unwrap();
            fence
        });
        let result = publisher
            .publish(
                prepared,
                tidepool_runtime::session::PublicationDecision::new(),
                ActorGenerationPublication::Terminal,
            )
            .await;
        let parent_fence = close.join().unwrap();
        let Err(error @ ResidentActorWorkbenchError::PublicationSettlement { .. }) = result else {
            panic!("lost publication owner must retain uncertainty")
        };
        assert!(error.requires_recovery());
        let ResidentActorWorkbenchError::PublicationSettlement { failure } = error else {
            unreachable!()
        };
        assert!(matches!(
            failure.outcome.as_ref(),
            Ok(ActorGenerationCommit::Published { .. })
        ));
        assert!(matches!(
            failure.settlement,
            PublicationSettlementError::OwnerUnavailable
        ));
        assert!(
            matches!(&state.0.lock().availability, InstalledToolsAvailability::GenerationUnavailable(generation) if generation.dependency().same_prepared(&target))
        );
        assert_eq!(parent_fence.pending_claims(), 1);
        assert_eq!(parent_fence.unconfirmed_claims(), 1);
        assert!(target.runtime_lease().admit_source().is_err());
    }

    fn quoted_toolset_reuses_completed_original_with_fresh_installations_and_refuses_source_replay_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
        generation_replacement: Option<crate::ActorPersistencePolicy>,
        publication_failure: Option<PublicationFailureControl>,
    ) -> impl std::future::Future<Output = ()> {
        Box::pin(run_quoted_generation_fixture(
            preparation_client,
            generation_replacement,
            publication_failure,
        ))
    }

    async fn run_quoted_generation_fixture(
        preparation_client: crate::CompilerPreparationClient,
        generation_replacement: Option<crate::ActorPersistencePolicy>,
        publication_failure: Option<PublicationFailureControl>,
    ) {
        let native_owner_control = matches!(
            publication_failure,
            Some(PublicationFailureControl::RetirementNativeOwnerLoss(_))
        );
        let mut recovery = None;
        let configure = |lib: &mut tidepool_runtime::session::SessionLib| {
            let fixture =
                crate::recovery::recovery_test_fixture::RecoveryFixture::create(lib.include_dir());
            tidepool_testing::with_settlement(|settlement| fixture.attach_root(lib, settlement));
            recovery = Some(fixture);
        };
        let (mut session, mut context, source, session_root) = if native_owner_control {
            host_mount_fixture_with_effects(
                configure,
                &[
                    tidepool_mcp::notifications_decl(),
                    tidepool_mcp::sleep_decl(),
                ],
                "'[Notifications, Sleep]",
            )
        } else {
            host_mount_fixture_with_lib(configure)
        };
        let recovery = recovery.unwrap();
        if publication_failure.is_some() {
            let lease = session.mint_notebook_scope_with_lease(None).unwrap();
            let parent = generation_admission::GenerationDependency::new(
                crate::ActorRef::first(crate::ActorId(99)),
                tidepool_runtime::session::NotebookGenerationId::INITIAL,
                crate::CheckpointSourceLayer::default(),
                &lease,
                None,
            );
            context.source_dependency = generation_admission::SourceDependency::World(
                generation_admission::BootstrapWorld::new(Some(parent)),
            );
        }
        let native_descriptor = native_owner_control.then(|| {
            crate::ActorDescriptor::new("quoted replacement", context.placement)
                .with_actor_path(tidepool_repr::ActorPath::parse("root/quoted-original").unwrap())
                .with_persistence_policy(generation_replacement.unwrap())
                .with_capabilities(crate::ActorCapabilities::default().with_effect_keys(vec![
                    crate::ActorEffectKey::Notifications,
                    crate::ActorEffectKey::Sleep,
                ]))
                .with_source_dependency(context.source_dependency().clone())
        });
        if let Some(descriptor) = &native_descriptor {
            let issued = descriptor.session_context(context.actor);
            assert_eq!(
                issued, context,
                "the real host and descriptor agree before A preparation"
            );
            context = issued;
        }
        let owner = tidepool_runtime::session::RecoveryPublicOwner::new(
            &tidepool_repr::ActorPath::parse("root/quoted-original").unwrap(),
            context.actor.incarnation.0,
        )
        .unwrap();
        let authored = Arc::new(tempfile::tempdir().unwrap());
        let quotation_input = authored.path().join("external-input");
        std::fs::write(&quotation_input, "41").unwrap();
        std::fs::write(
            authored.path().join("QuotedProvider.hs"),
            &tidepool_testing::fixture_source(
                "exomonad/actor/src/fixtures/quoted-agent-provider.hs",
            ),
        )
        .unwrap();
        std::fs::write(
            authored.path().join("QuotedAgentSpec.hs"),
            &tidepool_testing::fixture_source("exomonad/actor/src/fixtures/quoted-agent-spec.hs")
                .replace("{quotation-input}", quotation_input.to_str().unwrap()),
        )
        .unwrap();
        let mut roots = source.toolset_support.to_vec();
        roots.push(authored.path().canonicalize().unwrap());
        let source = source
            .with_toolset_support_roots(roots.clone())
            .with_spec("QuotedAgentSpec.agentSpec")
            .bind_preparation(preparation_client.clone());
        struct GenerationSource {
            issuer: crate::SourceLayerIssuer,
            inspection: crate::SourceInspectionServices,
            _owner: Arc<tempfile::TempDir>,
            _entries: Arc<tempfile::TempDir>,
            paths: Vec<PathBuf>,
            identities: Vec<String>,
            evidence: crate::SourceGenerationEvidence,
            entries: crate::SourceEntryStorage,
            compiler_sources: Arc<tidepool_toolchain::compiler_world::CapturedCompilerSources>,
        }
        impl crate::ActorSourceLayers for GenerationSource {
            fn inspection_services(self: Arc<Self>) -> crate::SourceInspectionServices {
                self.inspection.clone()
            }

            fn validate_source_authority(
                &self,
                source: &crate::CheckpointSourceLayer,
            ) -> Result<(), String> {
                if !self.issuer.owns(source)
                    || source.include_paths() != self.paths
                    || source.identities() != self.identities
                    || !source
                        .generation_evidence()
                        .is_some_and(|evidence| std::ptr::eq(evidence, &self.evidence))
                {
                    return Err("source is not the retained quoted generation selection".into());
                }
                let captured = source
                    .capture_compiler_sources()
                    .map_err(|error| error.to_string())?;
                if !captured.is_some_and(|captured| Arc::ptr_eq(&captured, &self.compiler_sources))
                {
                    return Err("source differs from the retained quoted compiler bytes".into());
                }
                Ok(())
            }

            fn toolset_layer_from(
                &self,
                source: &crate::CheckpointSourceLayer,
            ) -> Result<crate::CheckpointSourceLayer, String> {
                self.validate_source_authority(source)?;
                Ok(source.clone())
            }

            fn stage_reload(
                self: Arc<Self>,
                _: tidepool_repr::PrincipalId,
                _: &crate::CheckpointSourceLayer,
                _: &[String],
            ) -> Result<Box<dyn crate::StagedActorSourceReload>, crate::SourceLayerReload>
            {
                Err(crate::SourceLayerReload::Unavailable(
                    "the retained quoted source owner does not publish reloads".into(),
                ))
            }
        }
        impl crate::RetainedSourceLayer for GenerationSource {
            fn identities(&self) -> &[String] {
                &self.identities
            }
            fn include_paths(&self) -> &[PathBuf] {
                &self.paths
            }
            fn catalog_selection(&self) -> tidepool_toolchain::toolchain::CatalogSelection {
                tidepool_toolchain::toolchain::CatalogSelection::Acquired(None)
            }
            fn prepared_entries(&self) -> Option<&crate::SourceEntryStorage> {
                Some(&self.entries)
            }
            fn generation_evidence(&self) -> Option<&crate::SourceGenerationEvidence> {
                Some(&self.evidence)
            }
            fn capture_compiler_sources(
                &self,
            ) -> Result<
                Option<Arc<tidepool_toolchain::compiler_world::CapturedCompilerSources>>,
                crate::SourceInspectionError,
            > {
                Ok(Some(self.compiler_sources.clone()))
            }
        }
        let source_reference = tidepool_runtime::session::GenerationArtifactReference::capture(
            std::fs::read(authored.path().join("QuotedAgentSpec.hs")).unwrap(),
        );
        let entry_storage = Arc::new(tempfile::tempdir().unwrap());
        let source_issuer = crate::SourceLayerIssuer::default();
        let (compiler_source_capsule, compiler_source_owner) =
            world_query_test_source_files_with_support(&[], &roots);
        assert_eq!(compiler_source_owner.roots.len(), roots.len());
        let quoted_root = compiler_source_owner.roots.last().unwrap();
        assert_eq!(
            quoted_root
                .bodies
                .get(std::path::Path::new("QuotedAgentSpec.hs"))
                .unwrap()
                .as_ref(),
            std::fs::read(authored.path().join("QuotedAgentSpec.hs")).unwrap(),
            "the actual quoted module body contributes to the captured source domain"
        );
        let inspection = crate::SourceInspectionServices::new(compiler_source_owner.clone());
        let compiler_sources = Arc::new(
            tidepool_toolchain::compiler_world::CapturedCompilerSources::from_captured_roots(
                compiler_source_owner.roots.clone(),
                Arc::from(source_reference.bytes()),
                compiler_source_owner,
            )
            .unwrap(),
        );
        let generation_source_owner = Arc::new(GenerationSource {
            issuer: source_issuer.clone(),
            inspection,
            _owner: authored.clone(),
            _entries: entry_storage.clone(),
            entries: crate::SourceEntryStorage::FreshCompilation {
                directory: entry_storage.path().to_owned(),
                preparation: uuid::Uuid::new_v4(),
            },
            paths: roots.clone(),
            identities: vec!["quoted original source".into()],
            evidence: crate::SourceGenerationEvidence {
                reference: source_reference.clone(),
                configuration_digest: [0; 32],
            },
            compiler_sources,
        });
        let generation_source = source_issuer.issue(generation_source_owner.clone());
        let source_layers: crate::ActorSourceLayerResolver = generation_source_owner;
        assert!(
            source_layers
                .toolset_layer_from(&compiler_source_capsule)
                .is_err(),
            "equal captured roots from another actual issuer cannot authorize this source"
        );
        assert!(
            source_layers
                .toolset_layer_from(&crate::CheckpointSourceLayer::default())
                .is_err(),
            "an unowned default cannot substitute for the captured quoted source"
        );
        assert!(
            crate::resident_actor::WorkbenchCompilationAuthority::admit(
                context.clone(),
                compiler_source_capsule,
                None,
                Some(&source_layers),
            )
            .is_err(),
            "request admission must refuse the different genuine source capsule"
        );
        let (context, compilation_authority) =
            crate::resident_actor::WorkbenchCompilationAuthority::admit(
                context,
                generation_source.clone(),
                None,
                Some(&source_layers),
            )
            .expect("the actual quoted source owner admits its original request");
        let machines = Arc::new(ActorMachineRegistry::new());
        machines.insert_idle(context.placement.session, Box::new(session));
        let workbench = ResidentActorWorkbench::new(machines, source.clone(), None)
            .with_compilation_authority(compilation_authority);
        workbench_runner_for_test(&workbench)
            .adopt_final_source_scope(context.clone())
            .await
            .unwrap();
        let recover_context = || {
            let mut lib = tidepool_runtime::session::SessionLib::open(
                tidepool_repr::SessionId(8_141),
                session_root.path(),
                tidepool_runtime::session::ModuleEnv::standalone_default(),
            )
            .unwrap()
            .with_validation_include(roots.clone());
            tidepool_testing::with_settlement(|settlement| {
                recovery.reopen().attach_root(&mut lib, settlement)
            });
            let mut recovered = tidepool_runtime::session::PersistentSession::new(Some(lib), 0);
            let scope = recovered.recover_public_scope(&owner).unwrap();
            recovered.compile_view_in(scope).unwrap()
        };
        let install_quoted_tools = async {
            let warmed = if generation_replacement.is_some() {
                source
                    .prepare_source_toolset(
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        generation_source.clone(),
                        &[],
                        &[],
                        Arc::new(tidepool_runtime::session::ImageRegistry::new()),
                    )
                    .await
                    .unwrap()
            } else {
                workbench
                    .prepare_toolset_only(
                        context.clone(),
                        tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                        Vec::new(),
                    )
                    .await
                    .unwrap()
            };
            let warm_executions =
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap();
            let public_selection = warmed
                .prepared
                .entry
                .published_source_original_selection(
                    &warmed.prepared.source_revision,
                    &tidepool_toolchain::declaration_join::ExactModuleIdentity {
                        unit: "main".into(),
                        module: "QuotedAgentSpec".into(),
                    },
                )
                .unwrap();
            if generation_replacement.is_none() {
                assert_published_source_scope_histories(Arc::clone(&public_selection));
            }
            let publication = workbench_runner_for_test(&workbench)
                .initialize_durable_public_owner(context.clone(), owner.clone())
                .await
                .expect("the actual public owner initializes its captured source scope");
            match publication {
                tidepool_runtime::session::DurablePublicOwnerPublication::Committed(_) => {}
                tidepool_runtime::session::DurablePublicOwnerPublication::CommittedContinuing {
                    cancellation_pending,
                    ..
                } => panic!(
                    "public bootstrap continued with cancellation_pending={cancellation_pending}"
                ),
                tidepool_runtime::session::DurablePublicOwnerPublication::Refused { error } => {
                    panic!("public bootstrap refused: {error:?}")
                }
                tidepool_runtime::session::DurablePublicOwnerPublication::RecoveryRequired {
                    error,
                } => {
                    panic!("public bootstrap requires recovery: {error:?}")
                }
            }
            let warm_view = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    Ok(session
                        .compile_view_in(context.placement.lexical_scope)
                        .unwrap())
                })
                .await
                .unwrap();
            assert!(warm_view.exact_declaration_context().is_none());
            let (first_bootstrap, first_bootstrap_snapshot) = workbench
                .access
                .with_machine(context.clone(), {
                    let owner = owner.clone();
                    move |session, context, _| {
                        let bootstrap = session
                            .begin_durable_public_bootstrap(owner, context.placement.lexical_scope)
                            .map_err(|error| {
                                ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                            })?;
                        let snapshot = session
                            .public_visibility_snapshot_in(context.placement.lexical_scope)
                            .expect("the bootstrap owner holds its actual public scope");
                        Ok((bootstrap, snapshot))
                    }
                })
                .await
                .expect("the first installation borrows its actual public bootstrap ticket");
            let first = Arc::new(if generation_replacement.is_some() {
                workbench
                    .install_tools_action(
                        context.clone(),
                        1,
                        vec![],
                        warmed.effects.clone(),
                        InstalledToolCode::SourcePrepared(warmed.prepared.clone()),
                        ToolInstallationPurpose::InitialTools,
                    )
                    .await
                    .unwrap()
                    .tools
            } else {
                workbench
                    .prepare_tools(context.clone(), 1, vec![])
                    .await
                    .unwrap()
            });
            if generation_replacement == Some(crate::ActorPersistencePolicy::Ephemeral)
                && publication_failure.is_none()
            {
                let lease = InstalledToolLease::new(
                    context.actor,
                    generation_source.clone(),
                    Some(first.clone()),
                );
                let installation =
                    PersistedActorInstallation::capture(&lease, &source_reference).unwrap();
                assert_restore_preparation_stops_with_its_run(
                    source.config().clone(),
                    generation_source.clone(),
                    installation,
                )
                .await;
            }
            let initial_originals = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    let view = session
                        .compile_view_in(context.placement.lexical_scope)
                        .unwrap();
                    Ok(view
                        .exact_declaration_context()
                        .expect("initial installation publishes its issued original")
                        .published_source_original_selections()
                        .map_err(ResidentActorWorkbenchError::Compile)?)
                })
                .await
                .unwrap();
            assert_eq!(initial_originals.len(), 1);
            assert_eq!(
                initial_originals[0].public_root(),
                public_selection.public_root()
            );
            assert_eq!(initial_originals[0].revision(), public_selection.revision());
            let source_identity =
                |context: &tidepool_toolchain::declaration_join::ExactDeclarationContext| {
                    let mut identities = context.compiler_input_roles().into_iter().filter_map(|role| {
                    let tidepool_toolchain::artifact_inventory::CompilerInputRole::PublishedSourceOriginal {
                        interface, original, source_revision, original_input_identity, selection_sha256, ..
                    } = role else { return None; };
                    Some((interface, original, source_revision, original_input_identity, selection_sha256))
                }).collect::<Vec<_>>();
                    identities.sort();
                    identities
                };
            assert_eq!(
                source_identity(initial_originals[0].context()),
                source_identity(public_selection.context()),
                "installation preserves the exact issued original selection"
            );
            assert!(public_selection
                .context()
                .artifact_view()
                .selected_native_groups()
                .is_subset(
                    &initial_originals[0]
                        .context()
                        .artifact_view()
                        .selected_native_groups()
                ));
            if publication_failure.is_none() {
                assert_eq!(
                    initial_originals[0].context().semantic_sha256(),
                    public_selection.context().semantic_sha256(),
                    "ordinary installation carries the exact completed original before bootstrap publication"
                );
            }
            workbench
                .access
                .with_machine(context.clone(), move |session, _, _| {
                    let current = session
                        .public_visibility_snapshot_in(first_bootstrap_snapshot.scope)
                        .expect("the first installation retains its actual public scope");
                    session.publish_durable_public_bootstrap(first_bootstrap).map_err(|error| {
                            eprintln!(
                                "first bootstrap ticket refusal: {error:?}; initial machine={:?} scope={:?} epoch={} tip={:?} bindings={} sources={}; current machine={:?} scope={:?} epoch={} tip={:?} bindings={} sources={}",
                                first_bootstrap_snapshot.machine_incarnation,
                                first_bootstrap_snapshot.scope,
                                first_bootstrap_snapshot.epoch,
                                first_bootstrap_snapshot.declaration_tip,
                                first_bootstrap_snapshot.bindings.len(),
                                first_bootstrap_snapshot.source_instances.len(),
                                current.machine_incarnation,
                                current.scope,
                                current.epoch,
                                current.declaration_tip,
                                current.bindings.len(),
                                current.source_instances.len(),
                            );
                            ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                        })
                })
                .await
                .expect("the first installation publishes only its own bootstrap ticket");
            let installed_view = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    Ok(session
                        .compile_view_in(context.placement.lexical_scope)
                        .unwrap())
                })
                .await
                .unwrap();
            assert_ne!(
                installed_view, warm_view,
                "same-tip installation invalidates the warm view"
            );
            assert!(installed_view.exact_declaration_context().is_some());
            assert!(
                warm_view.exact_declaration_context().is_none(),
                "earlier capture remains immutable"
            );
            let generation_zero_recovered = recover_context();
            assert_eq!(generation_zero_recovered.library(), None);
            assert_eq!(
                generation_zero_recovered
                    .exact_declaration_context()
                    .unwrap()
                    .semantic_sha256(),
                installed_view
                    .exact_declaration_context()
                    .unwrap()
                    .semantic_sha256(),
                "generation-zero recovery restores the issued original policy"
            );

            assert!(Arc::ptr_eq(
                &warmed.prepared,
                &first.code.prepared().expect("source-prepared installation")
            ));
            assert_eq!(first.revision(), Some(warmed.source_revision()));
            let resolved = first.resolved_spec().unwrap();
            assert!(std::ptr::eq(resolved, &warmed.prepared.resolved));
            assert_eq!(
                resolved.checked_module().as_deref(),
                Some("QuotedAgentSpec")
            );
            assert_eq!(
                first.provenance(),
                format!(
                    "install=1 revision={} {}",
                    warmed.source_revision(),
                    resolved.describe()
                )
            );
            let completed_executions =
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap();
            assert!(
                !completed_executions.is_empty(),
                "the original compiler executes the actual local quoter"
            );
            assert_eq!(
                completed_executions, warm_executions,
                "the actual installation reuses immutable readiness without another compiler turn"
            );
            let proof = first
                .code
                .prepared()
                .expect("source-prepared installation")
                .entry
                .ordinary_original_compile_input();
            assert!(
                proof.replay_eligible_identity().is_none(),
                "quotation remains ineligible for ordinary source replay"
            );
            assert_ne!(
                proof.source_replay_eligibility(),
                tidepool_toolchain::artifacts::SourceReplayEligibility::Eligible
            );
            let stale_installation = workbench
                .access
                .with_machine(context.clone(), {
                    let selection = Arc::clone(&public_selection);
                    move |session, context, _| {
                        session
                            .stage_published_source_originals_in(
                                context.placement.lexical_scope,
                                selection,
                            )
                            .map_err(ResidentActorWorkbenchError::Resident)
                    }
                })
                .await
                .unwrap();
            let second_bootstrap = workbench
                .access
                .with_machine(context.clone(), {
                    let owner = owner.clone();
                    move |session, context, _| {
                        session
                            .begin_durable_public_bootstrap(owner, context.placement.lexical_scope)
                            .map_err(|error| {
                                ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                            })
                    }
                })
                .await
                .unwrap();
            let second = Arc::new(if generation_replacement.is_some() {
                workbench
                    .install_tools_action(
                        context.clone(),
                        2,
                        vec![],
                        warmed.effects.clone(),
                        InstalledToolCode::SourcePrepared(warmed.prepared.clone()),
                        ToolInstallationPurpose::InitialTools,
                    )
                    .await
                    .unwrap()
                    .tools
            } else {
                workbench
                    .prepare_tools(context.clone(), 2, vec![])
                    .await
                    .unwrap()
            });
            workbench
                .access
                .with_machine(context.clone(), move |session, _, _| {
                    session
                        .publish_durable_public_bootstrap(second_bootstrap)
                        .map_err(|error| {
                            ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                        })
                })
                .await
                .unwrap();
            workbench
                .access
                .with_machine(context.clone(), move |session, context, _| {
                    let before = session
                        .compile_view_in(context.placement.lexical_scope)
                        .unwrap();
                    assert!(matches!(
                        session.publish_source_originals(stale_installation),
                        Err(ResidentError::Session(
                            tidepool_runtime::session::SessionError::StaleStagedDeclaration
                        ))
                    ));
                    assert_eq!(
                        session
                            .compile_view_in(context.placement.lexical_scope)
                            .unwrap(),
                        before
                    );
                    Ok(())
                })
                .await
                .unwrap();

            assert!(Arc::ptr_eq(
                &first.code.prepared().expect("source-prepared installation"),
                &second
                    .code
                    .prepared()
                    .expect("source-prepared installation")
            ));
            assert!(
                !Arc::ptr_eq(&first.dispatch, &second.dispatch),
                "separate installations own separate actual dispatch custody"
            );
            assert_ne!(
                first._installation_scope.scope(),
                second._installation_scope.scope()
            );
            assert_eq!(
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap(),
                completed_executions
            );
            assert_eq!(first.surface(), second.surface());
            (
                first,
                second,
                completed_executions,
                warmed,
                Some(generation_zero_recovered),
            )
        };
        let (first, second, completed_executions, warmed, generation_zero_recovered) =
            install_quoted_tools.await;
        let proof = first
            .code
            .prepared()
            .unwrap()
            .entry
            .ordinary_original_compile_input();
        if generation_replacement.is_some() {
            let replacement_publication_history = async {
                // Replacement publishes its own issued source base without inheriting the notebook.
                let descriptor = native_descriptor.clone().unwrap_or_else(|| {
                    crate::ActorDescriptor::new("quoted replacement", context.placement)
                        .with_actor_path(
                            tidepool_repr::ActorPath::parse("root/quoted-original").unwrap(),
                        )
                        .with_persistence_policy(generation_replacement.unwrap())
                });
                let state = Arc::new(InstalledToolsState::default());
                let installation = InstalledToolLease::new(
                    context.actor,
                    generation_source.clone(),
                    Some(second.clone()),
                );
                assert_eq!(
                    state.install_bootstrap(
                        BootstrapExpectation::Available(&installation),
                        installation.clone()
                    ),
                    Err(BootstrapInstallationError::Changed)
                );
                assert!(state.snapshot().is_none());
                state
                    .install_bootstrap(BootstrapExpectation::Empty, installation.clone())
                    .unwrap();
                assert_eq!(
                    state.install_bootstrap(BootstrapExpectation::Empty, installation.clone()),
                    Err(BootstrapInstallationError::Changed)
                );
                let stale_bootstrap = InstalledToolLease::new(
                    context.actor,
                    generation_source.clone(),
                    Some(first.clone()),
                );
                assert_eq!(
                    state.install_bootstrap(
                        BootstrapExpectation::Available(&stale_bootstrap),
                        installation.clone()
                    ),
                    Err(BootstrapInstallationError::Changed)
                );
                assert!(state.current().unwrap().same_installation(&installation));
                state
                    .install_bootstrap(
                        BootstrapExpectation::Available(&installation),
                        installation.clone(),
                    )
                    .unwrap();
                let prompts = tidepool_runtime::session::ComposedPromptSnapshot::capture(
                    "quoted generation".into(),
                );
                let prepared = workbench
                    .prepare_initial_generation(
                        state.clone(),
                        context.clone(),
                        descriptor.clone(),
                        installation.clone(),
                        prompts.clone(),
                    )
                    .await
                    .unwrap_or_else(|error| {
                        panic!(
                            "initial generation preparation {:?}: {error:?}",
                            descriptor.persistence_policy()
                        )
                    });
                let expected_work = InstallationObservationWork {
                    captures: 1,
                    encodings: usize::from(
                        descriptor.persistence_policy() == crate::ActorPersistencePolicy::Durable,
                    ),
                    restored_decodes: 0,
                };
                assert_eq!(prepared.installation_work, expected_work);
                if let Some(control) = publication_failure.filter(|control| control.bootstrap()) {
                    if matches!(control, PublicationFailureControl::BootstrapCancelledBody) {
                        let publisher = workbench.generation_publisher(
                            state.clone(),
                            ActorPublicationOwner::Preparation(preparation_client.clone()),
                        );
                        let decision = tidepool_runtime::session::PublicationDecision::new();
                        let preparation = publisher.into_publication_preparation(
                            prepared,
                            decision.clone(),
                            ActorGenerationPublication::Terminal,
                        );
                        let (directory, task) = crate::LocalActorDirectory::start().await.unwrap();
                        directory
                            .assert_cancelled_initial_publication(
                                preparation,
                                state,
                                decision,
                                descriptor.persistence_policy()
                                    == crate::ActorPersistencePolicy::Durable,
                            )
                            .await;
                        directory.stop_owner_for_test().await;
                        tokio::time::timeout(std::time::Duration::from_secs(10), task)
                            .await
                            .unwrap()
                            .unwrap();
                    } else {
                        assert_real_publisher_failure(&workbench, state, prepared, control).await;
                    }
                    return;
                }
                let initial = match workbench
                    .generation_publisher(
                        state.clone(),
                        ActorPublicationOwner::Preparation(preparation_client.clone()),
                    )
                    .publish(
                        prepared,
                        tidepool_runtime::session::PublicationDecision::new(),
                        ActorGenerationPublication::Terminal,
                    )
                    .await
                    .unwrap()
                {
                    ActorGenerationCommit::Published { generation, .. } => generation,
                    _ => panic!("initial generation must publish"),
                };
                assert_eq!(
                    state.install_bootstrap(
                        BootstrapExpectation::Available(&installation),
                        installation.clone()
                    ),
                    Err(BootstrapInstallationError::PublishedGeneration)
                );
                assert!(Arc::ptr_eq(&state.current_generation().unwrap(), &initial));
                if let Some(selected) = &initial.durable {
                    // The stored reference is produced by real generation publication;
                    // this control does not manufacture native or source authority.
                    let mut observed = installation.clone().observe_generation().unwrap();
                    observed
                        .verify_restored(&selected.references, &prompts)
                        .unwrap();
                    assert_eq!(
                        observed.work,
                        InstallationObservationWork {
                            captures: 1,
                            encodings: 0,
                            restored_decodes: 1,
                        }
                    );
                    assert!(observed.lease.same_installation(&installation));
                    let mut corrupt = selected.references.clone();
                    corrupt.installation =
                        tidepool_runtime::session::GenerationArtifactReference::capture(
                            b"not installation json".to_vec(),
                        );
                    assert!(observed.verify_restored(&corrupt, &prompts).is_err());
                    assert!(observed.lease.same_installation(&installation));
                    assert!(Arc::ptr_eq(&state.current_generation().unwrap(), &initial));
                    let source_bytes = observed.source.bytes().as_ptr();
                    let encoded = observed.into_durable_references(prompts.clone()).unwrap();
                    assert_eq!(
                        encoded.references.source.bytes().as_ptr(),
                        source_bytes,
                        "durable projection moves the exact observed source bytes"
                    );
                    assert!(encoded.lease.same_installation(&installation));
                    encoded
                        .lease
                        .verify_recovered_generation(&encoded.references)
                        .unwrap();
                }
                let pinned_endpoint = state.snapshot().unwrap().select("probe").unwrap();
                let (before, before_visibility) = workbench
                    .access
                    .with_machine(context.clone(), |session, context, _| {
                        Ok((
                            session
                                .compile_view_in(context.placement.lexical_scope)
                                .unwrap(),
                            session
                                .public_visibility_snapshot_in(context.placement.lexical_scope)
                                .unwrap(),
                        ))
                    })
                    .await
                    .unwrap();
                let before_commit = before.clone();
                let candidate = Arc::new(
                    workbench
                        .install_tools_action(
                            context.clone(),
                            7,
                            vec![],
                            warmed.effects.clone(),
                            InstalledToolCode::SourcePrepared(warmed.prepared.clone()),
                            ToolInstallationPurpose::CandidateTools,
                        )
                        .await
                        .unwrap()
                        .tools,
                );
                let next_installation = InstalledToolLease::new(
                    context.actor,
                    generation_source.clone(),
                    Some(candidate),
                );
                if let Some(control) = publication_failure.filter(|control| !control.bootstrap()) {
                    let prepared = workbench
                        .prepare_actor_generation(
                            context.clone(),
                            descriptor.clone(),
                            ActorRequestSnapshot::Generation(initial.clone()),
                            next_installation.clone(),
                            prompts.clone(),
                        )
                        .await
                        .unwrap();
                    if let PublicationFailureControl::RetirementNativeOwnerLoss(control) = control {
                        generation_admission::assert_native_retirement_owner_control(
                            &workbench,
                            state,
                            context.clone(),
                            descriptor.clone(),
                            initial.clone(),
                            prepared,
                            control,
                        )
                        .await;
                    } else if matches!(
                        control,
                        PublicationFailureControl::UnstartedSourceSettlements
                            | PublicationFailureControl::PublicationTransportProtocol
                    ) {
                        let mut preparations = vec![prepared];
                        for _ in 0..2 {
                            preparations.push(
                                workbench
                                    .prepare_actor_generation(
                                        context.clone(),
                                        descriptor.clone(),
                                        ActorRequestSnapshot::Generation(initial.clone()),
                                        next_installation.clone(),
                                        prompts.clone(),
                                    )
                                    .await
                                    .unwrap(),
                            );
                        }
                        if matches!(
                            control,
                            PublicationFailureControl::PublicationTransportProtocol
                        ) {
                            crate::resident_actor::assert_publication_transport_protocol(
                                &workbench,
                                state,
                                preparations,
                            )
                            .await;
                        } else {
                            assert_unstarted_source_settlements(&workbench, state, preparations)
                                .await;
                        }
                    } else {
                        assert_real_publisher_failure(&workbench, state, prepared, control).await;
                    }
                    return;
                }
                let replacement_validation_history = async {
                    for cancelled in [false, true] {
                        let rejected = workbench
                            .prepare_actor_generation(
                                context.clone(),
                                descriptor.clone(),
                                ActorRequestSnapshot::Generation(initial.clone()),
                                next_installation.clone(),
                                prompts.clone(),
                            )
                            .await
                            .unwrap();
                        assert_eq!(rejected.installation_work, expected_work);
                        let rejected_scope = rejected.candidate.scope.clone();
                        let decision = tidepool_runtime::session::PublicationDecision::new();
                        if cancelled {
                            decision.request_cancellation();
                        }
                        let domain = tidepool_runtime::session::RecoveryDomainId::Root;
                        let revision = recovery
                            .store
                            .read_domain(domain)
                            .unwrap()
                            .unwrap()
                            .revision;
                        assert!(matches!(
                            workbench
                                .generation_publisher(
                                    if cancelled {
                                        state.clone()
                                    } else {
                                        Arc::new(InstalledToolsState::default())
                                    },
                                    ActorPublicationOwner::Preparation(preparation_client.clone())
                                )
                                .publish(rejected, decision, ActorGenerationPublication::Terminal,)
                                .await
                                .unwrap(),
                            ActorGenerationCommit::Refused(_)
                        ));
                        assert_eq!(
                            recovery
                                .store
                                .read_domain(domain)
                                .unwrap()
                                .unwrap()
                                .revision,
                            revision,
                            "cancelled or unavailable publication owner writes no public manifest"
                        );
                        let old = before.clone();
                        workbench
                            .access
                            .with_machine(context.clone(), move |session, context, _| {
                                assert_eq!(
                                    session
                                        .compile_view_in(context.placement.lexical_scope)
                                        .unwrap(),
                                    old
                                );
                                assert!(session
                                    .compile_view_in(rejected_scope.scope())
                                    .unwrap()
                                    .exact_declaration_context()
                                    .is_none());
                                Ok(())
                            })
                            .await
                            .unwrap();
                    }
                    let foreign = workbench
                        .prepare_actor_generation(
                            context.clone(),
                            descriptor.clone(),
                            ActorRequestSnapshot::Generation(initial.clone()),
                            next_installation.clone(),
                            prompts.clone(),
                        )
                        .await
                        .unwrap();
                    let foreign_owner =
                        ResidentActorWorkbench::<frunk::HNil, tidepool_mcp::CapturedOutput>::new(
                            Arc::new(ActorMachineRegistry::new()),
                            source.clone(),
                            None,
                        );
                    assert!(matches!(
                        foreign_owner
                            .generation_publisher(
                                state.clone(),
                                ActorPublicationOwner::Preparation(preparation_client.clone())
                            )
                            .publish(
                                foreign,
                                tidepool_runtime::session::PublicationDecision::new(),
                                ActorGenerationPublication::Terminal,
                            )
                            .await
                            .unwrap(),
                        ActorGenerationCommit::Refused(_)
                    ));
                    assert!(Arc::ptr_eq(&state.current_generation().unwrap(), &initial));
                    let stale = workbench
                        .prepare_actor_generation(
                            context.clone(),
                            descriptor.clone(),
                            ActorRequestSnapshot::Generation(initial.clone()),
                            next_installation.clone(),
                            prompts.clone(),
                        )
                        .await
                        .unwrap();
                    state
                        .replace_explicit(
                            &initial.installation,
                            initial.installation.tools_arc().unwrap(),
                        )
                        .unwrap();
                    let current = state.current_generation().unwrap();
                    assert!(!Arc::ptr_eq(&initial, &current));
                    assert!(matches!(
                        workbench
                            .generation_publisher(
                                state.clone(),
                                ActorPublicationOwner::Preparation(preparation_client.clone())
                            )
                            .publish(
                                stale,
                                tidepool_runtime::session::PublicationDecision::new(),
                                ActorGenerationPublication::Terminal,
                            )
                            .await
                            .unwrap(),
                        ActorGenerationCommit::Refused(_)
                    ));
                    assert!(Arc::ptr_eq(&state.current_generation().unwrap(), &current));
                    let prepared = workbench
                        .prepare_actor_generation(
                            context.clone(),
                            descriptor.clone(),
                            ActorRequestSnapshot::Generation(current),
                            next_installation.clone(),
                            prompts.clone(),
                        )
                        .await
                        .unwrap();
                    assert_eq!(prepared.installation_work, expected_work);
                    let next_scope = prepared.candidate.scope.scope();
                    workbench
                        .access
                        .with_machine(context.clone(), move |session, context, _| {
                            assert_eq!(
                                session
                                    .compile_view_in(context.placement.lexical_scope)
                                    .unwrap(),
                                before
                            );
                            assert!(session
                                .compile_view_in(next_scope)
                                .unwrap()
                                .exact_declaration_context()
                                .is_none());
                            Ok(())
                        })
                        .await
                        .unwrap();
                    let domain = tidepool_runtime::session::RecoveryDomainId::Root;
                    let revision = recovery
                        .store
                        .read_domain(domain)
                        .unwrap()
                        .unwrap()
                        .revision;
                    workbench
                        .access
                        .with_machine(context.clone(), |session, _, _| {
                            let scope = session.mint_isolated_scope();
                            let owner = tidepool_runtime::session::RecoveryPublicOwner::new(
                                &tidepool_repr::ActorPath::parse("root/unrelated-source-owner")
                                    .unwrap(),
                                1,
                            )
                            .unwrap();
                            session
                                .initialize_durable_public_scope(owner, scope)
                                .map_err(|error| {
                                    ResidentActorWorkbenchError::Resident(ResidentError::Session(
                                        error,
                                    ))
                                })?;
                            Ok(())
                        })
                        .await
                        .unwrap();
                    assert_ne!(
                        recovery
                            .store
                            .read_domain(domain)
                            .unwrap()
                            .unwrap()
                            .revision,
                        revision,
                        "an unrelated public owner forces the prepared replacement to rebase"
                    );
                    let replacement = match workbench
                        .generation_publisher(
                            state.clone(),
                            ActorPublicationOwner::Preparation(preparation_client.clone()),
                        )
                        .publish(
                            prepared,
                            tidepool_runtime::session::PublicationDecision::new(),
                            ActorGenerationPublication::Terminal,
                        )
                        .await
                        .unwrap()
                    {
                        ActorGenerationCommit::Published { generation, .. } => generation,
                        _ => panic!("replacement must publish"),
                    };
                    crate::resident_actor::pinned_endpoint_generation_tests::assert_pinned_preflight(
                        ResidentActorRunner::new(
                            Arc::clone(&workbench.access.machines),
                            source.clone(),
                        ),
                        descriptor.clone(),
                        state.clone(),
                        initial.clone(),
                        replacement.clone(),
                        pinned_endpoint.clone(),
                        source_issuer.clone(),
                    );
                    assert_ne!(replacement.scope.scope(), initial.scope.scope());
                    assert!(Arc::ptr_eq(
                        pinned_endpoint.snapshot().generation().unwrap(),
                        &initial
                    ));
                    let current_endpoint = state.snapshot().unwrap().select("probe").unwrap();
                    assert!(Arc::ptr_eq(
                        current_endpoint.snapshot().generation().unwrap(),
                        &replacement
                    ));
                    assert_ne!(
                        pinned_endpoint
                            .snapshot()
                            .generation()
                            .unwrap()
                            .context
                            .placement
                            .lexical_scope,
                        current_endpoint
                            .snapshot()
                            .generation()
                            .unwrap()
                            .context
                            .placement
                            .lexical_scope,
                    );
                    let execution = Arc::new(
                        workbench_runner_for_test(&workbench)
                            .begin_private_execution(
                                replacement.context.clone(),
                                replacement.public_owner.clone(),
                                tidepool_runtime::session::PublicationDecision::new(),
                                None,
                            )
                            .await
                            .unwrap(),
                    );
                    let mut private_context = replacement.context.clone();
                    private_context.placement.lexical_scope = execution.private_scope;
                    let (private_context, authority) =
                        crate::resident_actor::WorkbenchCompilationAuthority::admit(
                            private_context,
                            replacement.installation.source().clone(),
                            Some(replacement.installation.clone()),
                            Some(&source_layers),
                        )
                        .expect(
                            "replacement cells retain their actual installation and source owner",
                        );
                    let private = workbench
                        .shared_view()
                        .with_compilation_authority(authority)
                        .with_private_execution(execution);

                    private.execute_cell_for_test(private_context.clone(),
                "import qualified QuotedAgentSpec as Replacement\nlet replacementSpec = Replacement.agentSpec @'[]").await.unwrap();
                    private
                        .publish_completed_cell_with_commit_for_test(
                            private_context,
                            if replacement.durable.is_some() {
                                tidepool_runtime::session::PublicManifestCommit::Durable
                            } else {
                                tidepool_runtime::session::PublicManifestCommit::Ephemeral
                            },
                        )
                        .await
                        .unwrap();
                    let old_scope = initial.scope.scope();
                    workbench
                        .access
                        .with_machine(context.clone(), move |session, _, _| {
                            let old_view = session.compile_view_in(old_scope).unwrap();
                            assert_eq!(
                                old_view
                                    .exact_declaration_context()
                                    .unwrap()
                                    .semantic_sha256(),
                                before_commit
                                    .exact_declaration_context()
                                    .unwrap()
                                    .semantic_sha256()
                            );
                            assert!(
                                session.public_visibility_snapshot_in(old_scope).unwrap()
                                    == before_visibility,
                                "replacement commit and import leave the previous notebook unchanged"
                            );
                            Ok(())
                        })
                        .await
                        .unwrap();
                    let replacement_view = workbench
                        .access
                        .with_machine(context.clone(), move |session, _, _| {
                            Ok(session.compile_view_in(next_scope).unwrap())
                        })
                        .await
                        .unwrap();
                    assert!(replacement_view.exact_declaration_context().unwrap().compiler_input_roles().iter().any(|role|
                matches!(role, tidepool_toolchain::artifact_inventory::CompilerInputRole::PublishedSourceOriginal { .. })));
                    assert_eq!(
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap(),
                completed_executions,
                "first replacement import must consume the issued original without quotation replay"
            );
                    if replacement.durable.is_some() {
                        let recovered_view = {
                            let mut lib = tidepool_runtime::session::SessionLib::open(
                                tidepool_repr::SessionId(8_143),
                                session_root.path(),
                                tidepool_runtime::session::ModuleEnv::standalone_default(),
                            )
                            .unwrap()
                            .with_validation_include(roots.clone());
                            tidepool_testing::with_settlement(|settlement| {
                                recovery.reopen().attach_root(&mut lib, settlement)
                            });
                            let mut recovered =
                                tidepool_runtime::session::PersistentSession::new(Some(lib), 0);
                            let scope = recovered
                                .recover_public_scope(&replacement.durable.as_ref().unwrap().owner)
                                .unwrap();
                            recovered.compile_view_in(scope).unwrap()
                        };
                        let current_view = workbench
                            .access
                            .with_machine(context.clone(), move |session, _, _| {
                                Ok(session.compile_view_in(next_scope).unwrap())
                            })
                            .await
                            .unwrap();
                        assert_eq!(
                    recovered_view
                        .exact_declaration_context()
                        .unwrap()
                        .semantic_sha256(),
                    current_view
                        .exact_declaration_context()
                        .unwrap()
                        .semantic_sha256(),
                    "replacement context and its artifacts remain resolvable after rebase and restart"
                );
                    }
                    let late_prepared = workbench
                        .prepare_actor_generation(
                            context.clone(),
                            descriptor.clone(),
                            ActorRequestSnapshot::Generation(replacement.clone()),
                            next_installation.clone(),
                            prompts.clone(),
                        )
                        .await
                        .unwrap();
                    state.0.lock().availability =
                        InstalledToolsAvailability::GenerationUnavailable(replacement.clone());
                    assert!(
                        state.current_generation().is_none(),
                        "uncertainty is not bootstrap admission"
                    );
                    assert!(matches!(
                        state.observe(),
                        InstalledToolsObservation::SourceUnavailable(_)
                    ));
                    assert_eq!(
                        state.install_bootstrap(
                            BootstrapExpectation::Available(&installation),
                            installation.clone()
                        ),
                        Err(BootstrapInstallationError::UnconfirmedGeneration)
                    );
                    assert!(
                        matches!(&state.0.lock().availability, InstalledToolsAvailability::GenerationUnavailable(retained)
                    if Arc::ptr_eq(retained, &replacement))
                    );
                    drop(state.drain_retired());
                    let revision = recovery
                        .store
                        .read_domain(domain)
                        .unwrap()
                        .unwrap()
                        .revision;
                    let decision = tidepool_runtime::session::PublicationDecision::new();
                    assert!(matches!(
                        workbench
                            .generation_publisher(
                                state.clone(),
                                ActorPublicationOwner::Preparation(preparation_client.clone())
                            )
                            .publish(
                                late_prepared,
                                decision.clone(),
                                ActorGenerationPublication::Terminal,
                            )
                            .await
                            .unwrap(),
                        ActorGenerationCommit::Refused(_)
                    ));
                    assert!(matches!(state.observe(), InstalledToolsObservation::Empty));
                    assert_eq!(
                        decision.phase(),
                        tidepool_runtime::session::PublicationPhase::Running,
                        "released installation custody refuses late publication before a native claim"
                    );
                    assert_eq!(
                        recovery
                            .store
                            .read_domain(domain)
                            .unwrap()
                            .unwrap()
                            .revision,
                        revision,
                        "late publication cannot change the retained public generation"
                    );
                };
                replacement_validation_history.await;
            };
            replacement_publication_history.await;
            return;
        }

        let candidate_isolation_history = async {
            #[derive(Clone, Copy)]
            enum CandidateOutcome {
                Refused,
                Cancelled,
                Published,
            }
            let candidate_compiler_calls = tidepool_extract_cmd::extract_spawn_count();
            for (index, outcome) in [
                CandidateOutcome::Refused,
                CandidateOutcome::Cancelled,
                CandidateOutcome::Published,
            ]
            .into_iter()
            .enumerate()
            {
                let (before, visibility, handles, custody) = workbench
                    .access
                    .with_machine(context.clone(), |session, context, _| {
                        Ok((
                            session
                                .compile_view_in(context.placement.lexical_scope)
                                .unwrap(),
                            session
                                .public_visibility_snapshot_in(context.placement.lexical_scope)
                                .unwrap(),
                            session.value_handle_count(),
                            session.outstanding_custody(),
                        ))
                    })
                    .await
                    .unwrap();
                let candidate = Arc::new(
                    workbench
                        .prepare_candidate_tools(
                            context.clone(),
                            3 + index as u64,
                            vec![],
                            SourceImports::new(),
                        )
                        .await
                        .unwrap(),
                );
                let candidate_scope = candidate._installation_scope.scope();
                assert!(
                    candidate._source_original.is_some(),
                    "the candidate retains its exact issued source selection privately"
                );
                assert!(Arc::ptr_eq(
                    candidate.code.prepared().unwrap(),
                    &warmed.prepared
                ));
                workbench
                    .access
                    .with_machine(context.clone(), {
                        let before = before.clone();
                        let visibility = visibility.clone();
                        move |session, context, _| {
                            assert_eq!(
                                session
                                    .compile_view_in(context.placement.lexical_scope)
                                    .unwrap(),
                                before
                            );
                            assert_eq!(
                                session
                                    .public_visibility_snapshot_in(context.placement.lexical_scope)
                                    .unwrap(),
                                visibility
                            );
                            Ok(())
                        }
                    })
                    .await
                    .unwrap();
                let source = crate::CheckpointSourceLayer::default();
                let old = InstalledToolLease::new(
                    context.actor,
                    source.clone(),
                    Some(Arc::clone(&first)),
                );
                let current = InstalledToolLease::new(
                    context.actor,
                    source.clone(),
                    Some(Arc::clone(&second)),
                );
                let state = InstalledToolsState::default();
                state
                    .install_bootstrap(BootstrapExpectation::Empty, current.clone())
                    .unwrap();
                let decision = tidepool_runtime::session::PublicationDecision::new();
                if matches!(outcome, CandidateOutcome::Cancelled) {
                    decision.request_cancellation();
                }
                match outcome {
                    CandidateOutcome::Refused => assert!(matches!(
                        state.replace_explicit(&old, Arc::clone(&candidate)),
                        Err(SpecReplacementError::Unavailable)
                    )),
                    CandidateOutcome::Cancelled => assert!(decision.claim_commit().is_none()),
                    CandidateOutcome::Published => state
                        .replace_explicit(&current, Arc::clone(&candidate))
                        .unwrap(),
                }
                let expected = if matches!(outcome, CandidateOutcome::Published) {
                    &candidate
                } else {
                    &second
                };
                assert!(Arc::ptr_eq(&state.current_tools().unwrap(), expected));
                workbench
                    .access
                    .with_machine(context.clone(), move |session, context, _| {
                        assert_eq!(
                            session
                                .compile_view_in(context.placement.lexical_scope)
                                .unwrap(),
                            before
                        );
                        assert_eq!(
                            session
                                .public_visibility_snapshot_in(context.placement.lexical_scope)
                                .unwrap(),
                            visibility
                        );
                        Ok(())
                    })
                    .await
                    .unwrap();
                drop(state.drain_retired());
                drop(candidate);
                wait_for_explicit_installation_cleanup(
                    &workbench,
                    context.clone(),
                    handles,
                    custody,
                    Vec::new(),
                    "source candidate settlement",
                )
                .await;
                workbench
                    .access
                    .with_machine(context.clone(), move |session, _, _| {
                        assert!(session
                            .public_visibility_snapshot_in(candidate_scope)
                            .is_none());
                        Ok(())
                    })
                    .await
                    .unwrap();
            }
            assert_eq!(
                tidepool_extract_cmd::extract_spawn_count(),
                candidate_compiler_calls,
                "candidate preparation reuses the immutable original without compiler requests"
            );
        };
        candidate_isolation_history.await;

        crate::agent_spec::preparation::tests::ready_bound_preserves_installed_lease(Arc::clone(
            &first.code.prepared().expect("source-prepared installation"),
        ))
        .await;
        let ordinary_successor_history = async {
            let original_identity = proof.original_input_identity().to_owned();
            let original_source = proof.original_source().to_owned();
            let original_owner = tidepool_toolchain::extract_module_name(&original_source)
                .expect("completed original source has its actual compiler owner");

            std::fs::write(&quotation_input, "42").unwrap();
            let public_owner = workbench
                .access
                .with_machine(context.clone(), {
                    let owner = owner.clone();
                    move |session, context, _| {
                        let descriptor =
                            crate::ActorDescriptor::new("quoted original", context.placement)
                                .with_actor_path(
                                    tidepool_repr::ActorPath::parse("root/quoted-original")
                                        .unwrap(),
                                )
                                .with_persistence_policy(crate::ActorPersistencePolicy::Durable);
                        let readiness = session
                            .durable_public_readiness(&owner, context.placement.lexical_scope)
                            .map_err(|error| {
                                ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                            })?;
                        Ok(crate::resident_actor::WorkbenchPublicOwner::issue(
                            context,
                            &descriptor,
                            Some(readiness),
                        )
                        .unwrap())
                    }
                })
                .await
                .unwrap();
            for cell in [
            "import qualified QuotedAgentSpec as Frozen\nlet frozenSpec = Frozen.agentSpec @'[]",
            "preparedOriginalHistory :: Int\npreparedOriginalHistory = 41",
            "import qualified QuotedAgentSpec as Frozen\nlet repeatedSpec = Frozen.agentSpec @'[]",
        ] {
            let execution = Arc::new(
                workbench_runner_for_test(&workbench)
                    .begin_private_execution(
                        context.clone(),
                        Arc::clone(&public_owner),
                        tidepool_runtime::session::PublicationDecision::new(),
                        None,
                    )
                    .await
                    .unwrap(),
            );
            let mut private_context = context.clone();
            private_context.placement.lexical_scope = execution.private_scope;
            let (private_context, authority) = crate::resident_actor::WorkbenchCompilationAuthority::admit(
                private_context,
                generation_source.clone(),
                None,
                Some(&source_layers),
            )
            .expect("successor cells require the same retained quoted source owner");
            let private = workbench
                .shared_view()
                .with_compilation_authority(authority)
                .with_private_execution(execution);

            private
                .execute_cell_for_test(private_context.clone(), cell)
                .await
                .unwrap();
            private
                .publish_completed_cell_with_commit_for_test(
                    private_context,
                    tidepool_runtime::session::PublicManifestCommit::Durable,
                )
                .await
                .unwrap();
            let current = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    Ok(session
                        .compile_view_in(context.placement.lexical_scope)
                        .unwrap())
                })
                .await
                .unwrap();
            let roles = current
                .exact_declaration_context()
                .unwrap()
                .compiler_input_roles();
            assert!(roles.iter().any(|role| matches!(role,
                tidepool_toolchain::artifact_inventory::CompilerInputRole::PublishedSourceOriginal { .. })));
            assert_eq!(
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap(),
                completed_executions,
                "published imports and later declarations retain quotation41"
            );
        }
            let (before_reinstall, before_visibility, bootstrap) = workbench
                .access
                .with_machine(context.clone(), {
                    let owner = owner.clone();
                    move |session, context, _| {
                        let scope = context.placement.lexical_scope;
                        let view = session.compile_view_in(scope).unwrap();
                        let visibility = session.public_visibility_snapshot_in(scope).unwrap();
                        assert!(
                            !visibility.bindings.is_empty(),
                            "published quoted-source cells establish binding winners"
                        );
                        let bootstrap = session
                            .begin_durable_public_bootstrap(owner, scope)
                            .map_err(|error| {
                                ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                            })?;
                        Ok((view, visibility, bootstrap))
                    }
                })
                .await
                .unwrap();
            let before_reinstall_recovered = recover_context();
            let reinstalled = workbench
                .install_tools_action(
                    context.clone(),
                    10,
                    Vec::new(),
                    Vec::new(),
                    InstalledToolCode::SourcePrepared(Arc::clone(&warmed.prepared)),
                    ToolInstallationPurpose::RecoveredTools,
                )
                .await
                .unwrap();
            workbench
                .access
                .with_machine(context.clone(), move |session, context, _| {
                    let scope = context.placement.lexical_scope;
                    assert_eq!(session.compile_view_in(scope).unwrap(), before_reinstall);
                    assert_eq!(
                        session.public_visibility_snapshot_in(scope).unwrap(),
                        before_visibility
                    );
                    session
                        .publish_durable_public_bootstrap(bootstrap)
                        .map_err(|error| {
                            ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                        })?;
                    assert_eq!(session.compile_view_in(scope).unwrap(), before_reinstall);
                    assert_eq!(
                        session.public_visibility_snapshot_in(scope).unwrap(),
                        before_visibility
                    );
                    Ok(())
                })
                .await
                .unwrap();
            let after_reinstall_recovered = recover_context();
            assert_eq!(
            after_reinstall_recovered, before_reinstall_recovered,
            "native recovery installation preserves the exact durable compiler and binding surface"
        );
            assert_eq!(
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap(),
                completed_executions
            );
            drop(reinstalled);
            let before_failed_cell = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    Ok(session
                        .compile_view_in(context.placement.lexical_scope)
                        .unwrap())
                })
                .await
                .unwrap();
            let execution = Arc::new(
                workbench_runner_for_test(&workbench)
                    .begin_private_execution(
                        context.clone(),
                        Arc::clone(&public_owner),
                        tidepool_runtime::session::PublicationDecision::new(),
                        None,
                    )
                    .await
                    .unwrap(),
            );
            let mut failed_context = context.clone();
            failed_context.placement.lexical_scope = execution.private_scope;
            let (failed_context, authority) =
                crate::resident_actor::WorkbenchCompilationAuthority::admit(
                    failed_context,
                    generation_source.clone(),
                    None,
                    Some(&source_layers),
                )
                .expect(
                    "failed source preparation still requires its actual retained source owner",
                );
            let failed = workbench
                .shared_view()
                .with_compilation_authority(authority)
                .with_private_execution(execution);

            assert!(failed
                .prepare_cell(
                    failed_context,
                    "preparedOriginalFailure :: Int\npreparedOriginalFailure = True".into(),
                )
                .await
                .is_err());
            drop(failed);
            let after_failed_cell = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    Ok(session
                        .compile_view_in(context.placement.lexical_scope)
                        .unwrap())
                })
                .await
                .unwrap();
            assert_eq!(after_failed_cell, before_failed_cell);
            let later_recovered = recover_context();
            assert!(later_recovered.library().is_some());
            assert_eq!(
                later_recovered
                    .exact_declaration_context()
                    .unwrap()
                    .semantic_sha256(),
                after_failed_cell
                    .exact_declaration_context()
                    .unwrap()
                    .semantic_sha256(),
                "later declaration recovery preserves the original selection"
            );
            assert_eq!(
                generation_zero_recovered
                    .as_ref()
                    .expect("source history performed actual recovery")
                    .library(),
                None
            );
            assert_eq!(
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap(),
                completed_executions,
            );
            // An independent ordinary source request still executes the untracked quoter.

            let installation =
                crate::agent_spec::installation_expression("QuotedAgentSpec.agentSpec", &[]);
            let dispatcher_effects = format!(
                "(Tidepool.Effects.Core.AgentTools ': Tidepool.Agent.Contract.SyncEffects {})",
                installation.effect_row,
            );
            let mut imports = source.config.workbench_imports.clone();
            imports.extend_text("qualified QuotedAgentSpec");
            imports.extend_text("qualified Tidepool.Agent.Contract");
            imports.extend_text("qualified Tidepool.Effects.Core");
            imports.extend_text("qualified Tidepool.Agent.Reply.Internal");
            imports.extend_text("qualified Tidepool.Agent.Watch.Internal");
            let templates = resident_workbench_templates(
                &source.config.preamble,
                &dispatcher_effects,
                &imports.template_text(),
            );
            let scratch = tempfile::tempdir().unwrap();
            let include = roots.iter().map(PathBuf::as_path).collect::<Vec<_>>();
            let ordinary = tidepool_testing::with_settlement(|settlement| {
                tidepool_runtime::session::run_turn(
                    tidepool_runtime::session::TurnRequest {
                        exact_context: None,
                        session_id: None,
                        turn_text: &installation.expression,
                        templates: &templates,
                        include: &include,
                        session_root: scratch.path(),
                        inject_modules: &[],
                        gen: 1,
                        verdict: Some(tidepool_runtime::session::TurnClassification {
                            kind: tidepool_runtime::session::TurnKind::Bind,
                            binders: Vec::new(),
                            items: Vec::new(),
                        }),
                        target: None,
                        retained_imports: &[],
                    },
                    settlement,
                )
            })
            .unwrap();
            let tidepool_runtime::session::TurnResult::Bind {
                compiled,
                wrapped_source,
                ..
            } = ordinary
            else {
                panic!("ordinary quotation request must complete its actual discarded bind")
            };
            let compiled = Arc::new(compiled);
            let successor = compiled.ordinary_original_compile_input().unwrap();
            assert_eq!(successor.original_source(), wrapped_source);
            // The independent scratch scope belongs to a different generated
            // scaffold. Exact input continuity includes that owner and its source;
            // it is separate from the shared logical installer recipe.
            let successor_owner =
                tidepool_toolchain::extract_module_name(successor.original_source())
                    .expect("fresh quotation source has its actual compiler owner");
            assert_ne!(original_owner, successor_owner);
            assert_ne!(original_source, successor.original_source());
            assert_ne!(original_identity, successor.original_input_identity());
            let retained = second
                .code
                .prepared()
                .expect("source-prepared installation")
                .entry
                .ordinary_original_compile_input();
            assert!(Arc::ptr_eq(proof, retained));
            assert_eq!(retained.original_source(), original_source);
            assert_eq!(
                retained.original_input_identity(),
                original_identity,
                "a fresh quotation cannot replace the selected completed original proof"
            );
            assert!(successor.replay_eligible_identity().is_none());
            let ordinary_executions =
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap();
            assert!(ordinary_executions.lines().any(|input| input == "42"));
            let before_native = tidepool_extract_cmd::extract_spawn_count();
            let ready = tidepool_runtime::session::PreparedSourceEntry::prepare(
                Arc::clone(&compiled),
                Arc::new(tidepool_runtime::session::ImageRegistry::new()),
            )
            .unwrap();
            let (ordinary_session, ordinary_context, _, _ordinary_root) = host_mount_fixture();
            run_native_quoted_probe(
                ordinary_session,
                ordinary_context,
                source.clone(),
                &ready,
                "42",
            )
            .await;
            let (original_session, original_context, _, _original_root) = host_mount_fixture();
            run_native_quoted_probe(
                original_session,
                original_context,
                source.clone(),
                &first
                    .code
                    .prepared()
                    .expect("source-prepared installation")
                    .entry,
                "41",
            )
            .await;
            assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before_native);
            assert_eq!(
                std::fs::read_to_string(quotation_input.with_extension("executions")).unwrap(),
                ordinary_executions
            );
            workbench.access.with_machine(context, move |session, _, _| {
            let entry = session.prepare_startup_entry(compiled.code())?;
            assert!(entry.compile_input_identity().is_none(), "changed untracked quotation output cannot authorize durable successor continuity");
            Ok(())
        }).await.unwrap();
            assert!(
                std::fs::read_to_string(quotation_input.with_extension("executions"))
                    .unwrap()
                    .lines()
                    .count()
                    > completed_executions.lines().count()
            );
        };
        ordinary_successor_history.await;
    }

    async fn wait_for_explicit_installation_cleanup<H, O>(
        workbench: &ResidentActorWorkbench<H, O>,
        context: crate::ActorSessionContext,
        expected_handles: usize,
        expected_custody: usize,
        producer_bindings: Vec<(String, tidepool_repr::SessionVarId)>,
        stage: &'static str,
    ) where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        let mut last_counts = None;
        let cleanup = tokio::time::timeout(std::time::Duration::from_secs(5), async {
            loop {
                let producer_bindings = producer_bindings.clone();
                let counts = workbench
                    .access
                    .with_machine(context.clone(), move |session, context, _| {
                        for (name, identity) in producer_bindings {
                            let retained = session.retain_binding_custody_in(
                                context.placement.lexical_scope,
                                &name,
                                identity,
                            )?;
                            assert!(
                                retained.is_some(),
                                "producer binding retains its exact live handle"
                            );
                            drop(retained);
                        }
                        Ok((
                            session.parked_count(),
                            session.stowed_roots_count(),
                            session.persistent_roots_count(),
                            session.value_handle_count(),
                            session.outstanding_custody(),
                        ))
                    })
                    .await
                    .expect("inspect explicit installer cleanup");
                last_counts = Some(counts);
                // Native program root blocks can retire between preparations.
                // Affine payload handles and custody must return exactly to the
                // surviving producer baseline, with no parked continuation.
                if (counts.0, counts.1, counts.3, counts.4)
                    == (0, 0, expected_handles, expected_custody)
                {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await;
        assert!(
            cleanup.is_ok(),
            "explicit installer cleanup after {stage}: expected parked/stowed/handles/custody (0, 0, {expected_handles}, {expected_custody}); last parked/stowed/persistent/handles/custody={last_counts:?}"
        );
    }

    #[tokio::test]
    async fn explicit_installer_keeps_capture_and_replacement_leases_without_recompiling() {
        with_test_compiler_owner(|preparation_client| async move {
            let (session, context, mut source, _root) = host_mount_fixture();
            let authored = tempfile::tempdir().unwrap();
            std::fs::write(
                authored.path().join("CapturedSpecInstaller.hs"),
                include_str!("fixtures/captured-spec-installer.hs"),
            )
            .unwrap();
            let mut include_roots = source.base_include.to_vec();
            include_roots.push(authored.path().to_path_buf());
            source.base_include = include_roots.into();
            source.preamble =
                insert_preamble_imports(&source.preamble, "qualified CapturedSpecInstaller").into();
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let (workbench, private_context) = ResidentActorWorkbench::new(machines, (source).bind_preparation(preparation_client.clone()), None)
                .admit_private_cell_for_test(context.clone())
                .await
                .unwrap();
            workbench
                .execute_cell_for_test(
                    private_context.clone(),
                    include_str!("fixtures/captured-replacement-installers-bind.hs"),
                )
                .await
                .unwrap();
            workbench
                .publish_completed_cell_for_test(private_context)
                .await
                .unwrap();
            let (installer, replacement) = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    let retain = |session: &mut ResidentSession<_, _>, name: &str| {
                        let identity = session
                            .current_binding_in(context.placement.lexical_scope, name)
                            .unwrap()
                            .0;
                        Arc::new(
                            session
                                .retain_binding_custody_in(
                                    context.placement.lexical_scope,
                                    name,
                                    identity,
                                )
                                .unwrap()
                                .unwrap(),
                        )
                    };
                    Ok((retain(session, "installer"), retain(session, "replacement")))
                })
                .await
                .unwrap();
            let before = tidepool_extract_cmd::extract_spawn_count();
        let first = Arc::new(workbench.prepare_explicit_tools(context.clone(), 1, vec![], installer.clone()).await.unwrap());
            assert!(installer.published_source_original_selections().is_empty(),
                "ordinary captured binding retains private provenance without public source selection");
            let public_before = workbench.access.with_machine(context.clone(), |session, context, _| {
                Ok(session.public_visibility_snapshot_in(context.placement.lexical_scope))
            }).await.unwrap();
            let second = Arc::new(workbench.prepare_explicit_candidate_tools(context.clone(), 2, vec![], replacement).await.unwrap());
            let public_after = workbench.access.with_machine(context.clone(), |session, context, _| {
                Ok(session.public_visibility_snapshot_in(context.placement.lexical_scope))
            }).await.unwrap();
            assert_eq!(public_after, public_before, "a replacement candidate must preserve the public namespace");
            assert_eq!(tidepool_extract_cmd::extract_spawn_count(), before);
            assert!(first.resolved_spec().is_none());
            assert_eq!(first.revision(), None);
            assert_eq!(
                first.provenance(),
                "install=1 revision=(run) origin=explicit live spec"
            );
            let expected = InstalledToolLease::new(
                context.actor,
                crate::CheckpointSourceLayer::default(),
                Some(first),
            );
            assert!(
                expected.toolset_acquisition().is_none(),
                "live values do not claim source-cache acquisition"
            );
            let state = InstalledToolsState::default();
            state.install_bootstrap(BootstrapExpectation::Empty, expected.clone()).unwrap();
            let pinned = expected.select("probe").unwrap();
            let pinned_last = expected.select("last_probe").unwrap();
            assert_eq!(pinned.entry_index(), 3);
            assert_eq!(pinned_last.entry_index(), 4);
            let startup = workbench.begin_initial_context(
                context.clone(), expected.tools().unwrap().dispatch.clone(),
                serde_json::json!({"operation": "integration", "callerSeed": null}),
            ).await.unwrap();
            let startup = match startup {
                ResidentWorkbenchStep::Running { fragment, outcome } => workbench
                    .settle_item(context.clone(), *fragment, (*outcome).into())
                    .await.unwrap(),
                other => other,
            };
            let ResidentWorkbenchStep::Committed { value: Some(seed), .. } = startup else {
                panic!("initializer did not return its semantic context seed")
            };
            assert_eq!(seed["sections"][0]["label"], "captured initializer");
            assert_eq!(seed["sections"][0]["body"], "retained notebook value");
            assert!(expected.select(crate::status_tool::STATUS_TOOL).is_none());
            assert!(pinned
                .clone()
                .admit(exomonad_tool::ToolArguments::Structured(serde_json::json!(
                    {}
                )))
                .is_err());
            state.replace_explicit(&expected, second.clone()).unwrap();
            assert_eq!(state.current().unwrap().tools().unwrap().install, 2);
            assert_eq!(expected.tools().unwrap().install, 1);
            assert_eq!(
                state.replace_explicit(&expected, second),
                Err(SpecReplacementError::Unavailable)
            );
            let active = state.current().unwrap();
            let mut changed = workbench
                .prepare_explicit_candidate_tools(context.clone(), 3, vec![], installer)
                .await
                .unwrap();
            changed.endpoints.clear();
            assert_eq!(
                state.replace_explicit(&active, Arc::new(changed)),
                Err(SpecReplacementError::SurfaceChanged)
            );
            assert_eq!(state.current().unwrap().tools().unwrap().install, 2);
            let public_after_refusal = workbench.access.with_machine(context.clone(), |session, context, _| {
                Ok(session.public_visibility_snapshot_in(context.placement.lexical_scope))
            }).await.unwrap();
            assert_eq!(public_after_refusal, public_before, "refused candidate preparation preserves public admission");
            let later = state.current().unwrap().select("probe").unwrap();
            let later_last = state.current().unwrap().select("last_probe").unwrap();
            assert_eq!(pinned.lease().tools().unwrap().install, 1);
            assert_eq!(later.lease().tools().unwrap().install, 2);
            drop(state.drain_retired());
            assert!(matches!(state.snapshot_for_call(), Err(crate::ResidentToolError::Unavailable(_))));
            for (selected, expected_output) in [
                (pinned, "retained notebook value"),
                (pinned_last, "retained notebook value"),
                (later, "replacement notebook value"),
                (later_last, "replacement notebook value"),
            ] {
                let call = selected
                    .admit(exomonad_tool::ToolArguments::Raw("input".into()))
                    .unwrap();
                let execution = tidepool_runtime::session::WorkbenchExecutionId::from_digest([17; 16]);
                let boundary = crate::ContextCheckpointBoundary::Execution {
                    actor_id: context.actor.id.0,
                    incarnation: context.actor.incarnation.0,
                    execution_id: execution.clone(),
                };
                let mut unbound = WorkbenchRequest::for_tool("probe".into(), serde_json::json!("input"))
                    .with_execution_id(execution.clone())
                    .with_checkpoint_boundary(boundary.clone());
                unbound.input = Some(serde_json::json!({"mount": "retained input"}));
                unbound.verbose = Some(true);
                let invocation = crate::ActorWorkbenchInvocation::installed(
                    call,
                    crate::kernel::WorkbenchInvocationMetadata::capture(&unbound),
                    None,
                    None,
                );
                assert_eq!(invocation.request().input, unbound.input);
                assert_eq!(invocation.request().verbose, Some(true));
                assert_eq!(invocation.request().tool_call().unwrap().name, "probe");
                assert_eq!(invocation.request().execution_id(), Some(&execution));
                assert_eq!(invocation.request().checkpoint_boundary(), Some(&boundary));
                let (request, operation, _, _) = invocation.into_parts();
                let crate::kernel::WorkbenchToolOperation::Installed(call) = operation else {
                    panic!("issued endpoint lost its installed operation")
                };
                assert_eq!(request.tool_call().unwrap().arguments, serde_json::json!("input"));
                assert_eq!(call.selected().lease().actor(), context.actor);
                let step = workbench
                    .begin_selected_tool(context.clone(), call)
                    .await
                    .unwrap();
                let step = match step {
                    ResidentWorkbenchStep::Running { fragment, outcome } => workbench
                        .settle_item(context.clone(), *fragment, (*outcome).into())
                        .await
                        .unwrap(),
                    other => other,
                };
                let ResidentWorkbenchStep::Committed { output, .. } = step else {
                    panic!("captured tool did not complete")
                };
                assert!(
                    output.contains(expected_output),
                    "expected {expected_output:?}: {output}"
                );
            }
            drop(state.drain_retired());
            assert!(matches!(
                state.snapshot_for_call(),
                Err(crate::ResidentToolError::Unavailable(_))
            ));
        })
        .await
    }

    #[tokio::test]
    async fn explicit_spawn_installer_requires_exactly_one_request_receiver() {
        with_test_compiler_owner(
            explicit_spawn_installer_requires_exactly_one_request_receiver_with_preparation_client,
        )
        .await
    }

    async fn explicit_spawn_installer_requires_exactly_one_request_receiver_with_preparation_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        with_test_compiler_owner(|_| async {
            let (session, public_context, mut source, _root) = host_mount_fixture();
            let authored = tempfile::tempdir().unwrap();
            std::fs::write(
                authored.path().join("CapturedSpecInstaller.hs"),
                include_str!("fixtures/captured-spec-installer.hs"),
            )
            .unwrap();
            let mut include_roots = source.base_include.to_vec();
            include_roots.push(authored.path().to_path_buf());
            source.base_include = include_roots.into();
            source.preamble =
                insert_preamble_imports(&source.preamble, "qualified CapturedSpecInstaller").into();
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(public_context.placement.session, Box::new(session));
            let (workbench, private_context) = ResidentActorWorkbench::new(
                machines,
                (source).bind_preparation(preparation_client.clone()),
                None,
            )
            .admit_private_cell_for_test(public_context.clone())
            .await
            .unwrap();
            workbench
                .execute_cell_for_test(
                    private_context.clone(),
                    include_str!("fixtures/captured-spec-installer-bind.hs"),
                )
                .await
                .unwrap();
            workbench
                .publish_completed_cell_for_test(private_context)
                .await
                .unwrap();
            let context = public_context;
            let (
                installer,
                application_installer,
                duplicate_installer,
                baseline_handles,
                baseline_custody,
                producer_bindings,
            ) = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    let scope = context.placement.lexical_scope;
                    let bindings = [
                        "installer",
                        "applicationInstaller",
                        "duplicateReceiverInstaller",
                    ]
                    .into_iter()
                    .map(|name| {
                        let identity = session
                            .current_binding_in(scope, name)
                            .expect("published compiler-issued installer binding")
                            .0;
                        (name.to_owned(), identity)
                    })
                    .collect::<Vec<_>>();
                    let mut retained = Vec::new();
                    for (name, identity) in &bindings {
                        retained.push(Arc::new(
                            session
                                .retain_binding_custody_in(scope, name, *identity)?
                                .expect("published installer retains its original custody"),
                        ));
                    }
                    let duplicate = retained.pop().unwrap();
                    let application = retained.pop().unwrap();
                    let installer = retained.pop().unwrap();
                    Ok((
                        installer,
                        application,
                        duplicate,
                        session.value_handle_count(),
                        session.outstanding_custody(),
                        bindings,
                    ))
                })
                .await
                .unwrap();
            let before_preparations = tidepool_extract_cmd::extract_spawn_count();

            // The same captured application value is accepted only by public
            // spawn preparation and yields both the tool lease and receiver.
            let (tools, receiver) = workbench
                .prepare_explicit_application(
                    context.clone(),
                    1,
                    vec![],
                    application_installer.clone(),
                )
                .await
                .expect("one registered receiver completes application preparation");
            assert!(tools.resolved_spec().is_none());
            let receiver_scope = receiver.scope.scope();
            let receiver_scope_lease = Arc::downgrade(&receiver.scope);
            drop(receiver);
            drop(tools);
            wait_for_explicit_installation_cleanup(
                &workbench,
                context.clone(),
                baseline_handles,
                baseline_custody,
                producer_bindings.clone(),
                "accepted application",
            )
            .await;
            assert!(
                receiver_scope_lease.upgrade().is_none(),
                "receiver source lease releases with its installation"
            );
            workbench
                .access
                .with_machine(context.clone(), move |session, _, _| {
                    assert!(
                        session.compile_view_in(receiver_scope).is_none(),
                        "released receiver source scope retires"
                    );
                    Ok(())
                })
                .await
                .unwrap();

            let missing = workbench
                .prepare_explicit_application(context.clone(), 2, vec![], installer.clone())
                .await;
            let Some(missing) = missing.err() else {
                panic!("a tools-only installer must be refused for public spawn")
            };
            assert!(
                matches!(missing, ResidentActorWorkbenchError::ActorProtocol(_)),
                "a tools-only installer must be refused for public spawn: {missing:?}"
            );
            wait_for_explicit_installation_cleanup(
                &workbench,
                context.clone(),
                baseline_handles,
                baseline_custody,
                producer_bindings.clone(),
                "missing receiver refusal",
            )
            .await;

            let duplicate = workbench
                .prepare_explicit_application(
                    context.clone(),
                    3,
                    vec![],
                    duplicate_installer.clone(),
                )
                .await;
            let Some(duplicate) = duplicate.err() else {
                panic!("a second receiver registration must be refused")
            };
            assert!(
                matches!(duplicate, ResidentActorWorkbenchError::ActorProtocol(_)),
                "a second receiver registration must be refused: {duplicate:?}"
            );
            wait_for_explicit_installation_cleanup(
                &workbench,
                context.clone(),
                baseline_handles,
                baseline_custody,
                producer_bindings.clone(),
                "duplicate receiver refusal",
            )
            .await;

            let replacement = workbench
                .prepare_explicit_tools(context.clone(), 4, vec![], application_installer.clone())
                .await;
            let Some(replacement) = replacement.err() else {
                panic!("tools-only preparation must refuse a receiver-bearing installer")
            };
            assert!(
                matches!(replacement, ResidentActorWorkbenchError::ActorProtocol(_)),
                "tools-only preparation must refuse a receiver-bearing installer: {replacement:?}"
            );
            wait_for_explicit_installation_cleanup(
                &workbench,
                context.clone(),
                baseline_handles,
                baseline_custody,
                producer_bindings.clone(),
                "tools-only receiver refusal",
            )
            .await;
            let tools = workbench
                .prepare_explicit_tools(context.clone(), 5, vec![], installer.clone())
                .await
                .expect("original retained installer remains callable after refusals");
            let lease = InstalledToolLease::new(
                context.actor,
                crate::CheckpointSourceLayer::default(),
                Some(Arc::new(tools)),
            );
            let call = lease
                .select("probe")
                .unwrap()
                .admit(exomonad_tool::ToolArguments::Raw("input".into()))
                .unwrap();
            let step = workbench
                .begin_selected_tool(context.clone(), Arc::new(call))
                .await
                .unwrap();
            let step = match step {
                ResidentWorkbenchStep::Running { fragment, outcome } => workbench
                    .settle_item(context.clone(), *fragment, (*outcome).into())
                    .await
                    .unwrap(),
                other => other,
            };
            let ResidentWorkbenchStep::Committed { output, .. } = step else {
                panic!("original captured tool remains callable after refusals")
            };
            assert!(output.contains("captured value"), "{output}");
            drop(lease);
            wait_for_explicit_installation_cleanup(
                &workbench,
                context,
                baseline_handles,
                baseline_custody,
                producer_bindings,
                "original producer liveness probe",
            )
            .await;
            assert_eq!(
                tidepool_extract_cmd::extract_spawn_count(),
                before_preparations,
                "explicit preparation applies retained closures without another extractor turn"
            );
        })
        .await;
    }

    #[tokio::test]
    async fn explicit_replacement_fence_refuses_changed_dispatch_and_retired_actor() {
        with_test_compiler_owner(|preparation_client| async move {
            let (session, context, source, _root) = host_mount_fixture();
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let workbench = ResidentActorWorkbench::new(
                machines,
                (source).bind_preparation(preparation_client.clone()),
                None,
            )
            .with_compilation_authority(
                crate::resident_actor::WorkbenchCompilationAuthority::for_test(context.clone()),
            );
            let first = Arc::new(
                workbench
                    .prepare_tools(context.clone(), 1, vec![])
                    .await
                    .unwrap(),
            );
            let second = Arc::new(
                workbench
                    .prepare_tools(context.clone(), 2, vec![])
                    .await
                    .unwrap(),
            );
            assert!(!Arc::ptr_eq(&first.dispatch, &second.dispatch));
            let expected = InstalledToolLease::new(
                context.actor,
                crate::CheckpointSourceLayer::default(),
                Some(first),
            );
            let state = InstalledToolsState::default();
            state
                .install_bootstrap(
                    BootstrapExpectation::Empty,
                    InstalledToolLease::new(
                        context.actor,
                        crate::CheckpointSourceLayer::default(),
                        Some(second.clone()),
                    ),
                )
                .unwrap();
            assert!(matches!(
                state.replace_explicit(&expected, second.clone()),
                Err(SpecReplacementError::Unavailable)
            ));
            assert_eq!(state.current().unwrap().tools().unwrap().install, 2);
            assert_eq!(
                expected.tools().unwrap().install,
                1,
                "accepted original installation survives replacement"
            );
            drop(state.drain_retired());
            assert!(matches!(
                state.replace_explicit(&expected, second),
                Err(SpecReplacementError::Unavailable)
            ));
            assert!(
                state.snapshot().is_none(),
                "replacement cannot resurrect a retired installation"
            );
        })
        .await
    }

