    async fn cancelling_child_preparation_cannot_register_a_late_machine_with_preparation_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        with_test_compiler_owner(|_| {
            cancelling_child_preparation_cannot_register_a_late_machine_with_compiler_owner(
                preparation_client.clone(),
            )
        })
        .await;
    }

    async fn cancelling_child_preparation_cannot_register_a_late_machine_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let id = tidepool_repr::SessionId(810);
        let root = tempfile::tempdir().unwrap();
        let root_path = root.path().to_path_buf();
        let machines = Arc::new(ActorMachineRegistry::<frunk::HNil, ChildOutput>::new());
        let dropped = Arc::new(tokio::sync::Notify::new());
        let worker_dropped = Arc::clone(&dropped);
        let (started, observe) = tokio::sync::oneshot::channel();
        let started = std::sync::Mutex::new(Some(started));
        let (release, wait) = std::sync::mpsc::channel();
        let wait = std::sync::Mutex::new(wait);
        let runner = ResidentActorRunner::new(
            Arc::clone(&machines),
            (ActorWorkbenchSource::new("", Vec::new()))
                .bind_preparation(preparation_client.clone()),
        )
        .with_child_bootstrap_program(child_bootstrap_fixture())
        .with_child_session_factory(Arc::new(move |id, _, _settlement| {
            let output = ChildOutput(Arc::new(ChildOutputLifetime(Arc::clone(&worker_dropped))));
            let weak = Arc::downgrade(&output.0);
            let machine = child_preparation_fixture(id, root_path.clone(), output);
            started.lock().unwrap().take().unwrap().send(weak).unwrap();
            wait.lock()
                .unwrap()
                .recv_timeout(Duration::from_secs(5))
                .unwrap();
            Ok(machine)
        }));
        let task_runner = runner.clone();
        let task_owner = crate::capabilities::CompilerOwnerScope::current().unwrap();
        let task = tokio::spawn(async move {
            task_owner
                .scope(
                    task_runner.provision_child_session(
                        id,
                        RealmId::ROOT,
                        None,
                        &[],
                        crate::ActorDescriptor::new(
                            "independent child fixture",
                            crate::ActorPlacement {
                                session: id,
                                resource_scope: RealmId::ROOT,
                                lexical_scope: tidepool_codegen::scope::ScopeId::ROOT,
                            },
                        )
                        .admit_independent_world()
                        .source_dependency(),
                    ),
                )
                .await
        });
        let lifetime = observe.await.unwrap();
        // This current-thread runtime reached another task while preparation is
        // synchronously blocked, proving the factory is off the async thread.
        assert!(machines.kind(id).is_none());
        task.abort();
        assert!(matches!(task.await, Err(error) if error.is_cancelled()));
        release.send(()).unwrap();
        tokio::time::timeout(Duration::from_secs(5), dropped.notified())
            .await
            .unwrap();
        assert!(lifetime.upgrade().is_none());
        assert!(machines.kind(id).is_none());
        assert!(!runner.access.child_sessions.lock().unwrap().contains(&id));
    }

