    async fn prepared_child_registration_remains_owned_by_retirement_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let id = tidepool_repr::SessionId(811);
        let root = tempfile::tempdir().unwrap();
        let root_path = root.path().to_path_buf();
        let machines = Arc::new(ActorMachineRegistry::<frunk::HNil, ChildOutput>::new());
        let dropped = Arc::new(tokio::sync::Notify::new());
        let factory_dropped = Arc::clone(&dropped);
        let runner = ResidentActorRunner::new(
            Arc::clone(&machines),
            (ActorWorkbenchSource::new("", Vec::new()))
                .bind_preparation(preparation_client.clone()),
        )
        .with_child_bootstrap_program(child_bootstrap_fixture())
        .with_child_session_factory(Arc::new(move |id, _, _settlement| {
            Ok(child_preparation_fixture(
                id,
                root_path.clone(),
                ChildOutput(Arc::new(ChildOutputLifetime(Arc::clone(&factory_dropped)))),
            ))
        }));
        let provisioned = runner
            .provision_child_session(
                id,
                RealmId::ROOT,
                None,
                &[],
                crate::ActorDescriptor::new(
                    "independent child fixture",
                    crate::ActorPlacement {
                        session: id,
                        resource_scope: RealmId::ROOT,
                        lexical_scope: tidepool_codegen::scope::ScopeId::ROOT,
                    },
                )
                .admit_independent_world()
                .source_dependency(),
            )
            .await
            .unwrap();
        assert_ne!(
            provisioned.lexical_scope,
            tidepool_codegen::scope::ScopeId::ROOT
        );
        provisioned.startup_lease.admitted();
        assert_eq!(
            machines.kind(id),
            Some(tidepool_runtime::session::registry::SlotKind::Idle)
        );
        assert!(runner.access.child_sessions.lock().unwrap().contains(&id));
        runner.retire_child_session(id, false).await.unwrap();
        tokio::time::timeout(Duration::from_secs(5), dropped.notified())
            .await
            .unwrap();
        assert!(machines.kind(id).is_none());
        assert!(!runner.access.child_sessions.lock().unwrap().contains(&id));
    }

    #[tokio::test]
    async fn child_publication_issues_drop_custody_without_claiming_collision_peers() {
        with_test_compiler_owner(|preparation_client| async move {
            let id = tidepool_repr::SessionId(812);
            let root = tempfile::tempdir().unwrap();
            let root_path = root.path().to_path_buf();
            let machines = Arc::new(ActorMachineRegistry::<frunk::HNil, ChildOutput>::new());
            let dropped = Arc::new(tokio::sync::Notify::new());
            let factory_dropped = dropped.clone();
            let runner = ResidentActorRunner::new(
                machines.clone(),
                (ActorWorkbenchSource::new("", Vec::new()))
                    .bind_preparation(preparation_client.clone()),
            )
            .with_child_bootstrap_program(child_bootstrap_fixture())
            .with_child_session_factory(Arc::new(move |id, _, _settlement| {
                Ok(child_preparation_fixture(
                    id,
                    root_path.clone(),
                    ChildOutput(Arc::new(ChildOutputLifetime(factory_dropped.clone()))),
                ))
            }));
            let original = runner
                .provision_child_session(
                    id,
                    RealmId::fresh(),
                    None,
                    &[],
                    crate::ActorDescriptor::new(
                        "independent child fixture",
                        crate::ActorPlacement {
                            session: id,
                            resource_scope: RealmId::ROOT,
                            lexical_scope: tidepool_codegen::scope::ScopeId::ROOT,
                        },
                    )
                    .admit_independent_world()
                    .source_dependency(),
                )
                .await
                .unwrap();
            match runner
                .provision_child_session(
                    id,
                    RealmId::fresh(),
                    None,
                    &[],
                    crate::ActorDescriptor::new(
                        "independent child fixture",
                        crate::ActorPlacement {
                            session: id,
                            resource_scope: RealmId::ROOT,
                            lexical_scope: tidepool_codegen::scope::ScopeId::ROOT,
                        },
                    )
                    .admit_independent_world()
                    .source_dependency(),
                )
                .await
            {
                Err(error) => assert!(error.contains("already had a live entry")),
                Ok(_) => panic!("collision must refuse without acquiring discard custody"),
            }
            let mut checkout = machines
                .checkout_run(id)
                .expect("collision preserves original machine");
            assert!(checkout
                .machine()
                .compile_view_in(original.lexical_scope)
                .is_some());
            checkout.restore_suspended(Vec::new());
            assert!(runner.access.child_sessions.lock().unwrap().contains(&id));
            drop(original);
            assert!(machines.kind(id).is_none());
            assert!(!runner.access.child_sessions.lock().unwrap().contains(&id));

            let task_runner = runner.clone();
            let task_owner = crate::capabilities::CompilerOwnerScope::current().unwrap();
            let (published, observe) = tokio::sync::oneshot::channel();
            let task = tokio::spawn(async move {
                let _owned = task_owner
                    .scope(
                        task_runner.provision_child_session(
                            id,
                            RealmId::fresh(),
                            None,
                            &[],
                            crate::ActorDescriptor::new(
                                "independent child fixture",
                                crate::ActorPlacement {
                                    session: id,
                                    resource_scope: RealmId::ROOT,
                                    lexical_scope: tidepool_codegen::scope::ScopeId::ROOT,
                                },
                            )
                            .admit_independent_world()
                            .source_dependency(),
                        ),
                    )
                    .await
                    .unwrap();
                published.send(()).unwrap();
                std::future::pending::<()>().await;
            });
            observe.await.unwrap();
            assert!(machines.kind(id).is_some());
            task.abort();
            assert!(matches!(task.await, Err(error) if error.is_cancelled()));
            assert!(
                machines.kind(id).is_none(),
                "discard custody survives publication before consumer cancellation"
            );
            assert!(!runner.access.child_sessions.lock().unwrap().contains(&id));
        })
        .await
    }

