    async fn progress_nominal_type_mismatch_preserves_snapshot_wakes_and_roots_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        use crate::request::sources::{RequestSourceKind, SourceDelivery, SourceEvent};
        use crate::request::{RequestRegistry, WatchRequirement};
        use ractor::{Actor, ActorProcessingErr};
        use tidepool_effect::{EffectRunPolicy, LivePayloadPolicy};

        struct SourceCollectorState {
            identity: crate::ActorRef,
            lifecycle: crate::LifecycleHandle,
            sender: tokio::sync::mpsc::UnboundedSender<SourceDelivery>,
        }
        struct SourceCollector;
        impl Actor for SourceCollector {
            type Msg = crate::KernelMessage;
            type State = SourceCollectorState;
            type Arguments = Self::State;
            async fn pre_start(
                &self,
                _: ractor::ActorRef<Self::Msg>,
                state: Self::Arguments,
            ) -> Result<Self::State, ActorProcessingErr> {
                Ok(state)
            }
            async fn handle(
                &self,
                _: ractor::ActorRef<Self::Msg>,
                message: Self::Msg,
                state: &mut Self::State,
            ) -> Result<(), ActorProcessingErr> {
                let (message, lease) = match message {
                    crate::KernelMessage::Admitted(envelope) => {
                        let (message, lease) = envelope.into_parts(state.identity)?;
                        (message, Some(lease))
                    }
                    message => (message, None),
                };
                if let crate::KernelMessage::Source(delivery) = message {
                    state.sender.send(delivery)?;
                }
                drop(lease);
                Ok(())
            }
            async fn post_stop(
                &self,
                _: ractor::ActorRef<Self::Msg>,
                state: &mut Self::State,
            ) -> Result<(), ActorProcessingErr> {
                state.lifecycle.close().await?;
                state.lifecycle.executor_retired();
                Ok(())
            }
        }

        tidepool_testing::eval_harness::require_extract();
        let surface = tidepool_testing::effect_surface::TestEffectSurface::minimal(&[]).unwrap();
        let publisher_id = tidepool_repr::SessionId(0xCA01);
        let observer_id = tidepool_repr::SessionId(0xCA02);
        let (mut publisher, publisher_root) = bare_session_at(publisher_id);
        let (mut observer, observer_root) = bare_session_at(observer_id);
        let images = Arc::new(tidepool_runtime::session::ImageRegistry::new());
        publisher.set_image_registry(images.clone());
        observer.set_image_registry(images);
        let fixture =
            tidepool_testing::fixture_source("exomonad/actor/src/fixtures/ProgressRuntime.hs");
        std::fs::write(publisher_root.path().join("ProgressRuntime.hs"), fixture).unwrap();
        let preamble = insert_preamble_imports(
            surface.preamble(),
            "qualified ProgressRuntime\nimport qualified Tidepool.Effects.Core as ProgressCore",
        );
        let templates = resident_workbench_templates(
            &preamble,
            "'[TidepoolReplies.Replies]",
            "qualified Tidepool.Agent.Reply.Internal as TidepoolReplies",
        );
        let source_templates = resident_workbench_templates(
            &preamble,
            "'[ProgressCore.ActorKernel, TidepoolReplies.Replies]",
            "qualified Tidepool.Agent.Reply.Internal as TidepoolReplies",
        );
        let mut include = surface.include_path_refs();
        include.push(publisher_root.path());
        let compile = |text: &str, source: bool| {
            let templates = if source {
                &source_templates
            } else {
                &templates
            };
            let TurnResult::Bind {
                compiled, bound, ..
            } = tidepool_testing::with_settlement(|settlement| {
                run_turn(
                    TurnRequest {
                        exact_context: None,
                        session_id: None,
                        turn_text: text,
                        templates,
                        include: &include,
                        session_root: publisher_root.path(),
                        inject_modules: &[],
                        gen: 1,
                        verdict: None,
                        target: None,
                        retained_imports: &[],
                    },
                    settlement,
                )
            })
            .unwrap()
            else {
                panic!("typed progress fixture must compile a bind")
            };
            (compiled, bound)
        };
        // Compile each immutable program once; publication retries use fresh frames.
        let (note, _) = compile("published <- ProgressRuntime.publishNote 1", false);
        let (wrong, _) = compile("published <- ProgressRuntime.publishInt 1", false);
        let (wrong_observer, _) = compile("observed <- ProgressRuntime.observeInt 1", false);
        let (correct_observer, _) = compile("observed <- ProgressRuntime.observeNote 1", false);
        let (wrong_source, _) = compile("installed <- ProgressRuntime.installIntSource 1", true);
        let (correct_source, _) = compile("installed <- ProgressRuntime.installNoteSource 1", true);
        let (verifier, verifier_binders) =
            compile("sourceVerifier <- pure ProgressRuntime.verifySource", false);
        let [verifier_binder] = verifier_binders.as_slice() else {
            panic!("source verifier must have one compiler-issued binder")
        };
        let verified = tidepool_testing::with_settlement(|settlement| {
            observer.run_bind_with_sites(
                "source-verifier",
                verifier.code(),
                verifier_binder,
                tidepool_repr::Generation(1),
                settlement,
            )
        })
        .unwrap();
        assert!(matches!(verified, ResidentOutcome::Completed { .. }));
        let source_verifier = observer
            .retain_binding_custody("sourceVerifier")
            .unwrap()
            .unwrap();
        let expected = Arc::new(
            note.sites()
                .iter()
                .find_map(|site| site.input_type_witnesses.first().and_then(Option::as_ref))
                .unwrap()
                .clone(),
        );
        publisher.set_effect_execution(
            EffectRunPolicy::SuspendAll,
            LivePayloadPolicy::HASKELL_EFFECT_VALUE,
        );
        observer.set_effect_execution(
            EffectRunPolicy::SuspendAll,
            LivePayloadPolicy::HASKELL_EFFECT_VALUE,
        );
        let suspend = |outcome| match outcome {
            ResidentOutcome::Suspended { hole, .. } => hole,
            other => panic!("progress fixture did not suspend: {other:?}"),
        };
        let owner = crate::ActorRef::first(crate::ActorId(0xCA01));
        let target = crate::ActorRef::first(crate::ActorId(0xCA02));
        let registry = Arc::new(RequestRegistry::default());
        let request = registry.reserve_native(owner, target);
        assert_eq!(
            request.0, 1,
            "fixture names the first exact registry request"
        );
        registry.mark_queued(owner, target, request).unwrap();
        registry
            .present_with_progress_type(target, request, Some(expected))
            .unwrap();
        let (watch, initial) = registry
            .register_watch_requirements(
                owner,
                "typed-progress".into(),
                vec![(request, WatchRequirement::ProgressAfter(0))],
            )
            .unwrap();
        assert!(initial.is_empty());
        let (source_send, mut source_events) = tokio::sync::mpsc::unbounded_channel();
        let (directory, directory_task) = crate::LocalActorDirectory::start().await.unwrap();
        let reservation = directory.reserve(crate::Incarnation::FIRST).await.unwrap();
        let source_identity = reservation.identity();
        let source_lifecycle = reservation.lifecycle().clone();
        let source_terminal = reservation.terminal().clone();
        let (source_address, source_task) = SourceCollector::spawn(
            None,
            SourceCollector,
            SourceCollectorState {
                identity: source_identity,
                lifecycle: source_lifecycle.clone(),
                sender: source_send,
            },
        )
        .await
        .unwrap();
        let source_actor = crate::LocalActorRef::with_identity_admission(
            source_address.clone(),
            source_terminal,
            source_identity,
            source_lifecycle.clone(),
        );
        source_lifecycle
            .attach_executor(source_address.clone())
            .await
            .unwrap();
        directory
            .register_executor(
                reservation,
                source_actor.clone(),
                std::sync::Weak::new(),
                crate::local_actor::SpawnOwnership::Independent,
            )
            .await
            .unwrap();
        directory.observe_executor_linked(&source_actor);
        source_lifecycle.executor_started().await.unwrap();
        let sources = registry
            .attach_sources(
                owner,
                source_actor,
                &[(0, request, RequestSourceKind::Progress)],
            )
            .unwrap();
        let baseline = publisher.value_handle_count();
        let hole = suspend(
            tidepool_testing::with_settlement(|settlement| {
                publisher.run_with_sites("wrong-progress", wrong.code(), settlement)
            })
            .unwrap(),
        );
        let token = publisher
            .capture_progress_publication(&hole, RealmId::ROOT)
            .unwrap();
        publisher
            .abort(hole.cont_id(), "publication fixture captured".into())
            .unwrap();
        assert_eq!(
            registry
                .publish_progress(target, request, token, publisher_id)
                .unwrap_err(),
            crate::ReplyError::ProgressTypeMismatch
        );
        assert_eq!(
            publisher.value_handle_count(),
            baseline,
            "refused publication releases its private root"
        );
        assert!(matches!(
            registry.observe_progress(owner, request),
            Ok((None, false))
        ));
        assert!(matches!(
            registry.observe_watch(owner, watch),
            Ok(crate::request::WatchObservation::Pending(_))
        ));
        assert!(
            source_events.try_recv().is_err(),
            "refused publication cannot enqueue a source event"
        );
        let hole = suspend(
            tidepool_testing::with_settlement(|settlement| {
                publisher.run_with_sites("correct-progress", note.code(), settlement)
            })
            .unwrap(),
        );
        let token = publisher
            .capture_progress_publication(&hole, RealmId::ROOT)
            .unwrap();
        publisher
            .abort(hole.cont_id(), "publication fixture captured".into())
            .unwrap();
        let (revision, notifications) = registry
            .publish_progress(target, request, token, publisher_id)
            .unwrap();
        assert_eq!(revision, 1, "refusal does not consume a revision");
        assert_eq!(
            notifications.len(),
            1,
            "only accepted publication wakes the watch"
        );
        let first_source = tokio::time::timeout(Duration::from_secs(2), source_events.recv())
            .await
            .unwrap()
            .unwrap();
        assert!(
            matches!(&first_source.event, SourceEvent::Progress(snapshot) if snapshot.revision == 1)
        );
        let snapshot = registry
            .observe_progress(owner, request)
            .unwrap()
            .0
            .unwrap();
        let hole = suspend(
            tidepool_testing::with_settlement(|settlement| {
                publisher.run_with_sites("wrong-progress-retry", wrong.code(), settlement)
            })
            .unwrap(),
        );
        let token = publisher
            .capture_progress_publication(&hole, RealmId::ROOT)
            .unwrap();
        publisher
            .abort(hole.cont_id(), "publication fixture captured".into())
            .unwrap();
        assert_eq!(
            registry
                .publish_progress(target, request, token, publisher_id)
                .unwrap_err(),
            crate::ReplyError::ProgressTypeMismatch
        );
        let current = registry
            .observe_progress(owner, request)
            .unwrap()
            .0
            .unwrap();
        assert_eq!(current.revision, snapshot.revision);
        assert!(
            Arc::ptr_eq(&current.value, &snapshot.value),
            "refusal preserves the previous publication"
        );
        assert_eq!(publisher.value_handle_count(), baseline + 1);
        assert!(
            source_events.try_recv().is_err(),
            "wrong retry cannot emit another source revision"
        );

        let no_progress = RequestRegistry::default();
        let request_without_progress = no_progress.reserve(owner, target);
        no_progress
            .mark_queued(owner, target, request_without_progress)
            .unwrap();
        no_progress
            .present_with_progress_type(target, request_without_progress, None)
            .unwrap();
        let hole = suspend(
            tidepool_testing::with_settlement(|settlement| {
                publisher.run_with_sites("absent-progress-contract", note.code(), settlement)
            })
            .unwrap(),
        );
        let token = publisher
            .capture_progress_publication(&hole, RealmId::ROOT)
            .unwrap();
        publisher
            .abort(hole.cont_id(), "publication fixture captured".into())
            .unwrap();
        assert_eq!(
            no_progress
                .publish_progress(target, request_without_progress, token, publisher_id)
                .unwrap_err(),
            crate::ReplyError::ProgressTypeMismatch,
            "an admitted request with no progress contract cannot publish"
        );
        assert_eq!(publisher.value_handle_count(), baseline + 1);

        // The erased representations are equal, but the observer's nominal
        // witness differs. The common resume path must refuse BEFORE importing.
        let warm = suspend(
            tidepool_testing::with_settlement(|settlement| {
                observer.run_with_sites("observer-publication-image", note.code(), settlement)
            })
            .unwrap(),
        );
        observer
            .abort(
                warm.cont_id(),
                "observer installed original publication image".into(),
            )
            .unwrap();
        let observer_handles = observer.value_handle_count();
        let observer_hole = suspend(
            tidepool_testing::with_settlement(|settlement| {
                observer.run_with_sites("wrong-observer", wrong_observer.code(), settlement)
            })
            .unwrap(),
        );
        let machines = Arc::new(ActorMachineRegistry::new());
        machines.insert_idle(publisher_id, Box::new(publisher));
        machines.insert_idle(observer_id, Box::new(observer));
        let source = ActorWorkbenchSource::new(preamble, surface.include_paths().to_vec());
        let runner = ResidentActorRunner::new(
            Arc::clone(&machines),
            (source).bind_preparation(preparation_client.clone()),
        );
        let context = crate::ActorDescriptor::new(
            "progress-observer",
            crate::ActorPlacement {
                session: observer_id,
                resource_scope: RealmId::ROOT,
                lexical_scope: ScopeId::ROOT,
            },
        )
        .session_context(owner);
        runner
            .resume_progress_observation(
                context.clone(),
                observer_hole,
                Ok((Some(snapshot), false)),
            )
            .await
            .unwrap();
        let after = runner
            .access
            .with_host_machine(
                "count-refused-progress-import",
                observer_id,
                None,
                |session, _| Ok(session.value_handle_count()),
            )
            .await
            .unwrap();
        assert_eq!(
            after, observer_handles,
            "wrong nominal observation never imports a payload root"
        );
        let mut entries = Vec::new();
        for (label, compiled) in [
            ("wrong-source", wrong_source),
            ("correct-source", correct_source),
        ] {
            let outcome = runner
                .access
                .with_host_machine(label, observer_id, None, move |session, _| {
                    tidepool_testing::with_settlement(|settlement| {
                        session.run_with_sites(label, compiled.code(), settlement)
                    })
                    .map_err(Into::into)
                })
                .await
                .unwrap();
            let ResidentActorStartupStep::InstallSource {
                continuation,
                source,
            } = runner
                .capture_startup_step(context.clone(), outcome, RealmId::ROOT)
                .await
                .unwrap()
            else {
                panic!("fixture must capture the real installed source mapper")
            };
            runner
                .access
                .with_machine(context.clone(), move |session, _, _| {
                    session
                        .abort(continuation.cont_id(), "source fixture captured".into())
                        .map_err(Into::into)
                })
                .await
                .unwrap();
            entries.push(source.entry);
        }
        let [wrong_entry, correct_entry]: [_; 2] = entries.try_into().ok().unwrap();
        let source_handles = runner
            .access
            .with_host_machine("source-handle-baseline", observer_id, None, |session, _| {
                Ok(session.value_handle_count())
            })
            .await
            .unwrap();
        let wrong_message = runner
            .map_source(
                context.clone(),
                wrong_entry.clone(),
                registry.accept_source_delivery(first_source.clone()).event,
            )
            .await
            .unwrap();
        let verifier = Arc::new(source_verifier);
        let verify_message = |message: crate::MailboxValue| {
            let verifier = verifier.clone();
            runner
                .access
                .with_machine(context.clone(), move |session, _, _| {
                    tidepool_testing::with_settlement(|settlement| {
                        session.run_rooted_application(
                            "verify-progress-source",
                            &verifier,
                            &message.into_custody(),
                            RealmId::ROOT,
                            None,
                            settlement,
                        )
                    })
                    .map_err(Into::into)
                })
        };
        let wrong_result = verify_message(wrong_message).await.unwrap();
        assert!(matches!(wrong_result, ResidentOutcome::Completed { .. }));
        let after_wrong_source = runner
            .access
            .with_host_machine(
                "source-refused-import-count",
                observer_id,
                None,
                |session, _| Ok(session.value_handle_count()),
            )
            .await
            .unwrap();
        assert_eq!(
            after_wrong_source, source_handles,
            "wrong mapper neither imports nor retains progress; verifier input is consumed"
        );
        assert_eq!(
            registry
                .observe_progress(owner, request)
                .unwrap()
                .0
                .unwrap()
                .revision,
            1
        );
        assert!(source_events.try_recv().is_err());

        let correct_observer = Arc::new(correct_observer);
        let retained_observer = correct_observer.clone();
        let correct_hole = runner
            .access
            .with_host_machine(
                "same-session-typed-observer",
                publisher_id,
                None,
                move |session, _| {
                    tidepool_testing::with_settlement(|settlement| {
                        session.run_with_sites(
                            "correct-observer",
                            correct_observer.code(),
                            settlement,
                        )
                    })
                    .map_err(Into::into)
                },
            )
            .await
            .unwrap();
        let publisher_context = crate::ActorDescriptor::new(
            "correct-progress-observer",
            crate::ActorPlacement {
                session: publisher_id,
                resource_scope: RealmId::ROOT,
                lexical_scope: ScopeId::ROOT,
            },
        )
        .session_context(owner);
        runner
            .resume_progress_observation(
                publisher_context,
                suspend(correct_hole),
                Ok((Some(current), false)),
            )
            .await
            .unwrap();
        let correct_message = runner
            .map_source(
                context.clone(),
                correct_entry.clone(),
                registry.accept_source_delivery(first_source).event,
            )
            .await
            .unwrap();
        assert!(matches!(
            verify_message(correct_message).await.unwrap(),
            ResidentOutcome::Completed { .. }
        ));
        let (later_watch, initial) = registry
            .register_watch_requirements(
                owner,
                "later-correct".into(),
                vec![(request, WatchRequirement::ProgressAfter(1))],
            )
            .unwrap();
        assert!(initial.is_empty());
        let later = runner
            .access
            .with_host_machine(
                "later-correct-source-publication",
                publisher_id,
                None,
                move |session, _| {
                    let ResidentOutcome::Suspended { hole, .. } =
                        tidepool_testing::with_settlement(|settlement| {
                            session.run_with_sites("later-note", note.code(), settlement)
                        })?
                    else {
                        panic!("later publication must suspend")
                    };
                    let token = session.capture_progress_publication(&hole, RealmId::ROOT)?;
                    session.abort(hole.cont_id(), "later publication captured".into())?;
                    Ok(token)
                },
            )
            .await
            .unwrap();
        let (revision, notifications) = registry
            .publish_progress(target, request, later, publisher_id)
            .unwrap();
        assert_eq!(revision, 2);
        assert_eq!(notifications.len(), 1);
        assert_eq!(notifications[0].watch, later_watch);
        let later_source = tokio::time::timeout(Duration::from_secs(2), source_events.recv())
            .await
            .unwrap()
            .unwrap();
        assert!(
            matches!(&later_source.event, SourceEvent::Progress(snapshot) if snapshot.revision == 2)
        );
        let later_message = runner
            .map_source(
                context.clone(),
                correct_entry.clone(),
                registry.accept_source_delivery(later_source).event,
            )
            .await
            .unwrap();
        assert!(matches!(
            verify_message(later_message).await.unwrap(),
            ResidentOutcome::Completed { .. }
        ));
        let claim = registry.begin_reply(target, request).unwrap();
        crate::request::test_support::complete_reply(&registry, claim, None);
        let closed = tokio::time::timeout(Duration::from_secs(2), source_events.recv())
            .await
            .unwrap()
            .unwrap();
        assert!(matches!(&closed.event, SourceEvent::ProgressClosed));
        let closed_message = runner
            .map_source(
                context.clone(),
                correct_entry,
                registry.accept_source_delivery(closed).event,
            )
            .await
            .unwrap();
        assert!(matches!(
            verify_message(closed_message).await.unwrap(),
            ResidentOutcome::Completed { .. }
        ));
        registry.forget_response(owner, request).unwrap();
        for (identity, cursor, revision) in [(watch, 0, 1), (later_watch, 1, 2)] {
            let captured = registry
                .observe_watch_progress(owner, identity, request, cursor)
                .unwrap();
            assert_eq!(captured.0.as_ref().unwrap().revision, revision);
            let retained_observer = retained_observer.clone();
            let observed = runner
                .access
                .with_host_machine(
                    "project-released-watch-snapshot",
                    observer_id,
                    None,
                    move |session, _| {
                        tidepool_testing::with_settlement(|settlement| {
                            session.run_with_sites(
                                "captured-note",
                                retained_observer.code(),
                                settlement,
                            )
                        })
                        .map_err(Into::into)
                    },
                )
                .await
                .unwrap();
            runner
                .resume_progress_observation(context.clone(), suspend(observed), Ok(captured))
                .await
                .unwrap();
        }
        drop(sources);
        assert!(matches!(
            registry.begin_reply(target, request),
            Err(crate::ReplyError::Stale | crate::ReplyError::AlreadySettled)
        ));
        assert_eq!(
            registry.forget_watch(owner, watch).unwrap(),
            crate::request::ForgetWatchOutcome::Forgotten
        );
        assert_eq!(
            registry.forget_watch(owner, later_watch).unwrap(),
            crate::request::ForgetWatchOutcome::Forgotten
        );
        assert!(matches!(
            registry.observe_progress(owner, request),
            Err(crate::ReplyError::Stale)
        ));
        source_address.stop(None);
        source_task.await.unwrap();
        directory_task.abort();
        assert!(source_events.try_recv().is_err());
        drop(observer_root);
    }

    /// [`ResidentActorRunner::import_shared_custody`]: the non-consuming,
    /// borrowing counterpart `transfer_custody` cannot stand in for, used by
    /// `resume_progress_observation` when an observer's session differs
    /// from a published `ProgressSnapshot`'s owning session. A published
    /// snapshot may be observed by several observers off the SAME retained
    /// `Arc<RootCustody>` -- proves: (a) two independent observers each get
    /// their own readable custody from one shared owning root; (b) the
    /// owning root's own handle count is UNCHANGED by either import (the
    /// export never consumes it, so a later observer -- or a retry of an
    /// earlier one -- can still export it again); (c) both imported
    /// custodies are independently discardable with no double-free.
    #[tokio::test]
    async fn import_shared_custody_lets_two_observers_read_one_published_root() {
        with_test_compiler_owner(|preparation_client| {
            import_shared_custody_lets_two_observers_read_one_published_root_with_compiler_owner(
                preparation_client.clone(),
            )
        })
        .await
    }

    async fn import_shared_custody_lets_two_observers_read_one_published_root_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        tidepool_testing::eval_harness::require_extract();
        let surface = tidepool_testing::effect_surface::TestEffectSurface::minimal(&[])
            .expect("materialize minimal effect surface");

        let owner_id = tidepool_repr::SessionId(0xC0_C0);
        let observer_one_id = tidepool_repr::SessionId(0xC1_C1);
        let observer_two_id = tidepool_repr::SessionId(0xC2_C2);
        let (mut owner_session, owner_root) = bare_session_at(owner_id);
        let (mut observer_one, observer_one_root) = bare_session_at(observer_one_id);
        let (mut observer_two, observer_two_root) = bare_session_at(observer_two_id);

        let _warm_owner = bind_bare_value(
            &mut owner_session,
            owner_id,
            owner_root.path(),
            &surface,
            1,
            "warmOwner",
            "0 :: Int",
        );
        let _warm_one = bind_bare_value(
            &mut observer_one,
            observer_one_id,
            observer_one_root.path(),
            &surface,
            1,
            "warmOne",
            "0 :: Int",
        );
        let _warm_two = bind_bare_value(
            &mut observer_two,
            observer_two_id,
            observer_two_root.path(),
            &surface,
            1,
            "warmTwo",
            "0 :: Int",
        );

        let registry = Arc::new(tidepool_runtime::session::ImageRegistry::new());
        owner_session.set_image_registry(Arc::clone(&registry));
        observer_one.set_image_registry(Arc::clone(&registry));
        observer_two.set_image_registry(Arc::clone(&registry));

        let progress_value = bind_bare_value(
            &mut owner_session,
            owner_id,
            owner_root.path(),
            &surface,
            2,
            "progress",
            "333 :: Int",
        );
        let progress_before = owner_session
            .render_retained_preview(&progress_value, 64)
            .expect("the owning session can render its own custody");
        // Every observer must independently install the SAME image for its
        // import to resolve the exported static top -- same reasoning as
        // `transfer_custody`'s own cross-session case above.
        let _progress_warm_one = bind_bare_value(
            &mut observer_one,
            observer_one_id,
            observer_one_root.path(),
            &surface,
            2,
            "progress",
            "333 :: Int",
        );
        let _progress_warm_two = bind_bare_value(
            &mut observer_two,
            observer_two_id,
            observer_two_root.path(),
            &surface,
            2,
            "progress",
            "333 :: Int",
        );

        let machines = Arc::new(ActorMachineRegistry::<
            frunk::HNil,
            tidepool_mcp::CapturedOutput,
        >::new());
        machines.insert_idle(owner_id, Box::new(owner_session));
        machines.insert_idle(observer_one_id, Box::new(observer_one));
        machines.insert_idle(observer_two_id, Box::new(observer_two));
        let source = ActorWorkbenchSource::new(
            surface.preamble().to_string(),
            surface.include_paths().to_vec(),
        );
        let runner: ResidentActorRunner<frunk::HNil, tidepool_mcp::CapturedOutput> =
            ResidentActorRunner::new(
                Arc::clone(&machines),
                (source).bind_preparation(preparation_client.clone()),
            );

        async fn handle_count(
            runner: &ResidentActorRunner<frunk::HNil, tidepool_mcp::CapturedOutput>,
            session_id: tidepool_repr::SessionId,
        ) -> usize {
            runner
                .access
                .with_host_machine("count", session_id, None, |session, _| {
                    Ok(session.value_handle_count())
                })
                .await
                .expect("checkout for counting handles")
        }

        let owner = RealmId::fresh();
        let shared = Arc::new(progress_value);

        let owner_before = handle_count(&runner, owner_id).await;

        let one_before = handle_count(&runner, observer_one_id).await;
        let imported_one = runner
            .import_shared_custody(Arc::clone(&shared), owner_id, observer_one_id, owner)
            .await
            .expect("first observer imports its own custody");
        let one_after = handle_count(&runner, observer_one_id).await;
        assert_eq!(
            one_after,
            one_before + 1,
            "the first observer mints exactly one new handle"
        );

        let owner_after_one = handle_count(&runner, owner_id).await;
        assert_eq!(
            owner_after_one, owner_before,
            "a borrowed export never changes the owning session's own handle count"
        );

        let two_before = handle_count(&runner, observer_two_id).await;
        let imported_two = runner
            .import_shared_custody(Arc::clone(&shared), owner_id, observer_two_id, owner)
            .await
            .expect("a second observer can export the SAME still-live root again");
        let two_after = handle_count(&runner, observer_two_id).await;
        assert_eq!(
            two_after,
            two_before + 1,
            "the second observer mints its own, independent new handle"
        );

        let owner_after_two = handle_count(&runner, owner_id).await;
        assert_eq!(
            owner_after_two, owner_before,
            "the second (repeated) export still never touches the owning session's handle count"
        );

        let render_one = runner
            .access
            .with_host_machine("render", observer_one_id, None, move |session, _| {
                Ok(session.render_retained_preview(&imported_one, 64))
            })
            .await
            .expect("checkout for rendering")
            .expect("observer one can render its independent import");
        let render_two = runner
            .access
            .with_host_machine("render", observer_two_id, None, move |session, _| {
                Ok(session.render_retained_preview(&imported_two, 64))
            })
            .await
            .expect("checkout for rendering")
            .expect("observer two can render its independent import");
        assert_eq!(
            render_one, progress_before,
            "observer one sees the published content"
        );
        assert_eq!(
            render_two, progress_before,
            "observer two sees the published content"
        );

        // The owning root is still live and unconsumed after both imports --
        // a later (third) observer, or a retry, could still export it again.
        let owner_final_render = runner
            .access
            .with_host_machine("render", owner_id, None, move |session, _| {
                Ok(session.render_retained_preview(&shared, 64))
            })
            .await
            .expect("checkout for rendering")
            .expect("the owning session can still render its own retained root");
        assert_eq!(
            owner_final_render, progress_before,
            "the owning root outlives both borrowed exports, unconsumed"
        );
    }

    #[tokio::test]
    async fn spawn_child_session_without_an_installed_factory_is_a_named_error() {
        with_test_compiler_owner(|client| async move {
            spawn_child_session_without_an_installed_factory_is_a_named_error_with_client(client)
        })
        .await;
    }

    fn spawn_child_session_without_an_installed_factory_is_a_named_error_with_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, _context, source, _root) = actor_registry_fixture();
        let runner: ResidentActorRunner<frunk::HNil, tidepool_mcp::CapturedOutput> =
            ResidentActorRunner::new(
                machines,
                (source).bind_preparation(preparation_client.clone()),
            );
        let error = tidepool_testing::with_settlement(|settlement| {
            runner.spawn_child_session(tidepool_repr::SessionId(999_999), settlement)
        })
        .expect_err("no factory installed");
        assert!(error.contains("no child-session factory"));
    }

    fn child_session_with_outstanding_custody(
        preparation_client: crate::CompilerPreparationClient,
    ) -> (
        ResidentActorRunner<frunk::HNil, tidepool_mcp::CapturedOutput>,
        Arc<ActorMachineRegistry<frunk::HNil, tidepool_mcp::CapturedOutput>>,
        tidepool_repr::SessionId,
        RootCustody,
    ) {
        let (machines, context, source, _root) = actor_registry_fixture();
        let child_id = tidepool_repr::SessionId(context.placement.session.0.wrapping_add(11));
        let (mut child_session, _child_root) = bare_session_at(child_id);
        // `ResidentSession::retain_binding_custody` resolves a name only in
        // `ScopeId::ROOT` (`BindingTable::resolve`'s own doc comment: "the
        // ROOT frame"), so the binding this test mounts (and later resolves
        // a custody token for) must live there too, not in a freshly minted
        // scope.
        let lexical_scope = tidepool_codegen::scope::ScopeId::ROOT;
        let resource_scope = RealmId::fresh();
        child_session
            .set_actor_execution(
                tidepool_runtime::session::SessionRunContext {
                    lexical_scope,
                    resource_scope,
                    ..tidepool_runtime::session::SessionRunContext::ROOT
                },
                tidepool_effect::EffectRunPolicy::HandleOrSuspend,
                tidepool_effect::LivePayloadPolicy::HASKELL_EFFECT_VALUE,
            )
            .expect("actor execution context");
        let child_context = crate::ActorSessionContext {
            placement: crate::ActorPlacement {
                session: child_id,
                resource_scope,
                lexical_scope,
            },
            ..context.clone()
        };
        // A real compiled/mounted binding bootstraps the session's engine;
        // `retain_binding_custody` then mints a `RootCustody` over it —
        // the SAME shape a reply or retained-progress value crosses the
        // resident-workbench boundary as — and this local variable is what
        // "outside the session" means: it is not released until this test
        // drops it below.
        mount_text_binding(
            &mut child_session,
            &child_context,
            &source,
            "outstanding",
            "still here",
            None,
        )
        .expect("mount a real binding to hold a live handle");
        let custody = child_session
            .retain_binding_custody("outstanding")
            .expect("retain mounted binding")
            .expect("the mounted binding resolves to a live custody token");
        machines.insert_idle(child_id, Box::new(child_session));

        let runner = ResidentActorRunner::new(
            Arc::clone(&machines),
            (source).bind_preparation(preparation_client.clone()),
        );
        runner
            .access
            .child_sessions
            .lock()
            .unwrap()
            .insert(child_id);
        (runner, machines, child_id, custody)
    }

    fn child_session_with_binding_lease(
        preparation_client: crate::CompilerPreparationClient,
    ) -> (
        ResidentActorRunner<frunk::HNil, tidepool_mcp::CapturedOutput>,
        Arc<ActorMachineRegistry<frunk::HNil, tidepool_mcp::CapturedOutput>>,
        tidepool_repr::SessionId,
        tidepool_runtime::session::resident::BindingLease,
        tempfile::TempDir,
    ) {
        let (machines, runner, context, root) = child_admission_fixture(preparation_client.clone());
        let id = context.placement.session;
        runner.access.child_sessions.lock().unwrap().insert(id);
        let (mut session, receipt) = machines.checkout_run(id).unwrap().into_parts();
        let lease = session.lease_bindings(&[]);
        machines.settle_suspended(receipt, session, Vec::new());
        (runner, machines, id, lease, root)
    }

    async fn assert_child_cleanup_finished(
        runner: &ResidentActorRunner<frunk::HNil, tidepool_mcp::CapturedOutput>,
        id: tidepool_repr::SessionId,
        owner: &Arc<PendingChildTeardown>,
    ) {
        tokio::time::timeout(Duration::from_secs(2), async {
            while runner.access.machines.kind(id).is_some()
                || !owner
                    .worker
                    .lock()
                    .unwrap()
                    .as_ref()
                    .is_some_and(tokio::task::JoinHandle::is_finished)
            {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("terminal cleanup worker finishes");
        assert!(!runner.access.child_sessions.lock().unwrap().contains(&id));
        assert!(!runner
            .access
            .pending_child_teardown
            .lock()
            .unwrap()
            .contains_key(&id));
    }

