    async fn planned_cell_defers_declaration_until_its_admitted_item_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, context, source, _root) = actor_registry_fixture();
        let workbench = ResidentActorWorkbench::new(
            machines,
            (source).bind_preparation(preparation_client.clone()),
            None,
        );
        let public_context = context.clone();
        let (workbench, context) = workbench
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
        let cell = "plannedDecl args = length (args :: [Int])".to_owned();
        let (checked, prepared) = workbench
            .prepare_cell(context.clone(), cell.clone())
            .await
            .expect("admitted declaration program");
        assert_eq!(checked.items.len(), 1);
        workbench
            .access
            .with_machine(context.clone(), |session, context, _| {
                assert!(!session
                    .current_decl_heads_in(context.placement.lexical_scope)
                    .iter()
                    .any(|(name, _)| name == "plannedDecl"));
                Ok(())
            })
            .await
            .unwrap();
        let PreparedCell { mut items, .. } = prepared;
        assert!(matches!(&items[0].ready, PreparedCellStep { item, .. }
            if item.kind() == tidepool_toolchain::checked_cell::CheckedItemKind::Declaration));
        let step = workbench
            .begin_prepared_cell_item(
                context.clone(),
                ParsedBlock {
                    ordinal: 1,
                    total: 1,
                    source: cell,
                },
                items.remove(0),
            )
            .await
            .expect("admitted declaration settles");
        assert!(matches!(step, ResidentWorkbenchStep::Committed { .. }));
        workbench
            .access
            .with_machine(context.clone(), |session, context, _| {
                assert!(session
                    .current_decl_heads_in(context.placement.lexical_scope)
                    .iter()
                    .any(|(name, _)| name == "plannedDecl"));
                Ok(())
            })
            .await
            .unwrap();
        workbench
            .access
            .with_machine(public_context.clone(), |session, context, _| {
                assert!(
                    !session
                        .current_decl_heads_in(context.placement.lexical_scope)
                        .iter()
                        .any(|(name, _)| name == "plannedDecl"),
                    "native declaration execution remains private before publication"
                );
                Ok(())
            })
            .await
            .unwrap();
        let published = workbench_runner_for_test(&workbench)
            .publish_private_execution(
                context,
                workbench.private_execution.as_ref().unwrap().clone(),
            )
            .await
            .unwrap();
        assert!(matches!(
            published,
            PrivateExecutionPublication::Manifest { .. }
        ));
        workbench
            .access
            .with_machine(public_context, |session, context, _| {
                assert!(session
                    .current_decl_heads_in(context.placement.lexical_scope)
                    .iter()
                    .any(|(name, _)| name == "plannedDecl"));
                Ok(())
            })
            .await
            .unwrap();
    }

    #[tokio::test]
    async fn request_annotations_survive_checked_prologue_adoption_and_publication() {
        with_test_compiler_owner(|preparation_client| async move {
            let (session, public_context, mut source, inputs, _root) =
                activation_input_fixture(|_| {});
            let evidence = inputs[0].type_evidence().clone();
            let signatures = evidence.request_type_signatures().unwrap().clone();
            source.request_evidence = Some(evidence.clone());
            let issuer_view = actor_compile_view(&session, &public_context, &source).unwrap();
            let issuer = issuer_view.session_view().exact_compile_context().unwrap();
            let producer = issuer.declarations().toolchain_identity_sha256();
            assert_ne!(producer, [0; 32]);
            assert!(Arc::ptr_eq(issuer.request_types().unwrap(), &signatures));
            let original_context = issuer.declarations().semantic_sha256();
            let public_before = session
                .public_visibility_snapshot_in(public_context.placement.lexical_scope)
                .unwrap();
            let machines = Arc::new(ActorMachineRegistry::<
                frunk::HNil,
                tidepool_mcp::CapturedOutput,
            >::new());
            machines.insert_idle(public_context.placement.session, Box::new(session));
            let (workbench, private_context) = ResidentActorWorkbench::new(
                machines,
                (source).bind_preparation(preparation_client.clone()),
                None,
            )
            .admit_private_cell_for_test(public_context.clone())
            .await
            .unwrap();
            let (checked, prepared) = workbench
                .prepare_cell(
                    private_context.clone(),
                    "import qualified Prelude\nlet adoptedRequestValue = (41 :: Int)".into(),
                )
                .await
                .unwrap();
            assert_eq!(checked.items.len(), 2);
            assert!(checked.items[0].prologue_only);
            let PreparedCell {
                items,
                dependencies,
            } = prepared;
            let prefix = items[0].ready.prefix.clone();
            assert_eq!(
                items[0].ready.item.kind(),
                tidepool_toolchain::checked_cell::CheckedItemKind::Declaration
            );
            assert!(items[0].ready.item.source().is_empty());
            let assert_annotations = || {
                let snapshot = prefix.snapshot();
                let context = snapshot.view().unwrap().exact_compile_context().unwrap();
                assert_eq!(context.declarations().toolchain_identity_sha256(), producer);
                assert!(Arc::ptr_eq(context.request_types().unwrap(), &signatures));
                assert_eq!(
                    issuer.declarations().semantic_sha256(),
                    original_context,
                    "adoption cannot mutate the original request issuer"
                );
            };
            assert_annotations();
            for (index, item) in items.into_iter().enumerate() {
                let step = workbench
                    .begin_prepared_cell_item(
                        private_context.clone(),
                        ParsedBlock {
                            ordinal: index + 1,
                            total: checked.items.len(),
                            source: checked.items[index].source.clone(),
                        },
                        item,
                    )
                    .await
                    .unwrap();
                let ResidentWorkbenchStep::Committed {
                    installed_bindings, ..
                } = step
                else {
                    panic!("the prologue and pure bind must commit through their original owners");
                };
                assert_eq!(
                    installed_bindings,
                    if index == 0 {
                        vec![]
                    } else {
                        vec!["adoptedRequestValue".to_owned()]
                    }
                );
                assert_eq!(prefix.snapshot().compiler_prefix().next_item(), index + 1);
                assert_annotations();
                let expected = public_before.clone();
                workbench
                    .access
                    .with_machine(public_context.clone(), move |session, context, _| {
                        assert_eq!(
                            session.public_visibility_snapshot_in(context.placement.lexical_scope),
                            Some(expected)
                        );
                        assert!(session
                            .current_binding_in(
                                context.placement.lexical_scope,
                                "adoptedRequestValue"
                            )
                            .is_none());
                        Ok(())
                    })
                    .await
                    .unwrap();
            }
            drop(dependencies);
            let private_binding = workbench
                .access
                .with_machine(private_context.clone(), |session, context, _| {
                    Ok(session
                        .current_binding_in(context.placement.lexical_scope, "adoptedRequestValue")
                        .unwrap())
                })
                .await
                .unwrap();
            let publication = workbench_runner_for_test(&workbench)
                .publish_private_execution(
                    private_context.clone(),
                    workbench.private_execution.as_ref().unwrap().clone(),
                )
                .await
                .unwrap();
            assert!(matches!(
                publication,
                PrivateExecutionPublication::Manifest { .. }
            ));
            let private_scope = private_context.placement.lexical_scope;
            workbench
                .access
                .with_machine(public_context.clone(), move |session, context, _| {
                    assert_eq!(
                        session.current_binding_in(
                            context.placement.lexical_scope,
                            "adoptedRequestValue"
                        ),
                        Some(private_binding)
                    );
                    session.retire_scope(private_scope);
                    assert!(session.compile_view_in(private_scope).is_none());
                    let view = session
                        .compile_view_in(context.placement.lexical_scope)
                        .unwrap();
                    session.capture_inspection_inputs(&view).map_err(|error| {
                        ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                    })?;
                    Ok(())
                })
                .await
                .unwrap();
            drop(inputs);
        })
        .await
    }

    /// The native program retains its mounted request input across preparation;
    /// later items and closures retain the exact original input after a new mount.
    #[tokio::test]
    async fn planned_cell_keeps_request_json_input_owned_across_native_preparation() {
        with_test_compiler_owner(|preparation_client| planned_cell_keeps_request_json_input_owned_across_native_preparation_with_compiler_owner(preparation_client.clone(), )).await
    }

    async fn planned_cell_keeps_request_json_input_owned_across_native_preparation_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, public, source, _root) = actor_registry_fixture();
        let workbench = ResidentActorWorkbench::new(
            machines,
            (source).bind_preparation(preparation_client.clone()),
            None,
        )
        .with_json_input(Some(serde_json::json!({"greeting": "hi"})));
        let (workbench, context) = workbench
            .admit_private_cell_for_test(public.clone())
            .await
            .unwrap();
        let (carrier, host_dependencies) = workbench
            .prepare_host_input(context.clone(), HostCarrierKind::Json, None)
            .await
            .expect("host JSON has its original checked interface");
        assert_eq!(
            carrier.binding().unwrap().host_authority,
            Some(tidepool_runtime::session::turn::HostBindingAuthority::JsonValue)
        );
        let carrier = workbench
            .refuse_host_payload_for_test(context.clone(), carrier)
            .await;
        let host_owner = workbench
            .mount_prepared_json_input(
                context.clone(),
                carrier,
                serde_json::json!({"greeting": "hi"}),
            )
            .await
            .unwrap();
        drop(host_dependencies);
        workbench
            .access
            .with_machine(context.clone(), |session, context, _| {
                let view = session
                    .compile_view_in(context.placement.lexical_scope)
                    .unwrap();
                let input = session.capture_inspection_inputs(&view).unwrap();
                assert_eq!(input.view().reachable_values().len(), 1);
                let owner = input.view().reachable_values()[0];
                assert!(!view.session_root().join(owner.relative_hs_path()).exists());
                Ok(())
            })
            .await
            .unwrap();
        let cell = "seen <- pure input\nechoed <- pure seen\ncapturedInput <- pure (\\() -> input)"
            .to_string();

        let (checked, prepared) = workbench
            .prepare_checked_cell(
                context.clone(),
                cell,
                workbench.compilation_authority.clone().unwrap(),
                workbench.private_execution.clone().unwrap(),
                Some(host_owner),
            )
            .await
            .expect("a three-item native program retains its request input and closure");
        assert_eq!(
            checked.items.len(),
            3,
            "all three bind statements must classify as items: {checked:?}"
        );
        assert!(
            checked
                .items
                .iter()
                .all(|item| item.verdict.kind == TurnKind::Bind),
            "every item is a binding: {checked:?}"
        );
        let PreparedCell {
            items,
            dependencies,
        } = prepared;
        assert_eq!(items.len(), 3);
        assert!(
            items.iter().all(|item| item.ready.item.kind()
                == tidepool_toolchain::checked_cell::CheckedItemKind::Bind),
            "all three items retain their admitted program authority"
        );
        let input_name = dependencies
            ._input
            .as_ref()
            .unwrap()
            .mounted_input()
            .binder
            .name
            .clone();
        for (index, (observed, item)) in checked.items.iter().zip(items).enumerate() {
            let step = workbench
                .begin_prepared_cell_item(
                    context.clone(),
                    ParsedBlock {
                        ordinal: index + 1,
                        total: checked.items.len(),
                        source: observed.source.clone(),
                    },
                    item,
                )
                .await
                .expect("admitted JSON item executes");
            match step {
                ResidentWorkbenchStep::Running { fragment, outcome } => {
                    workbench
                        .settle_item(context.clone(), *fragment, (*outcome).into())
                        .await
                        .expect("JSON bind settles");
                }
                ResidentWorkbenchStep::Committed { .. } => {}
                _ => panic!("JSON item did not commit"),
            }
        }
        drop(dependencies);
        tokio::time::timeout(Duration::from_secs(10), async {
            loop {
                let retired = workbench
                    .access
                    .with_machine(context.clone(), {
                        let input_name = input_name.clone();
                        move |session, context, _| {
                            let scope = context.placement.lexical_scope;
                            assert!(session.current_binding_in(scope, "seen").is_some());
                            assert!(session.current_binding_in(scope, "echoed").is_some());
                            assert!(session.current_binding_in(scope, "capturedInput").is_some());
                            Ok(session.current_binding_in(scope, &input_name).is_none())
                        }
                    })
                    .await
                    .unwrap();
                if retired {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the input owner retires while completed JSON values remain bound");
        let workbench = workbench.with_json_input(None);
        let original = workbench
            .host_binding_identity_for_test(context.clone(), "seen")
            .await;
        let original_echo = workbench
            .host_binding_identity_for_test(context.clone(), "echoed")
            .await;
        let original_capture = workbench
            .host_binding_identity_for_test(context.clone(), "capturedInput")
            .await;
        workbench
            .execute_cell_for_test(
                context.clone(),
                &tidepool_testing::fixture_source("exomonad/actor/src/fixtures/host-json-first.hs"),
            )
            .await
            .unwrap();
        workbench
            .publish_completed_cell_for_test(context)
            .await
            .unwrap();
        let (workbench, context) = workbench
            .admit_private_cell_for_test(public.clone())
            .await
            .unwrap();
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "seen")
                .await,
            original
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "echoed")
                .await,
            original_echo
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "capturedInput")
                .await,
            original_capture
        );
        workbench
            .execute_cell_for_test(context.clone(), "data Value = SourceValue Bool")
            .await
            .unwrap();
        let (carrier, host_dependencies) = workbench
            .prepare_host_input(context.clone(), HostCarrierKind::Json, None)
            .await
            .expect("second JSON mount authenticates retained Value and Scientific owners");
        let binder = carrier.binding().unwrap();
        assert_eq!(
            binder.host_authority,
            Some(tidepool_runtime::session::turn::HostBindingAuthority::JsonValue)
        );
        let second_input_name = binder.name.clone();
        let carrier = workbench
            .refuse_host_payload_for_test(context.clone(), carrier)
            .await;
        let input = workbench
            .mount_prepared_json_input(
                context.clone(),
                carrier,
                serde_json::json!({"greeting": "again", "count": 42}),
            )
            .await
            .unwrap();
        drop(host_dependencies);
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "capturedInput")
                .await,
            original_capture
        );
        let source =
            tidepool_testing::fixture_source("exomonad/actor/src/fixtures/host-json-retained.hs");
        let (checked, prepared) = workbench
            .prepare_checked_cell(
                context.clone(),
                source,
                workbench.compilation_authority.clone().unwrap(),
                workbench.private_execution.clone().unwrap(),
                Some(input),
            )
            .await
            .expect("second native program uses its new input and the original JSON values");
        let PreparedCell {
            items,
            dependencies,
        } = prepared;
        assert_eq!(items.len(), 2);
        for (index, (observed, item)) in checked.items.iter().zip(items).enumerate() {
            let step = workbench
                .begin_prepared_cell_item(
                    context.clone(),
                    ParsedBlock {
                        ordinal: index + 1,
                        total: checked.items.len(),
                        source: observed.source.clone(),
                    },
                    item,
                )
                .await
                .unwrap();
            let settled = match step {
                ResidentWorkbenchStep::Running { fragment, outcome } => workbench
                    .settle_item(context.clone(), *fragment, (*outcome).into())
                    .await
                    .unwrap(),
                other => other,
            };
            assert!(matches!(settled, ResidentWorkbenchStep::Committed { .. }));
        }
        drop(dependencies);
        workbench
            .wait_for_host_input_retirement_for_test(context.clone(), second_input_name)
            .await;
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "seen")
                .await,
            original
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "echoed")
                .await,
            original_echo
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "capturedInput")
                .await,
            original_capture
        );
        workbench
            .host_binding_identity_for_test(context.clone(), "secondSeen")
            .await;
        workbench
            .publish_completed_cell_for_test(context)
            .await
            .unwrap();
        assert_eq!(
            workbench
                .host_binding_identity_for_test(public.clone(), "seen")
                .await,
            original
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(public, "capturedInput")
                .await,
            original_capture
        );
    }

    /// `scopeBindings` is world-owned. Its decode must produce
    /// `WorldScopeBindings`, and resuming that boundary must read the admitted
    /// world without entering `resume_compiler_query`.
    #[tokio::test]
    async fn scope_bindings_decode_dispatch_and_resume() {
        with_test_compiler_owner(|preparation_client| async move {
            let (session, context, source, _root) = host_mount_fixture_with_effects(
                |_| {},
                &[tidepool_mcp::introspection_decl()],
                "'[Introspection]",
            );
            let machines = Arc::new(ActorMachineRegistry::new());
            let session_id = context.placement.session;
            machines.insert_idle(session_id, Box::new(session));
            let (captured, owner) = world_query_test_source_files_with_support(
                &[vec![(
                    "WorldScope.hs",
                    "module WorldScope where\nworldA :: Int\nworldA = 7\n",
                )]],
                &source.base_include,
            );
            // Production reads only a retained captured source owner; an
            // incomplete layer must not admit this route.
            let mut context = context;
            context.source_layer = crate::ActorSourceRoots::Complete(captured.clone());
            assert!(public_module_query_source(&context.source_layer).is_ok());
            let workbench = ResidentActorWorkbench::new(
                machines,
                (source).bind_preparation(preparation_client),
                None,
            );
            workbench_runner_for_test(&workbench)
                .adopt_final_source_scope(context.clone())
                .await
                .expect("adopt the fixture world's final source scope");
            let descriptor = crate::ActorDescriptor::new("private-cell-test", context.placement);
            let public_owner =
                crate::resident_actor::WorkbenchPublicOwner::issue(&context, &descriptor, None)
                    .unwrap();
            let private = Arc::new(
                workbench_runner_for_test(&workbench)
                    .begin_private_execution(
                        context.clone(),
                        public_owner,
                        tidepool_runtime::session::PublicationDecision::new(),
                        None,
                    )
                    .await
                    .unwrap(),
            );
            let mut private_context = context.clone();
            private_context.placement.lexical_scope = private.private_scope;
            let layers: crate::ActorSourceLayerResolver = owner.clone();
            let (frontend_context, authority) =
                crate::resident_actor::WorkbenchCompilationAuthority::admit(
                    private_context,
                    captured.clone(),
                    None,
                    Some(&layers),
                )
                .expect("the captured owner must admit its retained source");
            let frontend = workbench
                .shared_view()
                .with_compilation_authority(authority)
                .with_private_execution(private);
            // Short enough to stay inline; a fixture here would need its own
            // BUCK source declaration for no additional evidence.
            let code = concat!(
                "do\n",
                "  bindings <- scopeBindings Nothing\n",
                "  case bindings of\n",
                "    Right _ -> pure ()\n",
                "    Left _ -> error \"scopeBindings was refused\"\n",
            );
            let (_checked, prepared) = frontend
                .prepare_cell(frontend_context.clone(), code.into())
                .await
                .expect("compile the scopeBindings cell");
            let PreparedCell { mut items, .. } = prepared;
            let mut step = frontend
                .begin_prepared_cell_item(
                    frontend_context.clone(),
                    ParsedBlock {
                        ordinal: 1,
                        total: 1,
                        source: code.into(),
                    },
                    items.remove(0),
                )
                .await
                .expect("start the scopeBindings cell");
            let mut resumed_once = false;
            loop {
                match step {
                    ResidentWorkbenchStep::Running { fragment, outcome } => {
                        let boundary = workbench_runner_for_test(&workbench)
                            .capture_boundary(
                                frontend_context.clone(),
                                (*outcome).into(),
                                frontend_context.placement.resource_scope,
                            )
                            .await
                            .expect("capture the query boundary");
                        let (continuation, expected) = match boundary {
                            ResidentActorBoundary::WorldScopeBindings {
                                continuation,
                                expected,
                            } => (continuation, expected),
                            other => panic!(
                                "scopeBindings suspended on {} instead of WorldScopeBindings",
                                other.operation()
                            ),
                        };
                        let resumed = frontend
                            .resume_world_scope_bindings(
                                frontend_context.clone(),
                                continuation,
                                expected,
                            )
                            .await
                            .expect("resume world scope bindings");
                        resumed_once = true;
                        step = frontend
                            .settle_item(frontend_context.clone(), *fragment, resumed)
                            .await
                            .expect("settle the world scope bindings");
                    }
                    ResidentWorkbenchStep::Committed { .. } => break,
                    _ => panic!("unexpected scopeBindings workbench step"),
                }
            }
            assert!(resumed_once, "the fixture never suspended on scopeBindings");
        })
        .await;
    }

    /// The adoption above is a production requirement, not a fixture
    /// convenience: a world whose final scope was never adopted must refuse a
    /// private cell at exactly the source-admission seam.
    #[tokio::test]
    async fn compiler_query_boundary_requires_an_adopted_world_scope() {
        with_test_compiler_owner(|preparation_client| async move {
            let (session, context, source, _root) = host_mount_fixture_with_effects(
                |_| {},
                &[tidepool_mcp::introspection_decl()],
                "'[Introspection]",
            );
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let workbench = ResidentActorWorkbench::new(
                machines,
                (source).bind_preparation(preparation_client),
                None,
            );
            let refused = match workbench.admit_private_cell_for_test(context).await {
                Ok(_) => panic!("an unadopted world scope must refuse the private cell"),
                Err(error) => error,
            };
            assert!(matches!(
                refused,
                ResidentActorWorkbenchError::SourceAdmission(
                    generation_admission::GenerationAdmissionError::Unqualified
                )
            ));
        })
        .await;
    }

