    async fn current_request_cell_compiles_closed_site_evidence_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, mut context, mut source, _root) = actor_registry_fixture();
        context.haskell_effects_alias = "'[Exomonad.Replies]".into();
        source
            .workbench_imports
            .extend_text("qualified Tidepool.Agent.Reply as TidepoolReply");
        let workbench = ResidentActorWorkbench::new(
            machines,
            (source).bind_preparation(preparation_client.clone()),
            None,
        );
        let (workbench, context) = workbench
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
        let cell = "scope <- (TidepoolReply.currentRequest :: Eff '[Exomonad.Replies] (TidepoolReply.RequestScope () ()))".to_owned();
        let (checked, prepared) = workbench
            .prepare_cell(context.clone(), cell.clone())
            .await
            .expect("closed request scope compiles with site evidence");
        assert_eq!(checked.items.len(), 1);
        let PreparedCell { mut items, .. } = prepared;
        let PreparedCellStep { prefix, item } = items.remove(0).ready;
        let reservation = workbench
            .access
            .with_machine(context, move |session, _, _| {
                session.admit_checked_item(prefix, item).map_err(|error| {
                    ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                })
            })
            .await
            .unwrap();
        let compiled = consume_admitted_cell_item(
            reservation,
            &ParsedBlock {
                ordinal: 1,
                total: 1,
                source: cell,
            },
        )
        .unwrap();
        let CompiledBlock::Ready(ready) = compiled else {
            panic!("ready request native product")
        };
        let compiled = &ready.compiled;
        assert!(
            compiled.sites().iter().any(|site| site.inputs.len() == 3),
            "currentRequest carries input, result, and ResponseResult result evidence"
        );
    }

    /// Publish an alias of the original binding through its checked whole cell,
    /// retaining the value interface's issued package and type evidence.
    async fn publish_request_scope_test_input(
        workbench: &ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>,
        context: crate::ActorSessionContext,
    ) -> Result<tidepool_repr::SessionVarId, ResidentActorWorkbenchError> {
        let scope = context.placement.lexical_scope;
        workbench
            .publish_cell_for_test(context.clone(), "sessionInput <- pure sourceValue")
            .await?;

        workbench
            .access
            .with_machine(context, move |session, _, _| {
                session
                    .current_binding_in(scope, "sessionInput")
                    .map(|binding| binding.0)
                    .ok_or_else(|| {
                        ResidentActorWorkbenchError::InputMount(
                            "sessionInput alias was not published in the request scope".into(),
                        )
                    })
            })
            .await
    }

    /// Compile one authentic producer and receiver, then retain two original
    /// native inputs for independent activation mounts in the same machine.
    fn activation_input_fixture(
        configure: impl FnOnce(&mut tidepool_runtime::session::SessionLib),
    ) -> (
        ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
        ActorWorkbenchSource,
        Vec<tidepool_runtime::session::RuntimeActivationInput>,
        tempfile::TempDir,
    ) {
        let (mut session, context, source, parked, root) = activation_session_fixture(configure);
        let inputs = parked
            .into_iter()
            .map(|(hole, input)| {
                let activation_id = hole.cont_id().to_owned();
                assert!(matches!(
                    session.abort(&activation_id, "fixture retained original input".into()),
                    Err(ResidentError::Run(tidepool_runtime::RuntimeError::Jit(
                        tidepool_effect::EffectError::Handler(reason)
                    ))) if reason == "ask aborted by caller: fixture retained original input"
                ));
                assert!(!session.parked_holes().contains(&activation_id.as_str()));
                input
            })
            .collect();
        (session, context, source, inputs, root)
    }

    type ActivationSessionFixture = (
        ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
        ActorWorkbenchSource,
        Vec<(
            ResidentHole,
            tidepool_runtime::session::RuntimeActivationInput,
        )>,
        tempfile::TempDir,
    );

    #[tokio::test]
    async fn repeated_activation_fixtures_preserve_exact_nominal_constructor_identity() {
        with_test_compiler_owner(|_| async {
            for _ in 0..2 {
                drop(activation_session_fixture(|_| {}));
            }
        })
        .await;
    }

    #[tokio::test]
    async fn activation_fixture_interleaving_distinguishes_initialization_from_reset() {
        with_test_compiler_owner(|_| async {
            let construct = |phase| {
                eprintln!("activation fixture interleaving phase={phase} begin");
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    drop(activation_session_fixture(|_| {}));
                }));
                eprintln!(
                    "activation fixture interleaving phase={phase} completed={}",
                    outcome.is_ok(),
                );
                outcome
            };
            assert!(construct("before-result-initialization").is_ok());
            eprintln!("result fixture first genuine initialization begin");
            crate::request::test_support::fresh_history();
            eprintln!("result fixture first genuine initialization complete");
            let after_initialization = construct("after-result-initialization");
            eprintln!("result fixture reset-only begin");
            crate::request::test_support::fresh_history();
            eprintln!("result fixture reset-only complete");
            let after_reset = construct("after-result-reset");
            assert!(
                after_initialization.is_ok() && after_reset.is_ok(),
                "activation fixture interleaving: initialization={}, reset={}",
                after_initialization.is_ok(),
                after_reset.is_ok(),
            );
        })
        .await;
    }

    pub(crate) fn activation_session_fixture(
        configure: impl FnOnce(&mut tidepool_runtime::session::SessionLib),
    ) -> ActivationSessionFixture {
        activation_session_fixture_counted(configure, false)
    }

    fn activation_session_fixture_counted(
        configure: impl FnOnce(&mut tidepool_runtime::session::SessionLib),
        renderer_values: bool,
    ) -> ActivationSessionFixture {
        use tidepool_runtime::session::{ModuleEnv, SessionLib};
        let _source_closure_trace =
            (std::env::var("TIDEPOOL_KEEP_TEST_LOGS").as_deref() == Ok("1")).then(|| {
                tracing::subscriber::set_default(
                    tracing_subscriber::fmt()
                        .with_env_filter(tracing_subscriber::EnvFilter::new(
                            "tidepool::certified_products::source_closure_trace=debug",
                        ))
                        .with_test_writer()
                        .finish(),
                )
            });
        let (_, mut context, _, _) = host_mount_fixture();
        let declarations = [
            tidepool_mcp::agent_tools_decl(),
            tidepool_mcp::agent_session_decl(),
            tidepool_mcp::actor_decl(),
            tidepool_mcp::actor_kernel_decl(),
            tidepool_mcp::actor_local_decl(),
            tidepool_mcp::fs_read_decl(),
            tidepool_mcp::worktree_decl(),
            tidepool_mcp::notifications_decl(),
            tidepool_mcp::console_decl(),
            tidepool_mcp::sleep_decl(),
        ];
        let effects = tidepool_mcp::ensure_effects_module(&declarations).unwrap();
        let include = fixture_include_roots(&effects);
        let mut preamble = tidepool_mcp::build_notebook_preamble(&declarations, false);
        for import in [
            "Tidepool.Agent.Reply (Replies)",
            "Tidepool.Agent.Watch (Watches)",
            "Tidepool.Agent.Ref.Internal (AgentProtocol(..))",
            "qualified Tidepool.Agent.Ref.Internal as Ref",
            "qualified Tidepool.Actors.Internal.Agent as Agents",
            "qualified Tidepool.Effects.Core as Core",
        ] {
            preamble = insert_preamble_imports(&preamble, import);
        }
        let (fixture_sources, _fixture_sources_owner) =
            world_query_test_source_files_with_support(&[], &include);
        context.source_layer = crate::ActorSourceRoots::Complete(fixture_sources.clone());
        context.haskell_effects_alias = "'[Replies]".into();
        context.effect_policy = tidepool_effect::EffectRunPolicy::SuspendAll;
        let root = tempfile::tempdir().unwrap();
        let mut lib = SessionLib::open(
            context.placement.session,
            root.path(),
            ModuleEnv::standalone_default(),
        )
        .unwrap()
        .with_validation_include(include.clone());
        configure(&mut lib);
        let mut session = ResidentSession::unbootstrapped(
            frunk::HNil,
            tidepool_mcp::CapturedOutput::new(),
            tidepool_runtime::DEFAULT_NURSERY_SIZE,
            Some(lib),
        );
        let fixture_source = session.mint_notebook_scope_with_lease(None).unwrap();
        context.placement.lexical_scope = fixture_source.scope();
        context
            .source_dependency()
            .adopt_final_scope(&mut session, fixture_source.scope())
            .unwrap();
        assert!(Arc::ptr_eq(
            &fixture_source,
            &context.source_dependency().source_lease().unwrap()
        ));
        session
            .validate_lexical_scope_lease(context.placement.lexical_scope, &fixture_source)
            .unwrap();
        type FixtureSession = ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>;
        fn fixture_setup<T>(
            session: &mut FixtureSession,
            source: &Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
            action: impl FnOnce(&mut FixtureSession) -> T,
        ) -> T {
            let settled = session
                .with_source_compiler_transaction(
                    source.original_source().clone(),
                    tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                    tidepool_runtime::CompilerTransactionCancellation::new(),
                    None,
                    |_| {},
                    |session, _| action(session),
                )
                .unwrap();
            assert_eq!(
                settled.close(),
                &tidepool_runtime::CompilerTransactionClose::NotStarted,
                "pure renderer fixture setup must submit no compiler request"
            );
            settled.into_outcome().action
        }
        fn fixture_execution<T>(
            session: &mut FixtureSession,
            source: &Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
            action: impl FnOnce(
                &mut FixtureSession,
                &mut dyn FnMut(tidepool_runtime::CompilerTransactionClose),
            ) -> T,
        ) -> T {
            let settled = session
                .with_source_compiler_transaction(
                    source.original_source().clone(),
                    tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                    tidepool_runtime::CompilerTransactionCancellation::new(),
                    None,
                    |_| {},
                    action,
                )
                .unwrap();
            assert!(
                settled.close().resources_retired(),
                "renderer fixture execution: {:?}",
                settled.close()
            );
            settled.into_outcome().action
        }
        session
            .set_actor_execution(
                context.run_context(),
                context.effect_policy,
                context.live_payload,
            )
            .unwrap();
        let source = ActorWorkbenchSource::new(preamble, include);
        let view = actor_compile_view(&session, &context, &source).unwrap();
        let prepared = source.prepare(&view);
        let templates = resident_workbench_templates(
            &prepared.preamble,
            context.haskell_effects_alias.expression(),
            &prepared.imports,
        );
        assert!(
            prepared.injected.is_empty(),
            "ordinary producer has no session imports"
        );
        let include = source
            .base_include
            .iter()
            .map(PathBuf::as_path)
            .collect::<Vec<_>>();
        let producer_started = std::time::Instant::now();
        let producer_text = if renderer_values {
            tidepool_testing::fixture_source(
                "tidepool/runtime/src/session/fixtures/activation-input-twenty-renderers.hs",
            )
        } else {
            tidepool_testing::fixture_source(
                "tidepool/runtime/src/session/fixtures/activation-input-function.hs",
            )
        };
        struct ProducerFixture {
            compiled: CompiledTurn,
            original: Arc<tidepool_toolchain::artifacts::PublishedSourceOriginalSelection>,
            source: String,
            templates: Vec<tidepool_runtime::session::TurnTemplate>,
            include: Vec<PathBuf>,
            generation: u64,
            _root: tempfile::TempDir,
        }
        // The fresh receiver imports the producer's issued original closure.
        // Sharing immutable code alone would allow a later compiler transaction
        // to select a different nominal interface for the receiver.
        static FUNCTION_PRODUCER: std::sync::OnceLock<ProducerFixture> = std::sync::OnceLock::new();
        static RENDERER_PRODUCER: std::sync::OnceLock<ProducerFixture> = std::sync::OnceLock::new();
        let producer_fixture = if renderer_values {
            &RENDERER_PRODUCER
        } else {
            &FUNCTION_PRODUCER
        }
        .get_or_init(|| {
            let compile_root = tempfile::tempdir().unwrap();
            let TurnResult::Bind {
                compiled, bound, ..
            } = tidepool_testing::with_settlement(|settlement| {
                tidepool_runtime::session::turn::run_turn(
                    TurnRequest {
                        exact_context: None,
                        session_id: None,
                        turn_text: &producer_text,
                        templates: &templates,
                        include: &include,
                        session_root: compile_root.path(),
                        inject_modules: &[],
                        gen: view.next_value_generation().0,
                        verdict: None,
                        target: None,
                        retained_imports: &[],
                    },
                    settlement,
                )
            })
            .unwrap()
            else {
                panic!("native input producer must execute a bind");
            };
            assert!(
                bound.is_empty(),
                "request producer creates no persistent binding"
            );
            let original = compiled
                .published_source_original_selection(
                    compiled
                        .ordinary_original_compile_input()
                        .unwrap()
                        .original_input_identity(),
                    &tidepool_toolchain::declaration_join::ExactModuleIdentity {
                        unit: "main".into(),
                        module: "Tidepool.Agent.Ref.Internal".into(),
                    },
                )
                .unwrap();
            ProducerFixture {
                compiled,
                original,
                source: producer_text.clone(),
                templates: templates.clone(),
                include: source.base_include.to_vec(),
                generation: view.next_value_generation().0,
                _root: compile_root,
            }
        });
        assert_eq!(producer_fixture.source, producer_text);
        assert_eq!(producer_fixture.include, source.base_include.as_ref());
        assert_eq!(producer_fixture.generation, view.next_value_generation().0);
        assert!(producer_fixture
            .templates
            .iter()
            .zip(&templates)
            .all(|(left, right)| left.kind == right.kind && left.source == right.source));
        assert_eq!(producer_fixture.templates.len(), templates.len());
        let producer = &producer_fixture.compiled;
        let original = session
            .stage_published_source_originals_in(
                context.placement.lexical_scope,
                Arc::clone(&producer_fixture.original),
            )
            .unwrap();
        session.publish_source_originals(original).unwrap();
        eprintln!(
            "activation fixture producer preparation: {:?}",
            producer_started.elapsed()
        );
        // This owner-cluster fixture explicitly bootstraps its real World before
        // private setup; it does not qualify a cold first authored cell.
        let fixture_reference = fixture_sources
            .generation_evidence()
            .unwrap()
            .reference
            .clone();
        let admitted_world = session
            .capture_inspection_world_in(
                context.placement.lexical_scope,
                &fixture_reference,
                fixture_source.original_source(),
            )
            .unwrap();
        assert!(admitted_world.needs_source_capture());
        let dependency = context.source_dependency().clone();
        let compiler_work = crate::capabilities::CompilerOwnerScope::current()
            .unwrap()
            .with_source_dependency(&dependency)
            .admit_work()
            .unwrap();
        let settled_world = compiler_work.run_source_compiler_phase(
            &dependency, tidepool_toolchain::artifacts::CompileWorkload::Foreground,
            |owner, _| tidepool_runtime::session::run_admitted_compiler_world(
                owner, admitted_world,
                || fixture_sources.capture_compiler_sources().map_err(|error| match error {
                    crate::SourceInspectionError::Unavailable(detail) => tidepool_runtime::session::WorldInspectionError::SourceUnavailable(detail),
                    crate::SourceInspectionError::Unreadable(detail) => tidepool_runtime::session::WorldInspectionError::SourceUnreadable(detail),
                }),
            ),
        ).unwrap();
        assert!(settled_world.close().resources_retired());
        let completed_world =
            tidepool_runtime::session::finish_admitted_compiler_world(settled_world).unwrap();
        fixture_setup(&mut session, &fixture_source, |session| {
            assert!(session.install_compiler_world_if_current(
                &completed_world,
                &fixture_reference,
                fixture_source.original_source(),
            ));
        });
        let receiver_started = std::time::Instant::now();
        let previous_context = session.run_context();
        let execution = Arc::new(fixture_setup(&mut session, &fixture_source, |session| {
            session
                .begin_ephemeral_private_execution(context.placement.lexical_scope)
                .unwrap()
        }));
        let mut private_context = context.clone();
        private_context.placement.lexical_scope = execution.private_scope();
        session
            .set_run_context(private_context.run_context())
            .unwrap();
        let world = execution.compiler_world().unwrap().clone();
        assert!(Arc::ptr_eq(&world, completed_world.world()));
        assert!(Arc::ptr_eq(
            &execution.original_source().unwrap(),
            fixture_source.original_source(),
        ));
        let receiver_source = source.clone().for_workbench(&private_context, None);
        let preamble = cell_module_preamble(
            &hide_preamble_exports(
                &receiver_source.preamble,
                &[tidepool_runtime::session::ExportItem::Value {
                    name: "print".into(),
                }],
            ),
            "CellCheck",
        )
        .unwrap();
        let imports = receiver_source.workbench_imports.template_text();
        let template = resident_cell_check_template(
            &preamble,
            private_context.haskell_effects_alias.expression(),
            &imports,
        );
        let templates = resident_workbench_templates(
            &preamble,
            private_context.haskell_effects_alias.expression(),
            &imports,
        );
        let receiver_text = tidepool_testing::fixture_source(
            "tidepool/runtime/src/session/fixtures/activation-input-receiver.hs",
        );
        let specification = Arc::new(tidepool_extract_cmd::WorldCellRecipe {
            source: receiver_text,
            template,
            turn_templates: templates
                .iter()
                .map(|template| {
                    let kind = match template.kind {
                        tidepool_runtime::session::TemplateSelector::Decl => "decl",
                        tidepool_runtime::session::TemplateSelector::Bind => "bind",
                        tidepool_runtime::session::TemplateSelector::BindDiscard => "binddiscard",
                        tidepool_runtime::session::TemplateSelector::Expr => "expr",
                    };
                    (kind.to_owned(), template.source.clone())
                })
                .collect(),
        });
        let plan_work = crate::capabilities::CompilerOwnerScope::current()
            .unwrap()
            .with_source_dependency(&dependency)
            .admit_work()
            .unwrap();
        let settled_plan = plan_work
            .run_source_compiler_phase(
                &dependency,
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                |owner, _| {
                    tidepool_runtime::session::turn::prepare_world_cell_plan_admitted(
                        owner,
                        &world,
                        specification.clone(),
                        None,
                    )
                },
            )
            .unwrap();
        let plan =
            tidepool_runtime::session::turn::finish_world_cell_plan_admitted(settled_plan).unwrap();
        eprintln!(
            "activation fixture receiver parse: {:?}",
            receiver_started.elapsed()
        );
        let receiver_compile_started = std::time::Instant::now();
        let admission = fixture_setup(&mut session, &fixture_source, |session| {
            session
                .admit_world_planned_cell_for_execution(execution.clone(), plan)
                .unwrap()
        });
        let check_work = crate::capabilities::CompilerOwnerScope::current()
            .unwrap()
            .with_source_dependency(&dependency)
            .admit_work()
            .unwrap();
        let prepared_program = check_work
            .run_source_compiler_phase(
                &dependency,
                tidepool_toolchain::artifacts::CompileWorkload::Foreground,
                |owner, settlement| {
                    tidepool_runtime::session::turn::prepare_cell_program_admitted(
                        owner, admission, settlement,
                    )
                },
            )
            .unwrap();
        let (checked, program) =
            tidepool_runtime::session::turn::finish_cell_program_admitted(prepared_program)
                .unwrap();
        eprintln!(
            "activation fixture receiver compilation: {:?}",
            receiver_compile_started.elapsed()
        );
        assert_eq!(
            checked.items.len(),
            1,
            "receiver setup is one grouped binding"
        );
        let item = program.items()[0].checked_item().clone();
        let prefix = fixture_setup(&mut session, &fixture_source, |session| {
            session.begin_cell_program(program).unwrap().unwrap()
        });
        let reservation = fixture_setup(&mut session, &fixture_source, |session| {
            session.admit_checked_item(prefix.clone(), item).unwrap()
        });
        let TurnResult::Bind {
            compiled: receiver,
            bound,
            ..
        } = tidepool_runtime::session::turn::consume_cell_program_item(reservation.clone())
            .unwrap()
        else {
            panic!("native receiver must install retained bindings");
        };
        assert_eq!(bound.len(), 2, "receiver and original native Unit reply");
        for (role, compiled) in [("producer", producer), ("receiver", &receiver)] {
            for constructor in compiled
                .table()
                .iter()
                .filter(|constructor| constructor.identity.symbol.occurrence == "RunRequest")
            {
                eprintln!(
                    "activation fixture {role} RunRequest table id={:?} identity={:?}",
                    constructor.id, constructor.identity,
                );
            }
            for constructor in compiled
                .prepared()
                .constructors()
                .iter()
                .filter(|constructor| constructor.identity.symbol.occurrence == "RunRequest")
            {
                eprintln!(
                    "activation fixture {role} RunRequest prepared id={:?} identity={:?}",
                    constructor.host_id, constructor.identity,
                );
            }
        }

        let receiver_interface = receiver
            .certification()
            .unwrap()
            .checked_execution()
            .unwrap()
            .value_interface_certificate()
            .unwrap();
        assert_eq!(
            receiver_interface.owner(),
            tidepool_repr::SessionModule::val(reservation.generation())
        );
        let outcome = fixture_execution(&mut session, &fixture_source, |session, settlement| {
            session.run_projected_bind_with_sites(
                "activationReceiverFixture",
                receiver.code(),
                &bound,
                reservation.generation(),
                settlement,
            )
        })
        .unwrap();
        assert!(matches!(outcome, ResidentOutcome::BindingsCommitted { .. }));
        let intent = fixture_setup(&mut session, &fixture_source, |session| {
            session.freeze_private_execution(&execution).unwrap()
        });
        let tidepool_runtime::session::ExecutionPublication::Bindings(publication) =
            fixture_setup(&mut session, &fixture_source, |session| {
                session
                    .restage_ephemeral_execution_publication(intent)
                    .unwrap()
            })
        else {
            panic!("receiver setup publishes only native bindings");
        };
        let ticket = publication.stage().unwrap();
        assert!(matches!(
            fixture_setup(&mut session, &fixture_source, |session| session
                .attempt_public_manifest(
                    ticket,
                    &tidepool_runtime::session::PublicationDecision::new(),
                )
                .map(crate::resident_workbench::settled_manifest_attempt)
                .unwrap()),
            tidepool_runtime::session::PublicManifestCommit::Ephemeral
        ));
        session.set_run_context(previous_context).unwrap();
        drop(receiver);
        drop(reservation);
        drop(prefix);
        drop(execution);
        session.retire_scope(private_context.placement.lexical_scope);
        assert!(session
            .compile_view_in(private_context.placement.lexical_scope)
            .is_none());
        let public = session
            .compile_view_in(context.placement.lexical_scope)
            .unwrap();
        let captured = session.capture_inspection_inputs(&public).unwrap();
        assert!(captured
            .view()
            .reachable_values()
            .contains(&receiver_interface.owner()));
        for binder in &bound {
            assert_eq!(
                session
                    .current_binding_in(context.placement.lexical_scope, &binder.name)
                    .unwrap()
                    .0,
                tidepool_repr::SessionVarId::from_extract(binder.var_id)
            );
        }
        drop(captured);
        let suspend = |outcome| match outcome {
            ResidentOutcome::Suspended { hole, .. } => hole,
            other => panic!("native activation fixture must suspend: {other:?}"),
        };
        let mut reservation = suspend(
            fixture_execution(&mut session, &fixture_source, |session, settlement| {
                session.run_with_sites("originalActivationRequests", producer.code(), settlement)
            })
            .unwrap(),
        );
        let mut inputs = Vec::new();
        let requests = if renderer_values { 20 } else { 2 };
        for request in 1_i64..=requests {
            let submission = suspend(
                fixture_execution(&mut session, &fixture_source, |session, settlement| {
                    session.resume(reservation, Ok::<i64, ()>(request), settlement)
                })
                .unwrap(),
            );
            let payload = session
                .live_payload_handle(submission.cont_id())
                .unwrap()
                .unwrap();
            let receiver = session
                .retain_binding_custody("activationReceiver")
                .unwrap()
                .unwrap();
            let activation = suspend(
                fixture_execution(&mut session, &fixture_source, |session, settlement| {
                    session.run_rooted_application(
                        "originalActivationInput",
                        &receiver,
                        &payload,
                        context.placement.resource_scope,
                        None,
                        settlement,
                    )
                })
                .unwrap(),
            );
            let input = producer
                .sites()
                .iter()
                .filter(|site| !site.inputs.is_empty())
                .find_map(|site| {
                    session
                        .capture_activation_input(
                            &activation,
                            context.placement.resource_scope,
                            site.site,
                        )
                        .ok()
                })
                .expect("original authenticated input site");
            inputs.push((activation, input));
            assert!(session.parked_holes().contains(&submission.cont_id()));
            let next = fixture_execution(&mut session, &fixture_source, |session, settlement| {
                session.resume(submission, Ok::<(), ()>(()), settlement)
            })
            .unwrap();
            if request < requests {
                reservation = suspend(next);
            } else {
                break;
            }
        }
        (session, context, source, inputs, root)
    }

    /// Authentic retained input for request-settlement component histories.
    /// Ready-only histories share immutable admitted input with fresh decisions.
    /// Fence histories use fresh fixtures because a fenced run cannot be revived.
    pub(crate) struct ActivationPublicationPhaseFixture {
        prepared: PreparedActivationInput,
        session: Mutex<Option<Box<ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>>>>,
        context: crate::ActorSessionContext,
        receipt: Option<tidepool_runtime::session::CheckoutReceipt>,
        _machines: Arc<ActorMachineRegistry<frunk::HNil, tidepool_mcp::CapturedOutput>>,
        _run_root: tempfile::TempDir,
        recovery: crate::recovery::recovery_test_fixture::RecoveryFixture,
    }

    impl ActivationPublicationPhaseFixture {
        pub(crate) fn actor(&self) -> crate::ActorRef {
            self.context.actor
        }

        pub(crate) fn fresh_resources(
            &self,
        ) -> (
            Arc<ActivationPublicationResources>,
            Arc<tidepool_runtime::session::PublicationDecision>,
        ) {
            let original = &self.prepared.execution;
            let decision = tidepool_runtime::session::PublicationDecision::new();
            let execution = Arc::new(ExecutionPrivateScope {
                inspection: original.inspection.clone(),
                owner: original.owner.clone(),
                public_scope: original.public_scope,
                private_scope: original.private_scope,
                admitted_public: original.admitted_public.clone(),
                admission: original.admission.clone(),
                decision: decision.clone(),
            });
            (
                Arc::new(ActivationPublicationResources {
                    execution,
                    input: self.prepared.admission.clone(),
                }),
                decision,
            )
        }

        pub(crate) fn make_pending(&self) {
            let mut held = self.session.lock();
            let session = held.as_mut().unwrap();
            let owner = self.prepared.execution.owner.durable().unwrap();
            let scope = self.context.placement.lexical_scope;
            let writer = session
                .begin_durable_private_execution(owner, scope)
                .unwrap();
            let intent = session.freeze_private_execution(&writer).unwrap();
            let tidepool_runtime::session::ExecutionPublication::Bindings(base) = session
                .restage_execution_publication(owner.clone(), intent)
                .unwrap()
            else {
                panic!("empty native writer has no declaration projection");
            };
            let ticket = base.stage().unwrap();
            self.recovery.fail_commits();
            let outcome = session
                .attempt_public_manifest(
                    ticket,
                    &tidepool_runtime::session::PublicationDecision::new(),
                )
                .map(crate::resident_workbench::settled_manifest_attempt);
            self.recovery.clear_commit_failure();
            assert!(matches!(
                outcome.unwrap(),
                tidepool_runtime::session::PublicManifestCommit::RecoveryRequired { .. }
            ));
            assert!(!self.prepared.execution.owner.is_ready());
        }

        pub(crate) fn make_ready(&self) {
            assert!(self.prepared.execution.owner.is_ready());
        }
    }

    impl Drop for ActivationPublicationPhaseFixture {
        fn drop(&mut self) {
            let session = self.session.get_mut().take().unwrap();
            let holes = session
                .parked_holes()
                .into_iter()
                .map(str::to_owned)
                .collect();
            self._machines
                .settle_suspended(self.receipt.take().unwrap(), session, holes);
        }
    }

