    async fn activation_inputs_preserve_durable_private_admission_across_replacement_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let mut recovery = None;
        let (mut session, mut context, source, inputs, _root) = activation_input_fixture(|lib| {
            let fixture =
                crate::recovery::recovery_test_fixture::RecoveryFixture::create(lib.include_dir());
            tidepool_testing::with_settlement(|settlement| fixture.attach_root(lib, settlement));
            recovery = Some(fixture);
        });
        let recovery = recovery.unwrap();
        let path = tidepool_repr::ActorPath::parse("root/activation-child").unwrap();
        let durable_owner =
            tidepool_runtime::session::RecoveryPublicOwner::new(&path, context.actor.incarnation.0)
                .unwrap();
        context.placement.lexical_scope = session.mint_scope(ScopeId::ROOT).unwrap();
        let public_scope = context.placement.lexical_scope;
        session
            .initialize_durable_public_scope(durable_owner.clone(), public_scope)
            .unwrap();
        let descriptor = crate::ActorDescriptor::new("activation-child", context.placement)
            .with_persistence_policy(crate::ActorPersistencePolicy::Durable)
            .with_actor_path(path);
        let owner = crate::resident_actor::WorkbenchPublicOwner::issue(
            &context,
            &descriptor,
            Some(
                session
                    .durable_public_readiness(&durable_owner, public_scope)
                    .unwrap(),
            ),
        )
        .unwrap();
        let machines = Arc::new(ActorMachineRegistry::new());
        machines.insert_idle(context.placement.session, Box::new(session));
        let workbench = ResidentActorWorkbench::new(
            machines,
            (source).bind_preparation(preparation_client.clone()),
            None,
        )
        .with_compilation_authority(
            crate::resident_actor::WorkbenchCompilationAuthority::for_test(context.clone()),
        );
        let mut previous = None;
        let mut captured = None;
        for input in inputs {
            let before_manifest = recovery.public_owner(&durable_owner).unwrap();
            let bootstrap = workbench_runner_for_test(&workbench)
                .begin_public_bootstrap(context.clone(), owner.clone())
                .await
                .unwrap();
            let runner = workbench_runner_for_test(&workbench);
            assert!(matches!(
                runner
                    .publish_public_bootstrap(context.clone(), owner.clone(), bootstrap)
                    .await
                    .unwrap(),
                tidepool_runtime::session::PublicManifestCommit::Durable
            ));
            let execution = Arc::new(
                runner
                    .begin_private_execution(
                        context.clone(),
                        owner.clone(),
                        tidepool_runtime::session::PublicationDecision::new(),
                        None,
                    )
                    .await
                    .unwrap(),
            );
            let mut private_context = context.clone();
            private_context.placement.lexical_scope = execution.private_scope;
            let private_workbench = ResidentActorWorkbench::new(
                workbench.access.machines.clone(),
                workbench.access.source.clone(),
                None,
            )
            .with_compilation_authority(
                crate::resident_actor::WorkbenchCompilationAuthority::for_test(
                    private_context.clone(),
                ),
            )
            .with_private_execution(execution);
            let prepared = private_workbench
                .mount_activation_input(
                    private_context.clone(),
                    input,
                    None,
                    "()".into(),
                    None,
                    vec![],
                )
                .await
                .unwrap();
            let binding = prepared.binding;
            let requests = Arc::new(crate::request::RequestRegistry::default());
            let requester = crate::ActorRef::first(crate::ActorId(context.actor.id.0 + 100));
            let request = requests.reserve(requester, context.actor);
            requests
                .mark_queued(requester, context.actor, request)
                .unwrap();
            requests
                .present_with_progress_type(context.actor, request, None)
                .unwrap();
            let retirement = crate::RetainedActorExit::default();
            assert!(matches!(
                runner
                    .publish_activation_input(
                        private_context,
                        &prepared,
                        requests,
                        request,
                        retirement,
                        None
                    )
                    .await
                    .unwrap(),
                ActivationInputPublication::Published(_)
            ));
            drop(prepared);
            drop(private_workbench);
            assert_ne!(
                recovery.public_owner(&durable_owner).unwrap(),
                before_manifest
            );
            assert_ne!(previous, Some(binding));
            let expected = durable_owner.clone();
            let custody = workbench
                .access
                .with_machine(context.clone(), move |session, _, _| {
                    let _admission = session
                        .begin_durable_private_execution(&expected, public_scope)
                        .map_err(ResidentError::Session)?;
                    assert_eq!(
                        session
                            .current_binding_in(public_scope, "sessionInput")
                            .unwrap()
                            .0,
                        binding
                    );
                    let custody = session
                        .retain_binding_custody_in(public_scope, "sessionInput", binding)?
                        .unwrap();
                    Ok(custody)
                })
                .await
                .expect("published activation admits an ordinary durable private cell");
            if captured.is_none() {
                captured = Some(custody);
            }
            previous = Some(binding);
        }
        workbench
            .access
            .with_machine(context, move |session, _, _| {
                let _admission = session
                    .begin_durable_private_execution(&durable_owner, public_scope)
                    .map_err(ResidentError::Session)?;
                assert!(session
                    .render_retained_preview(&captured.unwrap(), 128)
                    .is_some());
                assert!(session
                    .retain_binding_custody_in(public_scope, "sessionInput", previous.unwrap())?
                    .is_some());
                Ok(())
            })
            .await
            .unwrap();
    }

