    async fn whole_cell_installs_bindings_before_and_after_native_bootstrap_with_preparation_client(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        with_test_compiler_owner(|_| async {
            let (machines, context, source, _root) = actor_registry_fixture();
            let (workbench, context) = ResidentActorWorkbench::new(
                machines,
                (source).bind_preparation(preparation_client.clone()),
                None,
            )
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
            let (checked, prepared) = workbench
                .prepare_cell(
                    context.clone(),
                    "installWarmup <- pure (0 :: Int)\ninstalledAfterBootstrap <- pure (1 :: Int)"
                        .into(),
                )
                .await
                .unwrap();
            let PreparedCell {
                items,
                dependencies,
            } = prepared;
            assert_eq!(items.len(), 2);
            for (index, item) in items.into_iter().enumerate() {
                workbench
                    .access
                    .with_machine(context.clone(), move |session, _, _| {
                        assert_eq!(session.is_bootstrapped(), index != 0);
                        Ok(())
                    })
                    .await
                    .unwrap();
                let step = workbench
                    .begin_prepared_cell_item(
                        context.clone(),
                        ParsedBlock {
                            ordinal: index + 1,
                            total: 2,
                            source: checked.items[index].source.clone(),
                        },
                        item,
                    )
                    .await
                    .unwrap();
                let ResidentWorkbenchStep::Committed {
                    installed_bindings, ..
                } = step
                else {
                    panic!("native whole-cell bind must commit");
                };
                assert_eq!(
                    installed_bindings,
                    vec![if index == 0 {
                        "installWarmup".to_owned()
                    } else {
                        "installedAfterBootstrap".to_owned()
                    }]
                );
            }
            drop(dependencies);
        })
        .await;
    }

    /// The fixture parks at an actor-context effect before any binder commits.
    fn suspending_fragment() -> (ParsedBlock, TurnClassification) {
        (
            ParsedBlock {
                ordinal: 1,
                total: 1,
                source: "notified <- maybe (pure Nothing) \
                          (\\p -> Just <$> Exomonad.sendMessage p \"hello\") =<< Exomonad.parentAgent"
                    .into(),
            },
            TurnClassification {
                kind: TurnKind::Bind,
                binders: vec!["notified".into()],
                items: Vec::new(),
            },
        )
    }

    #[tokio::test]
    async fn public_visibility_snapshot_pairs_declaration_and_exact_binding_identities() {
        with_test_compiler_owner(|preparation_client| public_visibility_snapshot_pairs_declaration_and_exact_binding_identities_with_compiler_owner(preparation_client.clone(), )).await
    }

    async fn public_visibility_snapshot_pairs_declaration_and_exact_binding_identities_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, context, source, _root) = actor_registry_fixture();
        let workbench = ResidentActorWorkbench::new(
            Arc::clone(&machines),
            (source.clone()).bind_preparation(preparation_client.clone()),
            None,
        );
        let runner = ResidentActorRunner::new(
            machines,
            (source.clone()).bind_preparation(preparation_client.clone()),
        );
        let before = runner
            .public_visibility_snapshot(context.clone())
            .await
            .expect("initial public view");
        workbench
            .publish_cell_for_test(context.clone(), "snapshotValue <- pure (42 :: Int)")
            .await
            .expect("source value executes and publishes through its private whole cell");
        let bound = runner
            .public_visibility_snapshot(context.clone())
            .await
            .expect("bound public view");
        assert!(bound.epoch > before.epoch);
        assert_eq!(bound.declaration_tip, before.declaration_tip);
        assert!(before
            .bindings
            .iter()
            .all(|(name, _)| name != "snapshotValue"));
        assert!(bound
            .bindings
            .iter()
            .any(|(name, _)| name == "snapshotValue"));

        workbench
            .publish_cell_for_test(context.clone(), "data SnapshotTag = SnapshotTag")
            .await
            .expect("declaration publishes through its private whole cell");
        let declared = runner
            .public_visibility_snapshot(context)
            .await
            .expect("declaration public view");
        assert!(declared.epoch > bound.epoch);
        assert!(declared.declaration_tip.0 > bound.declaration_tip.0);
        assert_eq!(declared.bindings, bound.bindings);
    }

