    async fn captured_haskell_binding_outlives_failed_parent_and_released_token_for_two_delayed_children_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, context, source, _root) = actor_registry_fixture();
        let workbench = ResidentActorWorkbench::new(
            Arc::clone(&machines),
            (source.clone()).bind_preparation(preparation_client.clone()),
            None,
        );
        let runner = ResidentActorRunner::new(
            Arc::clone(&machines),
            (source.clone()).bind_preparation(preparation_client.clone()),
        );
        let baseline_handles = workbench
            .access
            .with_machine(context.clone(), |session, _, _| {
                Ok(session.value_handle_count())
            })
            .await
            .expect("initial runtime binding-root ledger");
        let (binding_workbench, binding_context) = runner
            .application_workbench()
            .admit_private_cell_for_test(context.clone())
            .await
            .expect("parent checked-cell admission");
        binding_workbench
            .execute_cell_for_test(
                binding_context.clone(),
                "capturedValue <- pure ((+) (41 :: Int))",
            )
            .await
            .expect("parent checked Haskell binding commits privately");
        binding_workbench
            .publish_completed_cell_for_test(binding_context)
            .await
            .expect("certified binding publishes before checkpoint capture");
        drop(binding_workbench);

        let (captured_scope, retained) = runner
            .capture_retained_context_scope(context.clone())
            .await
            .expect("capture independently owned parent Haskell environment");
        let retained_scope = retained.scope();
        let admissions = crate::ActorAdmissionRegistry::new();
        let boundary = crate::ContextCheckpointBoundary::external(
            "thread".into(),
            "unfinished-parent".into(),
            "unfinished-parent".into(),
        );
        let token = admissions.capture_checkpoint_with_retained_scope(
            "real Haskell context".into(),
            context.actor,
            crate::ActorCapabilities::default(),
            None,
            None,
            crate::CheckpointSourceLayer::default(),
            context.placement.session,
            captured_scope,
            boundary.clone(),
            None,
            retained,
            crate::ActorPersistencePolicy::Ephemeral,
        );
        admissions
            .settle_checkpoint(&token, context.placement.session, true)
            .expect("Haskell checkpoint answer delivered");
        let first = admissions
            .claim_spawn(context.actor, context.placement.session, Some(&token), None)
            .expect("first child and checkpoint admitted before parent completion")
            .checkpoint
            .unwrap()
            .0;
        let second = admissions
            .claim_spawn(context.actor, context.placement.session, Some(&token), None)
            .expect("second child and checkpoint admitted before parent completion")
            .checkpoint
            .unwrap()
            .0;
        let (release_first, first_ready) = tokio::sync::oneshot::channel();
        let (release_second, second_ready) = tokio::sync::oneshot::channel();
        let delayed_child = |admitted: crate::lineage::CheckpointLease,
                             ready: tokio::sync::oneshot::Receiver<()>,
                             actor_id| {
            let runner = &runner;
            let workbench = &workbench;
            let context = context.clone();
            async move {
                // Production start_child retains this exact share before its
                // asynchronous workspace admission. Model that await here;
                // the actor integration fixture exercises the actual adapter.
                let capsule = Arc::clone(admitted.retained_scope().unwrap());
                ready.await.expect("workspace admission resumes");
                let provisional = workbench
                    .access
                    .with_machine(context.clone(), |session, _, _| {
                        Ok(session.mint_isolated_scope())
                    })
                    .await
                    .expect("child provisional scope");
                let mut child = context;
                child.actor = crate::ActorRef::first(crate::ActorId(actor_id));
                child.placement.lexical_scope = provisional;
                let custody = crate::resident_actor::child_launch::ChildPlacementCustody::new(
                    child.placement,
                );
                let _startup = custody.startup_guard();
                child.placement.lexical_scope = runner
                    .remint_checkpoint_child_scope_from_lease(
                        child.clone(),
                        capsule,
                        provisional,
                        custody,
                    )
                    .await
                    .expect("released token cannot erase admitted lexical state");
                (child, admitted)
            }
        };
        let retire_original = async {
            let (failing_workbench, failing_context) = runner
                .application_workbench()
                .admit_private_cell_for_test(context.clone())
                .await
                .expect("failing parent checked-cell admission");
            let failing_source = format!(
                "(sleep (minutes 0) >> error \"parent failed\") :: Eff {} ()",
                failing_context.haskell_effects_alias,
            );
            let (checked, prepared) = failing_workbench
                .prepare_cell(failing_context.clone(), failing_source.into())
                .await
                .expect("parent failing continuation compiles with certified value inputs");
            let PreparedCell {
                mut items,
                dependencies,
            } = prepared;
            assert_eq!(checked.items.len(), 1);
            assert_eq!(items.len(), 1);
            let failed = failing_workbench
                .begin_prepared_cell_item(
                    failing_context.clone(),
                    ParsedBlock {
                        ordinal: 1,
                        total: 1,
                        source: checked.items[0].source.clone(),
                    },
                    items.remove(0),
                )
                .await
                .expect("parent failing continuation starts");
            let ResidentWorkbenchStep::Running { outcome, .. } = failed else {
                panic!("parent failing continuation runs");
            };
            let ResidentWorkbenchSuspension::Ask { hole, .. } = *outcome else {
                panic!("parent suspends before failure");
            };
            assert!(matches!(
                runner.resume_unit(failing_context.clone(), hole).await,
                Err(ResidentActorWorkbenchError::Delivered(_))
            ));
            drop(dependencies);
            assert!(failing_workbench
                .private_execution
                .as_ref()
                .unwrap()
                .decision
                .terminate());
            runner
                .retire_context_scopes(
                    failing_context.clone(),
                    vec![failing_context.placement.lexical_scope],
                )
                .await
                .expect("failed private parent releases its unpublishable scope");
            drop(failing_workbench);
            assert!(admissions
                .settle_checkpoints(context.actor, &boundary, false)
                .is_empty());
            admissions.retire_actor(context.actor);
            let retired = admissions
                .release_checkpoint(&token, context.placement.session)
                .expect("release token while both children await workspace admission");
            runner
                .retire_checkpoint_scopes(context.placement.session, retired.into_iter().collect())
                .await
                .expect("original captured scope retires before remint");
            admissions
                .confirm_checkpoint_release(&token, context.placement.session, captured_scope)
                .expect("original scope retirement acknowledged");
            assert!(admissions.retains_session(context.placement.session));
            assert!(matches!(
                admissions.preview_checkpoint(&token, context.placement.session),
                Err(crate::CheckpointRefusal::ReleasedCheckpoint)
            ));
            release_first.send(()).unwrap();
            release_second.send(()).unwrap();
        };
        let ((first, first_lease), (second, second_lease), ()) = tokio::join!(
            delayed_child(first, first_ready, 2),
            delayed_child(second, second_ready, 3),
            retire_original,
        );
        drop(first_lease);
        assert!(admissions.retains_session(context.placement.session));
        workbench
            .access
            .with_machine(context.clone(), move |session, _, _| {
                session.outstanding_custody();
                assert!(
                    session.compile_view_in(retained_scope).is_some(),
                    "first lease drop preserves the capsule"
                );
                assert!(session
                    .binding_names_in(retained_scope)
                    .contains(&"capturedValue".into()));
                assert!(
                    session.residency().unwrap().persistent_roots > 0,
                    "captured closure has real machine roots"
                );
                Ok(())
            })
            .await
            .expect("runtime owner observes surviving capture");
        drop(second_lease);
        assert!(!admissions.retains_session(context.placement.session));
        workbench
            .access
            .with_machine(context.clone(), move |session, context, _| {
                assert!(
                    session.compile_view_in(retained_scope).is_some(),
                    "last lease drop queues retirement until owner entry settles it"
                );
                session.outstanding_custody();
                assert!(session.compile_view_in(retained_scope).is_none());
                assert!(session.binding_names_in(retained_scope).is_empty());
                assert_eq!(session.scope_binding_count(retained_scope), 0);
                session.retire_scope(context.placement.lexical_scope);
                assert!(
                    session.residency().unwrap().persistent_roots > 0,
                    "both reminted children still own the captured closure"
                );
                Ok(())
            })
            .await
            .expect("actual runtime owner drains final capsule retirement");

        for (index, child) in [first, second].into_iter().enumerate() {
            let (child_workbench, child_private) = runner
                .application_workbench()
                .admit_private_cell_for_test(child.clone())
                .await
                .expect("child checked-cell admission retains its inherited certificate");
            child_workbench
                .execute_cell_for_test(
                    child_private.clone(),
                    "if capturedValue 1 == (42 :: Int) then pure () else error \"unexpected inherited value\"",
                )
                .await
                .expect("child executes inherited closure after final capsule release");
            child_workbench
                .publish_completed_cell_for_test(child_private)
                .await
                .expect("child publishes checked evaluation and retires its private scope");
            drop(child_workbench);
            workbench
                .access
                .with_machine(child.clone(), move |session, context, _| {
                    let scope = context.placement.lexical_scope;
                    assert!(session
                        .binding_names_in(scope)
                        .contains(&"capturedValue".into()));
                    let roots_before = session.persistent_roots_count();
                    let retired = session.retire_scope(scope);
                    let roots_after = session.persistent_roots_count();
                    assert_eq!(roots_before - roots_after, retired.roots_released);
                    if index == 1 {
                        assert!(
                            retired.roots_released > 0,
                            "last child releases actual inherited closure roots"
                        );
                        assert_eq!(session.value_handle_count(), baseline_handles, "all callable and observation binding handles return to the initial ledger");
                    }
                    assert!(session.compile_view_in(scope).is_none());
                    assert_eq!(session.scope_binding_count(scope), 0);
                    Ok(())
                })
                .await
                .expect("last child releases inherited binding ownership");
        }
    }

    #[tokio::test]
    async fn checkpoint_release_retains_exact_scope_after_checkout_failure_until_retry() {
        with_test_compiler_owner(|preparation_client| checkpoint_release_retains_exact_scope_after_checkout_failure_until_retry_with_compiler_owner(preparation_client.clone(), )).await
    }

    async fn checkpoint_release_retains_exact_scope_after_checkout_failure_until_retry_with_compiler_owner(
        preparation_client: crate::CompilerPreparationClient,
    ) {
        let (machines, context, source, _root) = actor_registry_fixture();
        let runner = ResidentActorRunner::new(
            Arc::clone(&machines),
            (source).bind_preparation(preparation_client.clone()),
        );
        let scope = runner
            .capture_context_scope(context.clone())
            .await
            .expect("captured scope");
        let admissions = crate::ActorAdmissionRegistry::new();
        let token = admissions.capture_checkpoint(
            "retryable release".into(),
            context.actor,
            crate::ActorCapabilities::default(),
            None,
            None,
            crate::CheckpointSourceLayer::default(),
            context.placement.session,
            scope,
            crate::ContextCheckpointBoundary::external(
                "thread".into(),
                "call".into(),
                "call".into(),
            ),
        );
        admissions
            .settle_checkpoint(&token, context.placement.session, true)
            .expect("capture published");
        let removed = machines
            .remove(
                context.placement.session,
                "inject checkpoint cleanup checkout failure",
            )
            .expect("machine was registered");
        assert_eq!(
            admissions.release_checkpoint(&token, context.placement.session),
            Ok(Some(scope))
        );
        assert!(runner
            .retire_checkpoint_scopes(context.placement.session, vec![scope])
            .await
            .is_err());
        assert_eq!(
            admissions.pending_release_scopes(context.placement.session),
            vec![(token.clone(), scope)]
        );
        assert!(admissions.retains_session(context.placement.session));
        assert_eq!(
            admissions
                .checkpoint(&token, context.placement.session)
                .err(),
            Some(crate::CheckpointRefusal::ReleasedCheckpoint)
        );
        let tidepool_runtime::session::Slot::Idle(machine) = removed else {
            panic!("fixture machine was idle");
        };
        machines.insert_idle(context.placement.session, machine);
        let retry = admissions
            .release_checkpoint(&token, context.placement.session)
            .expect("idempotent retry");
        assert_eq!(retry, Some(scope));
        runner
            .retire_checkpoint_scopes(context.placement.session, vec![scope])
            .await
            .expect("retry retires exact scope");
        admissions
            .confirm_checkpoint_release(&token, context.placement.session, scope)
            .expect("cleanup acknowledged");
        assert!(admissions
            .pending_release_scopes(context.placement.session)
            .is_empty());
        assert!(!admissions.retains_session(context.placement.session));
        assert_eq!(
            admissions.release_checkpoint(&token, context.placement.session),
            Ok(None)
        );
    }

    enum InstallerDeferredStage {
        BeforePublication,
        AfterPublication,
    }

    async fn assert_installer_deferred_rejection(
        preparation_client: crate::CompilerPreparationClient,
        stage: InstallerDeferredStage,
    ) {
        use std::sync::atomic::{AtomicBool, Ordering};

        let (machines, mut context, source, _root) = actor_registry_fixture();
        context.haskell_effects_alias = "'[Exomonad.Notifications, Exomonad.ActorContext]".into();
        let workbench = ResidentActorWorkbench::new(
            machines,
            (source.clone()).bind_preparation(preparation_client.clone()),
            None,
        );
        let (workbench, context) = workbench
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
        let retained = workbench
            .access
            .with_machine(context.clone(), |session, context, _| {
                Ok(session.retain_lexical_scope(context.placement.lexical_scope)?)
            })
            .await
            .expect("retain actual installation scope");
        let retained_weak = Arc::downgrade(&retained);
        let guard = ParkedHoleAbortGuard::with_retained_latest(
            &workbench.access,
            context.clone(),
            None,
            "unexpected installer work was abandoned".into(),
            Some(retained),
        );
        let registration = guard.registration();
        let (block, _) = suspending_fragment();
        let step = registration
            .scope(workbench.begin_cell_for_test(context.clone(), block))
            .await
            .expect("real native frame parks under the installation guard");
        let ResidentWorkbenchStep::Running { outcome, .. } = step else {
            panic!("fixture must park a native frame")
        };
        let ResidentWorkbenchSuspension::Ask { hole, request } = *outcome else {
            panic!("fixture must yield an actor request")
        };
        let cont_id = hole.cont_id().to_owned();
        assert!(registration.awaiting_acknowledgement().contains(&cont_id));
        let started = Arc::new(AtomicBool::new(false));
        let work_started = Arc::clone(&started);
        let work_owner = Arc::new(());
        let work_weak = Arc::downgrade(&work_owner);
        // Only this refusal fixture supplies an unexpected deferred state.
        // Its actual native frame and scope remain owned by the guard.
        let suspension = ResidentWorkbenchSuspension::Deferred {
            hole,
            request,
            work: tidepool_effect::DeferredEffect::blocking(move || {
                work_started.store(true, Ordering::SeqCst);
                drop(work_owner);
                Err(tidepool_effect::EffectError::Handler(
                    "installer work must remain unstarted".into(),
                ))
            }),
        };
        let checked_registration = registration.clone();
        registration
            .scope(
                workbench
                    .access
                    .with_machine(context, move |session, _, _| {
                        assert!(session.parked_holes().contains(&cont_id.as_str()));
                        assert_eq!(session.stowed_roots_count(), 1);
                        let (result, expected) = match stage {
                            InstallerDeferredStage::BeforePublication => (
                                tool_installation_request(
                                    session,
                                    &checked_registration,
                                    suspension,
                                )
                                .map(|_| ()),
                                "external effect boundary before publication",
                            ),
                            InstallerDeferredStage::AfterPublication => {
                                let settled = ResidentOutcome::from(suspension);
                                let result = require_tool_installation_completion(
                                    session,
                                    &checked_registration,
                                    &settled,
                                );
                                drop(settled);
                                (result, "did not finish after publication")
                            }
                        };
                        assert!(matches!(result,
                    Err(ResidentActorWorkbenchError::ActorProtocol(detail))
                    if detail.contains(expected)));
                        assert_eq!(session.parked_count(), 0);
                        assert_eq!(session.stowed_roots_count(), 0);
                        assert!(checked_registration.awaiting_acknowledgement().is_empty());
                        Ok(())
                    }),
            )
            .await
            .expect("installer rejection confirms native retirement");
        assert!(!started.load(Ordering::SeqCst));
        assert!(work_weak.upgrade().is_none());
        assert!(retained_weak.upgrade().is_some());
        drop(guard);
        drop(registration);
        tokio::time::timeout(Duration::from_secs(5), async {
            while retained_weak.upgrade().is_some() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("installation scope releases after its frame and guard retire");
    }

